insert into public.premium_content (kind, lang, payload) values ('hajj', 'ar', $tk${"umrah":{"title":"العمرة خطوة بخطوة","intro":"العمرة هي زيارة البيت الحرام في مكة. ويمكن أداؤها في أي وقت من السنة تقريبًا، ولا تستغرق إلا ساعات قليلة. وهي أربعة أعمال، تؤدَّى دائمًا بالترتيب نفسه: الإحرام من الميقات، والطواف حول الكعبة، والسعي بين الصفا والمروة، ثم الحلق أو التقصير.\n\nهذا الدليل خلاصة موجزة. وهو لا يغني عن معلِّم مؤهَّل، ولا عن تعليمات الجهات المسؤولة في المكان، وهي تعليمات ينبغي أن تتبعها دائمًا. وحيث تختلف المذاهب الفقهية في تفصيل ما، نذكر ما عليه عمل أكثر الناس: فاسأل عالِمًا تثق به عن حالتك.","chapters":[{"id":"preparation","title":"قبل السفر","body":"الرحلة الطيبة تبدأ من البيت. ابدأ بنيَّتك: أنت تسافر لله وحده، لا ليراك الناس أو يمدحوك. تُب توبة صادقة، وسدِّد ديونك قدر استطاعتك، واطلب السماح ممن قد تكون ظلمتهم. وأنفِق على رحلتك من مال حلال.\n\nثم تعلَّم المناسك قبل أن تذهب. فالحاج الذي يعرف ما عليه أن يفعله يكون مطمئنًّا، ويستطيع أن يُقبل بقلبه على العبادة بدل أن ينشغل بالقلق. اقرأ هذا الدليل عدة مرات، واحضر إن أمكن درسًا عند معلِّم.\n\nوأخيرًا، هيِّئ جسمك وأوراقك: امشِ بانتظام في الأسابيع السابقة، وتحقق من تأشيرتك وتصريحك ولقاحاتك، وخفِّف أمتعتك. فستمشي كثيرًا، وغالبًا في الحر والزحام.","steps":["أخلِص نيَّتك: هذه الرحلة لله وحده.","تُب، وسدِّد ديونك، واطلب السماح ممن حولك.","تعلَّم أعمال العمرة الأربعة وترتيبها.","تحقق من جواز سفرك وتأشيرتك وتصريحك واللقاحات المطلوبة.","اعرف أي ميقات يقع على طريقك ومتى ستبلغه.","تدرَّب على المشي، وخذ معك أشياء خفيفة مريحة."],"duas":[]},{"id":"miqat-ihram","title":"الميقات والإحرام","body":"الميقات هو الحد الذي لا يجوز للحاج أو المعتمر أن يتجاوزه إلا وهو مُحرِم. والمواقيت خمسة: ذو الحليفة للقادمين من المدينة، والجحفة، وقرن المنازل، ويلملم، وذات عرق. وفي الطائرة يعلن الطاقم في العادة عن الميقات: فكن مستعدًّا قبل تلك اللحظة.\n\nويُستحب الاغتسال (الغُسل) قبل الإحرام. يلبس الرجال قطعتين غير مخيطتين من القماش، إزارًا حول الوسط ورداء على الكتفين، وتلبس النساء ثيابهن المعتادة المحتشمة. ثم انوِ بقلبك وقل التلبية. يرفع الرجال صوتهم بها، وتخفض النساء أصواتهن.\n\nوالإحرام هو الحال التي يدخل فيها المرء، لا الثوب. وفيه لا يجوز لك أن تقصَّ شعرًا أو أظفارًا، ولا أن تتطيَّب، ولا أن تصيد، ولا أن تعقد نكاحًا، ولا أن تعاشر زوجك. ولا يلبس الرجال الثياب المفصَّلة على البدن ولا يغطون رؤوسهم، ولا تلبس النساء النقاب ولا القفازين (صحيح البخاري 1838). واجتنب الجدال كذلك (القرآن 2:197).","steps":["قبل الميقات، قلِّم أظفارك واغتسل إن استطعت.","الرجال: البسوا إزار الإحرام ورداءه. النساء: ابقين في ثيابكن المعتادة المحتشمة.","للرجال أن يطيِّبوا البدن، لا ثياب الإحرام، قبل النية، ولا يجوز ذلك بعدها أبدًا.","عند الميقات، انوِ العمرة بقلبك وقل: لبيك اللهم عمرة.","أكثِر من ترديد التلبية في الطريق إلى مكة.","من الآن فصاعدًا، التزم بترك كل ما يحظره الإحرام.","اقطع التلبية حين تبدأ الطواف."],"duas":[{"ar":"لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لاَ شَرِيكَ لَكَ","tr":"Labbayka Allahumma labbayk, labbayka la sharika laka labbayk, inna al-hamda wa an-ni'mata laka wa al-mulk, la sharika lak","t":"أجبتُ دعوتك يا الله مرة بعد مرة. أجبتُك، لا شريك لك، أجبتُك. الحمد كله والنعمة كلها لك، والمُلك كله لك. لا شريك لك.","source":"التلبية — صحيح البخاري 1549؛ صحيح مسلم 1184"}]},{"id":"tawaf","title":"الطواف حول الكعبة","body":"الطواف سبعة أشواط حول الكعبة، تجعلها فيها عن يسارك. ولا بد أن تكون على وضوء. وكل شوط يبدأ وينتهي عند الحجر الأسود: استقبله، وكبِّر، وقبِّله أو استلمه إن تيسَّر ذلك فقط، وإلا فاكتفِ بالإشارة إليه. وكثير من الحجاج يقولون عنده «بسم الله، الله أكبر»، كما رُوي عن الصحابي ابن عمر رضي الله عنهما. وطُف من خارج الجدار المقوَّس (الحِجر)، لا من داخله.\n\nوفي طواف القدوم هذا، يكشف الرجال الكتف الأيمن (الاضطباع)، ويسرعون المشي مع تقارب الخطى في الأشواط الثلاثة الأولى (الرَّمَل). أما النساء فيمشين مشيًا معتادًا.\n\nوليس لكل شوط دعاء محدد واجب: فلك أن تدعو بما شئت، بأي لغة، وأن تذكر الله أو تقرأ القرآن. ولم يُروَ دعاء معيَّن إلا بين الركن اليماني والحجر الأسود: وهو ما في القرآن 2:201. وبعد الطواف، صلِّ ركعتين خلف مقام إبراهيم (القرآن 2:125)، ثم اشرب من ماء زمزم.","steps":["تأكد من أنك على وضوء. يكشف الرجال الكتف الأيمن (الاضطباع).","ابدأ من محاذاة الحجر الأسود: استقبله، وكبِّر، وأشِر إليه إن لم تستطع الوصول إليه.","طُف سبعة أشواط والكعبة عن يسارك، مارًّا من خارج الحِجر.","يسرع الرجال المشي في الأشواط الثلاثة الأولى (الرَّمَل)، ثم يمشون مشيًا معتادًا.","استلم الركن اليماني إن تيسَّر، واقرأ بينه وبين الحجر الأسود ما في القرآن 2:201.","في أثناء الأشواط، ادعُ بما شئت.","بعد الشوط السابع، يغطي الرجال الكتف من جديد، ثم صلِّ ركعتين خلف مقام إبراهيم، أو في أي مكان من المسجد إن كان الزحام شديدًا.","اشرب من ماء زمزم وادعُ."],"duas":[{"ar":"اللَّهُ أَكْبَرُ","tr":"Allahu akbar","t":"الله أعظم من كل شيء.","source":"التكبير عند محاذاة الحجر الأسود — صحيح البخاري 1613"},{"ar":"رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةࣰ وَفِي ٱلۡأٓخِرَةِ حَسَنَةࣰ وَقِنَا عَذَابَ ٱلنَّارِ","tr":"Rabbana atina fi ad-dunya hasanatan wa fi al-akhirati hasanatan wa qina 'adhab an-nar","t":"دعاء يسأل فيه العبد ربه أن يعطيه الخير في الدنيا والخير في الآخرة، وأن يحفظه من عذاب النار.","source":"القرآن 2:201 — يُقرأ بين الركن اليماني والحجر الأسود: سنن أبي داود 1892 (حسن)"}]},{"id":"say","title":"السعي بين الصفا والمروة","body":"بعد الطواف، اتجه إلى الصفا. والسعي سبعة أشواط بين الجبلين: من الصفا إلى المروة شوط، ومن المروة رجوعًا إلى الصفا الشوط الثاني، وهكذا. فتنتهي إذن عند المروة.\n\nوحين تقترب من الصفا أول مرة، اقرأ أول الآية 2:158 من القرآن، كما فعل النبي محمد ﷺ (صحيح مسلم 1218). اصعد قليلًا، واستقبل الكعبة، وارفع يديك، وكبِّر الله ووحِّده بالكلمات المذكورة أدناه، ثم ادعُ بما تريد. ويُفعل ذلك ثلاث مرات. وافعل مثله عند المروة كلما وصلت إليها.\n\nوبين العلمين الأخضرين يسرع الرجال في مشيهم، وتمشي النساء مشيًا معتادًا. وكما في الطواف، ليس لكل شوط دعاء معيَّن لازم. والوضوء مستحب، ولكبار السن والمرضى أن يستعملوا الكرسي المتحرك.","steps":["اتجه إلى الصفا، واقرأ أول الآية 2:158 من القرآن وأنت تقترب منه، في هذه المرة الأولى فقط.","على الصفا، استقبل الكعبة، وارفع يديك، وقل ذكر الصفا وادعُ، ثلاث مرات.","امشِ إلى المروة، ويسرع الرجال في مشيهم بين العلمين الأخضرين.","على المروة، استقبل الكعبة وأعِد الذكر والدعاء.","ارجع إلى الصفا: هذا هو الشوط الثاني.","استمر حتى الشوط السابع، وهو ينتهي عند المروة."],"duas":[{"ar":"إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِ","tr":"Inna as-Safa wa al-Marwata min sha'a'iri Allah","t":"الصفا والمروة من معالم دين الله التي جعلها مواضع لعبادته.","source":"القرآن 2:158 (أول الآية) — يُقرأ عند الاقتراب من الصفا: صحيح مسلم 1218"},{"ar":"لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ أَنْجَزَ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الأَحْزَابَ وَحْدَهُ","tr":"La ilaha illa Allahu wahdahu la sharika lah, lahu al-mulku wa lahu al-hamd, wa huwa 'ala kulli shay'in qadir. La ilaha illa Allahu wahdah, anjaza wa'dah, wa nasara 'abdah, wa hazama al-ahzaba wahdah","t":"لا معبود بحق إلا الله وحده، لا شريك له. له المُلك وله الحمد، وهو قادر على كل شيء. لا معبود بحق إلا الله وحده، وفَّى بوعده، ونصر عبده، وهزم الأحزاب وحده.","source":"الذكر على الصفا والمروة — صحيح مسلم 1218"}]},{"id":"halq-taqsir","title":"الحلق أو التقصير","body":"آخر أعمال العمرة حلق الرأس (الحلق) أو تقصير الشعر (التقصير). والأفضل للرجال حلق الرأس كله، فإن قصَّروا، فالذي عليه عمل أكثر الناس تقصير شعر الرأس كله، لا بضع شعرات فقط. أما النساء فلا يحلقن أبدًا: بل يجمعن شعرهن ويقصصن من طرفه قدر أنملة.\n\nوالرجل الذي يعتمر قبل الحج بقليل (التمتع) يختار كثيرًا أن يقصِّر الآن، ليبقى له شعر يحلقه في اليوم العاشر.\n\nواقصد الحلاقين خارج المسجد بدل قصِّ الشعر في المسعى، وينبغي أن تقصَّ النساء شعرهن في مكان مستور. وبهذا العمل تتم العمرة، وتنتهي كل محظورات الإحرام.","steps":["اخرج من المسعى بعد انتهاء الشوط السابع.","الرجال: احلقوا الرأس، أو قصِّروا شعر الرأس كله.","النساء: اقصصن قدر أنملة من طرف الشعر، في مكان مستور.","لقد تحلَّلت الآن من الإحرام: تمَّت عمرتك."],"duas":[]},{"id":"after","title":"بعد العمرة","body":"انتهت عمرتك: فاشكر الله الذي بلَّغك بيته. وكل ما كان الإحرام قد حظره عاد مباحًا، ولك أن تلبس ثيابك المعتادة.\n\nوأحسِن استغلال أيامك الباقية في مكة. صلِّ الصلوات الخمس في المسجد الحرام ما استطعت، وطُف تطوعًا حين لا يكون الزحام شديدًا، واقرأ القرآن، وادعُ لنفسك ولأهلك ولجميع المسلمين. وكن رفيقًا بغيرك من الحجاج، صبورًا على التعب والزحام.\n\nوكثير من الحجاج يسافرون أيضًا إلى المدينة للصلاة في المسجد النبوي. وهذه الزيارة عمل مبارك في نفسه، لكنها ليست جزءًا من العمرة. وإذا رجعت إلى بلدك، فاجتهد في المحافظة على العادات الطيبة التي اكتسبتها هناك.","steps":["اشكر الله والبس ثيابك المعتادة من جديد.","صلِّ في المسجد الحرام ما استطعت.","طُف تطوعًا، واقرأ القرآن، وأكثِر من الدعاء.","حافظ على عادات الرحلة الطيبة بعد عودتك إلى بلدك."],"duas":[]}]},"hajj":{"title":"الحج يومًا بيوم","intro":"الحج هو الركن الخامس من أركان الإسلام. وهو واجب مرة في العمر على كل مسلم بالغ يستطيع السفر إليه (القرآن 3:97). وتؤدَّى مناسكه الرئيسية من اليوم 8 إلى اليوم 13 من ذي الحجة، بين مكة ومنى وعرفات ومزدلفة.\n\nوله ثلاث صفات. في التمتع، تؤدي عمرة كاملة في أشهر الحج، ثم تتحلَّل من الإحرام، ثم تُحرِم من جديد بالحج في اليوم 8. وفي القِران، تجمع بين العمرة والحج بإحرام واحد، من غير أن تتحلَّل بينهما. وفي الإفراد، تُحرِم بالحج وحده. ويجب الهدي في التمتع والقِران (القرآن 2:196)، ولا يجب في الإفراد. والثلاثة كلها صحيحة، والعلماء يختلفون في أيها أفضل، وأكثر الحجاج القادمين من بعيد يحجُّون متمتعين.\n\nهذا الدليل خلاصة موجزة. وهو لا يغني عن معلِّم مؤهَّل، ولا عن تعليمات الجهات المسؤولة في المكان وتعليمات حملتك، وهي التي تنظِّم التنقلات والمواعيد حفاظًا على سلامة الجميع. وحيث تختلف المذاهب الفقهية في تفصيل ما، نذكر ما عليه عمل أكثر الناس: فاسأل عالِمًا تثق به عن حالتك.","chapters":[{"id":"day-8-tarwiyah","title":"8 ذو الحجة: يوم التروية، في منى","body":"يبدأ الحج في اليوم 8 من ذي الحجة، ويسمى يوم التروية. فالحاج المتمتع يُحرِم من جديد، بالحج هذه المرة، من مكان إقامته في مكة: يغتسل، ويلبس ثياب الإحرام، وينوي، ثم يلبِّي. أما القارن والمفرِد فما زالا على إحرامهما منذ الميقات.\n\nثم يذهب الجميع إلى منى، وهي وادٍ من الخيام على بعد كيلومترات قليلة من مكة. وهناك تصلِّي الظهر والعصر والمغرب والعشاء ثم فجر اليوم 9، كل صلاة في وقتها، وتُقصر الصلوات الرباعية إلى ركعتين، من غير جمع.\n\nوهذا اليوم وهذه الليلة في منى سُنَّة ووقت استعداد. فاسترح، وردِّد التلبية، واقرأ القرآن، وهيِّئ قلبك للغد، أعظم أيام الحج.","steps":["المتمتع: اغتسل والبس الإحرام في مكان إقامتك في مكة.","انوِ الحج بقلبك وقل: لبيك اللهم حجًّا.","اذهب إلى منى مع حملتك، وأنت تردِّد التلبية.","صلِّ الظهر والعصر والمغرب والعشاء في منى، كل صلاة في وقتها، مع قصر الرباعية.","بِت في منى وصلِّ الفجر فيها."],"duas":[{"ar":"لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لاَ شَرِيكَ لَكَ","tr":"Labbayka Allahumma labbayk, labbayka la sharika laka labbayk, inna al-hamda wa an-ni'mata laka wa al-mulk, la sharika lak","t":"أجبتُ دعوتك يا الله مرة بعد مرة. أجبتُك، لا شريك لك، أجبتُك. الحمد كله والنعمة كلها لك، والمُلك كله لك. لا شريك لك.","source":"التلبية — صحيح البخاري 1549؛ صحيح مسلم 1184"}]},{"id":"day-9-arafat","title":"9 ذو الحجة: عرفات، ثم مزدلفة","body":"الوقوف بعرفة هو ركن الحج: فمن فاته فقد فاته الحج. وقد علَّم النبي محمد ﷺ أن الحج عرفة (جامع الترمذي 889).\n\nبعد شروق الشمس، اخرج من منى إلى عرفات، وتأكد من أنك داخل حدودها، وهي مبيَّنة باللوحات. وبعد الخطبة، تُصلَّى الظهر والعصر جمعًا وقصرًا، في وقت الظهر. ثم يأتي قلب الحج: من الظهيرة إلى غروب الشمس، استقبل القبلة وادعُ الله، واستغفره، وادعُ لمن تحب. وليس هناك نص لازم. ولا تخرج قبل الغروب.\n\nوبعد الغروب، اذهب بسكينة إلى مزدلفة. وهناك تصلِّي المغرب والعشاء جمعًا، مع قصر العشاء، ثم تستريح الليل في العراء. ولك أن تلتقط منها الحصى الصغار للرمي.","steps":["بعد شروق الشمس، اذهب من منى إلى عرفات، وأنت تردِّد التلبية.","تأكد من أنك داخل حدود عرفات.","صلِّ الظهر والعصر جمعًا وقصرًا في وقت الظهر.","اقضِ ما بعد الظهر في الدعاء والذكر والتوبة، مستقبلًا القبلة.","ابقَ في عرفات حتى تغرب الشمس تمامًا.","اذهب بسكينة إلى مزدلفة وصلِّ فيها المغرب والعشاء جمعًا.","التقط حصى صغارًا، بحجم حبة الحمص، ثم نَم.","صلِّ الفجر، وادعُ مستقبلًا القبلة، وانطلق إلى منى قبل شروق الشمس."],"duas":[]},{"id":"day-10-nahr","title":"10 ذو الحجة: يوم النحر","body":"اليوم 10 هو يوم العيد وأكثر أيام الحج أعمالًا. وتؤدَّى فيه أربعة أعمال، والأفضل أن تكون بهذا الترتيب. أولًا، في منى، ارمِ سبع حصيات واحدة بعد واحدة على جمرة العقبة، وهي الجمرة الكبرى، مكبِّرًا مع كل حصاة، وهنا تنقطع التلبية (صحيح البخاري 1685). ثانيًا، الهدي، وهو واجب في التمتع والقِران، وكثيرًا ما يُرتَّب عن طريق قسيمة رسمية. ثالثًا، يحلق الرجال أو يقصِّرون، وتقصُّ النساء قدر أنملة. رابعًا، في مكة، طواف الإفاضة، وهو ركن من أركان الحج، ويتبعه سعي الحج لمن بقي عليه.\n\nوبعد الرمي والحلق، تُرفع محظورات الإحرام، إلا المعاشرة الزوجية، فإنها تحلُّ بعد طواف الإفاضة. والمذاهب تختلف في التفاصيل: فاسأل عالِمًا تثق به عن حالتك.\n\nوإن تغيَّر الترتيب فلا حرج: فقد قال النبي محمد ﷺ ذلك لمن سألوه في ذلك اليوم (صحيح البخاري 83).","steps":["في منى، ارمِ سبع حصيات واحدة بعد واحدة على جمرة العقبة، قائلًا: الله أكبر، مع كل حصاة.","اقطع التلبية حين تبدأ الرمي.","اذبح الهدي، أو تأكد من أنه ذُبح عنك (في التمتع والقِران).","يحلق الرجال الرأس كله أو يقصِّرون شعره كله، وتقصُّ النساء قدر أنملة.","البس ثيابك المعتادة: فقد عاد كل شيء مباحًا إلا المعاشرة الزوجية.","اذهب إلى مكة لطواف الإفاضة، بلا اضطباع ولا رَمَل، وصلِّ ركعتين.","اسعَ سعي الحج إن كان ما زال عليك.","ارجع إلى منى لتبيت فيها."],"duas":[{"ar":"اللَّهُ أَكْبَرُ","tr":"Allahu akbar","t":"الله أعظم من كل شيء.","source":"التكبير مع كل حصاة — صحيح البخاري 1751"}]},{"id":"days-11-13-tashriq","title":"11-13 ذو الحجة: أيام التشريق","body":"تُقضى أيام التشريق في منى. وهي أيام ذكر لله (القرآن 2:203)، ويُبات فيها بمنى كذلك.\n\nوفي كل يوم، بعد الزوال، ترمي الجمرات الثلاث بالترتيب: الصغرى، ثم الوسطى، ثم جمرة العقبة، كل واحدة بسبع حصيات، مكبِّرًا مع كل رمية. وبعد الأولى وبعد الثانية، تنحَّ جانبًا، واستقبل القبلة، وادعُ طويلًا رافعًا يديك، وبعد الثالثة انصرف من غير وقوف (صحيح البخاري 1751).\n\nولك أن تخرج من منى في اليوم 12 بعد الرمي، قبل غروب الشمس، ومن بقي رمى مرة أخرى في اليوم 13. وكلاهما جائز (القرآن 2:203). واتبع الجدول الزمني المعطى لحملتك. وإن كنت ضعيفًا أو مريضًا، أو كان سؤالك عن الوقت المحدد للرمي، فاسأل عالِمًا تثق به عن حالتك.","steps":["بِت ليلتَي 11 و12 في منى.","في كل يوم بعد الزوال، خذ 21 حصاة إلى الجمرات.","ارمِ الجمرة الصغرى بسبع حصيات، ثم تنحَّ جانبًا وادعُ.","ارمِ الجمرة الوسطى بسبع حصيات، ثم تنحَّ جانبًا وادعُ.","ارمِ جمرة العقبة بسبع حصيات وانصرف من غير وقوف.","في اليوم 12، اخرج من منى قبل غروب الشمس إن أردت التعجُّل.","وإلا فبِت فيها وارمِ الجمرات الثلاث مرة أخرى في اليوم 13."],"duas":[]},{"id":"farewell-tawaf","title":"طواف الوداع","body":"إذا انتهت المناسك كلها وأوشكت أن تغادر مكة، فآخر ما تفعله طواف الوداع. فقد أُمر الناس أن يكون آخر عهدهم بالبيت، ولم يُعفَ من ذلك إلا المرأة الحائض (صحيح البخاري 1755؛ صحيح مسلم 1328).\n\nوهو طواف عادي من سبعة أشواط بالثياب المعتادة، بلا اضطباع ولا رَمَل، تتبعه ركعتان. ولا سعي بعده. وأدِّه حين تكون أمتعتك جاهزة وسفرك قريبًا، ولا يضرُّ انتظار قصير لوسيلة النقل أو للرفقة.\n\nواخرج من المسجد الحرام بقلب شاكر. واسأل الله أن يتقبل حجك، وأن يغفر لك، وأن يكتب لك العودة. ثم اجتهد أن ترجع إلى بلدك إنسانًا أفضل من الذي خرج منه.","steps":["أتمَّ كل مناسكك وجهِّز أمتعتك أولًا.","طُف سبعة أشواط حول الكعبة بالثياب المعتادة.","صلِّ ركعتين بعد الطواف.","ادعُ الله أن يتقبل حجك، ثم غادر مكة من غير تأخير.","المرأة الحائض تغادر من غير هذا الطواف."],"duas":[]}]},"mistakes":[{"title":"المزاحمة لتقبيل الحجر الأسود","body":"تقبيل الحجر الأسود سُنَّة، وإيذاء المسلم حرام. فإن اشتد الزحام، فاكتفِ بالإشارة إلى الحجر وكبِّر: طوافك تام، ولم يتأذَّ أحد."},{"title":"اعتقاد أن لكل شوط دعاء خاصًّا لازمًا","body":"بعض الكتيِّبات تذكر دعاء لكل شوط. ولا يلزم شيء من ذلك: فليس لأشواط الطواف ولا لأشواط السعي دعاء محدد واجب. خاطِب الله بكلماتك أنت، وبلغتك أنت."},{"title":"الخروج من عرفات قبل الغروب","body":"بقي النبي محمد ﷺ في عرفات حتى غربت الشمس (صحيح مسلم 1218). فلا تتعجَّل إلى الحافلات في آخر العصر: فهذه أثمن ساعات الحج كله."},{"title":"صعود جبل الرحمة ظنًّا أنه لازم","body":"صعيد عرفات كله موقف. وصعود الجبل ليس من الحج ولا يزيد في الأجر، والتدافع هناك متعب وخطير. فابقَ حيث تستطيع أن تدعو في طمأنينة."},{"title":"الوقوف خارج حدود عرفات","body":"بعض الحجاج ينزلون خارج عرفات بقليل وهم لا يشعرون. ولأن الوقوف هو ركن الحج، فابحث عن لوحات الحدود، واسأل مرشدك إن كان عندك أدنى شك."},{"title":"التقاط حصى أكبر مما ينبغي","body":"الحصى صغار، بحجم حبة الحمص تقريبًا. أما الحجارة الكبيرة والأحذية وغيرها من الأشياء فليست من النُّسُك، وقد تصيب الناس بالأذى. والرمي طاعة لله تؤدَّى بسكينة، لا انفجار غضب."},{"title":"التصوير بدل العبادة","body":"صورة للذكرى تأخذ ثواني قليلة، أما تصوير الطواف كله أو البث المباشر من عرفات فيصرف قلبك عن العبادة. فضع الهاتف جانبًا في أثناء المناسك، واحفظ إخلاص نيَّتك."},{"title":"إهمال الميقات عند السفر بالطائرة","body":"تعبر الطائرة الميقات في الجو. فالبس ثياب الإحرام قبل الصعود إلى الطائرة أو في أول الرحلة، وانوِ حين يُعلن عن الميقات، أو قبله بقليل. وإن تجاوزته غير مُحرِم، فاسأل عالِمًا تثق به عن حالتك."},{"title":"إبقاء الكتف الأيمن مكشوفًا طوال الوقت","body":"الاضطباع خاص بالرجال، وفي طواف القدوم وحده. وقبله وبعده، ومن ذلك وقت الصلاة والسعي، يُغطَّى الكتفان كلاهما."},{"title":"عدُّ الذهاب والرجوع شوطًا واحدًا في السعي","body":"من الصفا إلى المروة شوط، ومن المروة إلى الصفا شوط آخر. والسعي سبعة أشواط وينتهي عند المروة. وعدُّ كل ذهاب ورجوع شوطًا واحدًا معناه أن تمشي أربعة عشر شوطًا."},{"title":"الإصرار على الصلاة خلف مقام إبراهيم مباشرة","body":"الصلاة في طريق الطائفين تعطِّلهم وتعرِّضك للخطر. فإذا اشتد الزحام، جاز أن تُصلَّى الركعتان في أي مكان من المسجد."},{"title":"الجدال وفقدان الصبر","body":"الحر والطوابير والتعب امتحان للجميع. والقرآن ينهى عن الرفث والفسوق والجدال في الحج (2:197). فأفسِح لغيرك، وابتسم، واعفُ: فحسن الخلق جزء من حجك."}],"checklist":[{"id":"passport","group":"documents","label":"جواز سفر صالح لستة أشهر على الأقل"},{"id":"visa-permit","group":"documents","label":"تأشيرة الحج أو العمرة والتصريح الرسمي"},{"id":"tickets-bookings","group":"documents","label":"تذاكر الطيران وحجوزات السكن"},{"id":"id-copies","group":"documents","label":"نسخ ورقية ورقمية من جميع الوثائق"},{"id":"emergency-contacts","group":"documents","label":"بطاقة فيها أرقام حملتك وفندقك وأرقام الطوارئ"},{"id":"money-card","group":"documents","label":"شيء من النقود المحلية وبطاقة مصرفية"},{"id":"ihram-garments","group":"clothing","label":"الرجال: طقمان من ثياب الإحرام"},{"id":"modest-clothing","group":"clothing","label":"النساء: ثياب واسعة محتشمة مريحة"},{"id":"sandals","group":"clothing","label":"نعال مريحة سبق لك لبسها"},{"id":"ihram-belt","group":"clothing","label":"حزام الإحرام أو كيس للنقود والأوراق"},{"id":"small-bag","group":"clothing","label":"كيس صغير للحذاء والحصى"},{"id":"umbrella","group":"clothing","label":"مظلة فاتحة اللون تقي من الشمس"},{"id":"vaccinations","group":"health","label":"اللقاحات المطلوبة وشهادتها"},{"id":"medication","group":"health","label":"أدويتك المعتادة مع الوصفة الطبية"},{"id":"unscented-toiletries","group":"health","label":"صابون وأدوات نظافة غير معطَّرة للإحرام"},{"id":"water-bottle","group":"health","label":"قارورة ماء قابلة لإعادة الاستعمال"},{"id":"masks-sanitizer","group":"health","label":"كمامات ومعقِّم يدين غير معطَّر"},{"id":"first-aid","group":"health","label":"حقيبة إسعافات أولية صغيرة فيها لصقات لتقرُّحات القدم"},{"id":"sincere-intention","group":"spiritual","label":"جدِّد نيَّتك: لله وحده"},{"id":"repentance-debts","group":"spiritual","label":"تُب، وسدِّد الديون، واطلب السماح"},{"id":"learn-rites","group":"spiritual","label":"تعلَّم المناسك وترتيبها"},{"id":"talbiyah-memorised","group":"spiritual","label":"احفظ التلبية"},{"id":"dua-list","group":"spiritual","label":"اكتب قائمة بأدعيتك الخاصة ليوم عرفات"},{"id":"quran-dhikr","group":"spiritual","label":"مصحف جيب أو تطبيق للقراءة والذكر"}]}$tk$::jsonb)
  on conflict (kind, lang) do update set payload = excluded.payload, updated_at = now();
insert into public.premium_content (kind, lang, payload) values ('quiz', 'ar', $tk$[{"id":"q001","cat":"prophets","q":"بحسب القرآن الكريم، من هو أول إنسان خلقه الله؟","options":["نوح","آدم","إبراهيم","إدريس"],"answer":1,"explain":"آدم عليه السلام هو أول إنسان وأبو البشر. ويذكر القرآن خلقه في 2:30-37."},{"id":"q002","cat":"prophets","q":"أي نبي عليه السلام صنع السفينة بأمر الله؟","options":["موسى","يونس","نوح","هود"],"answer":2,"explain":"أُمر نوح عليه السلام بصنع السفينة قبل الطوفان، كما جاء في القرآن (11:37)."},{"id":"q003","cat":"prophets","q":"أي نبي عليه السلام ابتلعه حوت عظيم؟","options":["أيوب","يوسف","إلياس","يونس"],"answer":3,"explain":"ابتلع الحوت يونس عليه السلام، فدعا الله في الظلمات فنجَّاه (37:139-144)."},{"id":"q004","cat":"prophets","q":"أي الأبناء أعان إبراهيم عليه السلام على رفع قواعد الكعبة؟","options":["إسحاق","يعقوب","إسماعيل","لوط"],"answer":2,"explain":"يذكر القرآن أن إبراهيم وإسماعيل عليهما السلام رفعا قواعد البيت معًا (2:127)."},{"id":"q005","cat":"prophets","q":"أي نبي عليه السلام ألقاه إخوته في البئر وهو صغير؟","options":["يحيى","يوسف","هارون","داود"],"answer":1,"explain":"ألقى يوسفَ عليه السلام في البئر إخوتُه الذين حسدوه. وقصته تملأ سورة يوسف، وهي السورة 12 (12:15)."},{"id":"q006","cat":"prophets","q":"على أي نبي عليه السلام أُنزلت التوراة؟","options":["عيسى","داود","إبراهيم","موسى"],"answer":3,"explain":"أُوتي التوراةَ موسى عليه السلام، الذي خرج ببني إسرائيل من مصر."},{"id":"q007","cat":"prophets","q":"أي نبي عليه السلام أُوتي الزبور؟","options":["داود","سليمان","موسى","زكريا"],"answer":0,"explain":"يذكر القرآن أن الله آتى داود عليه السلام الزبور (4:163 و17:55)."},{"id":"q008","cat":"prophets","q":"أي نبي عليه السلام أُوتي الإنجيل؟","options":["عيسى","يحيى","موسى","يونس"],"answer":0,"explain":"أُوتي الإنجيلَ عيسى ابن مريم عليهما السلام، كما جاء في القرآن في 5:46."},{"id":"q009","cat":"prophets","q":"أي نبي كان أخا موسى عليه السلام وأعانه في رسالته؟","options":["يوشع","شعيب","إلياس","هارون"],"answer":3,"explain":"سأل موسى ربه أن يجعل أخاه هارون معينًا له (20:29-32). عليهما السلام."},{"id":"q010","cat":"prophets","q":"أي نبي عليه السلام، ابتُلي ببلاء طويل، اشتهر بصبره وبدعائه ربه بأنه «أرحم الراحمين»؟","options":["أيوب","هارون","لوط","صالح"],"answer":0,"explain":"صبر أيوب عليه السلام على بلائه ودعا ربه، فكشف عنه ما به (21:83-84)."},{"id":"q011","cat":"prophets","q":"أي نبي عليه السلام أُرسل إلى قوم عاد؟","options":["صالح","شعيب","هود","لوط"],"answer":2,"explain":"أُرسل هود عليه السلام إلى قوم عاد يدعوهم إلى عبادة الله وحده (7:65)."},{"id":"q012","cat":"prophets","q":"الناقة التي جُعلت آية لقوم ثمود مرتبطة بأي نبي عليه السلام؟","options":["هود","صالح","نوح","يونس"],"answer":1,"explain":"أُرسل صالح عليه السلام إلى ثمود، وكانت الناقة آية لهم من الله (7:73)."},{"id":"q013","cat":"prophets","q":"أي نبي عليه السلام ألقاه قومه في النار فجعلها الله بردًا وسلامًا عليه؟","options":["موسى","إبراهيم","يحيى","هود"],"answer":1,"explain":"لما ألقى القوم إبراهيم عليه السلام في النار، أمرها الله أن تكون بردًا وسلامًا عليه (21:68-69)."},{"id":"q014","cat":"prophets","q":"بحسب القرآن الكريم، أي نبي عليه السلام فهم كلام نملة تحذِّر سائر النمل؟","options":["يونس","عيسى","سليمان","يوسف"],"answer":2,"explain":"سمع سليمان عليه السلام نملة تحذِّر النمل حين اقترب جيشه، فتبسَّم وشكر الله (27:18-19)."},{"id":"q015","cat":"prophets","q":"أي نبي عليه السلام كان والد يحيى؟","options":["عمران","يعقوب","أيوب","زكريا"],"answer":3,"explain":"دعا زكريا عليه السلام ربه أن يرزقه ولدًا وهو شيخ كبير، فبُشِّر بيحيى (19:7)."},{"id":"q016","cat":"seerah","q":"في أي مدينة وُلد النبي محمد ﷺ؟","options":["المدينة المنورة","مكة المكرمة","الطائف","القدس"],"answer":1,"explain":"وُلد النبي محمد ﷺ في مكة، في قبيلة قريش."},{"id":"q017","cat":"seerah","q":"أين نزل الوحي أول مرة على النبي محمد ﷺ؟","options":["في غار ثور","في غار حراء","على جبل أُحد","في صعيد عرفات"],"answer":1,"explain":"نزل الوحي أول مرة في غار حراء، في جبل النور قرب مكة، حيث كان يخلو بنفسه."},{"id":"q018","cat":"seerah","q":"أي ملَك نزل بالوحي على النبي محمد ﷺ؟","options":["ميكائيل","جبريل","إسرافيل","مالك"],"answer":1,"explain":"نزل الملَك جبريل عليه السلام بالقرآن على النبي محمد ﷺ."},{"id":"q019","cat":"seerah","q":"ما أول كلمة من القرآن نزلت على النبي محمد ﷺ؟","options":["قُل","قُم","اقرأ","سبِّح"],"answer":2,"explain":"يبدأ أول ما نزل من الوحي بكلمة «اقرأ»، وهي أمر بالقراءة والتلاوة (96:1)."},{"id":"q020","cat":"seerah","q":"من هي أولى زوجات النبي محمد ﷺ؟","options":["خديجة بنت خويلد","عائشة بنت أبي بكر","حفصة بنت عمر","سودة بنت زمعة"],"answer":0,"explain":"خديجة رضي الله عنها، وكانت تاجرة ذات مكانة في مكة، هي أولى زوجاته. ولم يتزوج عليها امرأة أخرى في حياتها."},{"id":"q021","cat":"seerah","q":"في أي سنة ميلادية كانت الهجرة من مكة إلى المدينة؟","options":["622","570","610","632"],"answer":0,"explain":"كانت الهجرة سنة 622م. وصارت تلك السنة لاحقًا السنة الأولى في التقويم الهجري."},{"id":"q022","cat":"seerah","q":"ماذا كانت المدينة المنورة تسمى قبل الهجرة؟","options":["خيبر","تبوك","الطائف","يثرب"],"answer":3,"explain":"كانت تسمى يثرب. وبعد أن استقر فيها النبي محمد ﷺ عُرفت باسم «المدينة»."},{"id":"q023","cat":"seerah","q":"في أي غار اختبأ النبي محمد ﷺ في أثناء الهجرة؟","options":["غار ثور","غار حراء","غار في جبل أُحد","غار في جبل الصفا"],"answer":0,"explain":"اختبأ في غار ثور مع صاحبه أبي بكر رضي الله عنه وقريش تبحث عنهما. ويذكر القرآن هذا الموقف في 9:40."},{"id":"q024","cat":"seerah","q":"في أي سنة من الهجرة وقعت غزوة بدر؟","options":["السنة الثانية","السنة الأولى","السنة الخامسة","السنة الثامنة"],"answer":0,"explain":"وقعت غزوة بدر في رمضان من السنة الثانية للهجرة. وكانت أول معركة كبرى للمسلمين."},{"id":"q025","cat":"seerah","q":"ما اسم الجد الذي كفل النبي محمدًا ﷺ بعد وفاة أمه؟","options":["أبو لهب","أبو سفيان","عبد المطلب","ورقة بن نوفل"],"answer":2,"explain":"كفله جده عبد المطلب، وكان من سادة مكة. وبعد وفاة الجد ضمَّه إليه عمه أبو طالب."},{"id":"q026","cat":"seerah","q":"ما اسم أم النبي محمد ﷺ؟","options":["حليمة السعدية","فاطمة بنت أسد","أم أيمن","آمنة بنت وهب"],"answer":3,"explain":"أمه هي آمنة بنت وهب. وقد توفيت وهو ما زال طفلًا صغيرًا. أما حليمة السعدية فكانت مرضعته."},{"id":"q027","cat":"seerah","q":"إلى أي قبيلة ينتمي النبي محمد ﷺ؟","options":["الأوس","الخزرج","ثقيف","قريش"],"answer":3,"explain":"كان من قريش، قبيلة مكة، من بني هاشم."},{"id":"q028","cat":"seerah","q":"ما اسم الهدنة التي عُقدت بين المسلمين وقريش في السنة السادسة للهجرة؟","options":["بيعة العقبة","صحيفة المدينة","صلح الحديبية","حلف الفضول"],"answer":2,"explain":"عُقد صلح الحديبية في السنة السادسة للهجرة قرب مكة. وجاءت بعده فترة سلام انتشر فيها الإسلام انتشارًا واسعًا."},{"id":"q029","cat":"seerah","q":"في أي سنة من الهجرة كان فتح مكة؟","options":["السنة الثانية","السنة الرابعة","السنة الثامنة","السنة السادسة"],"answer":2,"explain":"دخل المسلمون مكة في السنة الثامنة للهجرة (630م). وعفا النبي محمد ﷺ عن أهلها."},{"id":"q030","cat":"seerah","q":"قبل النبوة، بأي لقب كان أهل مكة يلقِّبون النبي محمدًا ﷺ؟","options":["الحكيم","الكريم","الشجاع","الأمين"],"answer":3,"explain":"كان يُعرف بالأمين لصدقه وأمانته. وكان الناس يودعون عنده نفائسهم."},{"id":"q031","cat":"companions","q":"من هو أول مؤذن في الإسلام؟","options":["سلمان الفارسي","أنس بن مالك","بلال بن رباح","زيد بن حارثة"],"answer":2,"explain":"بلال بن رباح رضي الله عنه، وهو عبد مُعتَق من أصل حبشي، اختاره النبي محمد ﷺ ليرفع الأذان."},{"id":"q032","cat":"companions","q":"أي صحابي رافق النبي محمدًا ﷺ في الهجرة؟","options":["بلال بن رباح","مصعب بن عمير","خالد بن الوليد","أبو بكر الصديق"],"answer":3,"explain":"كان أبو بكر رضي الله عنه صاحبه في الرحلة من مكة إلى المدينة، وكان معه في غار ثور."},{"id":"q033","cat":"companions","q":"أي صحابي أشار بحفر خندق للدفاع عن المدينة؟","options":["بلال بن رباح","أبو أيوب الأنصاري","سلمان الفارسي","مصعب بن عمير"],"answer":2,"explain":"سلمان الفارسي رضي الله عنه، القادم من بلاد فارس، هو الذي أشار بالخندق. ولذلك تسمى غزوة السنة الخامسة للهجرة غزوة الخندق."},{"id":"q034","cat":"companions","q":"أي صحابي يُعرف بلقب «سيف الله»؟","options":["خالد بن الوليد","بلال بن رباح","زيد بن ثابت","أنس بن مالك"],"answer":0,"explain":"خالد بن الوليد رضي الله عنه، القائد المشهور، يُعرف بسيف الله."},{"id":"q035","cat":"companions","q":"من هو أول من آمن برسالة النبي محمد ﷺ؟","options":["عمر بن الخطاب","خديجة بنت خويلد","خالد بن الوليد","أبو سفيان"],"answer":1,"explain":"كانت زوجته خديجة رضي الله عنها أول من آمن به. وقد واسته وآزرته منذ أول نزول الوحي."},{"id":"q036","cat":"companions","q":"في عهد أي خليفة اعتُمد التقويم الهجري، وجُعلت سنة الهجرة بدايته؟","options":["عمر بن الخطاب","هارون الرشيد","عبد الملك بن مروان","عمر بن عبد العزيز"],"answer":0,"explain":"وُضع التقويم الهجري في خلافة عمر بن الخطاب رضي الله عنه، بعد وفاة النبي محمد ﷺ ببضع سنين."},{"id":"q037","cat":"companions","q":"أي صحابي من كُتَّاب الوحي كُلِّف بجمع القرآن في مجموع واحد مكتوب؟","options":["بلال بن رباح","خالد بن الوليد","سلمان الفارسي","زيد بن ثابت"],"answer":3,"explain":"زيد بن ثابت رضي الله عنه، أحد كُتَّاب النبي محمد ﷺ، جمع القرآن المكتوب في مجموع واحد في خلافة أبي بكر رضي الله عنه."},{"id":"q038","cat":"companions","q":"أي صحابي أُرسل إلى يثرب قبل الهجرة ليعلِّم أهلها الإسلام؟","options":["مصعب بن عمير","خالد بن الوليد","أنس بن مالك","أبو أيوب الأنصاري"],"answer":0,"explain":"أُرسل مصعب بن عمير رضي الله عنه إلى يثرب بعد بيعة العقبة الأولى. وأسلم على يديه كثير من أهلها."},{"id":"q039","cat":"companions","q":"في أي غزوة استُشهد حمزة، عم النبي محمد ﷺ؟","options":["بدر","الخندق","حنين","أُحد"],"answer":3,"explain":"استُشهد حمزة بن عبد المطلب رضي الله عنه في غزوة أُحد، في السنة الثالثة للهجرة."},{"id":"q040","cat":"companions","q":"من يُذكر على أنه أول شهيد في الإسلام؟","options":["أم أيمن","سمية بنت خياط","حليمة السعدية","أم سلمة"],"answer":1,"explain":"سمية بنت خياط رضي الله عنها، أم عمار بن ياسر، قُتلت في مكة لأنها أبت أن تترك دينها."},{"id":"q041","cat":"companions","q":"أي صحابي تكلَّم باسم المهاجرين المسلمين أمام النجاشي ملك الحبشة؟","options":["بلال بن رباح","جعفر بن أبي طالب","زيد بن ثابت","أنس بن مالك"],"answer":1,"explain":"شرح جعفر بن أبي طالب رضي الله عنه الإسلام للنجاشي، فترك المسلمين يعيشون آمنين في بلاده."},{"id":"q042","cat":"companions","q":"أي بنات النبي محمد ﷺ تزوجت علي بن أبي طالب؟","options":["فاطمة","زينب","رقية","أم كلثوم"],"answer":0,"explain":"تزوجت فاطمة عليَّ بن أبي طالب في المدينة، رضي الله عنهما. وهما والدا الحسن والحسين."},{"id":"q043","cat":"companions","q":"بأي اسم يُعرف أهل المدينة الذين استقبلوا المهاجرين القادمين من مكة ونصروهم؟","options":["المهاجرون","قريش","التابعون","الأنصار"],"answer":3,"explain":"يسمى مسلمو المدينة الأنصار. أما الذين هاجروا من مكة فيسمَّون المهاجرين."},{"id":"q044","cat":"companions","q":"من نام في فراش النبي محمد ﷺ ليلة خروجه من مكة مهاجرًا؟","options":["زيد بن حارثة","بلال بن رباح","علي بن أبي طالب","أنس بن مالك"],"answer":2,"explain":"نام الفتى علي بن أبي طالب رضي الله عنه مكانه في الفراش تلك الليلة، وبقي بعده ليردَّ الأمانات التي كان الناس قد أودعوها عنده."},{"id":"q045","cat":"companions","q":"في بيت من أقام النبي محمد ﷺ في المدينة ريثما يُبنى مسجده؟","options":["سلمان الفارسي","أبو أيوب الأنصاري","خالد بن الوليد","مصعب بن عمير"],"answer":1,"explain":"نزل في بيت أبي أيوب الأنصاري رضي الله عنه حتى بُني مسجده وحُجُراته."},{"id":"q046","cat":"quran","q":"كم عدد سور القرآن الكريم؟","options":["114","99","110","120"],"answer":0,"explain":"في القرآن 114 سورة، من الفاتحة إلى الناس."},{"id":"q047","cat":"quran","q":"ما أطول سورة في القرآن؟","options":["آل عمران","النساء","يس","البقرة"],"answer":3,"explain":"البقرة، وهي السورة 2، أطول سور القرآن."},{"id":"q048","cat":"quran","q":"ما أقصر سورة في القرآن؟","options":["الإخلاص","الكوثر","الفلق","الفاتحة"],"answer":1,"explain":"الكوثر، وهي السورة 108، أقصر السور: فليس فيها إلا ثلاث آيات قصار."},{"id":"q049","cat":"quran","q":"بأي سورة يُفتتح القرآن؟","options":["البقرة","الإخلاص","الفاتحة","العلق"],"answer":2,"explain":"الفاتحة هي أول سور القرآن، وتُقرأ في كل صلاة."},{"id":"q050","cat":"quran","q":"ما السورة التي تأتي آخرًا في المصحف؟","options":["الفلق","الإخلاص","الناس","النصر"],"answer":2,"explain":"الناس، وهي السورة 114، تختم القرآن."},{"id":"q051","cat":"quran","q":"إلى كم جزء يُقسم القرآن؟","options":["7","30","60","114"],"answer":1,"explain":"يُقسم القرآن إلى 30 جزءًا، وهذا ييسِّر قراءته كله في شهر واحد."},{"id":"q052","cat":"quran","q":"في أي شهر بدأ نزول القرآن؟","options":["رمضان","رجب","المحرَّم","ذو الحجة"],"answer":0,"explain":"يذكر القرآن أنه أُنزل في شهر رمضان (2:185)."},{"id":"q053","cat":"quran","q":"في أي سورة توجد آية الكرسي؟","options":["آل عمران","البقرة","الكهف","الملك"],"answer":1,"explain":"آية الكرسي هي الآية 255 من سورة البقرة (2:255)."},{"id":"q054","cat":"quran","q":"ما السورة الوحيدة التي لا تبدأ بالبسملة؟","options":["التوبة","الأنفال","يونس","الملك"],"answer":0,"explain":"التوبة، وهي السورة 9، هي السورة الوحيدة التي لا تُفتتح بالبسملة، أي «بسم الله الرحمن الرحيم»."},{"id":"q055","cat":"quran","q":"في أي سورة ترد البسملة مرتين؟","options":["النحل","العنكبوت","سبأ","النمل"],"answer":3,"explain":"في سورة النمل ترد البسملة في أولها، ثم ترد مرة أخرى في كتاب سليمان عليه السلام (27:30)."},{"id":"q056","cat":"quran","q":"أي سورة من القرآن تحمل اسم أم عيسى عليه السلام؟","options":["النساء","مريم","آل عمران","النور"],"answer":1,"explain":"السورة 19 سُمِّيت باسم مريم، أم عيسى عليهما السلام. وهي المرأة الوحيدة المذكورة باسمها في القرآن."},{"id":"q057","cat":"quran","q":"في كم سنة تقريبًا نزل القرآن؟","options":["نحو 23 سنة","نحو 3 سنوات","نحو 10 سنوات","نحو 40 سنة"],"answer":0,"explain":"نزل القرآن شيئًا فشيئًا في نحو 23 سنة، في مكة أولًا ثم في المدينة."},{"id":"q058","cat":"quran","q":"كم عدد آيات سورة الفاتحة؟","options":["3","5","10","7"],"answer":3,"explain":"في الفاتحة سبع آيات. وتُقرأ في كل ركعة من الصلاة."},{"id":"q059","cat":"quran","q":"ماذا تسمى السور التي نزلت قبل الهجرة؟","options":["المدنية","المحكَم","المكية","المفصَّل"],"answer":2,"explain":"السور التي نزلت قبل الهجرة تسمى مكية، والتي نزلت بعدها تسمى مدنية."},{"id":"q060","cat":"quran","q":"ما أطول آية في القرآن؟","options":["آية الكرسي (2:255)","آية النور (24:35)","آية الدَّين (2:282)","الآية الأولى من الفاتحة"],"answer":2,"explain":"أطول آية هي الآية 282 من سورة البقرة. وهي تعلِّم الناس أن يكتبوا ديونهم وأن يُشهدوا عليها."},{"id":"q061","cat":"history","q":"أي مدينة كانت عاصمة الخلافة الأموية؟","options":["بغداد","دمشق","القاهرة","المدينة المنورة"],"answer":1,"explain":"حكم الأمويون من دمشق، في الشام، من سنة 661م إلى سنة 750م."},{"id":"q062","cat":"history","q":"أي خليفة عباسي أسس مدينة بغداد سنة 762م؟","options":["هارون الرشيد","المنصور","المأمون","المعتصم"],"answer":1,"explain":"أسس الخليفة المنصور بغداد سنة 762م على ضفاف دجلة. وصارت من أعظم مدن العالم."},{"id":"q063","cat":"history","q":"من استولى على بغداد ودمَّرها سنة 1258م؟","options":["المغول","الصليبيون","السلاجقة","العثمانيون"],"answer":0,"explain":"استولى جيش المغول بقيادة هولاكو على بغداد سنة 1258م، وبذلك انتهت الخلافة العباسية في بغداد."},{"id":"q064","cat":"history","q":"أي سلطان عثماني فتح القسطنطينية سنة 1453م؟","options":["محمد الثاني","سليمان القانوني","سليم الأول","عثمان الأول"],"answer":0,"explain":"محمد الثاني، المعروف بالفاتح، فتح القسطنطينية سنة 1453م. وصارت المدينة عاصمة العثمانيين، إسطنبول."},{"id":"q065","cat":"history","q":"من قاد الجيش الإسلامي الذي عبر من شمال إفريقيا إلى شبه الجزيرة الإيبيرية سنة 711م؟","options":["عقبة بن نافع","خالد بن الوليد","صلاح الدين الأيوبي","طارق بن زياد"],"answer":3,"explain":"عبر طارق بن زياد المضيق سنة 711م. والصخرة المعروفة بجبل طارق تحمل اسمه."},{"id":"q066","cat":"history","q":"من استردَّ القدس من الصليبيين سنة 1187م؟","options":["بيبرس","نور الدين زنكي","صلاح الدين الأيوبي","محمد الثاني"],"answer":2,"explain":"استردَّ صلاح الدين الأيوبي القدس سنة 1187م، بعد انتصاره في معركة حطين."},{"id":"q067","cat":"history","q":"أي مدينة، وهي آخر مملكة إسلامية في الأندلس، سقطت سنة 1492م؟","options":["قرطبة","غرناطة","إشبيلية","طليطلة"],"answer":1,"explain":"سقطت مملكة غرناطة، مملكة بني نصر، سنة 1492م، وانتهت بذلك نحو ثمانية قرون من الحكم الإسلامي في أجزاء من شبه الجزيرة الإيبيرية."},{"id":"q068","cat":"history","q":"من هزم المغول في معركة عين جالوت سنة 1260م؟","options":["مماليك مصر","العثمانيون","السلاجقة","الموحِّدون"],"answer":0,"explain":"أوقف مماليك مصر زحف المغول في عين جالوت، في فلسطين، سنة 1260م."},{"id":"q069","cat":"history","q":"أي دولة تولَّت الخلافة سنة 750م ثم اتخذت بغداد عاصمة لها؟","options":["العثمانيون","المماليك","المرابطون","العباسيون"],"answer":3,"explain":"خلف العباسيون الأمويين سنة 750م، وأسسوا بغداد سنة 762م."},{"id":"q070","cat":"history","q":"أي أمير أموي فرَّ إلى الأندلس وأسس إمارة قرطبة سنة 756م؟","options":["طارق بن زياد","هارون الرشيد","صلاح الدين الأيوبي","عبد الرحمن الداخل"],"answer":3,"explain":"عبد الرحمن الأول، المعروف بالداخل، وهو من الناجين من البيت الأموي، بلغ الأندلس وأسس إمارة قرطبة سنة 756م."},{"id":"q071","cat":"history","q":"تأخذ الدولة العثمانية اسمها من مؤسسها. فمن هو؟","options":["محمد الثاني","تيمورلنك","ألب أرسلان","عثمان الأول"],"answer":3,"explain":"أسس عثمان الأول الدولة العثمانية في الأناضول نحو سنة 1300م. ومن اسمه جاءت تسمية «العثمانيين»."},{"id":"q072","cat":"history","q":"من أسس الدولة المغولية في الهند سنة 1526م؟","options":["أكبر","شاه جهان","بابر","أورنكزيب"],"answer":2,"explain":"أسس بابر الدولة المغولية في الهند بعد انتصاره في معركة باني بت سنة 1526م."},{"id":"q073","cat":"history","q":"أي سلطان عثماني من القرن السادس عشر الميلادي يُعرف بلقبَي «العظيم» و«القانوني»؟","options":["محمد الثاني","سليمان الأول","عثمان الأول","عبد الحميد الثاني"],"answer":1,"explain":"حكم سليمان الأول من سنة 1520م إلى سنة 1566م، حين كانت الدولة العثمانية في أوج قوتها. ويلقَّب بالقانوني، أي واضع القوانين."},{"id":"q074","cat":"history","q":"منسا موسى، المشهور بحجِّه إلى مكة سنة 1324م، حكم أي إمبراطورية؟","options":["إمبراطورية سونغاي","إمبراطورية غانا","إمبراطورية مالي","إمبراطورية كانم"],"answer":2,"explain":"حكم منسا موسى إمبراطورية مالي في غرب إفريقيا. وقد جعل حجُّه سنة 1324م ثراء مالي مشهورًا في الآفاق."},{"id":"q075","cat":"history","q":"أي سلطان سلجوقي انتصر على البيزنطيين في معركة ملاذكرد سنة 1071م؟","options":["صلاح الدين الأيوبي","بيبرس","ألب أرسلان","عثمان الأول"],"answer":2,"explain":"هزم ألب أرسلان الجيش البيزنطي في ملاذكرد سنة 1071م، ففُتحت أبواب الأناضول أمام الأتراك."},{"id":"q076","cat":"sciences","q":"أي فرع من الرياضيات أخذ اسمه في لغات العالم من عنوان كتاب للخوارزمي؟","options":["الهندسة","الجبر","حساب المثلثات","الحساب"],"answer":1,"explain":"اسم علم الجبر في اللغات الأخرى مأخوذ من كلمة «الجبر» الواردة في عنوان الكتاب الذي ألَّفه الخوارزمي في بغداد في القرن التاسع الميلادي."},{"id":"q077","cat":"sciences","q":"كلمة «ألغوريتم» المستعملة في اللغات الأوروبية مأخوذة من الصيغة اللاتينية لاسم أي عالِم؟","options":["الخوارزمي","الكندي","البيروني","البتَّاني"],"answer":0,"explain":"كلمة «ألغوريتم» مأخوذة من «ألغوريتمي»، وهي الصيغة اللاتينية لاسم الرياضي الخوارزمي."},{"id":"q078","cat":"sciences","q":"من مؤلف كتاب «القانون في الطب»؟","options":["الرازي","الزهراوي","ابن سينا","ابن النفيس"],"answer":2,"explain":"ألَّف ابن سينا القانون في الطب في القرن الحادي عشر الميلادي. وظل يُستعمل في تعليم الطب قرونًا، في العالم الإسلامي وفي أوروبا."},{"id":"q079","cat":"sciences","q":"أي عالِم ألَّف «كتاب المناظر» وبيَّن أننا نرى لأن الضوء يدخل العين؟","options":["الخوارزمي","ابن الهيثم","ابن خلدون","الإدريسي"],"answer":1,"explain":"ابن الهيثم، الذي عاش في القرنين العاشر والحادي عشر الميلاديين، ألَّف كتاب المناظر واعتمد على تجارب دقيقة."},{"id":"q080","cat":"sciences","q":"العالِم الأندلسي الزهراوي مشهور بأنه رائد في أي مجال؟","options":["علم الفلك","الجراحة","الجغرافيا","الجبر"],"answer":1,"explain":"الزهراوي، الذي عاش قرب قرطبة في القرن العاشر الميلادي، وصف العمليات الجراحية وآلات كثيرة في موسوعته «التصريف»."},{"id":"q081","cat":"sciences","q":"أي طبيب ألَّف رسالة مشهورة فرَّقت بين الجدري والحصبة؟","options":["الكندي","الفارابي","الإدريسي","الرازي"],"answer":3,"explain":"الرازي، وهو طبيب كبير من القرنين التاسع والعاشر الميلاديين، ألَّف رسالة في الجدري والحصبة تصف المرضين وصفًا دقيقًا."},{"id":"q082","cat":"sciences","q":"أي طبيب من القرن الثالث عشر الميلادي وصف كيف يمرُّ الدم من القلب عبر الرئتين؟","options":["الخوارزمي","البيروني","ابن النفيس","ابن خلدون"],"answer":2,"explain":"وصف ابن النفيس الدورة الدموية الرئوية في القرن الثالث عشر الميلادي، قبل أن تُعرف في أوروبا بزمن طويل."},{"id":"q083","cat":"sciences","q":"أي عالِم من القرن الحادي عشر الميلادي حسب نصف قطر الأرض وألَّف دراسة كبرى عن الهند؟","options":["ابن رشد","جابر بن حيان","الزهراوي","البيروني"],"answer":3,"explain":"حسب البيروني نصف قطر الأرض بطريقة بارعة، وكانت نتيجته قريبة من القيمة الحديثة، وألَّف كتابًا مفصَّلًا عن الهند."},{"id":"q084","cat":"sciences","q":"أي جغرافي رسم خريطة مشهورة للعالم للملك روجر الثاني ملك صقلية في القرن الثاني عشر الميلادي؟","options":["ابن بطوطة","ابن خلدون","الإدريسي","الخوارزمي"],"answer":2,"explain":"أتمَّ الإدريسي خريطته للعالم والكتاب المصاحب لها سنة 1154م، في بلاط روجر الثاني في صقلية."},{"id":"q085","cat":"sciences","q":"جابر بن حيان معروف خصوصًا بأعماله في أي مجال؟","options":["البصريات","الجراحة","الكيمياء","الجغرافيا"],"answer":2,"explain":"جابر بن حيان من كبار أعلام الكيمياء القديمة (الخيمياء)، وتُنسب إليه مؤلفات كثيرة."},{"id":"q086","cat":"sciences","q":"في أي مدينة كان بيت الحكمة، المكتبة العباسية الشهيرة المرتبطة بحركة الترجمة؟","options":["بغداد","قرطبة","القاهرة","دمشق"],"answer":0,"explain":"كان بيت الحكمة في بغداد العباسية، حيث كان العلماء يترجمون ويدرسون مؤلفات من التراث اليوناني والفارسي والهندي."},{"id":"q087","cat":"sciences","q":"من مؤلف «المقدمة»، الكتاب المشهور في التاريخ والمجتمع؟","options":["ابن خلدون","ابن بطوطة","ابن رشد","الغزالي"],"answer":0,"explain":"ابن خلدون، المولود في تونس سنة 1332م، هو مؤلف المقدمة. ويُعدُّ رائدًا سبق إلى علم الاجتماع وإلى الدراسة الحديثة للتاريخ."},{"id":"q088","cat":"sciences","q":"فيمَ كان يُستعمل الأسطرلاب، وهو آلة أتقنها العلماء المسلمون؟","options":["قياس درجة الحرارة","وزن الذهب والفضة","طحن الحبوب","رصد مواقع الشمس والنجوم"],"answer":3,"explain":"كان الأسطرلاب يُستعمل لرصد الشمس والنجوم، وهذا يعين الناس على معرفة الوقت وتحديد الاتجاهات."},{"id":"q089","cat":"sciences","q":"بماذا يُعرف المهندس الجزري، الذي أتمَّ كتابه المشهور سنة 1206م؟","options":["آلات بديعة وساعات مائية","خريطة للعالم","رسالة في الجدري","كتاب في الجبر"],"answer":0,"explain":"ألَّف الجزري كتاب «الجامع بين العلم والعمل النافع في صناعة الحيل»، وفيه وصف لساعات مائية ومضخات وآلات ذاتية الحركة."},{"id":"q090","cat":"sciences","q":"بأي اسم لاتيني يُعرف العالِم الأندلسي ابن رشد في أوروبا؟","options":["أفيسينا (Avicenna)","الهازن (Alhazen)","رازيس (Rhazes)","أفيرويس (Averroes)"],"answer":3,"explain":"ابن رشد القرطبي يُعرف باسم أفيرويس. وقد انتشرت قراءة شروحه على أرسطو في أوروبا في العصور الوسطى."},{"id":"q091","cat":"pillars","q":"كم عدد أركان الإسلام؟","options":["ثلاثة","خمسة","أربعة","سبعة"],"answer":1,"explain":"أركان الإسلام خمسة: الشهادتان، والصلاة، والزكاة، وصوم رمضان، والحج إلى مكة."},{"id":"q092","cat":"pillars","q":"ما الركن الأول من أركان الإسلام؟","options":["الصلاة","الصوم","الحج","الشهادتان"],"answer":3,"explain":"الركن الأول هو الشهادتان: أن تشهد أن لا إله إلا الله وأن محمدًا ﷺ رسول الله."},{"id":"q093","cat":"pillars","q":"كم عدد الصلوات المفروضة في اليوم؟","options":["اثنتان","ثلاث","خمس","سبع"],"answer":2,"explain":"الصلوات المفروضة في اليوم خمس: الفجر والظهر والعصر والمغرب والعشاء."},{"id":"q094","cat":"pillars","q":"ما اسم صلاة أول النهار التي تُصلَّى عند طلوع الفجر؟","options":["الظهر","الفجر","العصر","العشاء"],"answer":1,"explain":"الفجر هي صلاة طلوع الفجر، وهي أولى الصلوات الخمس اليومية."},{"id":"q095","cat":"pillars","q":"كم عدد الركعات المفروضة في صلاة الفجر؟","options":["ركعة واحدة","ركعتان","ثلاث ركعات","أربع ركعات"],"answer":1,"explain":"صلاة الفجر المفروضة ركعتان."},{"id":"q096","cat":"pillars","q":"ما ترتيب شهر رمضان بين شهور التقويم الهجري؟","options":["التاسع","الأول","السابع","الثاني عشر"],"answer":0,"explain":"رمضان هو الشهر التاسع في التقويم الهجري. وهو شهر الصيام."},{"id":"q097","cat":"pillars","q":"في رمضان، متى يبدأ صيام كل يوم؟","options":["عند طلوع الفجر","عند شروق الشمس","عند الظهر","عند منتصف الليل"],"answer":0,"explain":"يبدأ الصيام عند طلوع الفجر، حين يظهر أول الضوء، كما يبيِّن القرآن في 2:187."},{"id":"q098","cat":"pillars","q":"ماذا تسمى الوجبة التي يُنهى بها الصيام في المساء؟","options":["السحور","الوليمة","العقيقة","الإفطار"],"answer":3,"explain":"الإفطار هو الوجبة التي يُنهى بها الصيام. أما السحور فهو الوجبة التي تؤكل قبل الفجر."},{"id":"q099","cat":"pillars","q":"ما المقدار المعتاد لزكاة المدَّخرات كالنقود والذهب والفضة؟","options":["2.5%","1%","5%","15%"],"answer":0,"explain":"زكاة المدَّخرات 2.5%، أي ربع العُشر، إذا بقي النصاب في مِلك صاحبه سنة قمرية كاملة."},{"id":"q100","cat":"pillars","q":"في أي شهر يكون الحج؟","options":["رمضان","ذو الحجة","المحرَّم","شوال"],"answer":1,"explain":"يكون الحج في ذي الحجة، وهو الشهر الثاني عشر والأخير في التقويم الهجري."},{"id":"q101","cat":"pillars","q":"كم مرة يدور الحجاج حول الكعبة في الطواف الواحد؟","options":["ثلاث مرات","خمس مرات","سبع مرات","تسع مرات"],"answer":2,"explain":"الطواف سبعة أشواط حول الكعبة."},{"id":"q102","cat":"pillars","q":"بين أي جبلين يمشي الحجاج في السعي؟","options":["أُحد وثور","عرفات ومنى","الصفا والمروة","حراء وثور"],"answer":2,"explain":"يمشي الحجاج سبع مرات بين الصفا والمروة، وقد وصفهما القرآن بأنهما من شعائر الله (2:158)."},{"id":"q103","cat":"pillars","q":"في أي يوم من ذي الحجة يقف الحجاج بعرفة؟","options":["اليوم التاسع","اليوم الأول","اليوم العاشر","اليوم الثالث عشر"],"answer":0,"explain":"الوقوف بعرفة يكون في اليوم التاسع من ذي الحجة. وهو قلب الحج."},{"id":"q104","cat":"pillars","q":"كم مرة في العمر يجب الحج على المسلم المستطيع؟","options":["ثلاث مرات","كل سنة","كل خمس سنوات","مرة واحدة"],"answer":3,"explain":"يجب الحج مرة واحدة في العمر على من استطاع السفر إليه (3:97)."},{"id":"q105","cat":"pillars","q":"إلى أي مدينة كان المسلمون الأوائل يتجهون في صلاتهم قبل أن تصير الكعبة هي القبلة؟","options":["المدينة المنورة","دمشق","الطائف","القدس"],"answer":3,"explain":"كان المسلمون الأوائل يصلُّون نحو بيت المقدس. ثم حُوِّلت القبلة إلى المسجد الحرام في مكة (2:144)."},{"id":"q106","cat":"civilisation","q":"من أسس جامع القرويين في فاس في القرن التاسع الميلادي، وهو الذي صار جامعة مشهورة؟","options":["رابعة العدوية","فاطمة الفهرية","زبيدة بنت جعفر","شجر الدر"],"answer":1,"explain":"بحسب الروايات، أسست فاطمة الفهرية جامع القرويين في فاس، في المغرب، سنة 859م. ويوصف كثيرًا بأنه أقدم جامعة ما زالت تعمل."},{"id":"q107","cat":"civilisation","q":"في أي مدينة من مدن الأندلس يقع الجامع الكبير المشهور بغابة أعمدته وأقواسه الحمراء والبيضاء؟","options":["إشبيلية","قرطبة","غرناطة","طليطلة"],"answer":1,"explain":"بدأ بناء جامع قرطبة الكبير في القرن الثامن الميلادي، حين كانت قرطبة عاصمة الأندلس."},{"id":"q108","cat":"civilisation","q":"في أي مدينة يقع قصر الحمراء؟","options":["غرناطة","قرطبة","مراكش","فاس"],"answer":0,"explain":"يقع قصر الحمراء في غرناطة، في جنوب إسبانيا. وكان قصر حكام بني نصر."},{"id":"q109","cat":"civilisation","q":"أي إمبراطور مغولي أمر ببناء تاج محل؟","options":["أكبر","بابر","أورنكزيب","شاه جهان"],"answer":3,"explain":"أمر شاه جهان ببناء تاج محل في أغرا في القرن السابع عشر الميلادي، تخليدًا لذكرى زوجته ممتاز محل."},{"id":"q110","cat":"civilisation","q":"في أي مدينة وُلد الرحالة الكبير ابن بطوطة؟","options":["فاس","تونس","القاهرة","طنجة"],"answer":3,"explain":"وُلد ابن بطوطة في طنجة، في المغرب، سنة 1304م. وظل يرتحل نحو ثلاثين سنة في إفريقيا وآسيا وأوروبا."},{"id":"q111","cat":"civilisation","q":"تمبكتو، المركز المشهور للعلم والمخطوطات، تقع في أي بلد من بلدان اليوم؟","options":["مصر","المغرب","مالي","السودان"],"answer":2,"explain":"تقع تمبكتو في مالي. وكانت مساجدها ومدارسها تجتذب الطلاب والعلماء من أنحاء غرب إفريقيا."},{"id":"q112","cat":"civilisation","q":"في أي مدينة يقع الأزهر، وهو من أقدم جامعات العالم؟","options":["بغداد","القاهرة","دمشق","القيروان"],"answer":1,"explain":"تأسس الأزهر في القاهرة في القرن العاشر الميلادي، وما زال إلى اليوم مركزًا كبيرًا للعلم."},{"id":"q113","cat":"civilisation","q":"في أي مدينة تقع قبة الصخرة؟","options":["القدس","دمشق","المدينة المنورة","القاهرة"],"answer":0,"explain":"تقع قبة الصخرة في القدس. وقد اكتمل بناؤها في أواخر القرن السابع الميلادي في عهد الخليفة الأموي عبد الملك."},{"id":"q114","cat":"civilisation","q":"أي معماري عثماني صمَّم جامع السليمانية في إسطنبول؟","options":["الجزري","أولوغ بيك","المعمار سنان","ابن خلدون"],"answer":2,"explain":"المعمار سنان، كبير معماريي الدولة العثمانية في القرن السادس عشر الميلادي، صمَّم السليمانية في إسطنبول والسليمية في أدرنة."},{"id":"q115","cat":"civilisation","q":"في العالم الإسلامي في العصور الوسطى، ما «البيمارستان»؟","options":["مكتبة","مرصد فلكي","سوق مسقوفة","مستشفى"],"answer":3,"explain":"البيمارستان هو المستشفى. وكان في مدن مثل بغداد ودمشق والقاهرة مستشفيات كبيرة يُعالج فيها المرضى."},{"id":"q116","cat":"civilisation","q":"ما أول شهور التقويم الهجري؟","options":["المحرَّم","رمضان","رجب","شوال"],"answer":0,"explain":"المحرَّم هو أول الشهور الاثني عشر في التقويم الهجري، وهو تقويم يتبع القمر."},{"id":"q117","cat":"civilisation","q":"ما المحراب في المسجد؟","options":["المنبر الذي تُلقى منه خطبة الجمعة","التجويف الذي يدل على اتجاه مكة","البرج الذي يُرفع منه الأذان","النافورة التي يُتوضأ منها"],"answer":1,"explain":"المحراب تجويف في الجدار يدل على القبلة، أي اتجاه مكة. أما المنصة التي يخطب عليها الإمام فتسمى المنبر، وأما البرج فيسمى المئذنة."},{"id":"q118","cat":"civilisation","q":"جامع القيروان الكبير، وهو من أقدم جوامع إفريقيا، يقع في أي بلد؟","options":["تونس","المغرب","مصر","سوريا"],"answer":0,"explain":"تقع القيروان في تونس. ويعود جامعها الكبير إلى تأسيس المدينة على يد عقبة بن نافع سنة 670م."},{"id":"q119","cat":"civilisation","q":"الخط الكوفي، وهو من أقدم أنواع الخط العربي، يُنسب إلى أي مدينة؟","options":["قرطبة","قونية","الكوفة","كابل"],"answer":2,"explain":"يأخذ الخط الكوفي اسمه من الكوفة، في العراق. وقد كُتب كثير من المصاحف الأولى بهذا الخط ذي الزوايا."},{"id":"q120","cat":"civilisation","q":"ما «الوقف» في الحضارة الإسلامية؟","options":["قافلة تجارية","نوع من الخط","مال محبوس على أعمال الخير","ضريبة على المحاصيل"],"answer":2,"explain":"الوقف مال يُحبس على وجوه الخير، كمدرسة أو مستشفى أو سبيل ماء. ويظل ريعه ينفع الناس على مرِّ الزمن."}]$tk$::jsonb)
  on conflict (kind, lang) do update set payload = excluded.payload, updated_at = now();
insert into public.premium_content (kind, lang, payload) values ('days', 'ar', $tk${"new-year":{"detail":"أول يوم من شهر المحرم هو بداية السنة الهجرية. والتقويم الإسلامي تقويم قمري: يبدأ كل شهر فيه بظهور الهلال الجديد، ولذلك فإن السنة الهجرية أقصر من السنة الشمسية بنحو أحد عشر يومًا.\n\nوقد وُضع هذا التقويم في عهد الخليفة عمر بن الخطاب، بعد سنوات من وفاة النبي محمد ﷺ. واختار الصحابة أن يبدأ عدّ السنين من الهجرة، أي انتقال النبي ﷺ من مكة إلى المدينة سنة 622 للميلاد، وأن يبقى المحرم أول شهور السنة. أما الهجرة نفسها فقد وقعت بعد ذلك في السنة نفسها، في شهر ربيع الأول.\n\nوالمحرم أحد الأشهر الحرم الأربعة المذكورة في القرآن (9:36). وقد علّم النبي ﷺ أن أفضل الصيام بعد رمضان هو صيام شهر الله المحرم (صحيح مسلم 1163).\n\nولم تُشرع لهذا اليوم صلاة خاصة ولا احتفال خاص. وكثير من المسلمين يغتنمونه لتذكّر الهجرة، ومراجعة ما مضى من عامهم، وتجديد العزم على الخير.","sources":["القرآن 9:36","صحيح مسلم 1163"]},"tasua":{"detail":"تاسوعاء هو اليوم التاسع من شهر المحرم، وهو اليوم الذي يسبق عاشوراء.\n\nلما صام النبي محمد ﷺ يوم عاشوراء وأمر المسلمين بصيامه، ذكر له أصحابه أن اليهود والنصارى يعظّمون هذا اليوم أيضًا. فأجاب بأنهم في العام المقبل، إن شاء الله، سيصومون اليوم التاسع كذلك. وقد توفي ﷺ قبل أن يأتي المحرم التالي (صحيح مسلم 1134).\n\nولهذا يستحب العلماء صيام اليوم التاسع مع اليوم العاشر. وبذلك يكون لصيام المسلمين صورته الخاصة، مع بقاء الصلة باليوم الذي نجّى الله فيه موسى عليه السلام.\n\nوهذا الصيام تطوع وليس واجبًا. فمن لم يستطع إلا صيام اليوم العاشر فقد صام عاشوراء، ولا ينبغي لمن كان مريضًا أو مسافرًا أو عاجزًا عن الصيام أن يشعر بالذنب. وشهر المحرم كله شهر حرام، وقد علّم النبي ﷺ أن الصيام فيه أفضل الصيام بعد رمضان (صحيح مسلم 1163).","sources":["صحيح مسلم 1134","صحيح مسلم 1163"]},"ashura":{"detail":"عاشوراء هو اليوم العاشر من شهر المحرم. وترجع قصته إلى نبي الله موسى عليه السلام: ففي مثل هذا اليوم نجّاه الله هو وبني إسرائيل من عدوّهم.\n\nولما قدم النبي محمد ﷺ المدينة وجد اليهود يصومون هذا اليوم إحياءً لذكرى تلك النجاة. فقال إن المسلمين أحقّ بموسى من غيرهم، فصام هذا اليوم وأمر المسلمين بأن يصوموه (صحيح البخاري 2004). ولما فُرض صيام شهر رمضان بعد ذلك، بقي صيام يوم عاشوراء عملًا من أعمال التطوع المستحبة (صحيح البخاري 2002).\n\nوسُئل النبي ﷺ عن ثواب صيامه فقال إنه يكفّر ذنوب السنة التي مضت (صحيح مسلم 1162). ويُستحب لمن أراد صيام عاشوراء أن يصوم معه أيضًا اليوم التاسع من شهر المحرم، أي اليوم الذي قبله (صحيح مسلم 1134).","sources":["صحيح البخاري 2004","صحيح البخاري 2002","صحيح مسلم 1162","صحيح مسلم 1134"]},"mawlid":{"detail":"وُلد النبي محمد ﷺ في مكة، في بني هاشم من قبيلة قريش، في العام المعروف بعام الفيل، نحو سنة 570 للميلاد. وقد توفي أبوه عبد الله قبل ولادته، وتوفيت أمه آمنة وهو طفل صغير.\n\nومن الثابت أنه وُلد يوم الاثنين: فقد سُئل عن صيام يوم الاثنين فقال إنه اليوم الذي وُلد فيه واليوم الذي نزل عليه فيه الوحي (صحيح مسلم 1162). وأكثر المؤرخين على أن ولادته كانت في شهر ربيع الأول. واليوم الثاني عشر هو أشهر التواريخ، لكن ذُكرت أيام أخرى، وليس في شيء منها يقين.\n\nويختلف المسلمون في إحياء هذا اليوم. فكثير منهم يجتمعون لتذكّر سيرته والصلاة عليه وتقاسم الطعام. وآخرون لا يخصّون هذا اليوم بشيء، لأن النبي ﷺ وأصحابه لم يفعلوا ذلك. والجميع متفقون على محبته واتباع هديه في كل يوم، وقد وصفه القرآن بأنه رحمة للعالمين (21:107).","sources":["صحيح مسلم 1162","القرآن 21:107"]},"isra-miraj":{"detail":"الإسراء هو رحلة النبي محمد ﷺ ليلًا من المسجد الحرام في مكة إلى المسجد الأقصى في بيت المقدس. وقد ذكره القرآن في أول سورة الإسراء (17:1). والمعراج هو صعوده من هناك إلى السماوات، حيث لقي أنبياء سابقين عليهم السلام وأُري آيات عظيمة من آيات ربه، وقد أشارت سورة النجم إلى ذلك (53:13-18).\n\nوقع ذلك في مكة قبل الهجرة، في فترة شدة مرّ بها النبي ﷺ. وأبقى عطايا تلك الليلة أثرًا الصلوات الخمس اليومية، فقد فُرضت حينئذ (صحيح البخاري 349).\n\nوالتاريخ الدقيق غير معروف على وجه اليقين. وليلة السابع والعشرين من رجب هي أشهر ما يُذكر، لكن المؤرخين الأوائل ذكروا تواريخ أخرى.\n\nولم تثبت لهذه الليلة صلاة خاصة ولا صيام خاص. وكثير من المسلمين يغتنمون المناسبة لرواية الحدث وتذكّر قيمة الصلاة، وآخرون لا يحيون هذا التاريخ. ورجب أحد الأشهر الحرم الأربعة (9:36).","sources":["القرآن 17:1","القرآن 53:13-18","صحيح البخاري 349","القرآن 9:36"]},"mid-shaban":{"detail":"شعبان هو الشهر الثامن، ويأتي قبل رمضان مباشرة. وقد روت عائشة رضي الله عنها أنها لم ترَ النبي محمدًا ﷺ يصوم في شهر، غير رمضان، أكثر مما كان يصوم في شعبان (صحيح البخاري 1969). فهو شهر استعداد: صيام تطوع، وقضاء ما فات من صيام رمضان الماضي، وقراءة القرآن.\n\nوليلة الخامس عشر، في منتصف الشهر، تُعرف في بلدان كثيرة بأسماء مثل ليلة البراءة أو شبِ برات أو نصف شعبان. وقد وردت عدة روايات تذكر مغفرة الله في هذه الليلة. واختلف العلماء في قوة هذه الروايات، ولذلك اختلفوا في العمل: فكثير من المسلمين يقضون جزءًا من الليل في الصلاة والدعاء ويصومون نهارها، وآخرون يعدّونها كسائر ليالي شعبان ولا يخصّونها بعبادة معينة.\n\nوالمتفق عليه أن الاستغفار وإصلاح العلاقة مع الناس وصيام التطوع أعمال حسنة في شعبان كله، وهو الباب المؤدي إلى رمضان.","sources":["صحيح البخاري 1969"]},"ramadan-start":{"detail":"رمضان هو الشهر التاسع من السنة الهجرية، وهو الشهر الذي أُنزل فيه القرآن هدى للناس (2:185). وصيامه أحد أركان الإسلام الخمسة (صحيح البخاري 8). وقد فُرض صيامه في المدينة، في السنة الثانية بعد الهجرة.\n\nيبدأ الشهر برؤية الهلال الجديد، فإن تعذّرت رؤيته أُكمل شعبان ثلاثين يومًا (صحيح البخاري 1909). ولهذا قد تختلف بدايته يومًا واحدًا من بلد إلى آخر.\n\nمن الفجر إلى غروب الشمس يمتنع الصائمون عن تناول الطعام والشراب وعن العلاقة الزوجية. ويُعفى المريض والمسافر ويقضيان الأيام فيما بعد، ومن لا يستطيع الصيام أصلًا يطعم مسكينًا بدلًا منه (2:184-185). وقد بيّن القرآن غاية الصيام: تحقيق التقوى (2:183).\n\nوقال النبي محمد ﷺ إنه إذا دخل رمضان فُتحت أبواب السماء وأُغلقت أبواب جهنم وسُلسلت الشياطين (صحيح البخاري 1899). فهو شهر تكثر فيه الصلاة وقراءة القرآن والجود.","sources":["القرآن 2:183-185","صحيح البخاري 8","صحيح البخاري 1909","صحيح البخاري 1899"]},"last-ten-nights":{"detail":"تبدأ العشر الأواخر من رمضان في المساء الذي يسبق اليوم الحادي والعشرين، وتستمر إلى آخر الشهر الذي يكون 29 أو 30 يومًا. وهي أثمن أوقات رمضان، لأن ليلة القدر في إحدى لياليها.\n\nوقد روت عائشة رضي الله عنها أن النبي محمدًا ﷺ كان إذا دخلت هذه العشر شدّ مئزره وأحيا ليله وأيقظ أهله (صحيح البخاري 2024). وكان يجتهد في العبادة في هذه الليالي أكثر مما يجتهد في غيرها (صحيح مسلم 1175).\n\nوكان يعتكف كذلك، أي يلزم المسجد ليتفرغ للعبادة، في العشر الأواخر من رمضان حتى توفي (صحيح البخاري 2026).\n\nوالمستحب فيها: قيام الليل، وقراءة القرآن، والإكثار من الدعاء، والاستغفار، والصدقة. ومن لم يستطع السهر طويلًا فله أن يصلي قليلًا في كل ليلة، حتى لا تفوته الليلة التي هي خير من ألف شهر (97:3). وفي هذه الأيام أيضًا تُجهَّز زكاة الفطر قبل صلاة العيد.","sources":["صحيح البخاري 2024","صحيح مسلم 1175","صحيح البخاري 2026","القرآن 97:3"]},"laylat-al-qadr":{"detail":"ليلة القدر هي الليلة التي أُنزل فيها القرآن. وقد خُصّت بسورة كاملة: فهي خير من ألف شهر، تنزل فيها الملائكة والروح بإذن ربهم، وهي سلام حتى مطلع الفجر (97:1-5). وسمّاها القرآن أيضًا ليلة مباركة (44:3).\n\nوقد أُخفي تاريخها الدقيق. وأمر النبي محمد ﷺ المؤمنين بأن يلتمسوها في الليالي الوتر من العشر الأواخر من رمضان (صحيح البخاري 2017): أي ليلة 21 أو 23 أو 25 أو 27 أو 29. وليلة السابع والعشرين هي الأكثر ذكرًا، ويجتمع فيها كثير من الناس، لكن ذلك ليس مؤكدًا، وللعلماء فيها أقوال مختلفة. والأحكم أن يجتهد المسلم في الليالي العشر كلها.\n\nوقال النبي ﷺ إن من قام ليلة القدر إيمانًا واحتسابًا غُفر له ما تقدم من ذنبه (صحيح البخاري 2014). والأعمال المستحبة فيها هي قيام الليل وتلاوة القرآن والدعاء وطلب العفو من الله.","sources":["القرآن 97:1-5","القرآن 44:3","صحيح البخاري 2017","صحيح البخاري 2014"]},"eid-al-fitr":{"detail":"عيد الفطر يوافق أول يوم من شهر شوال، وبه يُختم شهر رمضان. وقد طلب القرآن من المؤمنين أن يكملوا عدة الأيام وأن يكبّروا الله على ما هداهم (2:185).\n\nوقبل صلاة العيد تُخرَج زكاة الفطر: وهي صدقة يسيرة من الطعام الأساسي، تجب عن كل فرد من أفراد الأسرة، ليشارك الفقراء في فرحة هذا اليوم. وقد أمر النبي محمد ﷺ بأن تُؤدّى قبل خروج الناس إلى الصلاة (صحيح البخاري 1503).\n\nوفي الصباح يكبّر المسلمون ويلبسون أحسن ثيابهم ويجتمعون لصلاة العيد، وتتبعها خطبة (صحيح البخاري 956). وكان النبي ﷺ لا يخرج إلى الصلاة في هذا اليوم حتى يأكل تمرات (صحيح البخاري 953).\n\nولا يجوز صيام يوم العيد (صحيح البخاري 1991). فهو يوم شكر وزيارة للأهل وإحسان إلى الجيران. أما صيام التطوع، كصيام الست من شوال، فيمكن أن يبدأ من اليوم الثاني.","sources":["القرآن 2:185","صحيح البخاري 1503","صحيح البخاري 956","صحيح البخاري 953","صحيح البخاري 1991"]},"six-shawwal":{"detail":"شوال هو الشهر الذي يلي رمضان. وقد قال النبي محمد ﷺ إن من صام رمضان ثم أتبعه ستة أيام من شوال كان كمن صام السنة كلها (صحيح مسلم 1164).\n\nويفسّر العلماء ذلك بقاعدة أن الحسنة بعشر أمثالها (6:160): فشهر رمضان يُحسب بعشرة أشهر، والأيام الستة تُحسب بشهرين، فيكتمل بذلك عام كامل.\n\nوتصحّ في أي ستة أيام من الشهر. ويعرض التطبيق الأيام من 2 إلى 7 على سبيل التيسير فقط: فيجوز صيامها متتابعة أو متفرقة، في أول شوال أو وسطه أو آخره. واليوم الوحيد المستثنى هو اليوم الأول، يوم العيد، الذي لا يجوز صيامه.\n\nوهذا الصيام تطوع وليس فرضًا. ومن بقيت عليه أيام من رمضان فعليه أن يحسب حسابها كذلك: فكثير من العلماء ينصحون بقضائها أولًا، وآخرون يجيزون صيام الست قبلها. وهو طريقة لطيفة للمحافظة على عادات رمضان الحسنة.","sources":["صحيح مسلم 1164","القرآن 6:160"]},"dhul-hijja-nine":{"detail":"ذو الحجة هو الشهر الثاني عشر، وهو شهر الحج. وأيامه العشرة الأولى من أفضل أيام السنة: فقد قال النبي محمد ﷺ إنه ما من عمل صالح أفضل من العمل في هذه الأيام (صحيح البخاري 969). ويرى كثير من المفسرين كذلك أن الليالي العشر التي أقسم الله بها في القرآن (89:2) هي هذه الأيام.\n\nولأن الصيام من أفضل الأعمال، يُستحب صيام الأيام التسعة الأولى بقدر الاستطاعة. واليوم التاسع، يوم عرفة، آكدها. أما اليوم العاشر فهو عيد الأضحى، ولا يجوز صيامه.\n\nومن الأعمال المستحبة أيضًا تكرار التكبير، والإكثار من حمد الله، والصلاة، والصدقة، وقراءة القرآن. وقد ذكر القرآن ذكر اسم الله في أيام معلومات (22:28).\n\nومن أراد أن يضحّي يُطلب منه ألا يأخذ من شعره ولا من أظفاره من أول الشهر حتى تُذبح أضحيته (صحيح مسلم 1977). وفي هذه الأيام يجتمع الحجاج من أنحاء العالم في مكة.","sources":["صحيح البخاري 969","القرآن 89:2","القرآن 22:28","صحيح مسلم 1977"]},"arafat":{"detail":"اليوم التاسع من ذي الحجة هو يوم عرفة، وهو قلب الحج. من الظهر إلى غروب الشمس يقف الحجاج في صعيد عرفات، قرب مكة، مصلّين داعين. والوقوف بعرفة هو الركن الأعظم في الحج.\n\nوفي هذا اليوم، وكان يوم جمعة، في حجة الوداع التي حجّها النبي محمد ﷺ، نزلت الآية التي تعلن أن الله أكمل الدين (5:3)، كما روى عمر بن الخطاب (صحيح البخاري 45).\n\nوقال النبي ﷺ إنه ما من يوم يُعتق الله فيه من النار عبادًا أكثر من يوم عرفة (صحيح مسلم 1348).\n\nولغير الحاج يُستحب صيام هذا اليوم استحبابًا مؤكدًا: فقد قال النبي ﷺ إنه يكفّر ذنوب السنة الماضية والسنة القادمة (صحيح مسلم 1162). أما الحجاج فلا يُطلب منهم الصيام، ولم يكن النبي ﷺ صائمًا وهو واقف بعرفة (صحيح البخاري 1988).\n\nفهو يوم دعاء وذكر لله واستغفار، أينما كان المسلم.","sources":["القرآن 5:3","صحيح البخاري 45","صحيح مسلم 1348","صحيح مسلم 1162","صحيح البخاري 1988"]},"eid-al-adha":{"detail":"عيد الأضحى يوافق اليوم العاشر من ذي الحجة، وهو اليوم الذي يلي عرفة. ويتزامن هذا العيد مع أهم مناسك الحج في منى ومكة.\n\nوهو يذكّر بالابتلاء الذي مرّ به إبراهيم عليه السلام. فقد رأى في المنام أنه يذبح ابنه، فاستسلم الاثنان لأمر الله، وفدى الله الابن بذبح عظيم (37:102-107).\n\nيبدأ هذا اليوم بصلاة العيد، وتتبعها خطبة (صحيح البخاري 956). وبعد الصلاة يذبح القادرون شاة من الضأن أو المعز أو بقرة أو بعيرًا. ويأكل أهل البيت من اللحم، ويُهدى منه إلى الأقارب والجيران، ويُعطى منه الفقراء. ويذكّر القرآن المؤمنين بأن الله لا يناله اللحم ولا الدم، وإنما تناله تقواهم (22:37).\n\nولا يجوز صيام هذا اليوم (صحيح البخاري 1991). ويكبّر المسلمون ويلبسون أحسن ثيابهم ويتزاورون ويتقاسمون الطعام. ويجوز كذلك أن تُذبح الأضحية في الأيام التي تليه.","sources":["القرآن 37:102-107","صحيح البخاري 956","القرآن 22:37","صحيح البخاري 1991"]},"tashriq":{"detail":"أيام التشريق هي الحادي عشر والثاني عشر والثالث عشر من ذي الحجة، وهي الأيام الثلاثة التي تلي عيد الأضحى. وقد وصفها النبي محمد ﷺ بأنها أيام أكل وشرب وذكر لله (صحيح مسلم 1141).\n\nوفي هذه الأيام يقيم الحجاج في منى ويرمون كل يوم بالحصى الجمرات الثلاث. وقد أمرهم القرآن بذكر الله في هذه الأيام المعدودات، وبيّن أنه لا إثم على من تعجّل فرحل بعد يومين، ولا على من تأخّر (2:203). فللحجاج أن يرحلوا في اليوم الثاني عشر أو أن يبقوا إلى الثالث عشر.\n\nولا يجوز صيام هذه الأيام. والاستثناء الوحيد المرويّ هو للحاج الذي وجب عليه الهدي ولم يجده (صحيح البخاري 1997).\n\nأما سائر الناس فهي لهم أيام فرح وشكر: يتقاسمون لحم الأضاحي، ويزورون الأقارب، ويكبّرون، وخاصة بعد الصلوات اليومية. ويجوز ذبح الأضحية في هذه الأيام كذلك، على تفصيل يختلف بين المذاهب الفقهية.","sources":["صحيح مسلم 1141","القرآن 2:203","صحيح البخاري 1997"]}}$tk$::jsonb)
  on conflict (kind, lang) do update set payload = excluded.payload, updated_at = now();

-- ===== 10-premium-es =====
-- Contenu Premium — es
-- Fichier GÉNÉRÉ par scripts/build-seed.mjs : ne pas modifier à la main. Idempotent (peut être relancé).

insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$adam$tk$, 'es', 1, $tk$Adam (Adán)$tk$, $tk$آدم$tk$, $tk$El primer ser humano y el primer profeta$tk$, $tk$Adam, la paz sea con él, es el primer ser humano y el primer profeta. El Corán nos cuenta que Allah anunció a los ángeles que pondría en la tierra a un ser al que se la confiaría. Los ángeles se preguntaron por una criatura que podría sembrar la corrupción y derramar sangre. Allah respondió que Él sabía lo que ellos no sabían.

Allah creó a Adam de barro y le enseñó los nombres de todas las cosas. Cuando se pidió a los ángeles que dijeran esos nombres, reconocieron que solo sabían lo que Allah les había enseñado. Entonces Adam los nombró. El conocimiento fue el primer honor concedido a la humanidad.

Allah ordenó a los ángeles que se postraran ante Adam. Todos obedecieron excepto Iblís, que se negó por orgullo, alegando que él, creado de fuego, era mejor que un ser hecho de barro. Fue expulsado, y juró que intentaría extraviar a los hijos de Adam.

Adam y su esposa fueron instalados en el Jardín. Podían comer libremente de todo, salvo de un árbol. Satanás les susurró, jurando que era un consejero sincero y prometiéndoles la vida eterna. Ambos comieron del árbol. El Corán no carga la culpa solo sobre la esposa: dice que los dos tropezaron. Su desnudez se les hizo evidente, y empezaron a cubrirse con hojas del Jardín.

Lo que siguió es el corazón de la historia. Adam y su esposa no discutieron ni pusieron excusas, como había hecho Iblís. Se volvieron hacia su Señor, reconocieron que habían sido injustos consigo mismos y pidieron Su perdón y Su misericordia. Adam recibió unas palabras de su Señor, y Allah aceptó su arrepentimiento. El Corán dice que su Señor entonces lo escogió, lo perdonó y lo guio.

Adam y su esposa fueron enviados a la tierra, donde los seres humanos vivirían, morirían y serían resucitados. Allah prometió que les llegaría la guía, y que quienes la sigan no tendrán nada que temer ni se afligirán.

El Corán no dice dónde estaba el Jardín, qué clase de árbol era ni cuánto vivió Adam, y no hace falta adivinarlo. Lo que sí enseña es que todos los seres humanos proceden del mismo padre y de la misma madre, y que la puerta del arrepentimiento está abierta desde el primer día.$tk$, $tk$Todo el mundo comete errores; lo que importa es reconocerlos sin excusas y volver pronto a Allah. El orgullo cierra la puerta que la humildad abre.$tk$, $tk$["2:30-39","7:11-25","20:115-123"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$idris$tk$, 'es', 2, $tk$Idris$tk$, $tk$إدريس$tk$, $tk$Un hombre veraz elevado a un alto rango$tk$, $tk$Idris, la paz sea con él, es uno de los profetas de los que el Corán dice muy poco. Se lo menciona por su nombre solo en dos lugares, y cada vez en pocas palabras.

En la sura Maryam, tras las historias de varios profetas, Allah dice al Profeta Muhammad ﷺ que mencione a Idris en el Libro. Se lo describe como un hombre veraz y un profeta, y el Corán añade que Allah lo elevó a un alto rango. En la sura al-Anbiya se lo nombra junto con Ismail y Dhul-Kifl: los tres estaban entre los pacientes, Allah los admitió en Su misericordia y estaban entre los justos.

Eso es todo lo que nos dice el Corán. No dice cuándo vivió Idris, a qué pueblo fue enviado ni qué ocurrió durante su misión. Los sabios han explicado el alto rango de distintas maneras: unos lo entienden como una alta posición y un honor ante Allah, otros como un lugar elevado en los cielos. En el hadiz auténtico sobre el Viaje Nocturno, el Profeta Muhammad ﷺ relata que encontró a Idris en el cuarto cielo, y que Idris le dio la bienvenida (Sahih al-Bukhari, n.º 3887).

Muchos libros posteriores añaden detalles: que fue el primero en escribir con un cálamo, en coser ropa o en estudiar las estrellas, o que es la misma persona que una figura conocida por escrituras más antiguas. Estos relatos no proceden del Corán ni de hadices auténticos. No pueden presentarse como hechos establecidos, y es más prudente dejarlos de lado.

Lo que queda es breve pero valioso. De toda una vida, el Corán ha conservado tres cualidades: la veracidad, la paciencia y la rectitud. La palabra árabe que se emplea para él, siddiq, designa a alguien profundamente veraz, cuyos actos concuerdan con sus palabras y cuyas palabras concuerdan con su fe. A su nombre no va unido ningún relato de poder, riqueza o fama; solo se ha conservado su carácter.

Las pocas aleyas sobre Idris nos recuerdan también que el valor de una persona ante Allah no depende de cuánto sepa la gente de ella. Un profeta puede ser honrado en el Corán en dos líneas, y esas dos líneas bastan para hacer de él un ejemplo.$tk$, $tk$Sé veraz y paciente aunque nadie lo note: ante Allah, el carácter cuenta más que la fama.$tk$, $tk$["19:56-57","21:85-86"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$nuh$tk$, 'es', 3, $tk$Nuh (Noé)$tk$, $tk$نوح$tk$, $tk$El predicador incansable y constructor del Arca$tk$, $tk$Nuh, la paz sea con él, fue enviado a un pueblo que había caído en la adoración de ídolos. El Corán da incluso los nombres de esos ídolos: Wadd, Suwa, Yaghuth, Yauq y Nasr. Nuh llegó a ellos con un mensaje sencillo: adorad solo a Allah, pedidle perdón, y Él os perdonará.

El Corán dice que Nuh permaneció entre su pueblo mil años menos cincuenta. Los llamó de noche y de día, en público y en privado. Les recordó que Allah es siempre indulgente y que les enviaría lluvia en abundancia. Pero cuanto más los llamaba, más se apartaban. Se metían los dedos en los oídos y se cubrían con sus ropas para no oírlo.

Los jefes de su pueblo lo despreciaban. Decían que no era más que un hombre como ellos, y que solo lo seguían los más humildes. Nuh respondió que no les pedía ninguna riqueza, que su recompensa solo incumbía a Allah, y que jamás echaría a los que creían.

Cuando se le reveló a Nuh que nadie más de su pueblo creería, Allah le ordenó construir el Arca bajo Su mirada. Los notables se burlaban de él cada vez que pasaban a su lado. Entonces llegó la orden de Allah, y comenzó el diluvio. A Nuh se le dijo que embarcara una pareja de cada especie de criatura, a su familia y a los que creían, y estos eran solo unos pocos.

El Arca navegó entre olas como montañas. Nuh vio a uno de sus hijos que se mantenía aparte y lo llamó para que subiera a bordo. El hijo respondió que se refugiaría en una montaña. Una ola se interpuso entre ambos, y él estuvo entre los ahogados. Nuh habló a su Señor de su hijo, y Allah le dijo que ese hijo no era verdaderamente de su familia, porque su conducta no era recta. Nuh lo aceptó con humildad.

Después se ordenó a la tierra que tragara su agua y al cielo que retuviera su lluvia. El Arca se posó sobre el monte Yudi, y a Nuh se le dijo que desembarcara en paz, con bendiciones sobre él y sobre quienes estaban con él. El Corán dice que el Arca quedó como un signo para todas las gentes.$tk$, $tk$Sigue haciendo lo correcto aunque los resultados tarden en llegar. El éxito se mide por la fidelidad, no por el número de personas que te siguen.$tk$, $tk$["11:25-48","71:1-28","29:14-15","54:9-15"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$hud$tk$, 'es', 4, $tk$Hud$tk$, $tk$هود$tk$, $tk$El mensajero enviado al pueblo de Ad$tk$, $tk$Hud, la paz sea con él, fue enviado al pueblo de Ad, que vivía en una región que el Corán llama al-Ahqaf, las dunas de arena. Vinieron después del pueblo de Nuh y habían recibido una gran fuerza. Hud era uno de ellos: el Corán lo llama su hermano.

Su mensaje era el mismo que el de todos los profetas: adorad solo a Allah, no tenéis otro dios. Les dijo que no les pedía recompensa alguna. Los invitó a pedir perdón a su Señor y a volverse hacia Él, prometiendo que entonces Allah les enviaría lluvia abundante y añadiría fuerza a su fuerza.

Los jefes de Ad respondieron con dureza. Lo acusaron de insensatez y de mentir. Algunos dijeron incluso que alguno de sus dioses debía de haberlo golpeado con un mal. Hud contestó con calma que no había insensatez en él, que era un mensajero del Señor de los mundos y un consejero digno de confianza para ellos. Les recordó que Allah los había hecho sucesores tras el pueblo de Nuh, y les pidió que recordaran Sus favores.

Luego pronunció palabras de gran valentía. Declaró que nada tenía que ver con los falsos dioses que adoraban, y los desafió a tramar contra él todos juntos, sin darle tregua alguna. Dijo que confiaba en Allah, su Señor y el Señor de ellos, que tiene poder sobre toda criatura viviente.

El pueblo de Ad no cambió. Incluso pidieron a Hud que trajera el castigo del que les advertía. Un día vieron una nube que se acercaba a sus valles y se alegraron, pensando que traería lluvia. Era en realidad un viento violento que llevaba un castigo doloroso. El Corán dice que sopló contra ellos siete noches y ocho días seguidos, dejando a la gente tendida como troncos huecos de palmera. Después no se veía nada más que sus moradas.

Hud y los que creyeron con él fueron salvados por la misericordia de Allah. El Corán no nos dice cuántos eran ni adónde fueron después.

La historia de Ad se cuenta varias veces en el Corán como advertencia para todo pueblo poderoso: la fuerza y la prosperidad son dones, y no protegen a nadie que las use para rechazar la verdad y actuar con arrogancia.$tk$, $tk$La fuerza, el talento y la riqueza son dones que hay que agradecer, no razones para sentirse por encima de los demás. Cuando alguien te dé un consejo sincero, escucha antes de juzgar.$tk$, $tk$["7:65-72","11:50-60","46:21-25","69:6-8"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$salih$tk$, 'es', 5, $tk$Salih$tk$, $tk$صالح$tk$, $tk$El mensajero enviado a Thamud$tk$, $tk$Salih, la paz sea con él, fue enviado al pueblo de Thamud, que vino después del pueblo de Ad. Eran constructores hábiles: el Corán dice que edificaban palacios en las llanuras y excavaban casas en las montañas. Salih era uno de ellos, y antes de su misión su pueblo había puesto en él grandes esperanzas.

Los llamó a adorar solo a Allah. Les recordó que era Allah quien los había sacado de la tierra y los había establecido en ella, y les pidió que buscaran Su perdón y no sembraran la corrupción en el país. Su respuesta fue de decepción: ¿cómo podía prohibirles adorar lo que habían adorado sus padres? Dijeron que tenían serias dudas sobre su mensaje.

Unos pocos creyeron, sobre todo entre los débiles. Los jefes orgullosos les preguntaron, con desprecio, si de verdad pensaban que Salih había sido enviado por su Señor. Los creyentes respondieron sin rodeos que creían en aquello con lo que había sido enviado.

Allah dio entonces a Thamud un signo claro: una camella. El Corán la llama la camella de Allah. Salih pidió a su pueblo que la dejaran pastar libremente en la tierra de Allah, que respetaran su turno para beber y que no le hicieran daño, o de lo contrario los alcanzaría un castigo. El Corán no describe cómo apareció la camella, y los relatos detallados que se cuentan al respecto no están establecidos.

La prueba era sencilla, y no la superaron. El Corán menciona también a nueve hombres de la ciudad que sembraban la corrupción y que juraron juntos atacar de noche a Salih y a su familia. El más miserable de ellos se alzó, y la camella fue desjarretada y muerta. Luego desafiaron a Salih a traer el castigo que había prometido.

Salih les dijo que les quedaban tres días para disfrutar en sus casas, una promesa que no sería desmentida. Entonces llegó el castigo: un estruendo terrible y un terremoto se apoderaron de ellos, y quedaron sin vida en sus casas, como si nunca hubieran vivido allí. Salih y los que creyeron con él fueron salvados por la misericordia de Allah.

El Corán recoge las últimas palabras de Salih al apartarse de ellos: les había transmitido el mensaje de su Señor y les había dado un consejo sincero, pero no querían a quienes aconsejan.$tk$, $tk$Una bendición es también una responsabilidad: respeta lo que se te ha confiado. Acoge el consejo sincero, incluso cuando no sea lo que querías oír.$tk$, $tk$["7:73-79","11:61-68","27:45-53","91:11-15"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$ibrahim$tk$, 'es', 6, $tk$Ibrahim (Abraham)$tk$, $tk$إبراهيم$tk$, $tk$El amigo de Allah y padre de los profetas$tk$, $tk$Ibrahim, la paz sea con él, creció entre gentes que adoraban ídolos y astros. Su propio padre, al que el Corán llama Azar, era uno de ellos. Desde su juventud, Allah había dado a Ibrahim un juicio recto, y no podía aceptar que la gente se inclinara ante estatuas que había hecho con sus propias manos.

El Corán cuenta cómo razonó con su pueblo. Miró una estrella, luego la luna, luego el sol. Cada uno se puso y desapareció, y cada vez mostró que algo que desaparece no puede ser el Señor. Entonces declaró que volvía su rostro hacia Aquel que creó los cielos y la tierra.

Un día, cuando la gente se había marchado, Ibrahim rompió sus ídolos en pedazos, salvo el más grande. Cuando lo interrogaron, les dijo que preguntaran al ídolo grande, si es que los ídolos podían hablar. Por un momento comprendieron lo absurda que era su adoración. Pero ganó el orgullo, y decidieron quemarlo. Allah ordenó al fuego que fuera fresco e inofensivo para Ibrahim, y salió ileso.

Ibrahim dejó entonces a su pueblo por amor a su Señor y Le pidió un hijo justo. En su vejez, Allah le concedió a Ismail y a Ishaq, y dio gracias a Aquel que escucha toda súplica.

Por orden de Allah, estableció a parte de su familia en un valle sin cultivos, junto a la Casa Sagrada, y rogó que los corazones se inclinaran hacia ellos y que se les proveyera de frutos. Más tarde levantó los cimientos de la Kaaba con su hijo Ismail. Mientras construían, pidieron a Allah que aceptara su obra y que enviara a la gente de aquella tierra un mensajero salido de entre ellos.

Ibrahim fue probado también de la manera más dura: vio en sueños que sacrificaba a su hijo. Se lo contó a su hijo, y este respondió que hiciera lo que se le ordenaba. Cuando ambos se hubieron sometido, Allah llamó a Ibrahim diciéndole que había cumplido la visión, y el hijo fue rescatado con un gran sacrificio. Los musulmanes lo recuerdan cada año en el Eid al-Adha.

El Corán dice que Ibrahim fue probado por su Señor con unas órdenes y las cumplió todas, y que Allah lo hizo guía para las gentes.$tk$, $tk$Usa tu inteligencia para buscar la verdad, y ten el valor de seguirla aunque te quedes solo. Lo que dejamos por Allah nunca se pierde.$tk$, $tk$["6:74-83","21:51-70","2:124-129","37:99-111","14:35-41"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$lut$tk$, 'es', 7, $tk$Lut (Lot)$tk$, $tk$لوط$tk$, $tk$El profeta que se mantuvo firme en medio de un pueblo corrupto$tk$, $tk$Lut, la paz sea con él, vivió en tiempos de Ibrahim, la paz sea con él. El Corán dice que creyó en el mensaje de Ibrahim. Después fue enviado como profeta a un pueblo cuya ciudad el Corán no nombra.

Aquella gente había caído en faltas graves. El Corán dice que cometían una indecencia que ningún pueblo había cometido antes que ellos: los hombres se acercaban con deseo a los hombres en lugar de a las mujeres. Además asaltaban a los viajeros en el camino y hacían el mal abiertamente en sus reuniones. Lut los llamó a temer a Allah y a abandonar esos actos. Les dijo que no pedía ningún pago y que era para ellos un mensajero digno de confianza.

Su única respuesta fue burlarse de él y amenazarlo. Dijeron: expulsad de la ciudad a Lut y a sus seguidores, pues son gente que quiere mantenerse pura. Incluso lo desafiaron a traer el castigo de Allah si decía la verdad. Lut pidió entonces ayuda a su Señor contra los que sembraban la corrupción.

Unos ángeles fueron enviados con una misión. Primero visitaron a Ibrahim, a quien llevaron la buena nueva de un hijo, y le dijeron que se dirigían al pueblo de Lut. Luego llegaron a Lut con apariencia de huéspedes. Él no sabía quiénes eran, y se angustió, porque temía lo que su pueblo les haría. En efecto, los hombres de la ciudad acudieron corriendo a su casa. Lut les suplicó que temieran a Allah y no lo avergonzaran delante de sus huéspedes. Deseó tener la fuerza para detenerlos.

Los ángeles revelaron entonces quiénes eran: mensajeros de su Señor, a los que aquella gente jamás alcanzaría. Dijeron a Lut que partiera durante la noche con su familia, y que nadie mirara atrás. Su esposa, sin embargo, estaría entre los que se quedaron y compartiría la suerte de los demás.

Por la mañana cayó el castigo. La ciudad fue puesta boca abajo y llovieron sobre ella piedras de arcilla dura. Lut y los de su familia que lo siguieron fueron salvados.

El Corán dice que los restos de aquel lugar quedaron como un signo claro para la gente que usa la razón.$tk$, $tk$Hacer lo correcto no depende de lo que haga la mayoría. Mantente fiel a tus valores, incluso cuando se burlen de ti por querer mantenerte puro.$tk$, $tk$["7:80-84","11:77-83","15:57-77","29:26-35"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$ismail$tk$, 'es', 8, $tk$Ismail (Ismael)$tk$, $tk$إسماعيل$tk$, $tk$Fiel a su promesa, constructor de la Kaaba con su padre$tk$, $tk$Ismail, la paz sea con él, es hijo de Ibrahim, la paz sea con él. Ibrahim había pedido a su Señor un hijo justo, y dio gracias a Allah por concederle a Ismail y a Ishaq en su vejez.

El Corán recoge la súplica de Ibrahim en la que dice que había establecido a parte de su descendencia en un valle sin cultivos, junto a la Casa Sagrada, para que establecieran la oración. Un largo hadiz de Sahih al-Bukhari (n.º 3364) relata cómo Ibrahim dejó a Ismail, todavía un bebé, con su madre Hayar en aquel valle desierto de La Meca, cómo ella corrió entre las colinas de Safa y Marwa buscando agua, y cómo apareció el manantial de Zamzam. Los peregrinos siguen caminando entre esas dos colinas en recuerdo de su confianza en Allah.

El Corán habla luego de una gran prueba. Ibrahim vio en sueños que sacrificaba a su hijo, y le preguntó qué le parecía. El hijo, descrito como dulce y paciente, respondió que su padre hiciera lo que se le ordenaba, y que lo encontraría, si Allah quería, entre los pacientes. Cuando ambos se hubieron sometido, Allah llamó a Ibrahim diciéndole que había cumplido la visión, y rescató al hijo con un gran sacrificio. El Corán no nombra al hijo en este pasaje; la mayoría de los sabios musulmanes sostiene que era Ismail.

Padre e hijo trabajaron después juntos en una tarea que todavía marca la vida de los musulmanes. Allah encargó a Ibrahim y a Ismail que purificaran Su Casa para quienes dan vueltas alrededor de ella, permanecen allí en adoración, se inclinan y se postran. Juntos levantaron los cimientos de la Kaaba, pidiendo a Allah que lo aceptara de ellos, que hiciera de ellos y de su descendencia gente sometida a Él, y que enviara a la gente de aquella tierra un mensajero salido de entre ellos. Los musulmanes ven en la llegada del Profeta Muhammad ﷺ, descendiente de Ismail, la respuesta a esta súplica.

El Corán resume el carácter de Ismail en pocas palabras. Era fiel a su promesa, mensajero y profeta. Ordenaba a su gente la oración y la limosna, y su Señor estaba complacido con él. En otro lugar se lo cuenta entre los pacientes y entre aquellos a quienes Allah favoreció.$tk$, $tk$Cumple tus promesas, incluso las pequeñas, y preocúpate por la fe de quienes tienes cerca. La confianza en Allah crece con la paciencia en los momentos difíciles.$tk$, $tk$["2:125-129","19:54-55","37:101-107","14:37-39","21:85-86"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$ishaq$tk$, 'es', 9, $tk$Ishaq (Isaac)$tk$, $tk$إسحاق$tk$, $tk$La buena nueva dada a Ibrahim en su vejez$tk$, $tk$Ishaq, la paz sea con él, es el segundo hijo de Ibrahim, la paz sea con él. El Corán cuenta con cierto detalle la historia de su nacimiento, pero dice poco sobre el resto de su vida.

Un día llegaron unos huéspedes a casa de Ibrahim y lo saludaron con la paz. Él les devolvió el saludo y, generoso como era, les trajo enseguida un ternero asado. Pero los huéspedes no alargaron la mano hacia la comida. Ibrahim se sintió inquieto. Le dijeron que no temiera: eran ángeles, enviados al pueblo de Lut, y le traían la buena nueva de un hijo lleno de saber.

La esposa de Ibrahim estaba de pie cerca de allí. El Corán dice que se le dio la buena nueva de Ishaq y, después de Ishaq, de Yaqub. Ella se asombró: ¿cómo iba a tener un hijo si era una anciana que nunca había podido tener hijos, y su marido era un anciano? Los ángeles respondieron: ¿acaso se sorprendía del decreto de Allah? Desearon la misericordia y las bendiciones de Allah para la gente de la casa.

La promesa se cumplió. Ibrahim alabó a Allah por darle a Ismail y a Ishaq en su vejez, y declaró que su Señor escucha toda súplica.

El Corán describe a Ishaq como un profeta de entre los justos, y dice que Allah bendijo a Ibrahim y a Ishaq. Añade que Allah hizo de Ishaq y de Yaqub guías que dirigían por Su orden, y les inspiró hacer buenas obras, establecer la oración y dar limosna; eran fervientes adoradores de Allah. Cuando Yaqub estaba cerca de la muerte, sus hijos prometieron adorar al Dios de sus padres, Ibrahim, Ismail e Ishaq, un Dios único.

Más allá de esto, el Corán no ofrece ningún relato de la misión de Ishaq ni de los acontecimientos de su vida. Los muchos detalles que se encuentran en otras fuentes no están confirmados por el Corán ni por hadices auténticos, así que no los repetimos aquí.

De Ishaq vino Yaqub, y de Yaqub un largo linaje de profetas entre los Hijos de Israel, entre ellos Yusuf, Musa, Dawud e Isa, la paz sea con todos ellos. El nacimiento de Ishaq muestra que Allah cumple Sus promesas a Su debido tiempo, incluso cuando toda causa visible parece decir que es demasiado tarde.$tk$, $tk$Nunca pienses que es demasiado tarde para que una súplica sea respondida. La generosidad con los huéspedes y la confianza en Allah abren puertas que parecían cerradas.$tk$, $tk$["11:69-73","37:112-113","51:24-30","14:39","21:72-73"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$yaqub$tk$, 'es', 10, $tk$Yaqub (Jacob)$tk$, $tk$يعقوب$tk$, $tk$El padre cuya paciencia fue hermosa$tk$, $tk$Yaqub, la paz sea con él, es hijo de Ishaq y nieto de Ibrahim, la paz sea con ellos. Se lo conoce también como Israil, y a sus descendientes se los llama los Hijos de Israel. El Corán habla de él sobre todo como padre, en la historia de su hijo Yusuf.

Cuando el joven Yusuf le contó un sueño en el que once estrellas, el sol y la luna se postraban ante él, Yaqub comprendió que Allah había escogido a ese niño. Le aconsejó que no se lo contara a sus hermanos, por temor a que los celos los empujaran a tramar algo contra él.

Los hermanos, en efecto, tramaron. Pidieron llevarse a Yusuf con ellos. Yaqub dijo que le entristecía dejarlo ir y que temía que se lo comiera un lobo. Por la noche volvieron llorando, con sangre falsa en la camisa de Yusuf. Yaqub no creyó su historia. Les dijo que sus propias almas los habían llevado a hacer algo, y eligió una hermosa paciencia, pidiendo ayuda solo a Allah.

Pasaron los años. Cuando un segundo hijo fue retenido en Egipto, el dolor regresó. Yaqub se apartó y se lamentó por Yusuf, y sus ojos se volvieron blancos de la pena, que guardaba dentro. Sus hijos le reprocharon que siguiera pensando en Yusuf. Él respondió que solo se quejaba de su tristeza y su pesar ante Allah, y que sabía por Allah lo que ellos no sabían.

Luego les dio este consejo: id y buscad a Yusuf y a su hermano, y no desesperéis de la misericordia de Allah.

Su esperanza fue recompensada. Yusuf, convertido en un alto funcionario de Egipto, envió su camisa para que la pusieran sobre el rostro de su padre. Cuando la caravana salía de Egipto, Yaqub dijo que percibía el olor de Yusuf. Cuando le pusieron la camisa sobre el rostro, recobró la vista. Sus hijos le pidieron que rogara por su perdón, y él prometió hacerlo. Toda la familia se reunió en Egipto.

El Corán recoge también la última preocupación de Yaqub. Al acercarse la muerte, preguntó a sus hijos qué adorarían después de él. Respondieron que adorarían a su Dios y al Dios de sus padres, Ibrahim, Ismail e Ishaq, un Dios único.$tk$, $tk$La tristeza no es falta de fe: lleva tu dolor a Allah y sigue esperando. Nunca desesperes de Su misericordia.$tk$, $tk$["2:132-133","12:4-6","12:83-87","12:93-100"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$yusuf$tk$, 'es', 11, $tk$Yusuf (José)$tk$, $tk$يوسف$tk$, $tk$El veraz, del pozo a los graneros de Egipto$tk$, $tk$La historia de Yusuf, la paz sea con él, ocupa una sura entera del Corán. De niño soñó que once estrellas, el sol y la luna se postraban ante él. Su padre Yaqub, la paz sea con él, le dijo que ocultara el sueño a sus hermanos.

Los hermanos tenían celos del amor de su padre por Yusuf. Se lo llevaron y lo arrojaron al fondo de un pozo, y luego dijeron a su padre que se lo había comido un lobo. Unos viajeros que pasaban sacaron a Yusuf del pozo, y fue vendido en Egipto por unas pocas monedas.

Creció en casa de un alto funcionario egipcio. Cuando se hizo hombre, la esposa de ese funcionario intentó seducirlo. Yusuf buscó refugio en Allah y corrió hacia la puerta; ella le rasgó la camisa por detrás, lo que probó su inocencia. Aun así fue enviado a prisión. Él mismo había dicho que prefería la prisión a aquello a lo que lo invitaban.

En la prisión, Yusuf era conocido por su bondad. Interpretó los sueños de dos compañeros de cárcel y aprovechó la ocasión para hablarles del Dios único. Uno de ellos fue liberado, pero olvidó mencionar a Yusuf ante su señor, y Yusuf siguió en prisión varios años.

Entonces el rey tuvo un sueño: siete vacas gordas devoradas por siete flacas, y siete espigas verdes junto a otras secas. Yusuf lo explicó: siete años de buenas cosechas y luego siete años duros, de modo que había que almacenar el grano. Antes de salir de prisión, pidió que se estableciera su inocencia, y la esposa del funcionario reconoció la verdad. Yusuf pidió que lo pusieran al frente de los graneros del país, y los administró con cuidado.

Cuando llegó la hambruna, sus hermanos viajaron a Egipto en busca de alimento. Yusuf los reconoció, pero ellos no lo reconocieron a él. Tras varios viajes, reveló quién era. Ellos reconocieron su falta. Él respondió que aquel día no había reproche contra ellos y que esperaba que Allah los perdonara.

Yusuf hizo venir entonces a Egipto a sus padres y a toda su familia. El sueño de su infancia se había cumplido. Terminó con una súplica, pidiendo a su Señor que lo hiciera morir sometido a Él y lo reuniera con los justos.$tk$, $tk$Mantente honrado y puro tanto si estás abajo como si estás arriba. Cuando por fin tengas poder sobre quienes te hicieron daño, el perdón es la elección más noble.$tk$, $tk$["12:4-21","12:23-35","12:36-57","12:88-101"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$ayyub$tk$, 'es', 12, $tk$Ayyub (Job)$tk$, $tk$أيوب$tk$, $tk$El modelo de la paciencia$tk$, $tk$Ayyub, la paz sea con él, es el profeta cuyo nombre se ha convertido en símbolo de paciencia. El Corán lo cuenta entre los profetas que recibieron la revelación y entre los descendientes de Ibrahim a los que Allah guio.

El Corán cuenta su historia en unas pocas aleyas, sin muchos detalles. Ayyub fue golpeado por una dura prueba que afectó a su salud y a su familia. El Corán no describe su enfermedad, ni dice cuánto duró. Se han contado muchas historias al respecto, algunas exageradas e indignas de un profeta; no están establecidas y las dejamos de lado.

Lo que el Corán ha conservado es la manera en que Ayyub habló a su Señor. No se quejó ante la gente, ni acusó a Allah. Simplemente clamó que la adversidad lo había alcanzado, y que Allah es el más Misericordioso de los misericordiosos. En otro pasaje dice que Satanás lo había afligido con angustia y sufrimiento. Su súplica no contiene ninguna exigencia: describe su estado, alaba la misericordia de su Señor y Le deja el resto.

Allah le respondió. Le dijo que golpeara el suelo con el pie: brotó un manantial de agua fresca, para lavarse y para beber. Su sufrimiento desapareció. Allah le devolvió a su familia y otros tantos con ellos, como misericordia Suya y recordatorio para quienes adoran y para la gente de entendimiento.

El Corán menciona también que Ayyub había hecho un juramento durante su prueba. Allah le mostró una manera suave de cumplir su palabra sin hacer daño: tomar en la mano un manojo de hierba y golpear con él. El Corán no explica en detalle las circunstancias de ese juramento.

El pasaje termina con el elogio del propio Allah: halló a Ayyub paciente, un siervo excelente, que siempre se volvía hacia Él.

La paciencia de Ayyub no fue silencio ni ausencia de dolor. Sintió su sufrimiento y lo dijo, pero se lo dijo a Allah, con respeto y esperanza. Su historia ha consolado durante siglos a enfermos y afligidos, porque muestra que una prueba no es señal de rechazo por parte de Allah, y que el alivio puede venir de donde nadie lo espera.$tk$, $tk$En la adversidad, habla a Allah de tu dolor sin perder el respeto ni la esperanza. La paciencia no significa no sentir nada; significa seguir siendo fiel mientras duele.$tk$, $tk$["21:83-84","38:41-44","4:163","6:84"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$shuayb$tk$, 'es', 13, $tk$Shuayb$tk$, $tk$شعيب$tk$, $tk$El profeta del comercio honrado$tk$, $tk$Shuayb, la paz sea con él, fue enviado al pueblo de Madyan. El Corán lo llama su hermano, pues era uno de ellos. Menciona también su predicación a la gente de la Espesura; los sabios difieren sobre si era el mismo pueblo que Madyan o un grupo vecino.

La gente de Madyan era próspera, pero su comercio se basaba en el engaño. Daban menos de lo debido al medir y al pesar, y privaban a la gente de lo que le pertenecía. Además se apostaban en los caminos para amenazar a la gente y apartar a los creyentes de la senda de Allah.

Shuayb los llamó primero a adorar solo a Allah. Luego les habló de sus negocios cotidianos: dad la medida y el peso completos con justicia, no defraudéis a la gente en sus bienes y no sembréis la corrupción en la tierra después de haber sido puesta en orden. Les dijo que lo que Allah les deja como ganancia honrada es mejor para ellos. Les recordó que en otro tiempo habían sido pocos y que Allah los había multiplicado.

Su respuesta fue burlona. ¿Acaso su oración le ordenaba que ellos abandonaran lo que adoraban sus padres, o que dejaran de hacer lo que quisieran con su propio dinero? Shuayb respondió con palabras que se han hecho célebres: no quería hacer él mismo lo que les prohibía; solo quería arreglar las cosas en la medida de lo posible, y su éxito dependía solo de Allah, en quien confiaba.

Les advirtió que su oposición a él no les acarreara una suerte como la de los pueblos de Nuh, Hud, Salih o Lut. Los invitó a pedir perdón, diciendo que su Señor es misericordioso y afectuoso.

Los jefes pasaron a las amenazas. Dijeron que no entendían gran cosa de lo que decía, que lo veían débil entre ellos, y que de no ser por su familia lo habrían lapidado. Amenazaron con expulsarlo a él y a los creyentes a menos que volvieran a su religión.

Llegó el castigo. El Corán habla de un terremoto y de un estruendo terrible que los dejaron sin vida en sus casas, y del castigo del día de la nube oscura. Shuayb y los que creyeron con él fueron salvados por la misericordia de Allah.$tk$, $tk$La fe se nota en la manera en que compramos, vendemos y trabajamos: da a cada uno lo que le corresponde. Practica lo que pides a los demás.$tk$, $tk$["7:85-93","11:84-95","26:176-191","29:36-37"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$musa$tk$, 'es', 14, $tk$Musa (Moisés)$tk$, $tk$موسى$tk$, $tk$Aquel a quien Allah habló$tk$, $tk$Musa, la paz sea con él, es el profeta más mencionado en el Corán. Nació en Egipto en una época en que el Faraón oprimía a los Hijos de Israel y hacía matar a sus hijos varones recién nacidos. Allah inspiró a la madre de Musa que pusiera a su bebé en el río, prometiéndole que se lo devolvería. La gente de la casa del Faraón lo recogió, y la esposa del Faraón pidió que lo dejaran vivir. Como el bebé rechazaba a todas las nodrizas, fue devuelto a su propia madre para que lo amamantara.

De joven, Musa golpeó a un egipcio que peleaba con un hombre de su pueblo, y el hombre murió. Musa no había querido matarlo; se arrepintió enseguida y pidió perdón a Allah. Huyó a Madyan. Allí ayudó a dos mujeres a abrevar su rebaño, luego se sentó a la sombra y rogó diciendo que necesitaba cualquier bien que Allah le enviara. El padre de ellas lo acogió, le dio en matrimonio a una de sus hijas, y Musa trabajó para él durante años.

En el camino de regreso con su familia, vio un fuego cerca del monte Tur. Allí Allah le habló, lo hizo Su mensajero y le dio signos: su bastón se convirtió en serpiente y su mano resplandeció blanca. Musa pidió que su hermano Harun fuera enviado con él. Allah les dijo que fueran al Faraón y le hablaran con suavidad.

El Faraón se negó a escuchar y convocó a sus magos. Pero cuando vieron que el bastón de Musa se tragaba sus trucos, reconocieron la verdad y declararon su fe, a pesar de las amenazas del Faraón.

Allah ordenó entonces a Musa que partiera de noche con su pueblo. El Faraón los persiguió con su ejército hasta el mar. La gente fue presa del pánico, pero Musa respondió que su Señor estaba con él y lo guiaría. Golpeó el mar con su bastón; se abrió, y cruzaron. El Faraón y sus soldados se ahogaron.

Musa fue después al encuentro de su Señor durante cuarenta noches y recibió las Tablas. En su ausencia, parte de su pueblo empezó a adorar un becerro hecho con sus joyas. Musa volvió enojado y apenado, y los llamó al arrepentimiento.

Durante el resto de su vida, Musa guio a su pueblo con paciencia, portando la Torá, una guía y una luz.$tk$, $tk$Nadie es demasiado débil para ser elegido para algo grande, y ningún tirano es demasiado fuerte para caer. Cuando te sientas atrapado, recuerda que Allah está con quienes confían en Él.$tk$, $tk$["28:3-35","20:9-79","26:52-68","7:142-145","2:51-54"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$harun$tk$, 'es', 15, $tk$Harun (Aarón)$tk$, $tk$هارون$tk$, $tk$El hermano y ayudante de Musa$tk$, $tk$Harun, la paz sea con él, es hermano de Musa, la paz sea con él. En el Corán su historia va siempre unida a la de Musa: es el profeta que fue dado como apoyo a otro profeta.

Cuando Allah habló a Musa y lo envió al Faraón, Musa midió el peso de la misión. Pidió a su Señor que le abriera el corazón, que le facilitara la tarea y que le soltara la lengua para que la gente lo entendiera. Luego pidió un ayudante de su propia familia: Harun, su hermano, para que lo fortaleciera y compartiera su tarea. Musa dijo que Harun era más elocuente que él. Allah concedió la petición, y el Corán dice que, por Su misericordia, Allah dio a Musa a su hermano Harun como profeta.

Los dos hermanos fueron juntos al Faraón. Allah les había dicho que le hablaran con suavidad, con la esperanza de que recapacitara o temiera. Le pidieron que dejara marchar a los Hijos de Israel y que dejara de atormentarlos. Cuando los magos del Faraón vieron la verdad, declararon que creían en el Señor de Harun y Musa.

Tras el paso del mar, Musa fue al encuentro de su Señor durante cuarenta noches. Antes de partir, pidió a Harun que ocupara su lugar entre el pueblo, que obrara rectamente y que no siguiera el camino de los que siembran la corrupción.

Durante esa ausencia llegó la prueba del becerro. Un hombre al que el Corán llama el Samirí extravió al pueblo con un becerro hecho con sus joyas. El Corán deja claro que Harun no participó en ello. Les dijo que con aquello se los estaba poniendo a prueba, que su Señor era el Misericordioso, y que debían seguirlo y obedecerlo. Se negaron a escuchar hasta que Musa regresara.

Cuando Musa volvió, enojado y apenado, agarró a su hermano por la cabeza. Harun le respondió con ternura, llamándolo hijo de mi madre. Explicó que el pueblo lo había dominado y había estado a punto de matarlo, y que había temido dividir a los Hijos de Israel. Musa pidió entonces a Allah que lo perdonara a él y a su hermano y que los admitiera a ambos en Su misericordia.

En otro lugar, el Corán cuenta a Harun entre los profetas que fueron guiados y recompensados por hacer el bien.$tk$, $tk$Apoyar la misión de otro es tan noble como dirigirla. En un conflicto con alguien cercano, responde con dulzura y explícate con calma.$tk$, $tk$["20:29-36","28:34-35","20:90-94","7:150-151","19:53"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$dhul-kifl$tk$, 'es', 16, $tk$Dhul-Kifl$tk$, $tk$ذو الكفل$tk$, $tk$Contado entre los pacientes y los mejores$tk$, $tk$Dhul-Kifl, la paz sea con él, es una de las figuras de las que el Corán nos dice menos. Solo se lo menciona dos veces, cada una en una sola aleya y junto a otros profetas.

En la sura al-Anbiya se lo nombra con Ismail e Idris. El Corán dice que todos ellos estaban entre los pacientes, que Allah los admitió en Su misericordia y que estaban entre los justos. En la sura Sad se lo nombra con Ismail y Al-Yasa, y el Corán dice que todos ellos estaban entre los mejores.

Eso es todo lo que dice el Corán. No nos dice dónde ni cuándo vivió, a qué pueblo fue enviado ni qué hizo. Tampoco ningún hadiz auténtico añade un detalle claro sobre su vida.

Su propio nombre ha sido objeto de discusión. En árabe, Dhul-Kifl significa algo así como el de la porción, o el que asumió un compromiso. Algunos comentaristas han sugerido que recibió ese nombre porque asumió un deber pesado y lo cumplió fielmente, pero eso es una explicación de la palabra, no un relato establecido. Otros han intentado identificarlo con figuras conocidas de otras tradiciones; esas propuestas son conjeturas, y ninguna descansa en pruebas firmes.

La mayoría de los sabios considera que fue un profeta, porque el Corán lo nombra y lo elogia entre profetas. Unos pocos sabios han sostenido que fue un hombre justo más que un profeta. En ambas opiniones, es un siervo al que el propio Allah ha elogiado, y ese es el mayor honor.

Vale la pena fijarse en qué cualidades eligió mencionar el Corán. La primera es la paciencia: la capacidad de seguir haciendo lo correcto durante mucho tiempo, sin rendirse cuando las cosas se ponen difíciles. La segunda es la rectitud. La tercera es ser contado entre los mejores, en compañía de profetas como Ismail y Al-Yasa.

Así pues, es mejor decir con honradez que no conocemos los detalles de su vida que llenar el silencio con leyendas. El Corán no siempre enseña mediante largos relatos. A veces un nombre y una palabra de elogio bastan para recordarnos que Allah conoce a Sus siervos fieles, incluidos aquellos cuya historia nadie ha puesto por escrito.$tk$, $tk$No hace falta ser famoso para ser valioso a los ojos de Allah. Él advierte la paciencia y la fidelidad a tus compromisos, incluso cuando nadie más las ve.$tk$, $tk$["21:85-86","38:48"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$dawud$tk$, 'es', 17, $tk$Dawud (David)$tk$, $tk$داود$tk$, $tk$Profeta, rey y adorador ferviente$tk$, $tk$Dawud, la paz sea con él, aparece por primera vez en el Corán en un campo de batalla. Los Hijos de Israel, dirigidos por su rey Talut, se enfrentaban al ejército de Yalut. Los creyentes eran pocos, pero pidieron a Allah paciencia y firmeza. Derrotaron a sus enemigos con el permiso de Allah, y Dawud mató a Yalut. Allah le dio entonces la realeza y la sabiduría y le enseñó lo que quiso.

Dawud llegó a ser a la vez profeta y rey. Allah le dio el Zabur, los Salmos. El Corán lo describe como un siervo de gran fuerza que se volvía constantemente hacia su Señor. Cuando glorificaba a Allah, las montañas y los pájaros repetían las alabanzas con él, al atardecer y al amanecer.

Allah también ablandó el hierro para él y le enseñó a hacer cotas de malla con eslabones bien medidos, para proteger a la gente en la batalla. Aunque era rey, un hadiz nos dice que Dawud solo comía de lo que ganaba con el trabajo de sus propias manos (Sahih al-Bukhari, n.º 2072).

Su reino fue fortalecido, y se le dio sabiduría y buen juicio al hablar. Pero el Corán cuenta también un momento en que fue puesto a prueba. Dos hombres en litigio entraron en su oratorio y le pidieron que juzgara entre ellos. Dawud dio su respuesta, y luego comprendió que Allah lo estaba probando. Pidió perdón a su Señor, cayó postrado y se arrepintió, y Allah lo perdonó. El Corán no da más detalles sobre esta prueba, y las historias que se le han añadido no son dignas de un profeta.

Después de esto, Allah se dirigió a él directamente: lo había hecho sucesor en la tierra, de modo que debía juzgar entre la gente con la verdad y no seguir sus propios deseos.

El Corán menciona también un caso sobre un campo dañado de noche por las ovejas de unas gentes. Dawud y su hijo Sulayman dictaron ambos una sentencia, y Allah dio a Sulayman la mejor comprensión del caso, aunque los dos habían recibido sabiduría y conocimiento.

Dawud reúne así cosas que solemos considerar separadas: el poder y la humildad, la destreza de un artesano y la devoción de un adorador.$tk$, $tk$Sea cual sea la responsabilidad que tengas, sé justo y no dejes que tus propios deseos decidan por ti. Cuando te des cuenta de que te equivocaste, vuélvete hacia Allah de inmediato.$tk$, $tk$["2:251","38:17-26","21:78-80","34:10-11","17:55"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$sulayman$tk$, 'es', 18, $tk$Sulayman (Salomón)$tk$, $tk$سليمان$tk$, $tk$El rey que respondía a cada don con gratitud$tk$, $tk$Sulayman, la paz sea con él, era hijo de Dawud, la paz sea con él, y heredó de él la profecía y la realeza. El Corán lo llama un siervo excelente que se volvía constantemente hacia Allah. Pidió a su Señor que lo perdonara y le concediera un reino como nadie tendría después de él.

Allah respondió a su súplica. Puso a su servicio el viento, que soplaba por orden suya hacia donde él lo dirigía. Unos genios trabajaban para él como constructores y buceadores y hacían lo que él quería. Se le enseñó el lenguaje de las aves, y su ejército estaba formado por genios, hombres y aves, alineados en filas.

Un día ese ejército llegó a un valle de hormigas. Una hormiga avisó a las demás de que entraran en sus moradas para que Sulayman y sus soldados no las aplastaran sin darse cuenta. Sulayman la entendió y sonrió. En lugar de enorgullecerse, pidió a Allah que lo ayudara a agradecer Sus favores y a hacer buenas obras que Le complacieran.

En otra ocasión, notó que faltaba la abubilla. El ave volvió con noticias de Saba: allí reinaba una reina, con un gran trono, y ella y su pueblo se postraban ante el sol en lugar de ante Allah. Sulayman le envió una carta, que empezaba con el nombre de Allah, el Compasivo, el Misericordioso, invitándolos a venir a él sometidos.

La reina consultó a sus consejeros y eligió la prudencia. Envió un regalo, que Sulayman rechazó: lo que Allah le había dado era mejor. Antes de que ella llegara, su trono le fue traído en un abrir y cerrar de ojos por uno que tenía conocimiento de la Escritura. Al verlo ante sí, Sulayman dijo que aquello era un favor de su Señor, para probar si sería agradecido o ingrato.

Cuando la reina entró en su palacio, tomó por agua el suelo de cristal pulido. Comprendió que se había equivocado en muchas cosas, y declaró que se sometía, con Sulayman, a Allah, el Señor de los mundos.

El Corán habla también de su muerte. Murió apoyado en su bastón, y los genios siguieron trabajando, sin saberlo, hasta que una pequeña criatura de la tierra carcomió el bastón y él cayó. Comprendieron entonces que no conocían lo oculto.$tk$, $tk$Cuanto más recibas, más agradecido y humilde debes ser. Toda capacidad es una prueba de lo que harás con ella.$tk$, $tk$["27:15-44","21:81-82","34:12-14","38:30-40"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$ilyas$tk$, 'es', 19, $tk$Ilyas (Elías)$tk$, $tk$إلياس$tk$, $tk$El mensajero que llamó a su pueblo a apartarse de Baal$tk$, $tk$Ilyas, la paz sea con él, es mencionado en dos pasajes del Corán. El primero, en la sura al-An'am, lo nombra en una lista de profetas, junto con Zakariyya, Yahya e Isa, y dice que todos ellos estaban entre los justos. El segundo, en la sura as-Saffat, ofrece el breve relato de su misión.

El Corán dice que Ilyas era uno de los mensajeros. Habló a su pueblo y les preguntó si no iban a temer a Allah. Adoraban a un ídolo llamado Baal. Ilyas les preguntó cómo podían invocar a Baal y abandonar al mejor de los creadores: Allah, su Señor y el Señor de sus antepasados.

Su argumento era sencillo y claro. Aquel que los creó a ellos y creó antes a sus antepasados es el único que merece ser adorado. Un ídolo no ha creado nada, y volverse hacia él es olvidar a Aquel a quien deben su existencia.

El Corán nos dice luego que su pueblo lo rechazó. Por eso se les pedirán cuentas, salvo a los siervos sinceros de Allah. Esto significa que algunas personas, aunque fueran pocas, sí lo escucharon y permanecieron fieles.

El pasaje termina con un homenaje. Allah dejó para Ilyas una mención honrosa entre las generaciones posteriores y envió la paz sobre él. Dice que así es como Él recompensa a quienes hacen el bien, y que Ilyas era uno de Sus siervos creyentes.

El Corán no da más detalles. No nombra al pueblo de Ilyas, la tierra donde vivió ni la época de su misión, y no describe cómo terminó su vida. Los comentaristas lo sitúan por lo general entre los profetas enviados a los Hijos de Israel, y otras tradiciones cuentan largas historias sobre él, pero esos relatos no están confirmados por el Corán ni por hadices auténticos. Por eso nos atenemos a lo que es seguro.

Lo que es seguro ya es rico en significado. Ilyas se plantó ante su pueblo y les hizo una pregunta que cada generación puede hacerse: ¿qué ponemos en el lugar de nuestro Creador? Puede que el ídolo ya no sea una estatua; puede ser cualquier cosa a la que obedezcamos o amemos más que a Allah. Muchos siglos después, su nombre se sigue pronunciando con un saludo de paz.$tk$, $tk$Pregúntate con honradez qué ocupa el primer lugar en tu corazón. Decir la verdad vale la pena aunque solo unos pocos escuchen.$tk$, $tk$["37:123-132","6:85"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$al-yasa$tk$, 'es', 20, $tk$Al-Yasa (Eliseo)$tk$, $tk$اليسع$tk$, $tk$Contado entre los elegidos y los mejores$tk$, $tk$Al-Yasa, la paz sea con él, es un profeta al que el Corán menciona solo dos veces, y cada vez muy brevemente. No hay ningún relato sobre él en el Corán: solo su nombre, colocado entre otros profetas, y palabras de elogio.

La primera mención está en la sura al-An'am. Después de hablar de Ibrahim, Allah enumera a muchos de los profetas que Él guio. Entre ellos figuran Ismail, Al-Yasa, Yunus y Lut, y el Corán dice que Allah los favoreció a todos por encima de todas las gentes. Un poco más adelante, el pasaje dice al Profeta Muhammad ﷺ que esos son aquellos a quienes Allah guio, y que debe seguir su guía.

La segunda mención está en la sura Sad. Allah dice al Profeta ﷺ que recuerde a Ismail, Al-Yasa y Dhul-Kifl, y dice que todos ellos estaban entre los mejores.

Esto es todo lo que el Corán dice de él. No se nos dice a qué pueblo fue enviado, cuándo vivió, qué dijo a su pueblo ni cómo le respondieron. Ningún hadiz auténtico ofrece un relato de su vida. Los comentaristas lo sitúan por lo general entre los profetas de los Hijos de Israel, después de Ilyas, y otras tradiciones cuentan historias sobre él. Como esas historias no están confirmadas por el Corán ni por hadices auténticos, no las presentamos como hechos.

Es mejor aceptar este silencio que llenarlo. El propio Corán dice en otro lugar que hay mensajeros cuyas historias Allah ha contado y otros cuyas historias no ha contado. Creer en todos los profetas no exige conocer los detalles de cada vida.

Aun así, las dos aleyas nos enseñan algo. A Al-Yasa se lo describe como elegido, guiado, favorecido y entre los mejores. Estas palabras las da el propio Allah, que sabe lo que hay en cada corazón. Y al Profeta Muhammad ﷺ se le dice que siga la guía de estos profetas, lo que significa que el camino de Al-Yasa era el mismo que el de todos los demás: adorar solo a Allah y hacer el bien.

Su nombre en el Corán es como una señal discreta. Nos recuerda que la cadena de los profetas es larga, que cada uno de ellos llevó el mismo mensaje, y que a muchas personas que hicieron un gran bien solo Allah las conoce plenamente.$tk$, $tk$Haz el bien sin esperar a que se cuente tu historia. Estar entre los mejores a los ojos de Allah importa más que ser conocido por la gente.$tk$, $tk$["6:86","38:48"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$yunus$tk$, 'es', 21, $tk$Yunus (Jonás)$tk$, $tk$يونس$tk$, $tk$El hombre del pez$tk$, $tk$Yunus, la paz sea con él, fue enviado como mensajero a un pueblo que, según el Corán, contaba cien mil personas o más. El Corán lo llama también Dhun-Nun, el hombre del pez.

Su historia empieza con una partida. Yunus se marchó enojado. El Corán no lo oculta: dice que se fue pensando que Allah no lo pondría en apuros. Los profetas son los mejores de los hombres, y el Corán nos muestra cómo vuelven a Allah cuando tropiezan.

Yunus subió a un barco cargado. A bordo se echó a suertes, y él estuvo entre los que perdieron. Fue arrojado al mar, y un gran pez se lo tragó. El Corán dice que en ese momento era digno de reproche.

En las tinieblas, Yunus invocó a su Señor. Declaró que no hay más dios que Allah, Lo glorificó y reconoció que había estado entre los injustos. No puso ninguna excusa ni culpó a nadie más. Esta breve súplica es una de las más célebres del Corán.

Allah le respondió y lo salvó de su angustia, y el Corán añade que así es como Él salva a los creyentes. Dice también que si Yunus no hubiera sido de los que glorifican a Allah, se habría quedado en el vientre del pez hasta el Día de la Resurrección.

Fue arrojado a una orilla desnuda, enfermo y débil, y Allah hizo crecer sobre él una planta de calabaza. El Corán dice luego que fue enviado a su pueblo, que creyeron, y que Allah los dejó disfrutar de la vida por un tiempo. El Corán señala que el pueblo de Yunus es un caso especial: creyeron a tiempo, y su fe los protegió de un castigo humillante.

El Corán no nombra la ciudad de Yunus ni dice cuánto tiempo permaneció dentro del pez, y no necesitamos saberlo.

Allah dice al Profeta Muhammad ﷺ que tenga paciencia y no sea como el compañero del pez cuando clamó angustiado. Dice también que su Señor escogió a Yunus y lo puso entre los justos. Su historia encierra, pues, a la vez una advertencia contra la impaciencia y una gran esperanza.$tk$, $tk$No abandones un deber por frustración. Y si has tropezado, ninguna oscuridad es demasiado profunda: reconoce tu error e invoca a Allah.$tk$, $tk$["37:139-148","21:87-88","10:98","68:48-50"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$zakariyya$tk$, 'es', 22, $tk$Zakariyya (Zacarías)$tk$, $tk$زكريا$tk$, $tk$El siervo que nunca desesperó de su súplica$tk$, $tk$Zakariyya, la paz sea con él, fue un profeta entre los Hijos de Israel. El Corán lo presenta primero como el tutor de Maryam, la madre de Isa, la paz sea con ellos. Ella había sido consagrada al servicio de Allah, y Zakariyya fue el encargado de cuidarla.

Cada vez que iba a verla al lugar donde rezaba, encontraba alimento junto a ella. Le preguntó de dónde venía. Ella respondió que venía de Allah, que provee sin medida a quien Él quiere.

Esta respuesta lo conmovió profundamente. Zakariyya era un hombre muy anciano, y su esposa nunca había podido tener hijos. Sin embargo, al ver la generosidad de Allah con Maryam, se volvió hacia su Señor allí mismo y pidió un buen hijo.

El Corán recoge esta súplica con ternura. Zakariyya invocó a su Señor en voz baja. Dijo que sus huesos se habían debilitado y que su cabello había encanecido, pero que nunca había quedado decepcionado al rogarle. Le preocupaban los que vendrían después de él, y pidió un heredero que fuera grato a Allah. Dijo también: Señor mío, no me dejes solo, y Tú eres el mejor de los herederos.

La respuesta llegó mientras estaba de pie rezando. Los ángeles le anunciaron un hijo llamado Yahya, un nombre que Allah no había dado a nadie antes. Sería noble, casto y un profeta de entre los justos.

Zakariyya se asombró: ¿cómo iba a tener un hijo a su edad, con una esposa que no podía tener hijos? Se le dijo que eso es fácil para Allah, que hace lo que quiere. Pidió un signo. El signo fue que no hablaría a la gente durante tres días, salvo por gestos, aunque estaba sano. Salió ante su pueblo y les indicó por señas que glorificaran a Allah mañana y tarde.

El Corán dice que Allah le respondió, le dio a Yahya y curó a su esposa. Luego explica por qué fue honrada esta familia: se apresuraban a hacer buenas obras, invocaban a Allah con esperanza y temor, y eran humildes ante Él.$tk$, $tk$Sigue pidiendo a Allah con esperanza, sea cual sea tu edad o tu situación. El bien que ves en otros puede ser una invitación a pedir más tú mismo.$tk$, $tk$["3:37-41","19:2-11","21:89-90"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$yahya$tk$, 'es', 23, $tk$Yahya (Juan)$tk$, $tk$يحيى$tk$, $tk$Sabio desde la infancia, tierno y puro$tk$, $tk$Yahya, la paz sea con él, es hijo de Zakariyya, la paz sea con él. Nació en respuesta a la súplica de su anciano padre, cuando nada parecía hacerlo posible. El propio Allah eligió su nombre, y el Corán dice que nadie había recibido ese nombre antes que él.

El Corán no cuenta los acontecimientos de su vida como un relato. Ofrece en cambio un retrato de su carácter, en unas pocas aleyas de la sura Maryam, y este retrato es uno de los más hermosos del Libro.

Allah le ordenó que se aferrara con firmeza a la Escritura, y le dio sabiduría cuando todavía era un niño. Yahya no esperó a hacerse mayor para tomarse en serio su fe: desde sus primeros años comprendió lo que Allah le pedía y se aferró a ello con fuerza.

Allah le dio también ternura de Su parte y pureza. Temía a Allah. Era bondadoso con sus padres, y no era ni arrogante ni desobediente. En la sura Al Imran, los ángeles lo anuncian a Zakariyya como alguien que confirmaría una palabra procedente de Allah, y como noble, casto y profeta de entre los justos. Los comentaristas explican que la palabra procedente de Allah se refiere a Isa, la paz sea con él, cuya misión confirmó Yahya.

En otro lugar, el Corán nombra a Yahya con Zakariyya, Isa e Ilyas, y dice que todos ellos estaban entre los justos. En el hadiz sobre el Viaje Nocturno, el Profeta Muhammad ﷺ relata que encontró a Yahya y a Isa juntos en el segundo cielo, y que eran primos (Sahih al-Bukhari, n.º 3887).

El retrato termina con un saludo que Allah le dirige: paz sobre él el día en que nació, el día en que muera y el día en que sea resucitado. Son los tres momentos en que un ser humano es más vulnerable, y a Yahya se le promete seguridad en cada uno de ellos.

El Corán no describe cómo llamó Yahya a su pueblo ni cómo murió. En otras fuentes existen relatos sobre su muerte, pero no se encuentran en el Corán, y no los presentamos como seguros.

Yahya muestra que la fuerza y la dulzura van juntas. Era firme con la Escritura y suave con la gente, serio en su fe y bueno con sus padres.$tk$, $tk$Nunca eres demasiado joven para tomarte en serio tu fe y tus valores. Sé firme en lo que es justo y dulce con las personas, empezando por tus padres.$tk$, $tk$["19:12-15","3:39","21:90","6:85"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$isa$tk$, 'es', 24, $tk$Isa (Jesús)$tk$, $tk$عيسى$tk$, $tk$El Mesías, hijo de Maryam$tk$, $tk$Isa, la paz sea con él, es uno de los más grandes mensajeros de Allah. El Corán lo llama el Mesías, hijo de Maryam (María), y da a su madre un lugar único: una sura entera lleva su nombre.

Maryam era una joven pura y devota. Un día, cuando se había retirado de su familia para adorar, se le apareció un ángel y le anunció que tendría un hijo puro. Ella se asombró: ¿cómo iba a tener un hijo si ningún hombre la había tocado? El ángel respondió que eso es fácil para Allah, que crea lo que quiere. Cuando decide un asunto, solo le dice: Sé, y es.

Maryam dio a luz sola, junto al tronco de una palmera, con dolor y angustia. Fue consolada: un arroyo corría a sus pies, y del árbol caían dátiles frescos cuando lo sacudía.

Cuando volvió a su gente con el niño en brazos, la acusaron. Ella se limitó a señalarlo. El recién nacido habló entonces, con el permiso de Allah. Dijo que era el siervo de Allah, que Allah le había dado la Escritura y lo había hecho profeta, que lo había hecho bendito dondequiera que estuviera, y que le había prescrito la oración, la limosna y la bondad con su madre.

Isa fue enviado como mensajero a los Hijos de Israel. Confirmó la Torá que lo precedía y recibió el Evangelio. Allah lo apoyó con signos claros: con el permiso de Allah, curó al ciego y al leproso, dio vida a los muertos y modeló con barro un pájaro que se convirtió en un pájaro vivo. El Corán repite cada vez que esos milagros ocurrieron con el permiso de Allah.

Su mensaje era el mismo que el de todos los profetas: Allah es mi Señor y vuestro Señor, así que adoradlo; ese es el camino recto. Sus discípulos creyeron en él y declararon que se sometían a Allah. A petición de ellos, Isa rogó que descendiera del cielo, como signo, una mesa servida con alimento.

El Corán dice también que Isa anunció a un mensajero que vendría después de él. Cuando sus enemigos tramaron contra él, el Corán enseña que ni lo mataron ni lo crucificaron, aunque así les pareció, y que Allah lo elevó hacia Sí.

Los musulmanes aman y honran a Isa y a su madre.$tk$, $tk$Honra a tu madre y defiende la verdad con dulzura. La verdadera grandeza está en ser un siervo fiel de Allah y en llevar el bien allí donde estés.$tk$, $tk$["3:45-51","19:16-36","5:110-115","4:157-158","61:6"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$muhammad$tk$, 'es', 25, $tk$Muhammad ﷺ$tk$, $tk$محمد$tk$, $tk$El Sello de los Profetas, una misericordia para los mundos$tk$, $tk$El Profeta Muhammad ﷺ nació en La Meca hacia el año 570 d. C., en la tribu de Quraysh. Su padre murió antes de su nacimiento y su madre cuando era un niño pequeño, de modo que fue criado por su abuelo y luego por su tío Abu Talib. De joven era tan honrado que la gente lo llamaba al-Amin, el digno de confianza. Se casó con Khadija, que Allah esté complacido con ella, una respetada comerciante de La Meca.

Solía retirarse a la cueva de Hira, en una montaña cercana a La Meca, para reflexionar y adorar. Allí, cuando tenía unos cuarenta años, el ángel Yibril (Gabriel) le trajo las primeras palabras del Corán, ordenándole leer en el nombre de su Señor, que creó. Khadija fue la primera en creer en él.

Durante trece años llamó a la gente de La Meca a adorar solo a Allah, a ser honrados, a cuidar de los huérfanos y los pobres, y a abandonar los ídolos. Unos pocos lo siguieron, pero los jefes de Quraysh se le opusieron, y los creyentes sufrieron insultos, boicot y persecución. Él respondió con paciencia.

En 622 emigró a la ciudad de Yathrib, que pasó a ser Medina. Este viaje, la Hégira, marca el comienzo del calendario islámico. El Corán recuerda cómo, oculto en una cueva con su compañero Abu Bakr, le dijo que no se afligiera, pues Allah estaba con ellos.

En Medina construyó una mezquita, hermanó a los emigrantes de La Meca con la gente de Medina y organizó la vida de una comunidad. Los musulmanes tuvieron que defenderse varias veces, y el Profeta ﷺ concluyó además una tregua con Quraysh. Cuando esta se rompió, volvió a La Meca en el año 8 de la Hégira, casi sin combatir. Perdonó a quienes lo habían combatido durante años y retiró los ídolos de la Kaaba. La gente entró entonces en masa en la religión de Allah.

En el año 10 realizó su peregrinación de despedida. En Arafat habló a una gran multitud: les recordó que la vida, los bienes y el honor son sagrados, pidió el buen trato a las mujeres, y declaró abolidas las antiguas venganzas de sangre y la usura. Fue durante esta peregrinación cuando se reveló la aleya que anuncia que la religión había sido perfeccionada.

Murió en Medina en el año 11 de la Hégira, 632 d. C. El Corán lo llama el Mensajero de Allah y el último de los profetas, enviado como misericordia para los mundos.$tk$, $tk$Sé digno de confianza antes de hablar de la fe: el carácter abre los corazones. Cuando tengas la ventaja, elige la misericordia y el perdón.$tk$, $tk$["96:1-5","9:40","110:1-3","5:3","33:40","21:107"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.premium_content (kind, lang, payload) values ('hajj', 'es', $tk${"umrah":{"title":"La Umrah paso a paso","intro":"La Umrah es la visita a la Casa Sagrada en La Meca. Puede realizarse en casi cualquier época del año y solo lleva unas horas. Consta de cuatro actos, siempre en el mismo orden: entrar en ihram en el miqat, el tawaf alrededor de la Kaaba, el sa'y entre Safa y Marwa, y luego rasurarse o recortarse el cabello.\n\nEsta guía es un resumen. No sustituye a un maestro cualificado, ni a las instrucciones de las autoridades del lugar, que debes seguir siempre. Cuando las escuelas jurídicas difieren en un detalle, indicamos la práctica común: consulta tu caso con un sabio de tu confianza.","chapters":[{"id":"preparation","title":"Antes de partir","body":"Un buen viaje empieza en casa. Comienza por tu intención: viajas solo por Allah, no para que te vean ni te elogien. Arrepiéntete con sinceridad, salda tus deudas en la medida de lo posible y pide perdón a las personas a las que hayas podido agraviar. Paga el viaje con dinero lícito.\n\nDespués, aprende los ritos antes de salir. El peregrino que sabe lo que tiene que hacer está tranquilo, y puede entregar su corazón a la adoración en lugar de preocuparse. Lee esta guía varias veces y, si es posible, asiste a una clase con un maestro.\n\nPor último, prepara tu cuerpo y tus papeles: camina con regularidad en las semanas previas, revisa tu visa, tu permiso y tus vacunas, y lleva poco equipaje. Caminarás mucho, a menudo con calor y entre la multitud.","steps":["Haz sincera tu intención: este viaje es solo por Allah.","Arrepiéntete, salda tus deudas y pide perdón a quienes te rodean.","Aprende los cuatro actos de la Umrah y su orden.","Revisa tu pasaporte, tu visa, tu permiso y las vacunas exigidas.","Averigua qué miqat está en tu ruta y cuándo llegarás a él.","Entrénate caminando y lleva cosas ligeras y cómodas."],"duas":[]},{"id":"miqat-ihram","title":"El miqat y el ihram","body":"El miqat es el límite que un peregrino no debe cruzar sin estar en ihram. Hay cinco: Dhul-Hulayfah para quienes vienen de Medina, al-Juhfah, Qarn al-Manazil, Yalamlam y Dhat Irq. En el avión, la tripulación suele anunciar el miqat: prepárate antes de ese momento.\n\nSe recomienda tomar un baño completo (ghusl) antes del ihram. Los hombres visten dos telas sin costuras, una alrededor de la cintura y otra sobre los hombros; las mujeres llevan su ropa recatada habitual. Después formula la intención en tu corazón y pronuncia la talbiyah. Los hombres la dicen en voz alta, las mujeres en voz baja.\n\nEl ihram es el estado, no la tela. En él no debes cortarte el cabello ni las uñas, usar perfume, cazar, contraer matrimonio ni tener relaciones conyugales. Los hombres no llevan ropa confeccionada a la medida del cuerpo ni se cubren la cabeza; las mujeres no llevan el velo del rostro (niqab) ni guantes (Sahih al-Bukhari 1838). Evita también las disputas (Corán 2:197).","steps":["Antes del miqat, córtate las uñas y toma un baño (ghusl) si puedes.","Hombres: pónganse las dos telas del ihram. Mujeres: conserven la ropa recatada habitual.","Los hombres pueden perfumarse el cuerpo, no las telas, antes de la intención; nunca después.","En el miqat, formula en tu corazón la intención de la Umrah y di: Labbayka Allahumma 'umrah.","Repite a menudo la talbiyah de camino a La Meca.","A partir de ahora, respeta todo lo que el ihram prohíbe.","Deja la talbiyah cuando empieces el tawaf."],"duas":[{"ar":"لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لاَ شَرِيكَ لَكَ","tr":"Labbayka Allahumma labbayk, labbayka la sharika laka labbayk, inna al-hamda wa an-ni'mata laka wa al-mulk, la sharika lak","t":"Aquí estoy, oh Allah, aquí estoy. Aquí estoy, no tienes asociado, aquí estoy. En verdad, toda alabanza y toda gracia son Tuyas, y toda la soberanía. No tienes asociado.","source":"La talbiyah — Sahih al-Bukhari 1549; Sahih Muslim 1184"}]},{"id":"tawaf","title":"El tawaf alrededor de la Kaaba","body":"El tawaf son siete vueltas alrededor de la Kaaba, manteniéndola a tu izquierda. Debes estar en estado de ablución. Cada vuelta empieza y termina en la Piedra Negra: ponte frente a ella, di el takbir, y bésala o tócala solo si resulta fácil; si no, basta con señalar hacia ella. Muchos peregrinos dicen allí « Bismillah, Allahu akbar », como se transmite del compañero Ibn Umar. Rodea por fuera el muro semicircular (el Hijr), no lo atravieses.\n\nEn este tawaf de llegada, los hombres descubren el hombro derecho (idtiba) y caminan a paso vivo, con pasos cortos, en las tres primeras vueltas (raml). Las mujeres caminan con normalidad.\n\nNo hay una súplica fija obligatoria para cada vuelta: puedes hacer cualquier dua, en cualquier idioma, recordar a Allah o recitar el Corán. Solo entre la esquina yemení y la Piedra Negra se transmite una súplica precisa: Corán 2:201. Después, reza dos rak'at detrás del Maqam Ibrahim (Corán 2:125), y luego bebe agua de Zamzam.","steps":["Asegúrate de tener la ablución. Los hombres descubren el hombro derecho (idtiba).","Empieza a la altura de la Piedra Negra: ponte frente a ella, di el takbir y señálala si no puedes alcanzarla.","Da siete vueltas con la Kaaba a tu izquierda, pasando por fuera del Hijr.","Los hombres caminan a paso vivo en las tres primeras vueltas (raml), y luego con normalidad.","Toca la esquina yemení si resulta fácil; entre ella y la Piedra Negra recita Corán 2:201.","Durante las vueltas, haz el dua que desees.","Tras la séptima vuelta, los hombres vuelven a cubrirse el hombro; reza dos rak'at detrás del Maqam Ibrahim, o en cualquier lugar de la mezquita si hay mucha gente.","Bebe agua de Zamzam y haz dua."],"duas":[{"ar":"اللَّهُ أَكْبَرُ","tr":"Allahu akbar","t":"Allah es el más Grande.","source":"Takbir a la altura de la Piedra Negra — Sahih al-Bukhari 1613"},{"ar":"رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةࣰ وَفِي ٱلۡأٓخِرَةِ حَسَنَةࣰ وَقِنَا عَذَابَ ٱلنَّارِ","tr":"Rabbana atina fi ad-dunya hasanatan wa fi al-akhirati hasanatan wa qina 'adhab an-nar","t":"Señor nuestro, danos el bien en esta vida y el bien en la Otra Vida, y protégenos del castigo del Fuego.","source":"Corán 2:201 — recitado entre la esquina yemení y la Piedra Negra: Sunan Abi Dawud 1892 (hasan)"}]},{"id":"say","title":"El sa'y entre Safa y Marwa","body":"Después del tawaf, dirígete a Safa. El sa'y son siete trayectos entre las dos colinas: de Safa a Marwa es un trayecto, de Marwa de vuelta a Safa es el segundo, y así sucesivamente. Por tanto, terminas en Marwa.\n\nAl acercarte a Safa por primera vez, recita el comienzo de Corán 2:158, como hizo el Profeta Muhammad ﷺ (Sahih Muslim 1218). Sube un poco, ponte de cara a la Kaaba, levanta las manos, proclama la grandeza y la unicidad de Allah con las palabras que figuran más abajo, y luego haz tu propio dua. Esto se hace tres veces. Haz lo mismo en Marwa cada vez que llegues.\n\nEntre las dos luces verdes, los hombres aprietan el paso; las mujeres caminan con normalidad. Como en el tawaf, no se impone ninguna súplica particular para cada trayecto. Se recomienda la ablución, y las personas mayores o enfermas pueden usar una silla de ruedas.","steps":["Ve a Safa y recita el comienzo de Corán 2:158 al acercarte, solo esta primera vez.","En Safa, ponte de cara a la Kaaba, levanta las manos, di el dhikr de Safa y haz dua, tres veces.","Camina hasta Marwa; los hombres aprietan el paso entre las luces verdes.","En Marwa, ponte de cara a la Kaaba y repite el dhikr y el dua.","Vuelve a Safa: ese es el segundo trayecto.","Continúa hasta el séptimo trayecto, que termina en Marwa."],"duas":[{"ar":"إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِ","tr":"Inna as-Safa wa al-Marwata min sha'a'iri Allah","t":"En verdad, Safa y Marwa están entre los símbolos de Allah.","source":"Corán 2:158 (palabras iniciales) — recitado al acercarse a Safa: Sahih Muslim 1218"},{"ar":"لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ أَنْجَزَ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الأَحْزَابَ وَحْدَهُ","tr":"La ilaha illa Allahu wahdahu la sharika lah, lahu al-mulku wa lahu al-hamd, wa huwa 'ala kulli shay'in qadir. La ilaha illa Allahu wahdah, anjaza wa'dah, wa nasara 'abdah, wa hazama al-ahzaba wahdah","t":"No hay más dios que Allah, Único, sin asociado. Suya es la soberanía y Suya es la alabanza, y Él tiene poder sobre todas las cosas. No hay más dios que Allah, Único; cumplió Su promesa, dio la victoria a Su siervo y derrotó Él solo a los coligados.","source":"Dhikr en Safa y Marwa — Sahih Muslim 1218"}]},{"id":"halq-taqsir","title":"Rasurarse o recortarse el cabello","body":"El último acto de la Umrah es rasurarse la cabeza (halq) o acortarse el cabello (taqsir). Para los hombres, rasurarse toda la cabeza es mejor; si en cambio se lo recortan, la práctica común es acortar el cabello de toda la cabeza, no solo unos mechones. Las mujeres nunca se rasuran: reúnen su cabello y cortan de la punta aproximadamente el largo de la yema de un dedo.\n\nEl hombre que realiza la Umrah poco antes del Hajj (tamattu) suele optar por recortárselo ahora, para que quede cabello que rasurar el día diez.\n\nAcude a los barberos de fuera de la mezquita en lugar de cortar el cabello en la zona del sa'y, y las mujeres deben cortarse el cabello en privado. Con este acto la Umrah queda completa, y todas las restricciones del ihram llegan a su fin.","steps":["Sal de la zona del sa'y una vez terminado el séptimo trayecto.","Hombres: rasúrense la cabeza, o acorten el cabello de toda la cabeza.","Mujeres: corten de la punta del cabello el largo de una yema de dedo, en privado.","Ya has salido del ihram: tu Umrah está completa."],"duas":[]},{"id":"after","title":"Después de la Umrah","body":"Tu Umrah ha terminado: da gracias a Allah, que te permitió llegar a Su Casa. Todo lo que el ihram había prohibido vuelve a estar permitido, y puedes ponerte tu ropa habitual.\n\nAprovecha bien los días que te quedan en La Meca. Reza las cinco oraciones en la Mezquita Sagrada tan a menudo como puedas, haz tawaf adicionales cuando no haya demasiada gente, lee el Corán y haz dua por ti, por tu familia y por todos los musulmanes. Sé amable con los demás peregrinos y paciente con el cansancio y las multitudes.\n\nMuchos peregrinos viajan también a Medina para rezar en la Mezquita del Profeta. Esta visita es en sí misma una obra bendita, pero no forma parte de la Umrah. De vuelta en casa, procura conservar los buenos hábitos que adquiriste allí.","steps":["Da gracias a Allah y vuelve a ponerte tu ropa habitual.","Reza en la Mezquita Sagrada tan a menudo como puedas.","Haz tawaf adicionales, lee el Corán y haz mucho dua.","Conserva los buenos hábitos del viaje una vez en casa."],"duas":[]}]},"hajj":{"title":"El Hajj día a día","intro":"El Hajj es el quinto pilar del islam. Es una obligación una vez en la vida para todo musulmán adulto que pueda hacer el viaje (Corán 3:97). Sus ritos principales tienen lugar del 8 al 13 de Dhul-Hiyya, entre La Meca, Mina, Arafat y Muzdalifah.\n\nHay tres maneras de realizarlo. En el tamattu, haces una Umrah completa durante los meses del Hajj, sales del ihram y vuelves a entrar en ihram para el Hajj el día 8. En el qiran, unes Umrah y Hajj en un solo ihram, sin salir de él entre ambos. En el ifrad, entras en ihram solo para el Hajj. Se debe un sacrificio en el tamattu y el qiran (Corán 2:196), no en el ifrad. Las tres son válidas; los sabios difieren sobre cuál es la mejor, y la mayoría de los peregrinos que vienen de lejos hacen el tamattu.\n\nEsta guía es un resumen. No sustituye a un maestro cualificado, ni a las instrucciones de las autoridades del lugar y de tu grupo, que organizan los desplazamientos y los horarios por la seguridad de todos. Cuando las escuelas jurídicas difieren en un detalle, indicamos la práctica común: consulta tu caso con un sabio de tu confianza.","chapters":[{"id":"day-8-tarwiyah","title":"8 de Dhul-Hiyya: el día de Tarwiyah, en Mina","body":"El Hajj comienza el 8 de Dhul-Hiyya, llamado el día de Tarwiyah. El peregrino que hace el tamattu vuelve a entrar en ihram, esta vez para el Hajj, desde el lugar donde se aloja en La Meca: baño, vestiduras del ihram, intención, y luego la talbiyah. Quienes hacen el qiran o el ifrad siguen en ihram desde el miqat.\n\nTodos se dirigen entonces a Mina, un valle de tiendas a pocos kilómetros de La Meca. Allí rezas Dhuhr, Asr, Maghrib, Isha y luego el Fajr del día 9, cada una a su hora; las oraciones de cuatro rak'at se acortan a dos, sin juntarlas.\n\nEste día y esta noche en Mina son una sunnah y un tiempo de preparación. Descansa, repite la talbiyah, lee el Corán y prepara tu corazón para mañana, el día más grande del Hajj.","steps":["Tamattu: toma un baño y ponte el ihram en el lugar donde te alojas en La Meca.","Formula en tu corazón la intención del Hajj y di: Labbayka Allahumma hajjan.","Ve a Mina con tu grupo, repitiendo la talbiyah.","Reza Dhuhr, Asr, Maghrib e Isha en Mina, cada una a su hora, acortando las oraciones de cuatro rak'at.","Pasa la noche en Mina y reza allí el Fajr."],"duas":[{"ar":"لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لاَ شَرِيكَ لَكَ","tr":"Labbayka Allahumma labbayk, labbayka la sharika laka labbayk, inna al-hamda wa an-ni'mata laka wa al-mulk, la sharika lak","t":"Aquí estoy, oh Allah, aquí estoy. Aquí estoy, no tienes asociado, aquí estoy. En verdad, toda alabanza y toda gracia son Tuyas, y toda la soberanía. No tienes asociado.","source":"La talbiyah — Sahih al-Bukhari 1549; Sahih Muslim 1184"}]},{"id":"day-9-arafat","title":"9 de Dhul-Hiyya: Arafat, y luego Muzdalifah","body":"La estancia en Arafat es el pilar del Hajj: quien la pierde ha perdido el Hajj. El Profeta Muhammad ﷺ enseñó que el Hajj es Arafat (Jami' at-Tirmidhi 889).\n\nDespués de la salida del sol, sal de Mina hacia Arafat y comprueba que estás dentro de sus límites, indicados con señales. Tras el sermón, Dhuhr y Asr se rezan juntas y acortadas, a la hora de Dhuhr. Luego llega el corazón del Hajj: desde el mediodía hasta la puesta del sol, ponte de cara a la qiblah e invoca a Allah, pide perdón y ruega por tus seres queridos. No hay ningún texto impuesto. No te marches antes de la puesta del sol.\n\nDespués de la puesta del sol, ve con calma a Muzdalifah. Allí rezas Maghrib e Isha juntas, Isha acortada, y luego descansas durante la noche al aire libre. Puedes recoger allí las piedrecitas para la lapidación.","steps":["Después de la salida del sol, ve de Mina a Arafat, repitiendo la talbiyah.","Comprueba que estás dentro de los límites de Arafat.","Reza Dhuhr y Asr juntas y acortadas a la hora de Dhuhr.","Dedica la tarde al dua, al dhikr y al arrepentimiento, de cara a la qiblah.","Quédate en Arafat hasta que el sol se haya puesto por completo.","Ve con calma a Muzdalifah y reza allí Maghrib e Isha juntas.","Recoge piedrecitas, del tamaño de un garbanzo, y luego duerme.","Reza el Fajr, haz dua de cara a la qiblah y sal hacia Mina antes de la salida del sol."],"duas":[]},{"id":"day-10-nahr","title":"10 de Dhul-Hiyya: el día del sacrificio","body":"El día 10 es el día del Eid y el más ajetreado del Hajj. Se realizan cuatro actos, idealmente en este orden. Primero, en Mina, lanza siete piedrecitas una a una contra Jamrat al-Aqaba, el pilar más grande, diciendo el takbir con cada una; la talbiyah cesa aquí (Sahih al-Bukhari 1685). Segundo, el sacrificio, debido en el tamattu y el qiran, que a menudo se gestiona mediante un bono oficial. Tercero, los hombres se rasuran o se recortan el cabello y las mujeres cortan el largo de una yema de dedo. Cuarto, en La Meca, el tawaf al-ifadah, un pilar del Hajj, seguido del sa'y del Hajj para quienes aún lo deban.\n\nTras la lapidación y el rasurado, se levantan las restricciones del ihram, salvo las relaciones conyugales, que pasan a ser lícitas después del tawaf al-ifadah. Las escuelas difieren en los detalles: consulta tu caso con un sabio de tu confianza.\n\nSi el orden cambia, no hay mal en ello: así se lo dijo el Profeta Muhammad ﷺ a quienes le preguntaron aquel día (Sahih al-Bukhari 83).","steps":["En Mina, lanza siete piedrecitas una a una contra Jamrat al-Aqaba, diciendo Allahu akbar con cada una.","Deja la talbiyah cuando empieces la lapidación.","Ofrece el sacrificio, o asegúrate de que se hace en tu nombre (tamattu y qiran).","Los hombres se rasuran o se recortan toda la cabeza; las mujeres cortan el largo de una yema de dedo.","Ponte ropa corriente: todo vuelve a estar permitido salvo las relaciones conyugales.","Ve a La Meca para el tawaf al-ifadah, sin idtiba ni raml, y reza dos rak'at.","Haz el sa'y del Hajj si aún lo debes.","Regresa a Mina para pasar allí la noche."],"duas":[{"ar":"اللَّهُ أَكْبَرُ","tr":"Allahu akbar","t":"Allah es el más Grande.","source":"Takbir con cada piedrecita — Sahih al-Bukhari 1751"}]},{"id":"days-11-13-tashriq","title":"11–13 de Dhul-Hiyya: los días de Tashriq","body":"Los días de Tashriq se pasan en Mina. Son días de recuerdo de Allah (Corán 2:203), y las noches también se pasan allí.\n\nCada día, después del mediodía, lapidas los tres jamarat por orden: el pequeño, el mediano y luego Jamrat al-Aqaba, con siete piedrecitas cada uno, diciendo el takbir con cada lanzamiento. Después del primero y después del segundo, apártate a un lado, ponte de cara a la qiblah y haz un dua largo con las manos levantadas; después del tercero, márchate sin detenerte (Sahih al-Bukhari 1751).\n\nPuedes salir de Mina el día 12 después de la lapidación, antes de la puesta del sol; quien se queda vuelve a lapidar el día 13. Ambas cosas están permitidas (Corán 2:203). Sigue el horario dado a tu grupo. Si estás débil o enfermo, o sobre la hora exacta de la lapidación, consulta tu caso con un sabio de tu confianza.","steps":["Pasa en Mina las noches del 11 y del 12.","Cada día después del mediodía, lleva 21 piedrecitas a los jamarat.","Lapida el jamrah pequeño con siete piedrecitas, luego apártate y haz dua.","Lapida el jamrah mediano con siete piedrecitas, luego apártate y haz dua.","Lapida Jamrat al-Aqaba con siete piedrecitas y márchate sin detenerte.","El día 12, sal de Mina antes de la puesta del sol si deseas irte pronto.","Si no, quédate esa noche y vuelve a lapidar los tres jamarat el día 13."],"duas":[]},{"id":"farewell-tawaf","title":"El tawaf de despedida","body":"Cuando todos los ritos han terminado y estás a punto de dejar La Meca, lo último que haces es el tawaf de despedida (tawaf al-wada). A la gente se le ordenó que la Casa fuera su última parada; solo la mujer con la menstruación quedó dispensada de ello (Sahih al-Bukhari 1755; Sahih Muslim 1328).\n\nEs un tawaf ordinario de siete vueltas con ropa de diario, sin idtiba ni raml, seguido de dos rak'at. No hay sa'y después. Hazlo cuando tu equipaje esté listo y tu partida esté próxima; una breve espera del transporte o de tus compañeros no supone ningún problema.\n\nSal de la Mezquita Sagrada con el corazón agradecido. Pide a Allah que acepte tu Hajj, que te perdone y que te permita volver. Después procura regresar a casa siendo mejor persona que la que partió.","steps":["Termina primero todos tus ritos y prepara tu equipaje.","Da siete vueltas alrededor de la Kaaba con ropa corriente.","Reza dos rak'at después del tawaf.","Haz dua para que Allah acepte tu Hajj, y luego sal de La Meca sin demora.","La mujer con la menstruación se marcha sin este tawaf."],"duas":[]}]},"mistakes":[{"title":"Empujar para besar la Piedra Negra","body":"Besar la Piedra Negra es una sunnah; dañar a un musulmán está prohibido. Si la multitud es densa, basta con señalar hacia la Piedra y decir el takbir: tu tawaf está completo y nadie sale herido."},{"title":"Creer que cada vuelta tiene su propio dua obligatorio","body":"Algunos folletos dan una súplica por vuelta. Nada de eso es obligatorio: no hay un dua fijo obligatorio para las vueltas del tawaf ni para los trayectos del sa'y. Habla a Allah con tus propias palabras, en tu propio idioma."},{"title":"Salir de Arafat antes de la puesta del sol","body":"El Profeta Muhammad ﷺ permaneció en Arafat hasta que el sol se hubo puesto (Sahih Muslim 1218). No corras hacia los autobuses al final de la tarde: son las horas más valiosas de todo el Hajj."},{"title":"Subir a Jabal ar-Rahmah creyendo que es obligatorio","body":"Toda la llanura de Arafat es lugar de estancia. Subir a la colina no forma parte del Hajj ni aporta una recompensa adicional; las aglomeraciones allí son agotadoras y peligrosas. Quédate donde puedas rezar en paz."},{"title":"Quedarse fuera de los límites de Arafat","body":"Algunos peregrinos se instalan justo fuera de Arafat sin darse cuenta. Como la estancia es el pilar del Hajj, busca las señales de los límites y pregunta a tu guía si tienes la menor duda."},{"title":"Recoger piedrecitas demasiado grandes","body":"Las piedrecitas son pequeñas, más o menos del tamaño de un garbanzo. Las piedras grandes, los zapatos u otros objetos no forman parte del rito y pueden herir a la gente. La lapidación es un acto de obediencia a Allah, hecho con calma, no un arrebato de ira."},{"title":"Fotografiar en lugar de adorar","body":"Una foto de recuerdo lleva unos segundos; grabar todo el tawaf o publicar en directo desde Arafat te roba el corazón. Guarda el teléfono durante los ritos y protege la sinceridad de tu intención."},{"title":"Descuidar el miqat al viajar en avión","body":"El avión cruza el miqat en el aire. Ponte las telas del ihram antes de embarcar o al principio del vuelo, y formula la intención cuando se anuncie el miqat, o un poco antes. Si lo pasaste sin ihram, consulta tu caso con un sabio de tu confianza."},{"title":"Llevar el hombro derecho descubierto todo el tiempo","body":"El idtiba es solo para los hombres y solo durante el tawaf de llegada. Antes y después de él, también durante la oración y el sa'y, ambos hombros van cubiertos."},{"title":"Contar una ida y vuelta como un solo trayecto del sa'y","body":"De Safa a Marwa es un trayecto y de Marwa a Safa es otro. El sa'y son siete trayectos y termina en Marwa. Contar cada ida y vuelta como uno supondría caminar catorce trayectos."},{"title":"Empeñarse en rezar justo detrás del Maqam Ibrahim","body":"Rezar en el paso de quienes hacen el tawaf los bloquea y te pone en peligro. Cuando hay mucha gente, las dos rak'at pueden rezarse en cualquier lugar de la mezquita."},{"title":"Discutir y perder la paciencia","body":"El calor, las colas y el cansancio ponen a prueba a todos. El Corán prohíbe la obscenidad, la maldad y las disputas durante el Hajj (2:197). Cede el paso, sonríe, perdona: el buen carácter forma parte de tu peregrinación."}],"checklist":[{"id":"passport","group":"documents","label":"Pasaporte válido durante al menos seis meses"},{"id":"visa-permit","group":"documents","label":"Visado de Hajj o Umrah y permiso oficial"},{"id":"tickets-bookings","group":"documents","label":"Boletos de avión y reservas de alojamiento"},{"id":"id-copies","group":"documents","label":"Copias en papel y digitales de todos los documentos"},{"id":"emergency-contacts","group":"documents","label":"Tarjeta con los contactos de tu grupo, del hotel y de emergencia"},{"id":"money-card","group":"documents","label":"Algo de efectivo en moneda local y una tarjeta bancaria"},{"id":"ihram-garments","group":"clothing","label":"Hombres: dos juegos de telas de ihram"},{"id":"modest-clothing","group":"clothing","label":"Mujeres: ropa holgada, recatada y cómoda"},{"id":"sandals","group":"clothing","label":"Sandalias cómodas y ya usadas"},{"id":"ihram-belt","group":"clothing","label":"Cinturón de ihram o riñonera para el dinero y los papeles"},{"id":"small-bag","group":"clothing","label":"Bolsa pequeña para los zapatos y las piedrecitas"},{"id":"umbrella","group":"clothing","label":"Paraguas de color claro contra el sol"},{"id":"vaccinations","group":"health","label":"Vacunas exigidas y certificado"},{"id":"medication","group":"health","label":"Medicación habitual con receta"},{"id":"unscented-toiletries","group":"health","label":"Jabón y artículos de aseo sin perfume para el ihram"},{"id":"water-bottle","group":"health","label":"Botella de agua reutilizable"},{"id":"masks-sanitizer","group":"health","label":"Mascarillas y gel desinfectante de manos sin perfume"},{"id":"first-aid","group":"health","label":"Pequeño botiquín con apósitos para ampollas"},{"id":"sincere-intention","group":"spiritual","label":"Renueva tu intención: solo por Allah"},{"id":"repentance-debts","group":"spiritual","label":"Arrepiéntete, salda tus deudas y pide perdón"},{"id":"learn-rites","group":"spiritual","label":"Aprende los ritos y su orden"},{"id":"talbiyah-memorised","group":"spiritual","label":"Memoriza la talbiyah"},{"id":"dua-list","group":"spiritual","label":"Escribe una lista de duas personales para Arafat"},{"id":"quran-dhikr","group":"spiritual","label":"Corán de bolsillo o aplicación para la lectura y el dhikr"}]}$tk$::jsonb)
  on conflict (kind, lang) do update set payload = excluded.payload, updated_at = now();
insert into public.premium_content (kind, lang, payload) values ('quiz', 'es', $tk$[{"id":"q001","cat":"prophets","q":"Según el Corán, ¿quién fue el primer ser humano creado por Allah?","options":["Nuh (Noé)","Adam (Adán)","Ibrahim (Abraham)","Idris"],"answer":1,"explain":"Adam (la paz sea con él) es el primer ser humano y el padre de la humanidad. El Corán relata su creación en 2:30-37."},{"id":"q002","cat":"prophets","q":"¿Qué profeta (la paz sea con él) construyó el arca por orden de Allah?","options":["Musa (Moisés)","Yunus (Jonás)","Nuh (Noé)","Hud"],"answer":2,"explain":"A Nuh (la paz sea con él) se le ordenó construir el arca antes del diluvio, como cuenta el Corán (11:37)."},{"id":"q003","cat":"prophets","q":"¿Qué profeta (la paz sea con él) fue tragado por un gran pez?","options":["Ayyub (Job)","Yusuf (José)","Ilyas (Elías)","Yunus (Jonás)"],"answer":3,"explain":"Yunus (la paz sea con él) fue tragado por un gran pez, invocó a Allah desde las tinieblas y fue salvado (37:139-144)."},{"id":"q004","cat":"prophets","q":"¿Qué hijo ayudó a Ibrahim (la paz sea con él) a levantar los cimientos de la Kaaba?","options":["Ishaq (Isaac)","Yaqub (Jacob)","Ismail (Ismael)","Lut (Lot)"],"answer":2,"explain":"El Corán dice que Ibrahim e Ismail (la paz sea con ellos) levantaron juntos los cimientos de la Casa (2:127)."},{"id":"q005","cat":"prophets","q":"¿Qué profeta (la paz sea con él) fue arrojado a un pozo por sus hermanos cuando era niño?","options":["Yahya (Juan)","Yusuf (José)","Harun (Aarón)","Dawud (David)"],"answer":1,"explain":"Yusuf (la paz sea con él) fue arrojado a un pozo por sus hermanos celosos. Su historia ocupa la sura Yusuf, la sura 12 (12:15)."},{"id":"q006","cat":"prophets","q":"¿A qué profeta (la paz sea con él) le fue revelada la Tawrat (Torá)?","options":["Isa (Jesús)","Dawud (David)","Ibrahim (Abraham)","Musa (Moisés)"],"answer":3,"explain":"La Tawrat fue dada a Musa (la paz sea con él), que sacó de Egipto a los Hijos de Israel."},{"id":"q007","cat":"prophets","q":"¿Qué profeta (la paz sea con él) recibió el Zabur (Salmos)?","options":["Dawud (David)","Sulayman (Salomón)","Musa (Moisés)","Zakariyya (Zacarías)"],"answer":0,"explain":"El Corán afirma que Allah dio el Zabur a Dawud (la paz sea con él) (4:163 y 17:55)."},{"id":"q008","cat":"prophets","q":"¿Qué profeta (la paz sea con él) recibió el Inyil (Evangelio)?","options":["Isa (Jesús)","Yahya (Juan)","Musa (Moisés)","Yunus (Jonás)"],"answer":0,"explain":"El Inyil fue dado a Isa, hijo de Maryam (la paz sea con ellos), como dice el Corán en 5:46."},{"id":"q009","cat":"prophets","q":"¿Qué profeta era hermano de Musa (la paz sea con él) y lo ayudó en su misión?","options":["Yusha (Josué)","Shuayb","Ilyas (Elías)","Harun (Aarón)"],"answer":3,"explain":"Musa pidió a Allah que le diera a su hermano Harun como ayudante (20:29-32). La paz sea con ambos."},{"id":"q010","cat":"prophets","q":"¿Qué profeta (la paz sea con él), probado por una larga adversidad, es célebre por su paciencia y por invocar a su Señor como «el más Misericordioso de los misericordiosos»?","options":["Ayyub (Job)","Harun (Aarón)","Lut (Lot)","Salih"],"answer":0,"explain":"Ayyub (la paz sea con él) se mantuvo paciente durante su adversidad e invocó a su Señor, que lo alivió (21:83-84)."},{"id":"q011","cat":"prophets","q":"¿Qué profeta (la paz sea con él) fue enviado al pueblo de 'Ad?","options":["Salih","Shuayb","Hud","Lut (Lot)"],"answer":2,"explain":"Hud (la paz sea con él) fue enviado al pueblo de 'Ad para llamarlo a adorar solo a Allah (7:65)."},{"id":"q012","cat":"prophets","q":"¿A qué profeta (la paz sea con él) está vinculada la camella dada como señal al pueblo de Thamud?","options":["Hud","Salih","Nuh (Noé)","Yunus (Jonás)"],"answer":1,"explain":"Salih (la paz sea con él) fue enviado a Thamud, y la camella fue para ellos una señal de Allah (7:73)."},{"id":"q013","cat":"prophets","q":"¿Qué profeta (la paz sea con él) fue arrojado al fuego por su pueblo, y Allah hizo que este fuera fresco e inofensivo para él?","options":["Musa (Moisés)","Ibrahim (Abraham)","Yahya (Juan)","Hud"],"answer":1,"explain":"Cuando su pueblo arrojó a Ibrahim (la paz sea con él) al fuego, Allah ordenó al fuego que fuera frescor y seguridad para él (21:68-69)."},{"id":"q014","cat":"prophets","q":"Según el Corán, ¿qué profeta (la paz sea con él) entendió las palabras de una hormiga que avisaba a las demás hormigas?","options":["Yunus (Jonás)","Isa (Jesús)","Sulayman (Salomón)","Yusuf (José)"],"answer":2,"explain":"Sulayman (la paz sea con él) oyó a una hormiga avisar a las demás cuando su ejército se acercaba, y sonrió y dio gracias a Allah (27:18-19)."},{"id":"q015","cat":"prophets","q":"¿Qué profeta (la paz sea con él) fue el padre de Yahya (Juan)?","options":["Imran","Yaqub (Jacob)","Ayyub (Job)","Zakariyya (Zacarías)"],"answer":3,"explain":"Zakariyya (la paz sea con él) pidió un hijo en su vejez y recibió la buena nueva de Yahya (19:7)."},{"id":"q016","cat":"seerah","q":"¿En qué ciudad nació el Profeta Muhammad ﷺ?","options":["Medina","La Meca","Taif","Jerusalén"],"answer":1,"explain":"El Profeta Muhammad ﷺ nació en La Meca, en la tribu de Quraysh."},{"id":"q017","cat":"seerah","q":"¿Dónde recibió el Profeta Muhammad ﷺ la primera revelación?","options":["En la cueva de Thawr","En la cueva de Hira","En el monte Uhud","En la llanura de Arafat"],"answer":1,"explain":"La primera revelación llegó en la cueva de Hira, en la Montaña de la Luz, cerca de La Meca, adonde solía retirarse."},{"id":"q018","cat":"seerah","q":"¿Qué ángel llevó la revelación al Profeta Muhammad ﷺ?","options":["Mikail (Miguel)","Yibril (Gabriel)","Israfil","Malik"],"answer":1,"explain":"El ángel Yibril (la paz sea con él) llevó el Corán al Profeta Muhammad ﷺ."},{"id":"q019","cat":"seerah","q":"¿Cuál fue la primera palabra del Corán revelada al Profeta Muhammad ﷺ?","options":["Qul (Di)","Qum (Levántate)","Iqra (Lee)","Sabbih (Glorifica)"],"answer":2,"explain":"La primera revelación comienza con la palabra «Iqra», que significa lee o recita (96:1)."},{"id":"q020","cat":"seerah","q":"¿Quién fue la primera esposa del Profeta Muhammad ﷺ?","options":["Khadija bint Khuwaylid","Aisha bint Abi Bakr","Hafsa bint Umar","Sawda bint Zam'a"],"answer":0,"explain":"Khadija, una respetada comerciante de La Meca, fue su primera esposa. No se casó con ninguna otra mujer mientras ella vivió."},{"id":"q021","cat":"seerah","q":"¿En qué año de la era común tuvo lugar la Hégira, la emigración de La Meca a Medina?","options":["622","570","610","632"],"answer":0,"explain":"La Hégira tuvo lugar en el año 622 d. C. Ese año pasó a ser más tarde el año 1 del calendario islámico."},{"id":"q022","cat":"seerah","q":"¿Cómo se llamaba la ciudad de Medina antes de la Hégira?","options":["Khaybar","Tabuk","Taif","Yathrib"],"answer":3,"explain":"La ciudad se llamaba Yathrib. Después de que el Profeta Muhammad ﷺ se estableciera en ella, pasó a conocerse como Medina, «la Ciudad»."},{"id":"q023","cat":"seerah","q":"¿En qué cueva se refugió el Profeta Muhammad ﷺ durante la Hégira?","options":["La cueva de Thawr","La cueva de Hira","Una cueva del monte Uhud","Una cueva del monte Safa"],"answer":0,"explain":"Se ocultó en la cueva de Thawr con su compañero Abu Bakr mientras Quraysh los buscaba. El Corán menciona este momento en 9:40."},{"id":"q024","cat":"seerah","q":"¿En qué año de la Hégira tuvo lugar la batalla de Badr?","options":["Año 2","Año 1","Año 5","Año 8"],"answer":0,"explain":"La batalla de Badr tuvo lugar en el Ramadán del año 2 de la Hégira. Fue la primera gran batalla de los musulmanes."},{"id":"q025","cat":"seerah","q":"¿Cómo se llamaba el abuelo que cuidó del Profeta Muhammad ﷺ tras la muerte de su madre?","options":["Abu Lahab","Abu Sufyan","Abd al-Muttalib","Waraqa ibn Nawfal"],"answer":2,"explain":"Su abuelo Abd al-Muttalib, uno de los jefes de La Meca, se hizo cargo de él. Tras la muerte del abuelo, lo acogió su tío Abu Talib."},{"id":"q026","cat":"seerah","q":"¿Cómo se llamaba la madre del Profeta Muhammad ﷺ?","options":["Halima as-Sa'diyya","Fatima bint Asad","Umm Ayman","Amina bint Wahb"],"answer":3,"explain":"Su madre era Amina bint Wahb. Murió cuando él era todavía un niño pequeño. Halima as-Sa'diyya fue su nodriza."},{"id":"q027","cat":"seerah","q":"¿A qué tribu pertenecía el Profeta Muhammad ﷺ?","options":["Aws","Khazraj","Thaqif","Quraysh"],"answer":3,"explain":"Pertenecía a Quraysh, la tribu de La Meca, dentro del clan de Banu Hashim."},{"id":"q028","cat":"seerah","q":"¿Cómo se llama la tregua acordada entre los musulmanes y Quraysh en el año 6 de la Hégira?","options":["El Juramento de Aqaba","La Carta de Medina","El Tratado de Hudaybiyya","El Pacto de los Virtuosos (Hilf al-Fudul)"],"answer":2,"explain":"El Tratado de Hudaybiyya se acordó en el año 6 de la Hégira cerca de La Meca. Trajo un periodo de paz durante el cual el islam se difundió ampliamente."},{"id":"q029","cat":"seerah","q":"¿En qué año de la Hégira tuvo lugar la Conquista de La Meca?","options":["Año 2","Año 4","Año 8","Año 6"],"answer":2,"explain":"Los musulmanes entraron en La Meca en el año 8 de la Hégira (630 d. C.). El Profeta Muhammad ﷺ perdonó a sus habitantes."},{"id":"q030","cat":"seerah","q":"Antes de la profecía, ¿qué sobrenombre daban los habitantes de La Meca al Profeta Muhammad ﷺ?","options":["Al-Hakim (el Sabio)","Al-Karim (el Generoso)","Ash-Shuja (el Valiente)","Al-Amin (el Digno de Confianza)"],"answer":3,"explain":"Se lo conocía como al-Amin, el Digno de Confianza, por su honradez. La gente dejaba sus objetos de valor a su cuidado."},{"id":"q031","cat":"companions","q":"¿Quién fue el primer almuédano del islam?","options":["Salman al-Farisi","Anas ibn Malik","Bilal ibn Rabah","Zayd ibn Haritha"],"answer":2,"explain":"Bilal ibn Rabah, un esclavo liberado de origen abisinio, fue elegido por el Profeta Muhammad ﷺ para hacer el adhan, la llamada a la oración."},{"id":"q032","cat":"companions","q":"¿Qué compañero viajó con el Profeta Muhammad ﷺ durante la Hégira?","options":["Bilal ibn Rabah","Mus'ab ibn Umayr","Khalid ibn al-Walid","Abu Bakr"],"answer":3,"explain":"Abu Bakr fue su compañero en el viaje de La Meca a Medina y permaneció con él en la cueva de Thawr."},{"id":"q033","cat":"companions","q":"¿Qué compañero propuso cavar una trinchera para defender Medina?","options":["Bilal ibn Rabah","Abu Ayyub al-Ansari","Salman al-Farisi","Mus'ab ibn Umayr"],"answer":2,"explain":"Salman al-Farisi, que procedía de Persia, propuso la trinchera. Por eso la batalla del año 5 de la Hégira se llama la batalla de la Trinchera."},{"id":"q034","cat":"companions","q":"¿Qué compañero es conocido por el título de «Espada de Allah» (Sayf Allah)?","options":["Khalid ibn al-Walid","Bilal ibn Rabah","Zayd ibn Thabit","Anas ibn Malik"],"answer":0,"explain":"Khalid ibn al-Walid, un célebre comandante, es conocido como Sayf Allah, la Espada de Allah."},{"id":"q035","cat":"companions","q":"¿Quién fue la primera persona que creyó en el mensaje del Profeta Muhammad ﷺ?","options":["Umar ibn al-Khattab","Khadija bint Khuwaylid","Khalid ibn al-Walid","Abu Sufyan"],"answer":1,"explain":"Su esposa Khadija fue la primera en creer en él. Lo consoló y lo apoyó desde la primera revelación."},{"id":"q036","cat":"companions","q":"¿Bajo qué califa se adoptó el calendario de la Hégira, con el año de la Hégira como punto de partida?","options":["Umar ibn al-Khattab","Harun al-Rashid","Abd al-Malik ibn Marwan","Umar ibn Abd al-Aziz"],"answer":0,"explain":"El calendario de la Hégira se estableció durante el califato de Umar ibn al-Khattab, pocos años después de la muerte del Profeta Muhammad ﷺ."},{"id":"q037","cat":"companions","q":"¿A qué compañero, escriba de la revelación, se le encomendó reunir el Corán en una sola recopilación escrita?","options":["Bilal ibn Rabah","Khalid ibn al-Walid","Salman al-Farisi","Zayd ibn Thabit"],"answer":3,"explain":"Zayd ibn Thabit, uno de los escribas del Profeta Muhammad ﷺ, reunió el Corán escrito en una sola recopilación durante el califato de Abu Bakr."},{"id":"q038","cat":"companions","q":"¿Qué compañero fue enviado a Yathrib antes de la Hégira para enseñar el islam a sus habitantes?","options":["Mus'ab ibn Umayr","Khalid ibn al-Walid","Anas ibn Malik","Abu Ayyub al-Ansari"],"answer":0,"explain":"Mus'ab ibn Umayr fue enviado a Yathrib tras el primer juramento de Aqaba. Muchos de sus habitantes aceptaron el islam gracias a él."},{"id":"q039","cat":"companions","q":"¿En qué batalla murió Hamza, el tío del Profeta Muhammad ﷺ?","options":["Badr","La Trinchera","Hunayn","Uhud"],"answer":3,"explain":"Hamza ibn Abd al-Muttalib cayó mártir en la batalla de Uhud, en el año 3 de la Hégira."},{"id":"q040","cat":"companions","q":"¿A quién se recuerda como la primera mártir del islam?","options":["Umm Ayman","Sumayya bint Khayyat","Halima as-Sa'diyya","Umm Salama"],"answer":1,"explain":"Sumayya bint Khayyat, madre de Ammar ibn Yasir, fue asesinada en La Meca por negarse a renunciar a su fe."},{"id":"q041","cat":"companions","q":"¿Qué compañero habló en nombre de los emigrantes musulmanes ante el Negus, el rey de Abisinia?","options":["Bilal ibn Rabah","Ja'far ibn Abi Talib","Zayd ibn Thabit","Anas ibn Malik"],"answer":1,"explain":"Ja'far ibn Abi Talib explicó el islam al Negus, que entonces permitió a los musulmanes vivir a salvo en su tierra."},{"id":"q042","cat":"companions","q":"¿Qué hija del Profeta Muhammad ﷺ se casó con Ali ibn Abi Talib?","options":["Fátima","Zaynab","Ruqayya","Umm Kulthum"],"answer":0,"explain":"Fátima se casó con Ali ibn Abi Talib en Medina. Fueron los padres de al-Hasan y al-Husayn."},{"id":"q043","cat":"companions","q":"¿Qué nombre se da a los habitantes de Medina que acogieron y ayudaron a los emigrantes de La Meca?","options":["Los Muhayirun (Emigrantes)","Los Quraysh","Los Tabi'un (Sucesores)","Los Ansar (Auxiliares)"],"answer":3,"explain":"A los musulmanes de Medina se los llama los Ansar, los Auxiliares. A los que emigraron de La Meca se los llama los Muhayirun."},{"id":"q044","cat":"companions","q":"¿Quién durmió en el lecho del Profeta Muhammad ﷺ la noche en que este salió de La Meca para la Hégira?","options":["Zayd ibn Haritha","Bilal ibn Rabah","Ali ibn Abi Talib","Anas ibn Malik"],"answer":2,"explain":"El joven Ali ibn Abi Talib ocupó su lugar en el lecho aquella noche y se quedó para devolver los bienes que la gente le había confiado."},{"id":"q045","cat":"companions","q":"¿En casa de quién vivió el Profeta Muhammad ﷺ en Medina mientras se construía su mezquita?","options":["Salman al-Farisi","Abu Ayyub al-Ansari","Khalid ibn al-Walid","Mus'ab ibn Umayr"],"answer":1,"explain":"Se alojó en casa de Abu Ayyub al-Ansari hasta que se construyeron su mezquita y sus habitaciones."},{"id":"q046","cat":"quran","q":"¿Cuántas suras contiene el Corán?","options":["114","99","110","120"],"answer":0,"explain":"El Corán tiene 114 suras, de al-Fatiha a an-Nas."},{"id":"q047","cat":"quran","q":"¿Cuál es la sura más larga del Corán?","options":["Al-Imran","An-Nisa","Ya-Sin","Al-Baqara"],"answer":3,"explain":"Al-Baqara, la sura 2, es la más larga del Corán."},{"id":"q048","cat":"quran","q":"¿Cuál es la sura más corta del Corán?","options":["Al-Ikhlas","Al-Kawthar","Al-Falaq","Al-Fatiha"],"answer":1,"explain":"Al-Kawthar, la sura 108, es la más corta: solo tiene tres aleyas breves."},{"id":"q049","cat":"quran","q":"¿Qué sura abre el Corán?","options":["Al-Baqara","Al-Ikhlas","Al-Fatiha","Al-Alaq"],"answer":2,"explain":"Al-Fatiha, «la Apertura», es la primera sura del Corán y se recita en cada oración."},{"id":"q050","cat":"quran","q":"¿Qué sura ocupa el último lugar en el Corán?","options":["Al-Falaq","Al-Ikhlas","An-Nas","An-Nasr"],"answer":2,"explain":"An-Nas, la sura 114, cierra el Corán."},{"id":"q051","cat":"quran","q":"¿En cuántas partes (juz') se divide el Corán?","options":["7","30","60","114"],"answer":1,"explain":"El Corán se divide en 30 juz', lo que facilita leerlo entero en un mes."},{"id":"q052","cat":"quran","q":"¿En qué mes comenzó la revelación del Corán?","options":["Ramadán","Rayab","Muharram","Dhul-Hiyya"],"answer":0,"explain":"El Corán dice que fue revelado en el mes de Ramadán (2:185)."},{"id":"q053","cat":"quran","q":"¿En qué sura se encuentra Ayat al-Kursi, la Aleya del Trono?","options":["Al-Imran","Al-Baqara","Al-Kahf","Al-Mulk"],"answer":1,"explain":"Ayat al-Kursi es la aleya 255 de la sura al-Baqara (2:255)."},{"id":"q054","cat":"quran","q":"¿Cuál es la única sura que no comienza con la basmala?","options":["At-Tawba","Al-Anfal","Yunus","Al-Mulk"],"answer":0,"explain":"At-Tawba, la sura 9, es la única que no se abre con «En el nombre de Allah, el Compasivo, el Misericordioso»."},{"id":"q055","cat":"quran","q":"¿En qué sura aparece dos veces la basmala?","options":["An-Nahl","Al-Ankabut","Saba","An-Naml"],"answer":3,"explain":"En la sura an-Naml la basmala figura al comienzo y de nuevo en la carta de Sulayman, la paz sea con él (27:30)."},{"id":"q056","cat":"quran","q":"¿Qué sura del Corán lleva el nombre de la madre de Isa (la paz sea con él)?","options":["An-Nisa","Maryam","Al-Imran","An-Nur"],"answer":1,"explain":"La sura 19 lleva el nombre de Maryam, la madre de Isa (la paz sea con ellos). Es la única mujer mencionada por su nombre en el Corán."},{"id":"q057","cat":"quran","q":"¿A lo largo de cuántos años, aproximadamente, fue revelado el Corán?","options":["Unos 23 años","Unos 3 años","Unos 10 años","Unos 40 años"],"answer":0,"explain":"El Corán fue revelado poco a poco a lo largo de unos 23 años, primero en La Meca y después en Medina."},{"id":"q058","cat":"quran","q":"¿Cuántas aleyas tiene la sura al-Fatiha?","options":["3","5","10","7"],"answer":3,"explain":"Al-Fatiha tiene siete aleyas. Se recita en cada unidad de la oración."},{"id":"q059","cat":"quran","q":"¿Cómo se llaman las suras reveladas antes de la Hégira?","options":["Medinesas (madani)","Muhkam","Mecanas (makki)","Mufassal"],"answer":2,"explain":"Las suras reveladas antes de la Hégira se llaman mecanas, y las reveladas después, medinesas."},{"id":"q060","cat":"quran","q":"¿Cuál es la aleya más larga del Corán?","options":["Ayat al-Kursi (2:255)","La aleya de la luz (24:35)","La aleya de la deuda (2:282)","La primera aleya de al-Fatiha"],"answer":2,"explain":"La aleya más larga es la aleya 282 de al-Baqara. Enseña a poner por escrito las deudas y a llamar testigos."},{"id":"q061","cat":"history","q":"¿Qué ciudad fue la capital del califato omeya?","options":["Bagdad","Damasco","El Cairo","Medina"],"answer":1,"explain":"Los omeyas gobernaron desde Damasco, en Siria, de 661 a 750."},{"id":"q062","cat":"history","q":"¿Qué califa abasí fundó la ciudad de Bagdad en 762?","options":["Harun al-Rashid","Al-Mansur","Al-Mamún","Al-Mutasim"],"answer":1,"explain":"El califa al-Mansur fundó Bagdad en 762 a orillas del Tigris. Llegó a ser una de las mayores ciudades del mundo."},{"id":"q063","cat":"history","q":"¿Quiénes tomaron y destruyeron Bagdad en 1258?","options":["Los mongoles","Los cruzados","Los selyúcidas","Los otomanos"],"answer":0,"explain":"El ejército mongol dirigido por Hulagu tomó Bagdad en 1258, lo que puso fin al califato abasí de Bagdad."},{"id":"q064","cat":"history","q":"¿Qué sultán otomano tomó Constantinopla en 1453?","options":["Mehmed II","Solimán el Magnífico","Selim I","Osmán I"],"answer":0,"explain":"Mehmed II, conocido como «el Conquistador», tomó Constantinopla en 1453. La ciudad se convirtió en la capital otomana, Estambul."},{"id":"q065","cat":"history","q":"¿Quién dirigió el ejército musulmán que cruzó del norte de África a la península ibérica en 711?","options":["Uqba ibn Nafi","Khalid ibn al-Walid","Salah ad-Din (Saladino)","Tariq ibn Ziyad"],"answer":3,"explain":"Tariq ibn Ziyad cruzó el estrecho en 711. El peñón de Gibraltar lleva su nombre: Yabal Tariq, «la montaña de Tariq»."},{"id":"q066","cat":"history","q":"¿Quién recuperó Jerusalén de manos de los cruzados en 1187?","options":["Baybars","Nur ad-Din Zangi","Salah ad-Din (Saladino)","Mehmed II"],"answer":2,"explain":"Salah ad-Din al-Ayyubi recuperó Jerusalén en 1187, tras su victoria en la batalla de Hattin."},{"id":"q067","cat":"history","q":"¿Qué ciudad, último reino musulmán de al-Ándalus, cayó en 1492?","options":["Córdoba","Granada","Sevilla","Toledo"],"answer":1,"explain":"El reino nazarí de Granada cayó en 1492, lo que puso fin a casi ocho siglos de dominio musulmán en partes de la península ibérica."},{"id":"q068","cat":"history","q":"¿Quiénes derrotaron a los mongoles en la batalla de Ain Yalut en 1260?","options":["Los mamelucos de Egipto","Los otomanos","Los selyúcidas","Los almohades"],"answer":0,"explain":"Los mamelucos de Egipto detuvieron el avance mongol en Ain Yalut, en Palestina, en 1260."},{"id":"q069","cat":"history","q":"¿Qué dinastía se hizo con el califato en 750 y más tarde hizo de Bagdad su capital?","options":["Los otomanos","Los mamelucos","Los almorávides","Los abasíes"],"answer":3,"explain":"Los abasíes sustituyeron a los omeyas en 750 y fundaron Bagdad en 762."},{"id":"q070","cat":"history","q":"¿Qué príncipe omeya huyó a al-Ándalus y fundó el emirato de Córdoba en 756?","options":["Tariq ibn Ziyad","Harun al-Rashid","Salah ad-Din (Saladino)","Abd al-Rahman I"],"answer":3,"explain":"Abd al-Rahman I, superviviente de la familia omeya, llegó a al-Ándalus y fundó el emirato de Córdoba en 756."},{"id":"q071","cat":"history","q":"La dinastía otomana toma su nombre de su fundador. ¿Quién fue?","options":["Mehmed II","Timur (Tamerlán)","Alp Arslan","Osmán I"],"answer":3,"explain":"Osmán I fundó el Estado otomano en Anatolia hacia 1300. La palabra «otomano» procede de su nombre."},{"id":"q072","cat":"history","q":"¿Quién fundó el Imperio mogol en la India en 1526?","options":["Akbar","Shah Jahan","Babur","Aurangzeb"],"answer":2,"explain":"Babur fundó el Imperio mogol tras su victoria en la batalla de Panipat en 1526."},{"id":"q073","cat":"history","q":"¿Qué sultán otomano del siglo XVI es conocido como «el Magnífico» y «el Legislador»?","options":["Mehmed II","Solimán I","Osmán I","Abdulhamid II"],"answer":1,"explain":"Solimán I gobernó de 1520 a 1566, cuando el Imperio otomano estaba en su apogeo. Se lo llama «Kanuni», el Legislador."},{"id":"q074","cat":"history","q":"Mansa Musa, célebre por su peregrinación a La Meca en 1324, ¿qué imperio gobernó?","options":["El Imperio songhai","El Imperio de Ghana","El Imperio de Malí","El Imperio de Kanem"],"answer":2,"explain":"Mansa Musa gobernó el Imperio de Malí, en África Occidental. Su peregrinación de 1324 hizo famosa la riqueza de Malí en tierras lejanas."},{"id":"q075","cat":"history","q":"¿Qué sultán selyúcida ganó la batalla de Manzikert contra los bizantinos en 1071?","options":["Salah ad-Din (Saladino)","Baybars","Alp Arslan","Osmán I"],"answer":2,"explain":"Alp Arslan derrotó al ejército bizantino en Manzikert en 1071, lo que abrió Anatolia a los turcos."},{"id":"q076","cat":"sciences","q":"¿Qué rama de las matemáticas toma su nombre del libro «al-Yabr» de al-Juarismi (al-Khwarizmi)?","options":["La geometría","El álgebra","La trigonometría","La aritmética"],"answer":1,"explain":"La palabra álgebra viene de «al-yabr», que figura en el título del libro que al-Juarismi escribió en Bagdad en el siglo IX."},{"id":"q077","cat":"sciences","q":"¿De la forma latina del nombre de qué sabio procede la palabra «algoritmo»?","options":["Al-Juarismi (al-Khwarizmi)","Al-Kindi","Al-Biruni","Al-Battani"],"answer":0,"explain":"«Algoritmo» viene de «Algoritmi», la forma latina del nombre del matemático al-Juarismi."},{"id":"q078","cat":"sciences","q":"¿Quién escribió el «Canon de medicina» (al-Qanun fi al-Tibb)?","options":["Al-Razi (Rhazes)","Al-Zahrawi","Ibn Sina (Avicena)","Ibn al-Nafis"],"answer":2,"explain":"Ibn Sina escribió el Canon de medicina en el siglo XI. Se utilizó para enseñar medicina durante siglos, en el mundo musulmán y en Europa."},{"id":"q079","cat":"sciences","q":"¿Qué sabio escribió el «Libro de óptica» y explicó que vemos porque la luz entra en el ojo?","options":["Al-Juarismi (al-Khwarizmi)","Ibn al-Haytham","Ibn Jaldún","Al-Idrisi"],"answer":1,"explain":"Ibn al-Haytham, que vivió en los siglos X y XI, escribió el Libro de óptica (Kitab al-Manazir) y se basó en experimentos cuidadosos."},{"id":"q080","cat":"sciences","q":"El sabio andalusí al-Zahrawi es célebre como pionero ¿en qué campo?","options":["La astronomía","La cirugía","La geografía","El álgebra"],"answer":1,"explain":"Al-Zahrawi, que vivió cerca de Córdoba en el siglo X, describió operaciones quirúrgicas y muchos instrumentos en su enciclopedia al-Tasrif."},{"id":"q081","cat":"sciences","q":"¿Qué médico escribió un célebre tratado que distinguía la viruela del sarampión?","options":["Al-Kindi","Al-Farabi","Al-Idrisi","Al-Razi (Rhazes)"],"answer":3,"explain":"Al-Razi, gran médico de los siglos IX y X, escribió un tratado sobre la viruela y el sarampión que describe con cuidado ambas enfermedades."},{"id":"q082","cat":"sciences","q":"¿Qué médico del siglo XIII describió cómo la sangre pasa del corazón a través de los pulmones?","options":["Al-Juarismi (al-Khwarizmi)","Al-Biruni","Ibn al-Nafis","Ibn Jaldún"],"answer":2,"explain":"Ibn al-Nafis describió la circulación pulmonar de la sangre en el siglo XIII, mucho antes de que se conociera en Europa."},{"id":"q083","cat":"sciences","q":"¿Qué sabio del siglo XI calculó el radio de la Tierra y escribió un gran estudio sobre la India?","options":["Ibn Rushd (Averroes)","Jabir ibn Hayyan","Al-Zahrawi","Al-Biruni"],"answer":3,"explain":"Al-Biruni calculó el radio de la Tierra con un método ingenioso, con un resultado cercano al valor moderno, y escribió un libro detallado sobre la India."},{"id":"q084","cat":"sciences","q":"¿Qué geógrafo trazó un célebre mapa del mundo para el rey Roger II de Sicilia en el siglo XII?","options":["Ibn Battuta","Ibn Jaldún","Al-Idrisi","Al-Juarismi (al-Khwarizmi)"],"answer":2,"explain":"Al-Idrisi terminó su mapa del mundo y el libro que lo acompaña en 1154, en la corte de Roger II en Sicilia."},{"id":"q085","cat":"sciences","q":"Jabir ibn Hayyan es conocido sobre todo por su trabajo ¿en qué campo?","options":["La óptica","La cirugía","La química","La geografía"],"answer":2,"explain":"Jabir ibn Hayyan es uno de los grandes nombres de la química primitiva (alquimia), y se le atribuyen muchas obras."},{"id":"q086","cat":"sciences","q":"¿En qué ciudad estaba la Casa de la Sabiduría (Bayt al-Hikma), la célebre biblioteca abasí vinculada al movimiento de traducción?","options":["Bagdad","Córdoba","El Cairo","Damasco"],"answer":0,"explain":"La Casa de la Sabiduría estaba en el Bagdad abasí, donde los sabios tradujeron y estudiaron obras de las tradiciones griega, persa e india."},{"id":"q087","cat":"sciences","q":"¿Quién escribió la «Muqaddima», célebre obra sobre la historia y la sociedad?","options":["Ibn Jaldún","Ibn Battuta","Ibn Rushd (Averroes)","Al-Ghazali"],"answer":0,"explain":"Ibn Jaldún, nacido en Túnez en 1332, escribió la Muqaddima. Se lo considera un precursor de la sociología y del estudio moderno de la historia."},{"id":"q088","cat":"sciences","q":"¿Para qué servía el astrolabio, instrumento perfeccionado por los sabios musulmanes?","options":["Para medir la temperatura","Para pesar oro y plata","Para moler grano","Para observar la posición del sol y las estrellas"],"answer":3,"explain":"El astrolabio servía para observar el sol y las estrellas, lo que ayudaba a saber la hora y a orientarse."},{"id":"q089","cat":"sciences","q":"¿Por qué es conocido el ingeniero al-Jazari, que terminó su célebre libro en 1206?","options":["Por máquinas ingeniosas y relojes de agua","Por un mapa del mundo","Por un tratado sobre la viruela","Por un libro de álgebra"],"answer":0,"explain":"Al-Jazari escribió el Libro del conocimiento de los ingeniosos dispositivos mecánicos, que describe relojes de agua, bombas y autómatas."},{"id":"q090","cat":"sciences","q":"¿Con qué nombre latino se conoce en Europa al sabio andalusí Ibn Rushd?","options":["Avicena","Alhacén","Rhazes","Averroes"],"answer":3,"explain":"Ibn Rushd de Córdoba es conocido como Averroes. Sus comentarios a Aristóteles se leyeron ampliamente en la Europa medieval."},{"id":"q091","cat":"pillars","q":"¿Cuántos pilares tiene el islam?","options":["Tres","Cinco","Cuatro","Siete"],"answer":1,"explain":"El islam tiene cinco pilares: el testimonio de fe, la oración, el zakat, el ayuno de Ramadán y la peregrinación a La Meca."},{"id":"q092","cat":"pillars","q":"¿Cuál es el primer pilar del islam?","options":["La oración (salat)","El ayuno (sawm)","La peregrinación (hajj)","El testimonio de fe (shahada)"],"answer":3,"explain":"El primer pilar es la shahada: atestiguar que no hay más dios que Allah y que Muhammad ﷺ es Su Mensajero."},{"id":"q093","cat":"pillars","q":"¿Cuántas oraciones obligatorias hay cada día?","options":["Dos","Tres","Cinco","Siete"],"answer":2,"explain":"Hay cinco oraciones obligatorias cada día: Fajr, Dhuhr, Asr, Maghrib e Isha."},{"id":"q094","cat":"pillars","q":"¿Cómo se llama la oración del alba?","options":["Dhuhr","Fajr","Asr","Isha"],"answer":1,"explain":"Fajr es la oración del alba, la primera de las cinco oraciones diarias."},{"id":"q095","cat":"pillars","q":"¿Cuántas unidades obligatorias (rak'at) tiene la oración de Fajr?","options":["Una","Dos","Tres","Cuatro"],"answer":1,"explain":"La oración obligatoria de Fajr tiene dos rak'at."},{"id":"q096","cat":"pillars","q":"¿Qué mes del calendario islámico es Ramadán?","options":["El noveno","El primero","El séptimo","El duodécimo"],"answer":0,"explain":"Ramadán es el noveno mes del calendario de la Hégira. Es el mes del ayuno."},{"id":"q097","cat":"pillars","q":"En Ramadán, ¿cuándo empieza el ayuno de cada día?","options":["Al alba","A la salida del sol","Al mediodía","A medianoche"],"answer":0,"explain":"El ayuno empieza al alba, cuando aparece la primera luz, como explica el Corán en 2:187."},{"id":"q098","cat":"pillars","q":"¿Cómo se llama la comida con la que se rompe el ayuno al anochecer?","options":["Suhur","Walima","Aqiqa","Iftar"],"answer":3,"explain":"El iftar es la comida con la que se rompe el ayuno. El suhur es la comida que se toma antes del alba."},{"id":"q099","cat":"pillars","q":"¿Cuál es el porcentaje habitual del zakat sobre ahorros como el dinero, el oro y la plata?","options":["2,5%","1%","5%","15%"],"answer":0,"explain":"El zakat sobre los ahorros es del 2,5%, una cuadragésima parte, una vez que la cantidad mínima se ha poseído durante un año lunar completo."},{"id":"q100","cat":"pillars","q":"¿En qué mes tiene lugar el Hajj?","options":["Ramadán","Dhul-Hiyya","Muharram","Shawwal"],"answer":1,"explain":"El Hajj tiene lugar en Dhul-Hiyya, el duodécimo y último mes del calendario de la Hégira."},{"id":"q101","cat":"pillars","q":"¿Cuántas vueltas dan los peregrinos alrededor de la Kaaba en un tawaf?","options":["Tres","Cinco","Siete","Nueve"],"answer":2,"explain":"Un tawaf consta de siete vueltas alrededor de la Kaaba."},{"id":"q102","cat":"pillars","q":"¿Entre qué dos colinas caminan los peregrinos durante el sa'i?","options":["Uhud y Thawr","Arafat y Mina","Safa y Marwa","Hira y Thawr"],"answer":2,"explain":"Los peregrinos caminan siete veces entre Safa y Marwa, que el Corán llama símbolos de Allah (2:158)."},{"id":"q103","cat":"pillars","q":"¿Qué día de Dhul-Hiyya permanecen los peregrinos en Arafat?","options":["El día 9","El día 1","El día 10","El día 13"],"answer":0,"explain":"La estancia en Arafat es el día 9 de Dhul-Hiyya. Es el corazón del Hajj."},{"id":"q104","cat":"pillars","q":"¿Cuántas veces en la vida es obligatorio el Hajj para un musulmán que puede hacerlo?","options":["Tres veces","Cada año","Cada cinco años","Una vez"],"answer":3,"explain":"El Hajj es obligatorio una vez en la vida para quienes pueden hacer el viaje (3:97)."},{"id":"q105","cat":"pillars","q":"¿Hacia qué ciudad rezaban los primeros musulmanes antes de que la qibla pasara a ser la Kaaba?","options":["Medina","Damasco","Taif","Jerusalén"],"answer":3,"explain":"Los primeros musulmanes rezaban hacia Jerusalén. Después la qibla se orientó hacia la Mezquita Sagrada de La Meca (2:144)."},{"id":"q106","cat":"civilisation","q":"¿Quién fundó en Fez, en el siglo IX, la mezquita de al-Qarawiyyin, que llegó a ser una célebre universidad?","options":["Rabia al-Adawiyya","Fátima al-Fihri","Zubayda bint Ja'far","Shajar al-Durr"],"answer":1,"explain":"Según la tradición, Fátima al-Fihri fundó al-Qarawiyyin en Fez, Marruecos, en 859. A menudo se la describe como la universidad más antigua todavía en actividad."},{"id":"q107","cat":"civilisation","q":"¿En qué ciudad de al-Ándalus está la gran mezquita célebre por su bosque de columnas y sus arcos rojos y blancos?","options":["Sevilla","Córdoba","Granada","Toledo"],"answer":1,"explain":"La Gran Mezquita de Córdoba se comenzó en el siglo VIII, cuando Córdoba era la capital de al-Ándalus."},{"id":"q108","cat":"civilisation","q":"¿En qué ciudad está el palacio de la Alhambra?","options":["Granada","Córdoba","Marrakech","Fez"],"answer":0,"explain":"La Alhambra se alza en Granada, en el sur de España. Fue el palacio de los soberanos nazaríes."},{"id":"q109","cat":"civilisation","q":"¿Qué emperador mogol mandó construir el Taj Mahal?","options":["Akbar","Babur","Aurangzeb","Shah Jahan"],"answer":3,"explain":"Shah Jahan mandó construir el Taj Mahal en Agra en el siglo XVII, en memoria de su esposa Mumtaz Mahal."},{"id":"q110","cat":"civilisation","q":"¿En qué ciudad nació el gran viajero Ibn Battuta?","options":["Fez","Túnez","El Cairo","Tánger"],"answer":3,"explain":"Ibn Battuta nació en Tánger, Marruecos, en 1304. Viajó durante casi treinta años por África, Asia y Europa."},{"id":"q111","cat":"civilisation","q":"Tombuctú, célebre centro de saber y de manuscritos, ¿en qué país actual se encuentra?","options":["Egipto","Marruecos","Malí","Sudán"],"answer":2,"explain":"Tombuctú está en Malí. Sus mezquitas y escuelas atrajeron a estudiantes y sabios de toda África Occidental."},{"id":"q112","cat":"civilisation","q":"¿En qué ciudad está al-Azhar, una de las universidades más antiguas del mundo?","options":["Bagdad","El Cairo","Damasco","Kairuán"],"answer":1,"explain":"Al-Azhar se fundó en El Cairo en el siglo X y sigue siendo hoy un gran centro de saber."},{"id":"q113","cat":"civilisation","q":"¿En qué ciudad está la Cúpula de la Roca?","options":["Jerusalén","Damasco","Medina","El Cairo"],"answer":0,"explain":"La Cúpula de la Roca está en Jerusalén. Se terminó a finales del siglo VII bajo el califa omeya Abd al-Malik."},{"id":"q114","cat":"civilisation","q":"¿Qué arquitecto otomano diseñó la mezquita Süleymaniye de Estambul?","options":["Al-Jazari","Ulugh Beg","Mimar Sinan","Ibn Jaldún"],"answer":2,"explain":"Mimar Sinan, arquitecto jefe del Imperio otomano en el siglo XVI, diseñó la Süleymaniye de Estambul y la Selimiye de Edirne."},{"id":"q115","cat":"civilisation","q":"En el mundo musulmán medieval, ¿qué era un «bimaristán»?","options":["Una biblioteca","Un observatorio","Un mercado cubierto","Un hospital"],"answer":3,"explain":"Un bimaristán era un hospital. Ciudades como Bagdad, Damasco y El Cairo tenían grandes hospitales donde se atendía a los enfermos."},{"id":"q116","cat":"civilisation","q":"¿Cuál es el primer mes del calendario de la Hégira?","options":["Muharram","Ramadán","Rayab","Shawwal"],"answer":0,"explain":"Muharram es el primero de los doce meses del calendario de la Hégira, que sigue a la luna."},{"id":"q117","cat":"civilisation","q":"En una mezquita, ¿qué es el mihrab?","options":["El púlpito que se usa para el sermón del viernes","El nicho que indica la dirección de La Meca","La torre que se usa para la llamada a la oración","La fuente que se usa para las abluciones"],"answer":1,"explain":"El mihrab es un nicho en el muro que indica la qibla, la dirección de La Meca. El púlpito se llama minbar y la torre, alminar."},{"id":"q118","cat":"civilisation","q":"La Gran Mezquita de Kairuán, una de las más antiguas de África, ¿en qué país se encuentra?","options":["Túnez","Marruecos","Egipto","Siria"],"answer":0,"explain":"Kairuán está en Túnez. Su Gran Mezquita se remonta a la fundación de la ciudad por Uqba ibn Nafi en 670."},{"id":"q119","cat":"civilisation","q":"La escritura cúfica, uno de los estilos más antiguos de la caligrafía árabe, ¿de qué ciudad toma su nombre?","options":["Córdoba","Konya","Kufa","Kabul"],"answer":2,"explain":"La escritura cúfica toma su nombre de Kufa, en Irak. Muchas copias antiguas del Corán se escribieron en este estilo anguloso."},{"id":"q120","cat":"civilisation","q":"En la civilización islámica, ¿qué es un «waqf»?","options":["Una caravana comercial","Un estilo de caligrafía","Una fundación benéfica","Un impuesto sobre las cosechas"],"answer":2,"explain":"Un waqf es un bien reservado para una obra de bien, como una escuela, un hospital o una fuente. Sus rentas siguen sirviendo a la gente a lo largo del tiempo."}]$tk$::jsonb)
  on conflict (kind, lang) do update set payload = excluded.payload, updated_at = now();
insert into public.premium_content (kind, lang, payload) values ('days', 'es', $tk${"new-year":{"detail":"El primer día de Muharram abre el año de la Hégira. El calendario islámico es lunar: cada mes comienza con el nuevo creciente, por lo que el año tiene unos once días menos que el año solar.\n\nEl calendario se organizó bajo el califa Umar ibn al-Jattab, algunos años después de la muerte del Profeta Muhammad ﷺ. Los Compañeros eligieron contar los años desde la Hégira, la emigración del Profeta ﷺ de La Meca a Medina en el año 622, y mantener Muharram como primer mes. La Hégira en sí tuvo lugar más adelante en el año, en el mes de Rabi' al-Awwal.\n\nMuharram es uno de los cuatro meses sagrados mencionados en el Corán (9:36). El Profeta ﷺ enseñó que el mejor ayuno después de Ramadán es el del mes de Allah, Muharram (Sahih Muslim 1163).\n\nNo se prescribe ninguna oración ni celebración especial para este día. Muchos musulmanes simplemente lo aprovechan para recordar la Hégira, repasar el año pasado y hacer buenos propósitos.","sources":["Corán 9:36","Sahih Muslim 1163"]},"tasua":{"detail":"Tasu'a es el noveno día de Muharram, la víspera de Ashura.\n\nCuando el Profeta Muhammad ﷺ ayunó Ashura y pidió a los musulmanes que lo ayunaran, sus Compañeros le señalaron que los judíos y los cristianos también honraban ese día. Él respondió que al año siguiente, si Allah quería, ayunarían también el noveno. Falleció antes de que llegara el siguiente Muharram (Sahih Muslim 1134).\n\nPor eso los sabios recomiendan ayunar el noveno día junto con el décimo. Así el ayuno de los musulmanes tiene su propia forma y conserva el vínculo con el día en que Allah salvó a Moisés (la paz sea con él).\n\nEste ayuno es voluntario. Quien solo puede ayunar el décimo ayuna igualmente Ashura, y nadie que esté enfermo, de viaje o no pueda ayunar debe sentirse culpable. Todo Muharram es un mes sagrado, y el Profeta ﷺ enseñó que el ayuno en él es el mejor después del de Ramadán (Sahih Muslim 1163).","sources":["Sahih Muslim 1134","Sahih Muslim 1163"]},"ashura":{"detail":"Ashura es el décimo día de Muharram. Su historia se remonta a Moisés (la paz sea con él): ese día Allah lo salvó a él y a los Hijos de Israel de su enemigo.\n\nCuando el Profeta Muhammad ﷺ llegó a Medina, encontró a los judíos ayunando ese día en recuerdo de aquella liberación. Dijo que los musulmanes tenían más derecho a Moisés, así que lo ayunó y pidió a los musulmanes que lo ayunaran (Sahih al-Bujari 2004). Cuando el ayuno de Ramadán se hizo obligatorio, el de Ashura quedó como un acto voluntario y recomendado (Sahih al-Bujari 2002).\n\nPreguntado por su recompensa, el Profeta ﷺ dijo que expía los pecados del año pasado (Sahih Muslim 1162). Se recomienda ayunar también el noveno día (Sahih Muslim 1134).","sources":["Sahih al-Bujari 2004","Sahih al-Bujari 2002","Sahih Muslim 1162","Sahih Muslim 1134"]},"mawlid":{"detail":"El Profeta Muhammad ﷺ nació en La Meca, en el clan de Banu Hashim de la tribu de Quraish, en el año conocido como el Año del Elefante, hacia el 570. Su padre Abdullah murió antes de su nacimiento, y su madre Amina murió cuando él era un niño pequeño.\n\nEstá establecido que nació un lunes: cuando le preguntaron por el ayuno de los lunes, dijo que era el día en que nació y el día en que le llegó la revelación (Sahih Muslim 1162). La mayoría de los historiadores sitúan su nacimiento en el mes de Rabi' al-Awwal. El día 12 es la fecha más conocida, pero se han propuesto otros días y ninguno es seguro.\n\nLos musulmanes difieren sobre conmemorar este día. Muchos se reúnen para recordar su vida, pedir bendiciones para él y compartir comida. Otros no distinguen este día, porque el Profeta ﷺ y sus Compañeros no lo hicieron. Todos coinciden en amarlo y en seguir su ejemplo cada día; el Corán lo describe como una misericordia para los mundos (21:107).","sources":["Sahih Muslim 1162","Corán 21:107"]},"isra-miraj":{"detail":"Al-Isra es el viaje nocturno del Profeta Muhammad ﷺ desde la Mezquita Sagrada de La Meca hasta la mezquita de al-Aqsa en Jerusalén. El Corán lo menciona al comienzo de la sura al-Isra (17:1). Al-Mi'ray es su ascensión desde allí a través de los cielos, donde se encontró con profetas anteriores (la paz sea con ellos) y se le mostraron grandes signos de su Señor; la sura an-Naym alude a ello (53:13-18).\n\nOcurrió en La Meca, antes de la Hégira, en un periodo de dificultad para el Profeta ﷺ. El regalo más duradero de aquella noche son las cinco oraciones diarias, que se hicieron obligatorias entonces (Sahih al-Bujari 349).\n\nLa fecha exacta no se conoce con certeza. El 27 de Rayab es la fecha más recordada, pero los primeros historiadores mencionan otras.\n\nNo hay ninguna oración ni ayuno particular establecido para esta noche. Muchos musulmanes aprovechan la ocasión para relatar el acontecimiento y recordar el valor de la oración; otros no señalan la fecha. Rayab es uno de los cuatro meses sagrados (9:36).","sources":["Corán 17:1","Corán 53:13-18","Sahih al-Bujari 349","Corán 9:36"]},"mid-shaban":{"detail":"Sha'ban es el octavo mes, justo antes de Ramadán. Aisha (que Allah esté complacido con ella) relató que nunca vio al Profeta Muhammad ﷺ ayunar en ningún mes, aparte de Ramadán, tanto como en Sha'ban (Sahih al-Bujari 1969). Es un mes para prepararse: ayunos voluntarios, recuperar los ayunos pendientes del Ramadán anterior y leer el Corán.\n\nLa noche del 15, a mitad de mes, se conoce en muchos países con nombres como Laylat al-Bara'a, Shab-e-Barat o Nisfu Sya'ban. Varios relatos hablan del perdón de Allah en esta noche. Los sabios difieren sobre la solidez de esos relatos, y por eso difieren sobre la práctica: muchos musulmanes pasan parte de la noche en oración y súplica y ayunan durante el día; otros la tratan como cualquier otra noche de Sha'ban y no le reservan una adoración especial.\n\nEn lo que hay acuerdo es en que pedir perdón, reconciliarse con los demás y ayunar voluntariamente son cosas buenas durante todo Sha'ban, la puerta de entrada a Ramadán.","sources":["Sahih al-Bujari 1969"]},"ramadan-start":{"detail":"Ramadán es el noveno mes del año de la Hégira, el mes en que fue revelado el Corán como guía para la gente (2:185). Ayunarlo es uno de los cinco pilares del islam (Sahih al-Bujari 8). Se prescribió en Medina, en el segundo año después de la Hégira.\n\nEl mes comienza cuando se avista el nuevo creciente; si no puede verse, se completa Sha'ban con treinta días (Sahih al-Bujari 1909). Por eso el comienzo puede variar un día de un país a otro.\n\nDesde el alba hasta la puesta del sol, quienes ayunan se abstienen de comer, de beber y de las relaciones conyugales. Los enfermos y los viajeros están exentos y recuperan los días más tarde, y quienes no pueden ayunar en absoluto alimentan a un pobre en su lugar (2:184-185). El Corán indica el objetivo del ayuno: crecer en piedad (2:183).\n\nEl Profeta Muhammad ﷺ dijo que cuando comienza Ramadán se abren las puertas del cielo, se cierran las puertas del Infierno y los demonios son encadenados (Sahih al-Bujari 1899). Es un mes de oración, de Corán y de generosidad.","sources":["Corán 2:183-185","Sahih al-Bujari 8","Sahih al-Bujari 1909","Sahih al-Bujari 1899"]},"last-ten-nights":{"detail":"Las diez últimas noches de Ramadán comienzan la víspera del día 21 y llegan hasta el final del mes, que tiene 29 o 30 días. Son la parte más valiosa de Ramadán, porque Laylat al-Qadr está entre ellas.\n\nAisha (que Allah esté complacido con ella) relató que cuando empezaban estas diez noches, el Profeta Muhammad ﷺ se ceñía el cinturón, pasaba la noche en oración y despertaba a su familia (Sahih al-Bujari 2024). Se esforzaba en la adoración en estas noches más que en cualquier otro momento (Sahih Muslim 1175).\n\nTambién practicaba el i'tikaf, el retiro en la mezquita para dedicarse a la adoración, durante los diez últimos días de Ramadán, hasta su muerte (Sahih al-Bujari 2026).\n\nLo recomendado: la oración nocturna, la lectura del Corán, muchas súplicas, pedir perdón y dar caridad. Quienes no pueden velar mucho tiempo pueden rezar un poco cada noche, para no perderse la noche que es mejor que mil meses (97:3). En estos días también se prepara la zakat al-fitr, antes de la oración del Eid.","sources":["Sahih al-Bujari 2024","Sahih Muslim 1175","Sahih al-Bujari 2026","Corán 97:3"]},"laylat-al-qadr":{"detail":"Laylat al-Qadr, la Noche del Decreto, es la noche en que fue revelado el Corán. Una sura entera está dedicada a ella: es mejor que mil meses, los ángeles y el Espíritu descienden en ella con el permiso de su Señor, y es paz hasta que despunta el alba (97:1-5). El Corán también la llama una noche bendita (44:3).\n\nSu fecha exacta ha quedado oculta. El Profeta Muhammad ﷺ pidió a los creyentes que la buscaran en las noches impares de las diez últimas de Ramadán (Sahih al-Bujari 2017): la del 21, 23, 25, 27 o 29. La del 27 es la noche más citada, y muchas comunidades se reúnen en ella, pero no es seguro, y los sabios tienen opiniones distintas. Lo más prudente es esforzarse durante las diez noches.\n\nEl Profeta ﷺ dijo que a quien pase Laylat al-Qadr en oración, con fe y esperando la recompensa, se le perdonarán sus pecados pasados (Sahih al-Bujari 2014). Los actos recomendados son la oración nocturna, la recitación del Corán, la súplica y pedir perdón a Allah.","sources":["Corán 97:1-5","Corán 44:3","Sahih al-Bujari 2017","Sahih al-Bujari 2014"]},"eid-al-fitr":{"detail":"El Eid al-Fitr, la Fiesta de la Ruptura del Ayuno, cae el primer día de Shawwal y cierra el mes de Ramadán. El Corán pide a los creyentes que completen el número de días y que proclamen la grandeza de Allah por haberlos guiado (2:185).\n\nAntes de la oración del Eid se entrega la zakat al-fitr: una pequeña caridad en alimentos básicos, debida por cada miembro del hogar, para que los pobres puedan participar de la fiesta. El Profeta Muhammad ﷺ ordenó que se pagara antes de que la gente saliera a la oración (Sahih al-Bujari 1503).\n\nPor la mañana, los musulmanes pronuncian el takbir, se ponen sus mejores ropas y se reúnen para la oración del Eid, seguida de un sermón (Sahih al-Bujari 956). Ese día, el Profeta ﷺ no salía hacia la oración sin haber comido antes algunos dátiles (Sahih al-Bujari 953).\n\nNo está permitido ayunar el día del Eid (Sahih al-Bujari 1991). Es un día de gratitud, de visitas familiares y de bondad con los vecinos. Los ayunos voluntarios, como los seis días de Shawwal, pueden empezar a partir del segundo día.","sources":["Corán 2:185","Sahih al-Bujari 1503","Sahih al-Bujari 956","Sahih al-Bujari 953","Sahih al-Bujari 1991"]},"six-shawwal":{"detail":"Shawwal es el mes que sigue a Ramadán. El Profeta Muhammad ﷺ dijo que quien ayuna Ramadán y luego lo sigue con seis días de Shawwal, es como si hubiera ayunado todo el año (Sahih Muslim 1164).\n\nLos sabios lo explican con la regla de que una buena obra se recompensa diez veces (6:160): el mes de Ramadán cuenta como diez meses, y seis días más cuentan como dos meses, lo que suma un año completo.\n\nVale cualquier grupo de seis días del mes. La aplicación muestra del 2 al 7 solo como periodo práctico: los días pueden ayunarse seguidos o separados, al principio, a mitad o al final de Shawwal. El único día excluido es el 1, el día del Eid, en el que no está permitido ayunar.\n\nEste ayuno es voluntario, no una obligación. Quien todavía tenga días de Ramadán por recuperar debe tenerlos en cuenta: muchos sabios aconsejan recuperarlos primero, mientras que otros permiten ayunar antes los seis días. Es una manera suave de mantener vivos los buenos hábitos de Ramadán.","sources":["Sahih Muslim 1164","Corán 6:160"]},"dhul-hijja-nine":{"detail":"Dhul-Hiyya es el duodécimo mes, el mes del Hayy. Sus diez primeros días están entre los mejores del año: el Profeta Muhammad ﷺ dijo que no hay buenas obras mejores que las realizadas en estos días (Sahih al-Bujari 969). Muchos comentaristas entienden también que las diez noches por las que Allah jura en el Corán (89:2) se refieren a ellos.\n\nComo el ayuno es una de las mejores obras, se recomienda ayunar durante los nueve primeros días, tanto como se pueda. El noveno, el Día de Arafat, es el más recomendado. El décimo es el Eid al-Adha, en el que no está permitido ayunar.\n\nTambién se recomienda repetir el takbir, alabar a Allah a menudo, rezar, dar caridad y leer el Corán. El Corán habla de mencionar el nombre de Allah en días conocidos (22:28).\n\nA quien tiene intención de ofrecer un sacrificio se le pide que no se corte el pelo ni las uñas desde el comienzo del mes hasta que el sacrificio se haya realizado (Sahih Muslim 1977). Durante estos días, peregrinos de todo el mundo se reúnen en La Meca.","sources":["Sahih al-Bujari 969","Corán 89:2","Corán 22:28","Sahih Muslim 1977"]},"arafat":{"detail":"El 9 de Dhul-Hiyya es el Día de Arafat, el corazón del Hayy. Desde el mediodía hasta la puesta del sol, los peregrinos permanecen en la llanura de Arafat, cerca de La Meca, en oración y súplica. La estancia en Arafat es el pilar esencial de la peregrinación.\n\nFue en este día, un viernes, durante la Peregrinación de Despedida del Profeta Muhammad ﷺ, cuando se reveló la aleya que anuncia que Allah había perfeccionado la religión (5:3), como relató Umar ibn al-Jattab (Sahih al-Bujari 45).\n\nEl Profeta ﷺ dijo que no hay día en que Allah libere del Fuego a más siervos que el Día de Arafat (Sahih Muslim 1348).\n\nPara quienes no están en el Hayy, ayunar este día es muy recomendable: el Profeta ﷺ dijo que expía los pecados del año anterior y del año siguiente (Sahih Muslim 1162). A los peregrinos no se les pide que ayunen; el Profeta ﷺ no ayunó mientras estaba en Arafat (Sahih al-Bujari 1988).\n\nEs un día de súplica, de recuerdo de Allah y de pedir perdón, dondequiera que uno esté.","sources":["Corán 5:3","Sahih al-Bujari 45","Sahih Muslim 1348","Sahih Muslim 1162","Sahih al-Bujari 1988"]},"eid-al-adha":{"detail":"El Eid al-Adha, la Fiesta del Sacrificio, cae el 10 de Dhul-Hiyya, el día siguiente a Arafat. Coincide con los ritos principales del Hayy en Mina y La Meca.\n\nRecuerda la prueba de Abraham (la paz sea con él). Vio en sueños que sacrificaba a su hijo; ambos se sometieron a la orden de Allah, y Allah rescató al hijo con un gran sacrificio (37:102-107).\n\nEl día comienza con la oración del Eid, seguida de un sermón (Sahih al-Bujari 956). Después de la oración, quienes pueden sacrifican una oveja, una cabra, una vaca o un camello. La carne la come la familia, se ofrece a parientes y vecinos y se da a los pobres. El Corán recuerda a los creyentes que ni la carne ni la sangre llegan a Allah; lo que llega a Él es su piedad (22:37).\n\nNo está permitido ayunar este día (Sahih al-Bujari 1991). Los musulmanes pronuncian el takbir, se ponen sus mejores ropas, se visitan y comparten comida. El sacrificio también puede hacerse en los días siguientes.","sources":["Corán 37:102-107","Sahih al-Bujari 956","Corán 22:37","Sahih al-Bujari 1991"]},"tashriq":{"detail":"Los días de Tashriq son el 11, el 12 y el 13 de Dhul-Hiyya, los tres días posteriores al Eid al-Adha. El Profeta Muhammad ﷺ los describió como días para comer, beber y recordar a Allah (Sahih Muslim 1141).\n\nDurante estos días, los peregrinos permanecen en Mina y arrojan cada día piedrecitas a los tres pilares llamados yamarat. El Corán les pide que recuerden a Allah en estos días contados, y dice que no hay pecado para quien se apresura a partir al cabo de dos días, ni para quien se queda más tiempo (2:203). Así, los peregrinos pueden marcharse el día 12 o quedarse hasta el 13.\n\nNo está permitido ayunar estos días. La única excepción transmitida es para los peregrinos que deben una ofrenda y no la encuentran (Sahih al-Bujari 1997).\n\nPara todos los demás, son días de alegría y gratitud: compartir la carne del sacrificio, visitar a los familiares y pronunciar el takbir, sobre todo después de las oraciones diarias. El sacrificio del Eid todavía puede ofrecerse en estos días, con detalles que varían según las escuelas jurídicas.","sources":["Sahih Muslim 1141","Corán 2:203","Sahih al-Bujari 1997"]}}$tk$::jsonb)
  on conflict (kind, lang) do update set payload = excluded.payload, updated_at = now();

-- ===== 10-premium-id =====
-- Contenu Premium — id
-- Fichier GÉNÉRÉ par scripts/build-seed.mjs : ne pas modifier à la main. Idempotent (peut être relancé).

insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$adam$tk$, 'id', 1, $tk$Adam$tk$, $tk$آدم$tk$, $tk$Manusia pertama dan nabi pertama$tk$, $tk$Adam alaihissalam adalah manusia pertama dan nabi pertama. Al-Qur'an mengabarkan bahwa Allah memberitahukan kepada para malaikat bahwa Dia akan menempatkan di bumi satu makhluk yang diberi amanah atasnya. Para malaikat bertanya-tanya tentang makhluk yang mungkin akan berbuat kerusakan dan menumpahkan darah. Allah menjawab bahwa Dia mengetahui apa yang tidak mereka ketahui.

Allah menciptakan Adam dari tanah liat dan mengajarkan kepadanya nama segala sesuatu. Ketika para malaikat diminta menyebutkan nama-nama itu, mereka mengakui bahwa mereka hanya mengetahui apa yang telah Allah ajarkan kepada mereka. Adam pun menyebutkannya. Ilmu adalah kemuliaan pertama yang diberikan kepada umat manusia.

Allah memerintahkan para malaikat bersujud kepada Adam. Semuanya patuh kecuali Iblis, yang menolak karena sombong, dengan mengaku bahwa dirinya, yang diciptakan dari api, lebih baik daripada makhluk yang dibuat dari tanah liat. Ia diusir, dan ia bersumpah akan berusaha menyesatkan anak cucu Adam.

Adam dan istrinya ditempatkan di surga. Mereka boleh makan apa saja dengan leluasa, kecuali dari satu pohon. Setan membisiki keduanya, bersumpah bahwa ia adalah penasihat yang tulus dan menjanjikan kehidupan yang kekal kepada mereka. Keduanya pun memakan buah pohon itu. Al-Qur'an tidak menimpakan kesalahan kepada sang istri saja: ia menyebutkan bahwa keduanya tergelincir. Aurat mereka pun tampak bagi mereka, dan mereka mulai menutupi diri dengan daun-daun surga.

Apa yang terjadi sesudahnya adalah inti kisah ini. Adam dan istrinya tidak membantah atau mencari-cari alasan, seperti yang dilakukan Iblis. Mereka kembali kepada Tuhan mereka, mengakui bahwa mereka telah menzalimi diri sendiri, serta memohon ampunan dan rahmat-Nya. Adam menerima beberapa kalimat dari Tuhannya, dan Allah menerima tobatnya. Al-Qur'an menyebutkan bahwa Tuhannya kemudian memilihnya, mengampuninya, dan memberinya petunjuk.

Adam dan istrinya diturunkan ke bumi, tempat manusia akan hidup, mati, dan dibangkitkan kembali. Allah berjanji bahwa petunjuk akan datang kepada mereka, dan bahwa siapa pun yang mengikutinya tidak perlu merasa takut dan tidak akan bersedih hati.

Al-Qur'an tidak menyebutkan di mana surga itu berada, pohon apa itu, atau berapa lama Adam hidup, dan kita tidak perlu menebak-nebak. Yang diajarkannya ialah bahwa seluruh manusia berasal dari ayah dan ibu yang sama, dan bahwa pintu tobat telah terbuka sejak hari yang paling pertama.$tk$, $tk$Setiap orang pernah berbuat salah; yang penting adalah mengakuinya tanpa mencari-cari alasan dan segera kembali kepada Allah. Kesombongan menutup pintu yang dibuka oleh kerendahan hati.$tk$, $tk$["2:30-39","7:11-25","20:115-123"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$idris$tk$, 'id', 2, $tk$Idris$tk$, $tk$إدريس$tk$, $tk$Seorang yang sangat jujur dan diangkat ke kedudukan yang tinggi$tk$, $tk$Idris alaihissalam termasuk nabi yang sangat sedikit dibicarakan Al-Qur'an. Namanya hanya disebut di dua tempat, dan setiap kali hanya dalam beberapa kata.

Dalam Surah Maryam, setelah kisah beberapa nabi, Allah memerintahkan Nabi Muhammad ﷺ agar menceritakan Idris di dalam Kitab. Ia digambarkan sebagai seorang yang sangat jujur dan seorang nabi, dan Al-Qur'an menambahkan bahwa Allah mengangkatnya ke kedudukan yang tinggi. Dalam Surah al-Anbiya, ia disebut bersama Ismail dan Zulkifli: ketiganya termasuk orang-orang yang sabar, Allah memasukkan mereka ke dalam rahmat-Nya, dan mereka termasuk orang-orang saleh.

Hanya itu yang diberitakan Al-Qur'an kepada kita. Al-Qur'an tidak menyebutkan kapan Idris hidup, kepada kaum mana ia diutus, atau apa yang terjadi selama masa tugasnya. Para ulama menjelaskan kedudukan yang tinggi itu dengan cara yang berbeda-beda: sebagian memahaminya sebagai derajat dan kemuliaan yang tinggi di sisi Allah, sebagian lain sebagai tempat yang tinggi di langit. Dalam hadis sahih tentang Isra Mikraj, Nabi Muhammad ﷺ menuturkan bahwa beliau bertemu Idris di langit keempat, dan bahwa Idris menyambut beliau (Sahih al-Bukhari, no. 3887).

Banyak kitab yang ditulis belakangan menambahkan perincian: bahwa dialah orang pertama yang menulis dengan pena, menjahit pakaian, atau mempelajari bintang-bintang, atau bahwa ia sama dengan seorang tokoh yang dikenal dari kitab-kitab suci terdahulu. Riwayat-riwayat ini tidak bersumber dari Al-Qur'an ataupun hadis sahih. Semuanya tidak dapat disajikan sebagai fakta yang pasti, dan lebih bijak untuk mengesampingkannya.

Yang tersisa memang singkat, tetapi berharga. Dari seluruh perjalanan hidupnya, Al-Qur'an mengabadikan tiga sifat: kejujuran, kesabaran, dan kesalehan. Kata Arab yang dipakai untuknya, shiddiq, menggambarkan seseorang yang sangat jujur, yang perbuatannya selaras dengan ucapannya dan ucapannya selaras dengan imannya. Tidak ada cerita tentang kekuasaan, kekayaan, atau kemasyhuran yang melekat pada namanya; hanya akhlaknya yang diabadikan.

Beberapa ayat tentang Idris itu juga mengingatkan kita bahwa nilai seseorang di sisi Allah tidak bergantung pada seberapa banyak orang mengetahui tentang dirinya. Seorang nabi bisa dimuliakan dalam Al-Qur'an hanya dengan dua baris, dan dua baris itu sudah cukup untuk menjadikannya teladan.$tk$, $tk$Jadilah orang yang jujur dan sabar meskipun tidak ada yang memperhatikan: di sisi Allah, akhlak lebih berarti daripada kemasyhuran.$tk$, $tk$["19:56-57","21:85-86"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$nuh$tk$, 'id', 3, $tk$Nuh$tk$, $tk$نوح$tk$, $tk$Penyeru yang tak kenal lelah dan pembuat bahtera$tk$, $tk$Nuh alaihissalam diutus kepada suatu kaum yang telah terjerumus ke dalam penyembahan berhala. Al-Qur'an bahkan menyebutkan nama berhala-berhala itu: Wadd, Suwa', Yaghuts, Ya'uq, dan Nasr. Nuh datang kepada mereka dengan pesan yang sederhana: sembahlah Allah semata, mohonlah ampunan-Nya, niscaya Dia mengampuni kalian.

Al-Qur'an menyebutkan bahwa Nuh tinggal di tengah kaumnya selama seribu tahun kurang lima puluh. Ia menyeru mereka siang dan malam, secara terbuka maupun secara pribadi. Ia mengingatkan mereka bahwa Allah Maha Pengampun dan bahwa Dia akan menurunkan hujan yang lebat bagi mereka. Namun semakin ia menyeru, semakin mereka berpaling. Mereka memasukkan jari ke telinga dan menutupi diri dengan pakaian agar tidak mendengarnya.

Para pemuka kaumnya memandangnya rendah. Mereka berkata bahwa ia hanyalah manusia seperti mereka, dan bahwa yang mengikutinya hanyalah orang-orang paling hina. Nuh menjawab bahwa ia tidak meminta harta dari mereka, bahwa upahnya hanyalah dari Allah, dan bahwa ia tidak akan pernah mengusir orang-orang yang beriman.

Ketika diwahyukan kepada Nuh bahwa tidak ada lagi dari kaumnya yang akan beriman, Allah memerintahkannya membuat bahtera di bawah pengawasan-Nya. Para pemuka mengejeknya setiap kali mereka lewat. Kemudian datanglah ketetapan Allah, dan banjir besar pun mulai. Nuh diperintahkan menaikkan ke bahtera sepasang dari setiap jenis makhluk, keluarganya, dan orang-orang yang beriman, dan mereka itu hanya sedikit.

Bahtera itu berlayar di tengah gelombang laksana gunung. Nuh melihat salah seorang putranya berdiri menyendiri dan memanggilnya agar naik. Sang putra menjawab bahwa ia akan berlindung ke sebuah gunung. Gelombang pun memisahkan keduanya, dan ia termasuk orang-orang yang ditenggelamkan. Nuh mengadu kepada Tuhannya tentang putranya, dan Allah memberitahukan kepadanya bahwa putra itu bukanlah benar-benar termasuk keluarganya, karena perbuatannya tidak saleh. Nuh menerima hal itu dengan rendah hati.

Kemudian bumi diperintahkan menelan airnya dan langit menahan hujannya. Bahtera itu berlabuh di atas Gunung Judi, dan Nuh diperintahkan turun dengan selamat, disertai keberkahan atas dirinya dan atas orang-orang yang bersamanya. Al-Qur'an menyebutkan bahwa bahtera itu dijadikan tanda bagi seluruh manusia.$tk$, $tk$Teruslah berbuat benar meskipun hasilnya lambat terlihat. Keberhasilan diukur dari kesetiaan, bukan dari banyaknya orang yang mengikutimu.$tk$, $tk$["11:25-48","71:1-28","29:14-15","54:9-15"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$hud$tk$, 'id', 4, $tk$Hud$tk$, $tk$هود$tk$, $tk$Rasul yang diutus kepada kaum 'Ad$tk$, $tk$Hud alaihissalam diutus kepada kaum 'Ad, yang tinggal di suatu wilayah yang oleh Al-Qur'an disebut al-Ahqaf, bukit-bukit pasir. Mereka datang setelah kaum Nuh dan dikaruniai kekuatan yang besar. Hud adalah salah seorang dari mereka: Al-Qur'an menyebutnya saudara mereka.

Pesannya sama dengan pesan setiap nabi: sembahlah Allah semata, tidak ada tuhan lain bagi kalian. Ia mengatakan kepada mereka bahwa ia tidak meminta upah apa pun. Ia mengajak mereka memohon ampunan kepada Tuhan mereka dan kembali kepada-Nya, seraya menjanjikan bahwa Allah akan menurunkan hujan yang lebat bagi mereka dan menambahkan kekuatan di atas kekuatan mereka.

Para pemuka 'Ad menjawab dengan kasar. Mereka menuduhnya kurang akal dan berdusta. Sebagian bahkan berkata bahwa salah satu sembahan mereka pasti telah menimpakan keburukan kepadanya. Hud menjawab dengan tenang bahwa tidak ada kekurangan akal pada dirinya, bahwa ia adalah utusan dari Tuhan seluruh alam dan penasihat yang tepercaya bagi mereka. Ia mengingatkan mereka bahwa Allah telah menjadikan mereka pengganti setelah kaum Nuh, dan ia meminta mereka mengingat nikmat-nikmat-Nya.

Kemudian ia mengucapkan kata-kata yang amat berani. Ia menyatakan berlepas diri dari sembahan-sembahan palsu yang mereka sembah, dan ia menantang mereka agar bersama-sama membuat tipu daya terhadap dirinya, tanpa memberinya tangguh sedikit pun. Ia berkata bahwa ia bertawakal kepada Allah, Tuhannya dan Tuhan mereka, yang berkuasa atas setiap makhluk yang hidup.

Kaum 'Ad tidak berubah. Mereka bahkan meminta Hud mendatangkan azab yang ia peringatkan kepada mereka. Suatu hari mereka melihat awan yang bergerak menuju lembah-lembah mereka dan bergembira, karena mengira awan itu akan membawa hujan. Padahal itu adalah angin kencang yang membawa azab yang pedih. Al-Qur'an menyebutkan bahwa angin itu menerpa mereka selama tujuh malam dan delapan hari berturut-turut, sehingga kaum itu bergelimpangan seperti batang-batang pohon kurma yang telah lapuk. Sesudahnya tidak ada yang terlihat selain tempat tinggal mereka.

Hud dan orang-orang yang beriman bersamanya diselamatkan dengan rahmat Allah. Al-Qur'an tidak memberitahukan berapa jumlah mereka atau ke mana mereka pergi sesudah itu.

Kisah kaum 'Ad diceritakan beberapa kali dalam Al-Qur'an sebagai peringatan bagi setiap kaum yang kuat: kekuatan dan kemakmuran adalah karunia, dan keduanya tidak melindungi siapa pun yang memakainya untuk menolak kebenaran dan berlaku sombong.$tk$, $tk$Kekuatan, bakat, dan harta adalah karunia yang patut disyukuri, bukan alasan untuk merasa lebih tinggi daripada orang lain. Ketika seseorang memberimu nasihat yang tulus, dengarkanlah sebelum menilai.$tk$, $tk$["7:65-72","11:50-60","46:21-25","69:6-8"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$salih$tk$, 'id', 5, $tk$Shalih$tk$, $tk$صالح$tk$, $tk$Rasul yang diutus kepada kaum Tsamud$tk$, $tk$Shalih alaihissalam diutus kepada kaum Tsamud, yang datang setelah kaum 'Ad. Mereka adalah para pembangun yang mahir: Al-Qur'an menyebutkan bahwa mereka mendirikan istana-istana di tanah datar dan memahat rumah-rumah pada gunung. Shalih adalah salah seorang dari mereka, dan sebelum ia diutus kaumnya menaruh harapan besar kepadanya.

Ia menyeru mereka untuk menyembah Allah semata. Ia mengingatkan mereka bahwa Allah-lah yang telah menciptakan mereka dari bumi dan menjadikan mereka penghuninya, dan ia meminta mereka memohon ampunan-Nya serta tidak berbuat kerusakan di muka bumi. Jawaban mereka adalah kekecewaan: bagaimana mungkin ia melarang mereka menyembah apa yang disembah nenek moyang mereka? Mereka berkata bahwa mereka sungguh ragu terhadap seruannya.

Segelintir orang beriman, kebanyakan dari kalangan yang lemah. Para pemuka yang sombong bertanya kepada mereka, dengan nada menghina, apakah mereka benar-benar yakin bahwa Shalih diutus oleh Tuhannya. Orang-orang beriman itu menjawab dengan lugas bahwa mereka beriman kepada apa yang dibawanya.

Allah kemudian memberi kaum Tsamud sebuah tanda yang nyata: seekor unta betina. Al-Qur'an menyebutnya unta betina Allah. Shalih meminta kaumnya membiarkan unta itu makan dengan bebas di bumi Allah, menghormati giliran minumnya, dan tidak mengganggunya, sebab jika tidak, azab akan menimpa mereka. Al-Qur'an tidak menggambarkan bagaimana unta betina itu muncul, dan kisah-kisah terperinci yang diceritakan tentang hal itu tidak dapat dipastikan kebenarannya.

Ujian itu sederhana, dan mereka gagal. Al-Qur'an juga menyebut sembilan orang laki-laki di kota itu yang berbuat kerusakan dan bersumpah bersama untuk menyerang Shalih dan keluarganya pada malam hari. Orang yang paling celaka di antara mereka pun bangkit, lalu unta betina itu dipotong urat kakinya dan dibunuh. Kemudian mereka menantang Shalih agar mendatangkan azab yang ia ancamkan.

Shalih mengatakan kepada mereka bahwa mereka masih mempunyai tiga hari untuk bersenang-senang di rumah mereka, sebuah janji yang tidak akan didustakan. Lalu datanglah azab itu: suara yang mengguntur dan gempa menimpa mereka, dan mereka mati bergelimpangan di rumah-rumah mereka, seakan-akan mereka tidak pernah tinggal di sana. Shalih dan orang-orang yang beriman bersamanya diselamatkan dengan rahmat Allah.

Al-Qur'an mengabadikan kata-kata terakhir Shalih ketika ia meninggalkan mereka: ia telah menyampaikan risalah Tuhannya kepada mereka dan memberi mereka nasihat yang tulus, tetapi mereka tidak menyukai orang-orang yang memberi nasihat.$tk$, $tk$Nikmat juga merupakan tanggung jawab: hormatilah apa yang diamanahkan kepadamu. Sambutlah nasihat yang tulus, meskipun itu bukan hal yang ingin kamu dengar.$tk$, $tk$["7:73-79","11:61-68","27:45-53","91:11-15"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$ibrahim$tk$, 'id', 6, $tk$Ibrahim$tk$, $tk$إبراهيم$tk$, $tk$Kekasih Allah dan bapak para nabi$tk$, $tk$Ibrahim alaihissalam tumbuh di tengah kaum yang menyembah berhala dan benda-benda langit. Ayahnya sendiri, yang oleh Al-Qur'an disebut Azar, termasuk di antara mereka. Sejak muda, Allah telah mengaruniai Ibrahim pemikiran yang lurus, dan ia tidak dapat menerima bahwa manusia tunduk kepada patung-patung yang mereka buat dengan tangan mereka sendiri.

Al-Qur'an mengisahkan bagaimana ia berdialog dengan kaumnya memakai akal sehat. Ia memandang sebuah bintang, lalu bulan, lalu matahari. Masing-masing terbenam dan menghilang, dan setiap kali ia menunjukkan bahwa sesuatu yang menghilang tidak mungkin menjadi Tuhan. Ia kemudian menyatakan bahwa ia menghadapkan wajahnya kepada Zat yang menciptakan langit dan bumi.

Suatu hari, ketika orang-orang telah pergi, Ibrahim menghancurkan berhala-berhala mereka hingga berkeping-keping, kecuali yang terbesar. Ketika mereka menanyainya, ia menyuruh mereka bertanya kepada berhala besar itu, jika berhala memang dapat berbicara. Sesaat mereka menyadari betapa tidak masuk akalnya sembahan mereka. Namun kesombongan menang, dan mereka memutuskan untuk membakarnya. Allah memerintahkan api itu agar menjadi dingin dan menyelamatkan bagi Ibrahim, dan ia keluar tanpa cedera.

Ibrahim kemudian meninggalkan kaumnya demi Tuhannya dan memohon kepada-Nya seorang anak yang saleh. Pada usia tuanya, Allah mengaruniainya Ismail dan Ishaq, dan ia bersyukur kepada Zat yang mendengar setiap doa.

Atas perintah Allah, ia menempatkan sebagian keluarganya di sebuah lembah yang tidak bertanaman, di dekat Baitullah, dan berdoa agar hati manusia condong kepada mereka dan agar mereka diberi rezeki berupa buah-buahan. Kelak, ia meninggikan fondasi Ka'bah bersama putranya, Ismail. Sambil membangun, keduanya memohon agar Allah menerima amal mereka dan mengutus kepada penduduk negeri itu seorang rasul dari kalangan mereka sendiri.

Ibrahim juga diuji dengan ujian yang paling berat: ia melihat dalam mimpi bahwa ia menyembelih putranya. Ia menceritakan hal itu kepada putranya, dan sang putra menjawab agar ia mengerjakan apa yang diperintahkan kepadanya. Ketika keduanya telah berserah diri, Allah menyeru Ibrahim bahwa ia telah membenarkan mimpi itu, dan sang putra ditebus dengan seekor sembelihan yang besar. Kaum muslimin mengenang peristiwa ini setiap tahun pada Iduladha.

Al-Qur'an menyebutkan bahwa Ibrahim diuji oleh Tuhannya dengan beberapa perintah dan ia menunaikan semuanya, dan bahwa Allah menjadikannya pemimpin bagi umat manusia.$tk$, $tk$Gunakan akalmu untuk mencari kebenaran, dan beranilah mengikutinya meskipun kamu berdiri sendirian. Apa yang kita tinggalkan karena Allah tidak pernah sia-sia.$tk$, $tk$["6:74-83","21:51-70","2:124-129","37:99-111","14:35-41"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$lut$tk$, 'id', 7, $tk$Luth$tk$, $tk$لوط$tk$, $tk$Nabi yang tetap teguh di tengah kaum yang rusak$tk$, $tk$Luth alaihissalam hidup pada masa Ibrahim alaihissalam. Al-Qur'an menyebutkan bahwa ia beriman kepada risalah Ibrahim. Ia kemudian diutus sebagai nabi kepada suatu kaum yang nama kotanya tidak disebutkan Al-Qur'an.

Kaum ini telah terjerumus ke dalam dosa-dosa besar. Al-Qur'an menyebutkan bahwa mereka melakukan perbuatan keji yang belum pernah dilakukan oleh kaum mana pun sebelum mereka: kaum laki-lakinya mendatangi laki-laki dengan syahwat, bukan perempuan. Mereka juga menyerang para musafir di jalan dan berbuat mungkar secara terang-terangan di tempat-tempat pertemuan mereka. Luth menyeru mereka agar bertakwa kepada Allah dan meninggalkan perbuatan-perbuatan itu. Ia mengatakan kepada mereka bahwa ia tidak meminta imbalan dan bahwa ia adalah rasul yang tepercaya bagi mereka.

Satu-satunya jawaban mereka adalah mengejek dan mengancamnya. Mereka berkata: usirlah Luth dan para pengikutnya dari kota ini, sebab mereka adalah orang-orang yang ingin menjaga kesucian diri. Mereka bahkan menantangnya untuk mendatangkan azab Allah jika ia memang berkata benar. Luth pun memohon pertolongan kepada Tuhannya terhadap kaum yang berbuat kerusakan itu.

Para malaikat diutus dengan membawa tugas. Mula-mula mereka mengunjungi Ibrahim, menyampaikan kepadanya kabar gembira tentang seorang putra, dan memberitahukan bahwa mereka sedang menuju kaum Luth. Lalu mereka mendatangi Luth dalam rupa tamu. Ia tidak tahu siapa mereka, dan ia merasa susah, karena khawatir akan apa yang bakal dilakukan kaumnya terhadap mereka. Benar saja, kaum laki-laki kota itu datang bergegas ke rumahnya. Luth memohon kepada mereka agar bertakwa kepada Allah dan tidak mempermalukannya di hadapan tamu-tamunya. Ia berharap seandainya saja ia mempunyai kekuatan untuk menghalangi mereka.

Para malaikat itu kemudian menyingkapkan siapa mereka: utusan-utusan Tuhannya, yang tidak akan pernah bisa dijangkau oleh kaum itu. Mereka menyuruh Luth pergi pada malam hari bersama keluarganya, dan tidak seorang pun boleh menoleh ke belakang. Akan tetapi istrinya akan termasuk orang-orang yang tertinggal dan akan mengalami nasib yang sama dengan yang lain.

Pada pagi harinya, azab itu pun turun. Kota itu dijungkirbalikkan dan dihujani batu dari tanah liat yang keras. Luth dan anggota keluarganya yang mengikutinya diselamatkan.

Al-Qur'an menyebutkan bahwa bekas-bekas tempat itu dibiarkan sebagai tanda yang nyata bagi orang-orang yang menggunakan akalnya.$tk$, $tk$Berbuat benar tidak bergantung pada apa yang dilakukan kebanyakan orang. Tetaplah setia pada nilai-nilai yang kamu pegang, meskipun kamu diejek karena ingin menjaga kesucian diri.$tk$, $tk$["7:80-84","11:77-83","15:57-77","29:26-35"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$ismail$tk$, 'id', 8, $tk$Ismail$tk$, $tk$إسماعيل$tk$, $tk$Yang benar janjinya, pembangun Ka'bah bersama ayahnya$tk$, $tk$Ismail alaihissalam adalah putra Ibrahim alaihissalam. Ibrahim telah memohon kepada Tuhannya seorang anak yang saleh, dan ia bersyukur kepada Allah karena dikaruniai Ismail dan Ishaq pada usia tuanya.

Al-Qur'an mengabadikan doa Ibrahim yang menyatakan bahwa ia telah menempatkan sebagian keturunannya di sebuah lembah yang tidak bertanaman, di dekat Baitullah, agar mereka mendirikan salat. Sebuah hadis panjang dalam Sahih al-Bukhari (no. 3364) mengisahkan bagaimana Ibrahim meninggalkan Ismail, yang masih bayi, bersama ibunya, Hajar, di lembah Makkah yang sunyi itu, bagaimana Hajar berlari di antara bukit Shafa dan Marwah mencari air, dan bagaimana mata air Zamzam memancar. Para jemaah haji dan umrah hingga kini berjalan di antara kedua bukit itu untuk mengenang tawakalnya kepada Allah.

Al-Qur'an kemudian mengisahkan sebuah ujian besar. Ibrahim melihat dalam mimpi bahwa ia menyembelih putranya, dan ia menanyakan pendapat sang putra. Putra itu, yang digambarkan lembut dan penyantun, menjawab agar ayahnya mengerjakan apa yang diperintahkan kepadanya, dan bahwa ayahnya akan mendapatinya, insya Allah, termasuk orang-orang yang sabar. Ketika keduanya telah berserah diri, Allah menyeru Ibrahim bahwa ia telah membenarkan mimpi itu, dan Dia menebus sang putra dengan seekor sembelihan yang besar. Al-Qur'an tidak menyebutkan nama sang putra dalam ayat-ayat ini; kebanyakan ulama Islam berpendapat bahwa ia adalah Ismail.

Ayah dan anak itu kemudian bekerja bersama dalam sebuah tugas yang hingga kini mewarnai kehidupan kaum muslimin. Allah memerintahkan Ibrahim dan Ismail agar menyucikan rumah-Nya bagi orang-orang yang tawaf, yang beriktikaf, yang rukuk, dan yang sujud. Bersama-sama mereka meninggikan fondasi Ka'bah, seraya memohon agar Allah menerima amal itu dari mereka, menjadikan mereka dan keturunan mereka orang-orang yang berserah diri kepada-Nya, dan mengutus kepada penduduk negeri itu seorang rasul dari kalangan mereka sendiri. Kaum muslimin memandang kedatangan Nabi Muhammad ﷺ, seorang keturunan Ismail, sebagai jawaban atas doa ini.

Al-Qur'an merangkum akhlak Ismail dalam beberapa kata. Ia adalah seorang yang benar janjinya, seorang rasul dan nabi. Ia senantiasa menyuruh kaumnya mengerjakan salat dan menunaikan zakat, dan Tuhannya rida kepadanya. Di tempat lain ia disebut termasuk orang-orang yang sabar dan termasuk orang-orang yang diberi keutamaan oleh Allah.$tk$, $tk$Tepatilah janjimu, bahkan yang kecil sekalipun, dan pedulilah pada iman orang-orang terdekatmu. Tawakal kepada Allah tumbuh melalui kesabaran pada saat-saat yang sulit.$tk$, $tk$["2:125-129","19:54-55","37:101-107","14:37-39","21:85-86"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$ishaq$tk$, 'id', 9, $tk$Ishaq$tk$, $tk$إسحاق$tk$, $tk$Kabar gembira bagi Ibrahim pada usia tuanya$tk$, $tk$Ishaq alaihissalam adalah putra kedua Ibrahim alaihissalam. Al-Qur'an mengisahkan kelahirannya dengan cukup terperinci, tetapi hanya sedikit menyinggung sisa kehidupannya.

Suatu hari, beberapa tamu datang kepada Ibrahim dan mengucapkan salam kepadanya. Ia membalas salam mereka dan, karena sifatnya yang dermawan, segera menghidangkan daging anak sapi panggang untuk mereka. Akan tetapi para tamu itu tidak menjamah hidangan tersebut. Ibrahim pun merasa gelisah. Mereka berkata kepadanya agar tidak takut: mereka adalah malaikat yang diutus kepada kaum Luth, dan mereka membawa kabar gembira untuknya tentang seorang putra yang berilmu.

Istri Ibrahim berdiri di dekat situ. Al-Qur'an menyebutkan bahwa ia diberi kabar gembira tentang Ishaq dan, setelah Ishaq, tentang Ya'qub. Ia tercengang: bagaimana mungkin ia melahirkan anak padahal ia seorang perempuan tua yang tidak pernah bisa mempunyai anak, dan suaminya pun sudah lanjut usia? Para malaikat menjawab: apakah ia merasa heran terhadap ketetapan Allah? Mereka mendoakan rahmat dan keberkahan Allah bagi seisi rumah itu.

Janji itu menjadi kenyataan. Ibrahim memuji Allah karena telah mengaruniainya Ismail dan Ishaq pada usia tuanya, dan menyatakan bahwa Tuhannya mendengar setiap doa.

Al-Qur'an menggambarkan Ishaq sebagai seorang nabi yang termasuk orang-orang saleh, dan menyebutkan bahwa Allah melimpahkan keberkahan kepada Ibrahim dan Ishaq. Al-Qur'an menambahkan bahwa Allah menjadikan Ishaq dan Ya'qub pemimpin-pemimpin yang memberi petunjuk dengan perintah-Nya, serta mewahyukan kepada mereka agar berbuat kebajikan, mendirikan salat, dan menunaikan zakat; mereka adalah hamba-hamba yang tekun beribadah kepada Allah. Ketika Ya'qub menjelang wafat, putra-putranya berjanji akan menyembah Tuhan nenek moyangnya, Ibrahim, Ismail, dan Ishaq, yaitu Tuhan Yang Maha Esa.

Selain itu, Al-Qur'an tidak menguraikan tugas kenabian Ishaq ataupun peristiwa-peristiwa dalam hidupnya. Banyak perincian yang terdapat dalam sumber-sumber lain tidak dikukuhkan oleh Al-Qur'an ataupun hadis sahih, sehingga tidak kami ulangi di sini.

Dari Ishaq lahirlah Ya'qub, dan dari Ya'qub lahir mata rantai panjang para nabi di kalangan Bani Israil, di antaranya Yusuf, Musa, Dawud, dan Isa, alaihimussalam. Kelahiran Ishaq menunjukkan bahwa Allah menepati janji-Nya pada waktu yang Dia tentukan, bahkan ketika semua sebab yang tampak seolah berkata bahwa sudah terlambat.$tk$, $tk$Jangan pernah mengira sudah terlambat bagi sebuah doa untuk dikabulkan. Kemurahan hati kepada tamu dan tawakal kepada Allah membuka pintu-pintu yang tampak tertutup.$tk$, $tk$["11:69-73","37:112-113","51:24-30","14:39","21:72-73"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$yaqub$tk$, 'id', 10, $tk$Ya'qub$tk$, $tk$يعقوب$tk$, $tk$Sang ayah yang kesabarannya indah$tk$, $tk$Ya'qub alaihissalam adalah putra Ishaq dan cucu Ibrahim, alaihimussalam. Ia juga dikenal dengan nama Israil, dan keturunannya disebut Bani Israil. Al-Qur'an membicarakannya terutama sebagai seorang ayah, dalam kisah putranya, Yusuf.

Ketika Yusuf kecil menceritakan kepadanya sebuah mimpi bahwa sebelas bintang, matahari, dan bulan bersujud kepadanya, Ya'qub memahami bahwa Allah telah memilih anak ini. Ia menasihatinya agar tidak menceritakan mimpi itu kepada saudara-saudaranya, karena khawatir rasa dengki akan mendorong mereka berbuat makar terhadapnya.

Saudara-saudaranya memang berbuat makar. Mereka meminta izin membawa Yusuf pergi bersama mereka. Ya'qub berkata bahwa melepasnya pergi membuatnya sedih dan bahwa ia khawatir seekor serigala akan memangsanya. Pada petang hari mereka pulang sambil menangis, membawa baju Yusuf yang berlumur darah palsu. Ya'qub tidak memercayai cerita mereka. Ia berkata kepada mereka bahwa nafsu mereka sendirilah yang telah menyeret mereka melakukan sesuatu, dan ia memilih kesabaran yang indah, seraya memohon pertolongan kepada Allah semata.

Tahun-tahun berlalu. Ketika putranya yang lain ditahan di Mesir, kepedihan itu datang lagi. Ya'qub berpaling dan berduka atas Yusuf, dan kedua matanya menjadi putih karena kesedihan yang ia pendam. Putra-putranya menyalahkannya karena masih saja mengingat Yusuf. Ia menjawab bahwa ia hanya mengadukan kesusahan dan kesedihannya kepada Allah, dan bahwa ia mengetahui dari Allah apa yang tidak mereka ketahui.

Kemudian ia memberi mereka nasihat ini: pergilah dan carilah kabar tentang Yusuf dan saudaranya, dan janganlah berputus asa dari rahmat Allah.

Harapannya terbalas. Yusuf, yang kini menjadi pejabat tinggi di Mesir, mengirimkan bajunya agar diletakkan di wajah ayahnya. Ketika kafilah itu meninggalkan Mesir, Ya'qub berkata bahwa ia mencium bau Yusuf. Ketika baju itu diletakkan di wajahnya, ia dapat melihat kembali. Putra-putranya memintanya memohonkan ampunan bagi mereka, dan ia berjanji akan melakukannya. Seluruh keluarga itu pun berkumpul kembali di Mesir.

Al-Qur'an juga mengabadikan kepedulian terakhir Ya'qub. Ketika ajal mendekat, ia bertanya kepada putra-putranya apa yang akan mereka sembah sepeninggalnya. Mereka menjawab bahwa mereka akan menyembah Tuhannya dan Tuhan nenek moyangnya, Ibrahim, Ismail, dan Ishaq, yaitu Tuhan Yang Maha Esa.$tk$, $tk$Kesedihan bukanlah tanda kurangnya iman: adukanlah kepedihanmu kepada Allah dan teruslah berharap. Jangan pernah berputus asa dari rahmat-Nya.$tk$, $tk$["2:132-133","12:4-6","12:83-87","12:93-100"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$yusuf$tk$, 'id', 11, $tk$Yusuf$tk$, $tk$يوسف$tk$, $tk$Sang jujur, dari dasar sumur hingga perbendaharaan Mesir$tk$, $tk$Kisah Yusuf alaihissalam memenuhi satu surah penuh dalam Al-Qur'an. Semasa kecil, ia bermimpi bahwa sebelas bintang, matahari, dan bulan bersujud kepadanya. Ayahnya, Ya'qub alaihissalam, menyuruhnya merahasiakan mimpi itu dari saudara-saudaranya.

Saudara-saudaranya dengki karena kasih sayang ayah mereka kepada Yusuf. Mereka membawanya pergi dan melemparkannya ke dasar sebuah sumur, lalu berkata kepada ayah mereka bahwa seekor serigala telah memangsanya. Serombongan musafir yang lewat mengangkat Yusuf dari sumur itu, dan ia dijual di Mesir dengan harga beberapa keping uang saja.

Ia tumbuh besar di rumah seorang pejabat tinggi Mesir. Ketika ia dewasa, istri pejabat itu berusaha menggodanya. Yusuf berlindung kepada Allah dan berlari ke arah pintu; perempuan itu mengoyak bajunya dari belakang, dan hal itu membuktikan bahwa ia tidak bersalah. Meski demikian ia tetap dijebloskan ke penjara. Ia bahkan pernah berkata bahwa penjara lebih ia sukai daripada memenuhi ajakan mereka kepadanya.

Di penjara, Yusuf dikenal karena kebaikannya. Ia menafsirkan mimpi dua orang sesama tahanan dan memanfaatkan kesempatan itu untuk berbicara kepada mereka tentang Tuhan Yang Maha Esa. Salah seorang dari mereka dibebaskan, tetapi lupa menyebut perihal Yusuf kepada tuannya, sehingga Yusuf tetap berada di penjara selama beberapa tahun.

Kemudian sang raja bermimpi: tujuh ekor sapi gemuk dimakan oleh tujuh ekor sapi kurus, serta tujuh bulir gandum yang hijau dan tujuh lainnya yang kering. Yusuf menjelaskannya: tujuh tahun panen yang baik, lalu tujuh tahun yang sulit, sehingga hasil panen harus disimpan. Sebelum keluar dari penjara, ia meminta agar kebersihan namanya dibuktikan, dan istri pejabat itu mengakui kebenarannya. Yusuf meminta agar diserahi tugas mengurus perbendaharaan negeri, dan ia mengelolanya dengan cermat.

Ketika paceklik datang, saudara-saudaranya pergi ke Mesir untuk mencari bahan makanan. Yusuf mengenali mereka, tetapi mereka tidak mengenalinya. Setelah beberapa kali perjalanan, ia menyingkapkan siapa dirinya. Mereka mengakui kesalahan mereka. Ia menjawab bahwa pada hari itu tidak ada cercaan atas mereka dan bahwa ia berharap Allah mengampuni mereka.

Yusuf kemudian memboyong kedua orang tuanya dan seluruh keluarganya ke Mesir. Mimpi masa kecilnya telah menjadi kenyataan. Ia menutup dengan sebuah doa, memohon kepada Tuhannya agar diwafatkan dalam keadaan berserah diri kepada-Nya dan digabungkan dengan orang-orang saleh.$tk$, $tk$Tetaplah jujur dan menjaga kesucian diri, baik ketika kamu berada di bawah maupun di puncak. Ketika akhirnya kamu berkuasa atas orang-orang yang pernah menyakitimu, memaafkan adalah pilihan yang paling mulia.$tk$, $tk$["12:4-21","12:23-35","12:36-57","12:88-101"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$ayyub$tk$, 'id', 12, $tk$Ayyub$tk$, $tk$أيوب$tk$, $tk$Teladan kesabaran$tk$, $tk$Ayyub alaihissalam adalah nabi yang namanya telah menjadi lambang kesabaran. Al-Qur'an memasukkannya ke dalam golongan para nabi yang menerima wahyu dan ke dalam keturunan Ibrahim yang diberi petunjuk oleh Allah.

Al-Qur'an menceritakan kisahnya dalam beberapa ayat, tanpa banyak perincian. Ayyub ditimpa ujian berat yang mengenai kesehatannya dan keluarganya. Al-Qur'an tidak menggambarkan penyakitnya, juga tidak menyebutkan berapa lama penyakit itu berlangsung. Banyak cerita beredar tentang hal ini, sebagiannya berlebihan dan tidak layak bagi seorang nabi; cerita-cerita itu tidak dapat dipastikan kebenarannya dan kami kesampingkan.

Yang diabadikan Al-Qur'an adalah cara Ayyub berbicara kepada Tuhannya. Ia tidak mengeluh kepada manusia, dan ia tidak menyalahkan Allah. Ia hanya berseru bahwa kesusahan telah menimpanya, dan bahwa Allah adalah Yang Maha Penyayang di antara semua penyayang. Dalam ayat lain, ia berkata bahwa setan telah menimpakan kepayahan dan penderitaan kepadanya. Doanya tidak mengandung tuntutan apa pun: ia menggambarkan keadaannya, memuji rahmat Tuhannya, dan menyerahkan selebihnya kepada-Nya.

Allah mengabulkan doanya. Dia menyuruhnya menghentakkan kaki ke tanah: sebuah mata air yang sejuk pun memancar, untuk mandi dan untuk minum. Penderitaannya dihilangkan. Allah mengembalikan keluarganya kepadanya dan menambahkan sebanyak itu pula bersama mereka, sebagai rahmat dari-Nya dan peringatan bagi para ahli ibadah serta orang-orang yang berakal.

Al-Qur'an juga menyebutkan bahwa Ayyub pernah bersumpah pada masa ujiannya. Allah menunjukkan kepadanya cara yang lembut untuk memenuhi sumpahnya tanpa menyakiti: mengambil seikat rumput dengan tangannya lalu memukul dengan itu. Al-Qur'an tidak menjelaskan secara terperinci latar belakang sumpah tersebut.

Ayat-ayat itu ditutup dengan pujian dari Allah sendiri: Dia mendapati Ayyub seorang yang sabar, sebaik-baik hamba, yang selalu kembali kepada-Nya.

Kesabaran Ayyub bukanlah sikap diam atau ketiadaan rasa sakit. Ia merasakan penderitaannya dan mengungkapkannya, tetapi ia mengungkapkannya kepada Allah, dengan penuh adab dan harapan. Kisahnya telah menghibur orang-orang yang sakit dan berduka selama berabad-abad, karena kisah itu menunjukkan bahwa ujian bukanlah tanda bahwa Allah menolak seseorang, dan bahwa jalan keluar bisa datang dari arah yang tidak disangka-sangka.$tk$, $tk$Dalam kesulitan, adukanlah kepedihanmu kepada Allah tanpa kehilangan adab ataupun harapan. Sabar tidak berarti tidak merasakan apa-apa; sabar berarti tetap setia ketika terasa sakit.$tk$, $tk$["21:83-84","38:41-44","4:163","6:84"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$shuayb$tk$, 'id', 13, $tk$Syu'aib$tk$, $tk$شعيب$tk$, $tk$Nabi perniagaan yang jujur$tk$, $tk$Syu'aib alaihissalam diutus kepada penduduk Madyan. Al-Qur'an menyebutnya saudara mereka, sebab ia adalah salah seorang dari mereka. Al-Qur'an juga menyebut dakwahnya kepada penduduk Aikah; para ulama berbeda pendapat apakah mereka itu kaum yang sama dengan penduduk Madyan atau kelompok tetangganya.

Penduduk Madyan hidup makmur, tetapi perniagaan mereka dibangun di atas kecurangan. Mereka mengurangi takaran dan timbangan, serta merampas apa yang menjadi hak orang lain. Mereka juga duduk di jalan-jalan untuk menakut-nakuti orang dan menghalangi orang-orang beriman dari jalan Allah.

Syu'aib mula-mula menyeru mereka untuk menyembah Allah semata. Kemudian ia berbicara kepada mereka tentang urusan mereka sehari-hari: sempurnakanlah takaran dan timbangan dengan adil, jangan merugikan manusia dalam hak-hak mereka, dan jangan berbuat kerusakan di bumi setelah bumi itu diperbaiki. Ia mengatakan kepada mereka bahwa keuntungan halal yang Allah sisakan bagi mereka itu lebih baik bagi mereka. Ia mengingatkan mereka bahwa dahulu mereka berjumlah sedikit lalu Allah memperbanyak mereka.

Jawaban mereka bernada mengejek. Apakah salatnya yang menyuruhnya agar mereka meninggalkan apa yang disembah nenek moyang mereka, atau berhenti berbuat sekehendak hati terhadap harta mereka sendiri? Syu'aib menjawab dengan kata-kata yang tetap masyhur: ia tidak ingin mengerjakan sendiri apa yang ia larang bagi mereka; ia hanya ingin mengadakan perbaikan semampunya, dan keberhasilannya bergantung kepada Allah semata, yang kepada-Nya ia bertawakal.

Ia memperingatkan mereka agar permusuhan mereka terhadapnya jangan sampai mendatangkan nasib seperti yang menimpa kaum Nuh, Hud, Shalih, atau Luth. Ia mengajak mereka memohon ampunan, seraya berkata bahwa Tuhannya Maha Penyayang lagi Maha Pengasih.

Para pemuka itu beralih kepada ancaman. Mereka berkata bahwa mereka tidak banyak mengerti apa yang ia ucapkan, bahwa mereka memandangnya lemah di tengah mereka, dan bahwa kalau bukan karena keluarganya tentulah mereka telah merajamnya. Mereka mengancam akan mengusirnya bersama orang-orang beriman kecuali mereka kembali kepada agama kaum itu.

Azab pun datang. Al-Qur'an menyebut gempa dan suara yang mengguntur yang membuat mereka mati bergelimpangan di rumah-rumah mereka, dan menyebut pula azab pada hari awan yang menaungi. Syu'aib dan orang-orang yang beriman bersamanya diselamatkan dengan rahmat Allah.$tk$, $tk$Iman tampak dalam cara kita membeli, menjual, dan bekerja: berikanlah kepada setiap orang haknya. Amalkanlah apa yang kamu minta dari orang lain.$tk$, $tk$["7:85-93","11:84-95","26:176-191","29:36-37"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$musa$tk$, 'id', 14, $tk$Musa$tk$, $tk$موسى$tk$, $tk$Nabi yang diajak berbicara oleh Allah$tk$, $tk$Musa alaihissalam adalah nabi yang paling sering disebut dalam Al-Qur'an. Ia lahir di Mesir pada masa ketika Fir'aun menindas Bani Israil dan memerintahkan agar bayi-bayi laki-laki mereka dibunuh. Allah mengilhamkan kepada ibu Musa agar meletakkan bayinya di sungai, dengan janji akan mengembalikannya kepadanya. Keluarga Fir'aun memungutnya, dan istri Fir'aun meminta agar ia dibiarkan hidup. Karena bayi itu menolak setiap perempuan yang hendak menyusuinya, ia dikembalikan kepada ibunya sendiri untuk disusui.

Ketika telah menjadi pemuda, Musa memukul seorang Mesir yang sedang berkelahi dengan seorang lelaki dari kaumnya, lalu orang itu mati. Musa tidak bermaksud membunuhnya; ia langsung menyesal dan memohon ampunan kepada Allah. Ia melarikan diri ke Madyan. Di sana ia menolong dua orang perempuan memberi minum ternak mereka, lalu duduk berteduh dan berdoa bahwa ia sangat membutuhkan kebaikan apa pun yang Allah turunkan kepadanya. Ayah kedua perempuan itu menyambutnya, menikahkannya dengan salah seorang putrinya, dan Musa bekerja untuknya selama bertahun-tahun.

Dalam perjalanan pulang bersama keluarganya, ia melihat api di dekat Gunung Thur. Di sana Allah berbicara kepadanya, menjadikannya rasul-Nya, dan memberinya tanda-tanda: tongkatnya berubah menjadi ular dan tangannya bersinar putih. Musa memohon agar saudaranya, Harun, diutus bersamanya. Allah memerintahkan keduanya pergi menemui Fir'aun dan berbicara kepadanya dengan lemah lembut.

Fir'aun menolak mendengarkan dan mengumpulkan para penyihirnya. Namun ketika mereka melihat tongkat Musa menelan tipuan-tipuan mereka, mereka mengenali kebenaran dan menyatakan beriman, meskipun diancam oleh Fir'aun.

Allah kemudian memerintahkan Musa pergi pada malam hari bersama kaumnya. Fir'aun mengejar mereka dengan bala tentaranya sampai ke laut. Kaum itu panik, tetapi Musa menjawab bahwa Tuhannya bersamanya dan akan memberinya petunjuk. Ia memukul laut dengan tongkatnya; laut itu terbelah, dan mereka menyeberang. Fir'aun dan bala tentaranya ditenggelamkan.

Musa kemudian pergi memenuhi janji pertemuan dengan Tuhannya selama empat puluh malam dan menerima lembaran-lembaran (alwah). Selama ia pergi, sebagian kaumnya mulai menyembah patung anak sapi yang dibuat dari perhiasan mereka. Musa pulang dengan marah dan sedih, lalu menyeru mereka agar bertobat.

Sepanjang sisa hidupnya, Musa memimpin kaumnya dengan sabar, membawa Taurat, yang merupakan petunjuk dan cahaya.$tk$, $tk$Tidak ada orang yang terlalu lemah untuk dipilih mengemban sesuatu yang besar, dan tidak ada penguasa zalim yang terlalu kuat untuk tumbang. Ketika kamu merasa terjepit, ingatlah bahwa Allah bersama orang-orang yang bertawakal kepada-Nya.$tk$, $tk$["28:3-35","20:9-79","26:52-68","7:142-145","2:51-54"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$harun$tk$, 'id', 15, $tk$Harun$tk$, $tk$هارون$tk$, $tk$Saudara dan pembantu Musa$tk$, $tk$Harun alaihissalam adalah saudara Musa alaihissalam. Dalam Al-Qur'an, kisahnya selalu terkait dengan kisah Musa: dialah nabi yang dijadikan penopang bagi nabi yang lain.

Ketika Allah berbicara kepada Musa dan mengutusnya kepada Fir'aun, Musa menyadari betapa berat tugas itu. Ia memohon kepada Tuhannya agar melapangkan dadanya, memudahkan urusannya, dan melepaskan kekakuan lidahnya supaya orang-orang memahami perkataannya. Kemudian ia memohon seorang pembantu dari keluarganya sendiri: Harun, saudaranya, untuk menguatkannya dan menyertainya dalam tugasnya. Musa berkata bahwa Harun lebih fasih daripada dirinya. Allah mengabulkan permohonan itu, dan Al-Qur'an menyebutkan bahwa, karena rahmat-Nya, Allah menganugerahkan kepada Musa saudaranya, Harun, sebagai seorang nabi.

Kedua bersaudara itu pergi menemui Fir'aun bersama-sama. Allah telah memerintahkan mereka agar berbicara kepadanya dengan lemah lembut, dengan harapan ia mau ingat atau merasa takut. Mereka memintanya melepaskan Bani Israil dan berhenti menyiksa mereka. Ketika para penyihir Fir'aun melihat kebenaran, mereka menyatakan beriman kepada Tuhan Harun dan Musa.

Setelah menyeberangi laut, Musa pergi memenuhi janji pertemuan dengan Tuhannya selama empat puluh malam. Sebelum berangkat, ia meminta Harun menggantikannya di tengah kaumnya, berbuat baik, dan tidak mengikuti jalan orang-orang yang berbuat kerusakan.

Pada masa kepergian itulah datang ujian patung anak sapi. Seorang lelaki yang oleh Al-Qur'an disebut Samiri menyesatkan kaum itu dengan patung anak sapi yang dibuat dari perhiasan mereka. Al-Qur'an menegaskan bahwa Harun tidak ikut serta dalam hal ini. Ia mengatakan kepada mereka bahwa mereka sedang diuji dengan patung itu, bahwa Tuhan mereka adalah Yang Maha Pengasih, dan bahwa mereka hendaknya mengikutinya serta menaati perintahnya. Mereka menolak mendengarkan sampai Musa kembali.

Ketika Musa pulang, dalam keadaan marah dan sedih, ia memegang kepala saudaranya. Harun menjawabnya dengan lembut, memanggilnya wahai putra ibuku. Ia menjelaskan bahwa kaum itu telah menganggapnya lemah dan hampir membunuhnya, dan bahwa ia khawatir akan memecah belah Bani Israil. Musa kemudian memohon kepada Allah agar mengampuni dirinya dan saudaranya serta memasukkan keduanya ke dalam rahmat-Nya.

Di tempat lain, Al-Qur'an memasukkan Harun ke dalam golongan para nabi yang diberi petunjuk dan diberi balasan karena berbuat baik.$tk$, $tk$Mendukung tugas orang lain sama mulianya dengan memimpinnya. Dalam perselisihan dengan orang terdekat, jawablah dengan lembut dan jelaskan keadaanmu dengan tenang.$tk$, $tk$["20:29-36","28:34-35","20:90-94","7:150-151","19:53"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$dhul-kifl$tk$, 'id', 16, $tk$Zulkifli$tk$, $tk$ذو الكفل$tk$, $tk$Termasuk orang-orang yang sabar dan orang-orang pilihan$tk$, $tk$Zulkifli alaihissalam termasuk tokoh yang paling sedikit diberitakan Al-Qur'an kepada kita. Ia hanya disebut dua kali, setiap kali dalam satu ayat saja dan bersama nabi-nabi lain.

Dalam Surah al-Anbiya, ia disebut bersama Ismail dan Idris. Al-Qur'an menyebutkan bahwa mereka semua termasuk orang-orang yang sabar, bahwa Allah memasukkan mereka ke dalam rahmat-Nya, dan bahwa mereka termasuk orang-orang saleh. Dalam Surah Shad, ia disebut bersama Ismail dan Ilyasa, dan Al-Qur'an menyebutkan bahwa mereka semua termasuk orang-orang yang paling baik.

Itulah seluruh keterangan Al-Qur'an. Al-Qur'an tidak memberitahukan di mana atau kapan ia hidup, kepada kaum mana ia diutus, atau apa yang ia lakukan. Tidak ada pula hadis sahih yang menambahkan perincian yang jelas tentang kehidupannya.

Namanya sendiri menjadi bahan pembahasan. Dalam bahasa Arab, Dzulkifl kurang lebih berarti pemilik bagian, atau orang yang menanggung suatu kesanggupan. Sebagian ahli tafsir berpendapat bahwa ia diberi nama itu karena ia menanggung suatu kewajiban yang berat dan menunaikannya dengan setia, tetapi ini adalah penjelasan atas makna kata tersebut, bukan riwayat yang pasti. Yang lain mencoba menyamakannya dengan tokoh-tokoh yang dikenal dari tradisi lain; pendapat-pendapat ini hanyalah dugaan, dan tidak satu pun bersandar pada dalil yang kuat.

Kebanyakan ulama berpendapat bahwa ia seorang nabi, karena Al-Qur'an menyebut namanya dan memujinya di antara para nabi. Segelintir ulama berpendapat bahwa ia adalah seorang yang saleh, bukan nabi. Menurut kedua pendapat itu, ia adalah hamba yang dipuji oleh Allah sendiri, dan itulah kemuliaan yang paling agung.

Patut diperhatikan sifat-sifat apa yang dipilih Al-Qur'an untuk disebutkan. Yang pertama adalah kesabaran: kemampuan untuk terus berbuat benar dalam waktu yang lama, tanpa menyerah ketika keadaan sulit. Yang kedua adalah kesalehan. Yang ketiga adalah tergolong orang-orang yang paling baik, bersama nabi-nabi seperti Ismail dan Ilyasa.

Karena itu, lebih baik mengatakan dengan jujur bahwa kita tidak mengetahui perincian hidupnya daripada mengisi kekosongan itu dengan legenda. Al-Qur'an tidak selalu mengajar melalui kisah yang panjang. Kadang sebuah nama dan sepatah pujian sudah cukup untuk mengingatkan kita bahwa Allah mengetahui hamba-hamba-Nya yang setia, termasuk mereka yang kisahnya tidak pernah ditulis oleh siapa pun.$tk$, $tk$Kamu tidak perlu terkenal untuk menjadi berharga di sisi Allah. Kesabaran dan kesetiaan pada kesanggupanmu diperhatikan oleh-Nya, meskipun tidak ada orang lain yang melihatnya.$tk$, $tk$["21:85-86","38:48"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$dawud$tk$, 'id', 17, $tk$Dawud$tk$, $tk$داود$tk$, $tk$Nabi, raja, dan hamba yang tekun beribadah$tk$, $tk$Dawud alaihissalam muncul pertama kali dalam Al-Qur'an di sebuah medan perang. Bani Israil, di bawah pimpinan raja mereka, Thalut, berhadapan dengan bala tentara Jalut. Orang-orang beriman itu sedikit jumlahnya, tetapi mereka memohon kesabaran dan keteguhan kepada Allah. Mereka mengalahkan musuh dengan izin Allah, dan Dawud membunuh Jalut. Allah kemudian menganugerahkan kepadanya kerajaan dan hikmah serta mengajarkan kepadanya apa yang Dia kehendaki.

Dawud menjadi nabi sekaligus raja. Allah memberinya Zabur. Al-Qur'an menggambarkannya sebagai hamba yang mempunyai kekuatan besar dan senantiasa kembali kepada Tuhannya. Ketika ia bertasbih kepada Allah, gunung-gunung dan burung-burung mengulang tasbih itu bersamanya, pada waktu petang dan saat matahari terbit.

Allah juga melunakkan besi untuknya dan mengajarinya membuat baju besi dengan anyaman yang terukur baik, untuk melindungi manusia dalam peperangan. Meskipun ia seorang raja, sebuah hadis memberitakan bahwa Dawud hanya makan dari hasil kerja tangannya sendiri (Sahih al-Bukhari, no. 2072).

Kerajaannya dikukuhkan, dan ia dianugerahi hikmah serta kebijaksanaan dalam memutuskan perkara. Namun Al-Qur'an juga mengisahkan suatu saat ketika ia diuji. Dua orang yang berselisih masuk ke mihrabnya dan memintanya memutuskan perkara di antara mereka. Dawud memberikan jawabannya, lalu menyadari bahwa Allah sedang mengujinya. Ia memohon ampunan kepada Tuhannya, tersungkur sujud, dan bertobat, dan Allah pun mengampuninya. Al-Qur'an tidak memberikan perincian lebih lanjut tentang ujian ini, dan cerita-cerita yang ditambahkan kepadanya tidak layak bagi seorang nabi.

Setelah itu, Allah berfirman langsung kepadanya: Dia telah menjadikannya khalifah di bumi, maka ia harus memutuskan perkara di antara manusia dengan benar dan tidak mengikuti hawa nafsunya.

Al-Qur'an juga menyebut sebuah perkara tentang ladang yang dirusak pada malam hari oleh kambing-kambing milik suatu kaum. Dawud dan putranya, Sulaiman, masing-masing memberikan keputusan, dan Allah memberikan kepada Sulaiman pemahaman yang lebih tepat tentang perkara itu, sedangkan keduanya sama-sama telah dianugerahi hikmah dan ilmu.

Dengan demikian, pada diri Dawud berpadu hal-hal yang sering kita anggap terpisah: kekuasaan dan kerendahan hati, keterampilan seorang perajin dan ketekunan seorang ahli ibadah.$tk$, $tk$Apa pun tanggung jawab yang kamu pegang, berlakulah adil dan jangan biarkan keinginanmu sendiri yang memutuskan. Ketika menyadari bahwa kamu keliru, segeralah kembali kepada Allah.$tk$, $tk$["2:251","38:17-26","21:78-80","34:10-11","17:55"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$sulayman$tk$, 'id', 18, $tk$Sulaiman$tk$, $tk$سليمان$tk$, $tk$Raja yang membalas setiap karunia dengan rasa syukur$tk$, $tk$Sulaiman alaihissalam adalah putra Dawud alaihissalam, dan ia mewarisi kenabian serta kerajaan darinya. Al-Qur'an menyebutnya sebaik-baik hamba yang senantiasa kembali kepada Allah. Ia memohon kepada Tuhannya agar mengampuninya dan menganugerahkan kepadanya kerajaan yang tidak akan dimiliki oleh siapa pun sesudahnya.

Allah mengabulkan doanya. Dia menundukkan angin baginya, yang berembus atas perintahnya ke mana saja ia kehendaki. Para jin bekerja untuknya sebagai pembangun dan penyelam serta membuat apa yang ia inginkan. Ia diajari bahasa burung, dan bala tentaranya terdiri atas jin, manusia, dan burung, yang diatur berbaris-baris.

Suatu hari bala tentara ini sampai di sebuah lembah semut. Seekor semut memperingatkan kawan-kawannya agar masuk ke sarang mereka supaya tidak terinjak oleh Sulaiman dan bala tentaranya tanpa mereka sadari. Sulaiman memahami ucapannya dan tersenyum. Alih-alih merasa bangga, ia memohon kepada Allah agar membantunya mensyukuri nikmat-nikmat-Nya dan mengerjakan amal saleh yang Dia ridai.

Pada kesempatan lain, ia mendapati burung hudhud tidak hadir. Burung itu kembali membawa kabar dari negeri Saba': seorang ratu memerintah di sana, memiliki singgasana yang besar, dan ia bersama kaumnya bersujud kepada matahari, bukan kepada Allah. Sulaiman mengirimkan kepadanya sepucuk surat, yang dibuka dengan nama Allah Yang Maha Pengasih, Maha Penyayang, dan mengajak mereka datang kepadanya dalam keadaan berserah diri.

Sang ratu bermusyawarah dengan para pembesarnya dan memilih bersikap hati-hati. Ia mengirim hadiah, tetapi Sulaiman menolaknya: apa yang Allah berikan kepadanya lebih baik. Sebelum sang ratu tiba, singgasananya didatangkan kepada Sulaiman dalam sekejap mata oleh seseorang yang mempunyai ilmu dari Kitab. Ketika melihat singgasana itu di hadapannya, Sulaiman berkata bahwa ini adalah karunia Tuhannya, untuk menguji apakah ia bersyukur atau kufur.

Ketika sang ratu memasuki istananya, ia mengira lantai dari kaca yang licin itu adalah air. Ia pun menyadari bahwa dirinya telah keliru dalam banyak hal, dan menyatakan bahwa ia berserah diri, bersama Sulaiman, kepada Allah, Tuhan seluruh alam.

Al-Qur'an juga mengisahkan wafatnya. Ia wafat dalam keadaan bertelekan pada tongkatnya, dan para jin terus bekerja tanpa mengetahuinya, sampai seekor binatang kecil dari tanah memakan tongkat itu dan ia pun tersungkur. Barulah mereka mengerti bahwa mereka tidak mengetahui perkara gaib.$tk$, $tk$Semakin banyak yang kamu terima, semakin bersyukur dan rendah hati seharusnya dirimu. Setiap kemampuan adalah ujian tentang apa yang akan kamu perbuat dengannya.$tk$, $tk$["27:15-44","21:81-82","34:12-14","38:30-40"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$ilyas$tk$, 'id', 19, $tk$Ilyas$tk$, $tk$إلياس$tk$, $tk$Rasul yang menyeru kaumnya agar meninggalkan Ba'l$tk$, $tk$Ilyas alaihissalam disebut dalam dua tempat di Al-Qur'an. Yang pertama, dalam Surah al-An'am, menyebut namanya dalam deretan para nabi, bersama Zakaria, Yahya, dan Isa, serta menyatakan bahwa mereka semua termasuk orang-orang saleh. Yang kedua, dalam Surah ash-Shaffat, memuat kisah singkat tentang tugas kerasulannya.

Al-Qur'an menyebutkan bahwa Ilyas termasuk salah seorang rasul. Ia berbicara kepada kaumnya dan bertanya mengapa mereka tidak bertakwa kepada Allah. Mereka menyembah sebuah berhala yang disebut Ba'l. Ilyas bertanya kepada mereka bagaimana mungkin mereka menyeru Ba'l dan meninggalkan sebaik-baik pencipta: Allah, Tuhan mereka dan Tuhan nenek moyang mereka.

Hujahnya sederhana dan jelas. Zat yang menciptakan mereka dan menciptakan leluhur mereka sebelum mereka adalah satu-satunya yang berhak disembah. Berhala tidak menciptakan apa pun, dan berpaling kepadanya berarti melupakan Zat yang telah memberi mereka kehidupan.

Al-Qur'an kemudian memberitakan bahwa kaumnya mendustakannya. Karena itu mereka akan dihadapkan untuk dimintai pertanggungjawaban, kecuali hamba-hamba Allah yang ikhlas. Ini berarti ada sebagian orang, meskipun sedikit, yang mendengarkannya dan tetap setia.

Ayat-ayat itu ditutup dengan sebuah penghormatan. Allah mengabadikan bagi Ilyas sebutan yang baik di kalangan generasi yang datang kemudian dan melimpahkan salam sejahtera kepadanya. Dia berfirman bahwa demikianlah Dia memberi balasan kepada orang-orang yang berbuat baik, dan bahwa Ilyas termasuk hamba-hamba-Nya yang beriman.

Al-Qur'an tidak memberikan perincian lain. Al-Qur'an tidak menyebutkan nama kaum Ilyas, negeri tempat ia tinggal, atau masa kerasulannya, dan tidak menggambarkan bagaimana hidupnya berakhir. Para ahli tafsir umumnya menggolongkannya sebagai salah satu nabi yang diutus kepada Bani Israil, dan tradisi-tradisi lain menuturkan kisah panjang tentang dirinya, tetapi riwayat-riwayat itu tidak dikukuhkan oleh Al-Qur'an ataupun hadis sahih. Karena itu kami berpegang pada apa yang pasti.

Apa yang pasti itu pun sudah kaya makna. Ilyas berdiri di hadapan kaumnya dan mengajukan kepada mereka sebuah pertanyaan yang dapat diajukan setiap generasi kepada dirinya sendiri: apa yang kita tempatkan di posisi Pencipta kita? Berhala itu mungkin bukan lagi sebuah patung; ia bisa berupa apa saja yang kita taati atau cintai melebihi Allah. Berabad-abad kemudian, namanya masih disebut dengan iringan ucapan salam.$tk$, $tk$Tanyakan kepada dirimu dengan jujur apa yang menempati tempat pertama di hatimu. Menyampaikan kebenaran tetap berharga meskipun hanya segelintir orang yang mendengarkan.$tk$, $tk$["37:123-132","6:85"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$al-yasa$tk$, 'id', 20, $tk$Ilyasa$tk$, $tk$اليسع$tk$, $tk$Termasuk orang-orang terpilih dan orang-orang pilihan$tk$, $tk$Ilyasa alaihissalam adalah nabi yang hanya disebut dua kali oleh Al-Qur'an, dan setiap kali dengan sangat singkat. Tidak ada kisah tentang dirinya dalam Al-Qur'an: hanya namanya, yang ditempatkan di antara nabi-nabi lain, dan kata-kata pujian.

Penyebutan pertama terdapat dalam Surah al-An'am. Setelah membicarakan Ibrahim, Allah menyebutkan banyak nabi yang Dia beri petunjuk. Di antara mereka terdapat Ismail, Ilyasa, Yunus, dan Luth, dan Al-Qur'an menyatakan bahwa Allah melebihkan mereka semua di atas seluruh umat manusia. Sedikit sesudahnya, ayat-ayat itu memberitahukan kepada Nabi Muhammad ﷺ bahwa mereka itulah orang-orang yang diberi petunjuk oleh Allah, dan bahwa beliau hendaknya mengikuti petunjuk mereka.

Penyebutan kedua terdapat dalam Surah Shad. Allah memerintahkan Nabi ﷺ agar mengingat Ismail, Ilyasa, dan Zulkifli, serta menyatakan bahwa mereka semua termasuk orang-orang yang paling baik.

Hanya inilah yang dikatakan Al-Qur'an tentang dirinya. Kita tidak diberi tahu kepada kaum mana ia diutus, kapan ia hidup, apa yang ia katakan kepada kaumnya, atau bagaimana mereka menjawabnya. Tidak ada hadis sahih yang menguraikan kehidupannya. Para ahli tafsir umumnya menggolongkannya sebagai salah satu nabi Bani Israil, setelah Ilyas, dan tradisi-tradisi lain menuturkan berbagai kisah tentang dirinya. Karena kisah-kisah itu tidak dikukuhkan oleh Al-Qur'an ataupun hadis sahih, kami tidak menyajikannya sebagai fakta.

Lebih baik menerima diamnya Al-Qur'an ini daripada mengisinya. Al-Qur'an sendiri menyatakan di tempat lain bahwa ada rasul-rasul yang kisahnya Allah ceritakan dan ada pula yang kisahnya tidak Dia ceritakan. Beriman kepada semua nabi tidak mensyaratkan pengetahuan tentang perincian hidup masing-masing.

Meski demikian, kedua ayat itu mengajarkan sesuatu kepada kita. Ilyasa digambarkan sebagai orang yang terpilih, diberi petunjuk, dilebihkan, dan termasuk orang-orang yang paling baik. Kata-kata ini diberikan oleh Allah sendiri, yang mengetahui isi setiap hati. Dan Nabi Muhammad ﷺ diperintahkan mengikuti petunjuk para nabi ini, yang berarti bahwa jalan Ilyasa sama dengan jalan semua nabi lainnya: menyembah Allah semata dan berbuat baik.

Namanya dalam Al-Qur'an laksana sebuah isyarat yang hening. Ia mengingatkan kita bahwa mata rantai para nabi itu panjang, bahwa masing-masing membawa pesan yang sama, dan bahwa banyak orang yang telah berbuat kebaikan besar hanya dikenal sepenuhnya oleh Allah.$tk$, $tk$Berbuat baiklah tanpa menunggu kisahmu diceritakan. Menjadi salah satu yang terbaik di sisi Allah lebih penting daripada dikenal oleh manusia.$tk$, $tk$["6:86","38:48"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$yunus$tk$, 'id', 21, $tk$Yunus$tk$, $tk$يونس$tk$, $tk$Sang pemilik ikan$tk$, $tk$Yunus alaihissalam diutus sebagai rasul kepada suatu kaum yang, menurut Al-Qur'an, berjumlah seratus ribu orang atau lebih. Al-Qur'an juga menyebutnya Dzun Nun, sang pemilik ikan.

Kisahnya berawal dari sebuah kepergian. Yunus pergi dalam keadaan marah. Al-Qur'an tidak menyembunyikan hal ini: disebutkan bahwa ia pergi dengan sangkaan bahwa Allah tidak akan menyempitkan keadaannya. Para nabi adalah manusia-manusia terbaik, dan Al-Qur'an memperlihatkan kepada kita bagaimana mereka kembali kepada Allah ketika tergelincir.

Yunus menaiki sebuah kapal yang penuh muatan. Undian diadakan di atas kapal, dan ia termasuk yang kalah. Ia dilemparkan ke laut, lalu seekor ikan besar menelannya. Al-Qur'an menyebutkan bahwa pada saat itu ia dalam keadaan tercela.

Di dalam kegelapan, Yunus berdoa kepada Tuhannya. Ia menyatakan bahwa tiada tuhan selain Allah, menyucikan-Nya, dan mengakui bahwa dirinya termasuk orang-orang yang zalim. Ia tidak mencari-cari alasan dan tidak menyalahkan siapa pun. Doa yang singkat ini termasuk doa yang paling masyhur dalam Al-Qur'an.

Allah mengabulkan doanya dan menyelamatkannya dari kedukaan, dan Al-Qur'an menambahkan bahwa demikianlah Dia menyelamatkan orang-orang beriman. Disebutkan pula bahwa seandainya Yunus tidak termasuk orang-orang yang banyak bertasbih kepada Allah, niscaya ia akan tetap berada di perut ikan itu sampai hari kebangkitan.

Ia dilemparkan ke pantai yang tandus dalam keadaan sakit dan lemah, lalu Allah menumbuhkan sebatang pohon sejenis labu untuk menaunginya. Al-Qur'an kemudian menyebutkan bahwa ia diutus kepada kaumnya, bahwa mereka beriman, dan bahwa Allah memberi mereka kesenangan hidup hingga waktu tertentu. Al-Qur'an menegaskan bahwa kaum Yunus merupakan kekecualian: mereka beriman pada waktunya, dan iman mereka menyelamatkan mereka dari azab yang menghinakan.

Al-Qur'an tidak menyebutkan nama kota Yunus dan tidak mengatakan berapa lama ia berada di dalam perut ikan, dan kita tidak perlu mengetahuinya.

Allah memerintahkan Nabi Muhammad ﷺ agar bersabar dan tidak seperti sang pemilik ikan ketika ia berseru dalam kedukaan. Dia juga berfirman bahwa Tuhannya memilih Yunus dan menjadikannya termasuk orang-orang saleh. Dengan demikian, kisahnya mengandung peringatan terhadap ketidaksabaran sekaligus harapan yang besar.$tk$, $tk$Jangan meninggalkan suatu kewajiban karena kecewa. Dan jika kamu telah tergelincir, tidak ada kegelapan yang terlalu pekat: akuilah kesalahanmu dan berdoalah kepada Allah.$tk$, $tk$["37:139-148","21:87-88","10:98","68:48-50"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$zakariyya$tk$, 'id', 22, $tk$Zakaria$tk$, $tk$زكريا$tk$, $tk$Hamba yang tak pernah berputus asa dalam berdoa$tk$, $tk$Zakaria alaihissalam adalah seorang nabi di kalangan Bani Israil. Al-Qur'an mula-mula menampilkannya sebagai pengasuh Maryam, ibunda Isa, alaihimassalam. Maryam telah dinazarkan untuk berkhidmat kepada Allah, dan Zakaria-lah yang diserahi tugas memeliharanya.

Setiap kali ia menemui Maryam di tempat ia beribadah, ia mendapati makanan di sisinya. Ia bertanya dari mana makanan itu berasal. Maryam menjawab bahwa itu dari Allah, yang memberi rezeki kepada siapa yang Dia kehendaki tanpa perhitungan.

Jawaban itu sangat menyentuh hatinya. Zakaria sudah sangat tua, dan istrinya tidak pernah bisa mempunyai anak. Namun, ketika melihat kemurahan Allah kepada Maryam, saat itu juga di tempat itu ia menghadap kepada Tuhannya dan memohon seorang anak yang baik.

Al-Qur'an mengabadikan doa ini dengan penuh kelembutan. Zakaria berdoa kepada Tuhannya dengan suara yang lirih. Ia berkata bahwa tulangnya telah lemah dan rambutnya telah memutih, tetapi ia belum pernah kecewa dalam berdoa kepada-Nya. Ia mengkhawatirkan orang-orang yang akan datang sepeninggalnya, dan ia memohon seorang pewaris yang diridai Allah. Ia juga berkata: ya Tuhanku, janganlah Engkau biarkan aku hidup seorang diri, dan Engkaulah pewaris yang paling baik.

Jawaban itu datang ketika ia sedang berdiri mengerjakan salat. Para malaikat memberinya kabar gembira tentang seorang putra bernama Yahya, nama yang belum pernah Allah berikan kepada siapa pun sebelumnya. Ia akan menjadi orang yang mulia, menjaga kesucian diri, dan seorang nabi dari kalangan orang-orang saleh.

Zakaria tercengang: bagaimana mungkin ia mempunyai putra pada usianya itu, dengan istri yang tidak dapat melahirkan? Ia diberi tahu bahwa hal itu mudah bagi Allah, yang berbuat apa yang Dia kehendaki. Ia memohon sebuah tanda. Tandanya ialah bahwa ia tidak akan berbicara dengan manusia selama tiga hari, kecuali dengan isyarat, padahal ia dalam keadaan sehat. Ia keluar menemui kaumnya dan memberi isyarat kepada mereka agar bertasbih kepada Allah pada waktu pagi dan petang.

Al-Qur'an menyebutkan bahwa Allah mengabulkan doanya, menganugerahinya Yahya, dan menyembuhkan istrinya. Lalu dijelaskan mengapa keluarga ini dimuliakan: mereka bersegera dalam mengerjakan kebaikan, mereka berdoa kepada Allah dengan penuh harap dan cemas, dan mereka khusyuk kepada-Nya.$tk$, $tk$Teruslah memohon kepada Allah dengan penuh harap, berapa pun usiamu dan bagaimanapun keadaanmu. Kebaikan yang kamu lihat pada orang lain bisa menjadi ajakan bagimu untuk memohon lebih banyak lagi.$tk$, $tk$["3:37-41","19:2-11","21:89-90"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$yahya$tk$, 'id', 23, $tk$Yahya$tk$, $tk$يحيى$tk$, $tk$Bijaksana sejak kecil, lembut, dan suci$tk$, $tk$Yahya alaihissalam adalah putra Zakaria alaihissalam. Ia lahir sebagai jawaban atas doa ayahnya yang telah lanjut usia, ketika tidak ada satu hal pun yang tampaknya memungkinkan. Allah sendiri yang memilihkan namanya, dan Al-Qur'an menyebutkan bahwa belum pernah ada seorang pun yang diberi nama itu sebelumnya.

Al-Qur'an tidak menuturkan peristiwa-peristiwa hidupnya sebagai sebuah kisah. Sebagai gantinya, Al-Qur'an menyajikan gambaran akhlaknya, dalam beberapa ayat Surah Maryam, dan gambaran ini termasuk yang paling indah di dalam Kitab itu.

Allah memerintahkannya berpegang teguh pada Kitab, dan menganugerahinya hikmah selagi ia masih kanak-kanak. Yahya tidak menunggu sampai tua untuk bersungguh-sungguh dalam imannya: sejak usia paling dini, ia memahami apa yang Allah minta darinya dan memegangnya dengan kuat.

Allah juga mengaruniainya kasih sayang dari sisi-Nya serta kesucian. Ia bertakwa kepada Allah. Ia berbakti kepada kedua orang tuanya, dan ia bukan orang yang sombong ataupun durhaka. Dalam Surah Ali Imran, para malaikat mengabarkan kelahirannya kepada Zakaria sebagai orang yang akan membenarkan sebuah kalimat dari Allah, dan sebagai orang yang mulia, menjaga kesucian diri, dan seorang nabi dari kalangan orang-orang saleh. Para ahli tafsir menjelaskan bahwa kalimat dari Allah itu merujuk kepada Isa alaihissalam, yang kerasulannya dibenarkan oleh Yahya.

Di tempat lain, Al-Qur'an menyebut Yahya bersama Zakaria, Isa, dan Ilyas, serta menyatakan bahwa mereka semua termasuk orang-orang saleh. Dalam hadis tentang Isra Mikraj, Nabi Muhammad ﷺ menuturkan bahwa beliau bertemu Yahya dan Isa bersama-sama di langit kedua, dan bahwa keduanya bersaudara sepupu (Sahih al-Bukhari, no. 3887).

Gambaran itu ditutup dengan salam yang Allah berikan kepadanya: kesejahteraan atas dirinya pada hari ia dilahirkan, pada hari ia wafat, dan pada hari ia dibangkitkan hidup kembali. Itulah tiga saat ketika manusia berada dalam keadaan paling lemah, dan Yahya dijanjikan keselamatan pada ketiganya.

Al-Qur'an tidak menggambarkan bagaimana Yahya menyeru kaumnya atau bagaimana ia wafat. Riwayat tentang wafatnya terdapat dalam sumber-sumber lain, tetapi tidak terdapat dalam Al-Qur'an, dan kami tidak menyajikannya sebagai hal yang pasti.

Yahya menunjukkan bahwa keteguhan dan kelembutan dapat berjalan seiring. Ia teguh memegang Kitab dan lembut kepada manusia, bersungguh-sungguh dalam imannya dan berbakti kepada kedua orang tuanya.$tk$, $tk$Kamu tidak pernah terlalu muda untuk bersungguh-sungguh dalam iman dan nilai-nilai yang kamu pegang. Bersikaplah teguh dalam kebenaran dan lembut kepada manusia, dimulai dari kedua orang tuamu.$tk$, $tk$["19:12-15","3:39","21:90","6:85"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$isa$tk$, 'id', 24, $tk$Isa$tk$, $tk$عيسى$tk$, $tk$Al-Masih, putra Maryam$tk$, $tk$Isa alaihissalam adalah salah satu rasul Allah yang paling agung. Al-Qur'an menyebutnya al-Masih, putra Maryam, dan memberi ibundanya kedudukan yang istimewa: satu surah penuh menyandang namanya.

Maryam adalah seorang perempuan muda yang suci dan taat beribadah. Suatu hari, ketika ia menyendiri dari keluarganya untuk beribadah, seorang malaikat menampakkan diri kepadanya dan mengabarkan bahwa ia akan mempunyai seorang putra yang suci. Ia tercengang: bagaimana mungkin ia mempunyai anak padahal tidak ada seorang laki-laki pun yang pernah menyentuhnya? Malaikat itu menjawab bahwa hal itu mudah bagi Allah, yang menciptakan apa yang Dia kehendaki. Apabila Dia menetapkan suatu urusan, Dia hanya berfirman kepadanya: Jadilah, maka jadilah ia.

Maryam melahirkan seorang diri, di dekat pangkal sebatang pohon kurma, dalam kesakitan dan kesusahan. Ia pun dihibur: sebuah anak sungai mengalir di bawahnya, dan kurma yang masak berjatuhan dari pohon itu ketika ia menggoyangnya.

Ketika ia kembali kepada kaumnya sambil menggendong sang bayi, mereka menuduhnya. Ia hanya menunjuk kepada anaknya. Bayi yang baru lahir itu pun berbicara, dengan izin Allah. Ia berkata bahwa ia adalah hamba Allah, bahwa Allah telah memberinya Kitab dan menjadikannya seorang nabi, menjadikannya diberkahi di mana pun ia berada, dan memerintahkan kepadanya salat, zakat, serta berbakti kepada ibunya.

Isa diutus sebagai rasul kepada Bani Israil. Ia membenarkan Taurat yang datang sebelumnya dan menerima Injil. Allah menguatkannya dengan tanda-tanda yang nyata: dengan izin Allah, ia menyembuhkan orang buta dan orang yang berpenyakit kusta, menghidupkan orang mati, dan membentuk seekor burung dari tanah liat yang kemudian menjadi burung yang hidup. Al-Qur'an setiap kali mengulangi bahwa mukjizat-mukjizat ini terjadi dengan izin Allah.

Pesannya sama dengan pesan semua nabi: Allah adalah Tuhanku dan Tuhan kalian, maka sembahlah Dia; itulah jalan yang lurus. Para pengikut setianya (hawariyyun) beriman kepadanya dan menyatakan bahwa mereka berserah diri kepada Allah. Atas permintaan mereka, Isa berdoa agar diturunkan dari langit sebuah hidangan sebagai tanda.

Al-Qur'an juga menyebutkan bahwa Isa mengabarkan kedatangan seorang rasul sesudahnya. Ketika musuh-musuhnya berbuat makar terhadapnya, Al-Qur'an mengajarkan bahwa mereka tidak membunuhnya dan tidak pula menyalibnya, meskipun tampak demikian bagi mereka, dan bahwa Allah mengangkatnya kepada-Nya.

Kaum muslimin mencintai dan memuliakan Isa beserta ibundanya.$tk$, $tk$Muliakanlah ibumu dan belalah kebenaran dengan kelembutan. Keagungan yang sejati terletak pada menjadi hamba Allah yang setia dan membawa kebaikan di mana pun kamu berada.$tk$, $tk$["3:45-51","19:16-36","5:110-115","4:157-158","61:6"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$muhammad$tk$, 'id', 25, $tk$Muhammad ﷺ$tk$, $tk$محمد$tk$, $tk$Penutup para nabi, rahmat bagi seluruh alam$tk$, $tk$Nabi Muhammad ﷺ lahir di Makkah sekitar tahun 570 M, dari suku Quraisy. Ayahnya wafat sebelum beliau lahir dan ibunya wafat ketika beliau masih kecil, sehingga beliau diasuh oleh kakeknya, kemudian oleh pamannya, Abu Thalib. Semasa muda, beliau begitu jujur sehingga orang-orang menjulukinya al-Amin, yang tepercaya. Beliau menikah dengan Khadijah radhiyallahu 'anha, seorang saudagar terpandang di Makkah.

Beliau biasa menyendiri di Gua Hira, di sebuah gunung dekat Makkah, untuk merenung dan beribadah. Di sanalah, ketika beliau berusia sekitar empat puluh tahun, Malaikat Jibril membawa kepada beliau kalimat-kalimat pertama Al-Qur'an, yang memerintahkan beliau membaca dengan nama Tuhannya yang menciptakan. Khadijah adalah orang pertama yang beriman kepada beliau.

Selama tiga belas tahun beliau menyeru penduduk Makkah untuk menyembah Allah semata, berlaku jujur, menyantuni anak yatim dan orang miskin, serta meninggalkan berhala. Segelintir orang mengikuti beliau, tetapi para pemuka Quraisy menentang beliau, dan orang-orang beriman mengalami hinaan, pemboikotan, dan penindasan. Beliau menghadapinya dengan sabar.

Pada tahun 622, beliau berhijrah ke kota Yatsrib, yang kemudian menjadi Madinah. Perjalanan ini, Hijrah, menandai awal kalender Islam. Al-Qur'an mengingatkan bagaimana, ketika bersembunyi di sebuah gua bersama sahabatnya, Abu Bakar, beliau berkata kepadanya agar tidak bersedih, sebab Allah bersama mereka.

Di Madinah beliau membangun sebuah masjid, mempersaudarakan kaum Muhajirin dari Makkah dengan penduduk Madinah, dan menata kehidupan sebuah masyarakat. Kaum muslimin beberapa kali harus membela diri, dan Nabi ﷺ juga mengadakan perjanjian gencatan senjata dengan Quraisy. Ketika perjanjian itu dilanggar, beliau kembali ke Makkah pada tahun 8 Hijriah, hampir tanpa pertempuran. Beliau memaafkan orang-orang yang telah memerangi beliau selama bertahun-tahun dan menyingkirkan berhala-berhala dari Ka'bah. Orang-orang pun berbondong-bondong masuk ke dalam agama Allah.

Pada tahun 10, beliau menunaikan haji wada'. Di Arafah, beliau berkhotbah di hadapan khalayak yang sangat besar: beliau mengingatkan mereka bahwa nyawa, harta, dan kehormatan itu suci, menyerukan agar kaum perempuan diperlakukan dengan baik, dan menyatakan bahwa tuntutan balas dendam darah yang lama serta riba telah dihapuskan. Pada haji inilah turun ayat yang mengabarkan bahwa agama telah disempurnakan.

Beliau wafat di Madinah pada tahun 11 Hijriah, 632 M. Al-Qur'an menyebut beliau Rasulullah dan penutup para nabi, yang diutus sebagai rahmat bagi seluruh alam.$tk$, $tk$Jadilah orang yang dapat dipercaya sebelum berbicara tentang iman: akhlak membuka hati. Ketika kamu berada di atas angin, pilihlah kasih sayang dan pemaafan.$tk$, $tk$["96:1-5","9:40","110:1-3","5:3","33:40","21:107"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.premium_content (kind, lang, payload) values ('hajj', 'id', $tk${"umrah":{"title":"Umrah langkah demi langkah","intro":"Umrah adalah kunjungan ke Baitullah di Makkah. Umrah dapat dilaksanakan hampir kapan saja sepanjang tahun dan hanya memerlukan beberapa jam. Ia terdiri atas empat amalan, selalu dalam urutan yang sama: berihram di miqat, tawaf mengelilingi Ka'bah, sa'i antara Shafa dan Marwah, lalu mencukur atau memendekkan rambut.\n\nPanduan ini hanyalah ringkasan. Ia tidak menggantikan pembimbing yang mumpuni, juga tidak menggantikan arahan petugas yang berwenang di lokasi, yang harus selalu Anda ikuti. Apabila mazhab-mazhab fikih berbeda pendapat tentang suatu perincian, kami menyebutkan praktik yang umum: tanyakanlah keadaan Anda kepada ulama yang Anda percayai.","chapters":[{"id":"preparation","title":"Sebelum berangkat","body":"Perjalanan yang baik dimulai dari rumah. Awalilah dengan niat: Anda bepergian hanya karena Allah, bukan agar dilihat atau dipuji. Bertobatlah dengan sungguh-sungguh, lunasilah utang-utang Anda sebisa mungkin, dan mintalah maaf kepada orang-orang yang mungkin pernah Anda zalimi. Biayailah perjalanan ini dengan harta yang halal.\n\nKemudian pelajarilah manasik sebelum berangkat. Jemaah yang tahu apa yang harus dikerjakan akan tenang, dan dapat menyerahkan hatinya untuk beribadah alih-alih merasa cemas. Bacalah panduan ini beberapa kali dan, jika memungkinkan, ikutilah bimbingan bersama seorang guru.\n\nTerakhir, siapkan fisik dan dokumen Anda: biasakan berjalan kaki secara teratur pada minggu-minggu sebelumnya, periksa visa, izin, dan vaksinasi Anda, serta bawalah barang secukupnya. Anda akan banyak berjalan, sering kali dalam cuaca panas dan di tengah keramaian.","steps":["Ikhlaskan niat Anda: perjalanan ini hanya karena Allah.","Bertobatlah, lunasi utang, dan mintalah maaf kepada orang-orang di sekitar Anda.","Pelajari empat amalan umrah beserta urutannya.","Periksa paspor, visa, izin, dan vaksinasi yang diwajibkan.","Cari tahu miqat mana yang ada di rute Anda dan kapan Anda akan tiba di sana.","Berlatihlah dengan berjalan kaki dan bawalah barang yang ringan serta nyaman."],"duas":[]},{"id":"miqat-ihram","title":"Miqat dan ihram","body":"Miqat adalah batas yang tidak boleh dilewati jemaah kecuali dalam keadaan ihram. Jumlahnya ada lima: Dzulhulaifah bagi yang datang dari Madinah, al-Juhfah, Qarnul Manazil, Yalamlam, dan Dzatu Irq. Di pesawat, awak kabin biasanya mengumumkan miqat: bersiaplah sebelum saat itu tiba.\n\nDianjurkan mandi (ghusl) sebelum berihram. Laki-laki mengenakan dua helai kain tak berjahit, satu dililitkan di pinggang dan satu diselempangkan di bahu; perempuan mengenakan pakaian sehari-hari yang menutup aurat. Lalu berniatlah di dalam hati dan ucapkan talbiyah. Laki-laki mengucapkannya dengan suara keras, perempuan dengan suara pelan.\n\nIhram adalah keadaannya, bukan kainnya. Selama berihram Anda tidak boleh memotong rambut atau kuku, memakai wewangian, berburu, melangsungkan akad nikah, atau melakukan hubungan suami istri. Laki-laki tidak mengenakan pakaian yang dijahit mengikuti bentuk tubuh dan tidak menutup kepala; perempuan tidak mengenakan cadar (niqab) atau sarung tangan (Sahih al-Bukhari 1838). Hindari pula pertengkaran (Al-Qur'an 2:197).","steps":["Sebelum miqat, potonglah kuku dan mandilah (ghusl) jika bisa.","Laki-laki: kenakan dua helai kain ihram. Perempuan: tetap mengenakan pakaian biasa yang menutup aurat.","Laki-laki boleh memakai wewangian di badan, bukan di kain, sebelum berniat; sesudahnya tidak boleh sama sekali.","Di miqat, niatkan umrah di dalam hati dan ucapkan: Labbayka Allahumma 'umrah.","Perbanyaklah mengulang talbiyah dalam perjalanan menuju Makkah.","Mulai saat ini, patuhilah semua larangan ihram.","Hentikan talbiyah ketika Anda memulai tawaf."],"duas":[{"ar":"لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لاَ شَرِيكَ لَكَ","tr":"Labbayka Allahumma labbayk, labbayka la sharika laka labbayk, inna al-hamda wa an-ni'mata laka wa al-mulk, la sharika lak","t":"Aku penuhi panggilan-Mu, ya Allah, aku penuhi panggilan-Mu. Aku penuhi panggilan-Mu, tiada sekutu bagi-Mu, aku penuhi panggilan-Mu. Sesungguhnya segala puji dan segala nikmat adalah milik-Mu, begitu pula seluruh kerajaan. Tiada sekutu bagi-Mu.","source":"Talbiyah — Sahih al-Bukhari 1549; Sahih Muslim 1184"}]},{"id":"tawaf","title":"Tawaf mengelilingi Ka'bah","body":"Tawaf adalah tujuh putaran mengelilingi Ka'bah, dengan posisi Ka'bah di sebelah kiri Anda. Anda harus dalam keadaan berwudu. Setiap putaran dimulai dan berakhir di Hajar Aswad: menghadaplah kepadanya, ucapkan takbir, dan cium atau sentuhlah ia hanya jika hal itu mudah; jika tidak, cukup berisyarat ke arahnya. Banyak jemaah mengucapkan « Bismillah, Allahu akbar » di sana, sebagaimana diriwayatkan dari sahabat Ibnu Umar. Berjalanlah di luar dinding setengah lingkaran (Hijir), jangan melintas di dalamnya.\n\nPada tawaf kedatangan ini, laki-laki membuka bahu kanan (idhtiba') dan berjalan cepat dengan langkah pendek pada tiga putaran pertama (raml). Perempuan berjalan seperti biasa.\n\nTidak ada doa wajib tertentu untuk setiap putaran: Anda boleh memanjatkan doa apa saja, dalam bahasa apa saja, berzikir kepada Allah, atau membaca Al-Qur'an. Hanya di antara Rukun Yamani dan Hajar Aswad terdapat doa tertentu yang diriwayatkan: Al-Qur'an 2:201. Setelah itu, salatlah dua rakaat di belakang Maqam Ibrahim (Al-Qur'an 2:125), lalu minumlah air Zamzam.","steps":["Pastikan Anda mempunyai wudu. Laki-laki membuka bahu kanan (idhtiba').","Mulailah sejajar dengan Hajar Aswad: menghadaplah kepadanya, ucapkan takbir, dan berisyaratlah ke arahnya jika Anda tidak dapat menjangkaunya.","Berjalanlah tujuh putaran dengan Ka'bah di sebelah kiri Anda, melewati sisi luar Hijir.","Laki-laki berjalan cepat pada tiga putaran pertama (raml), lalu berjalan biasa.","Sentuhlah Rukun Yamani jika mudah; di antara rukun itu dan Hajar Aswad bacalah Al-Qur'an 2:201.","Selama berputar, panjatkan doa apa saja yang Anda inginkan.","Setelah putaran ketujuh, laki-laki menutup kembali bahunya; salatlah dua rakaat di belakang Maqam Ibrahim, atau di mana saja di dalam masjid jika sedang padat.","Minumlah air Zamzam dan berdoalah."],"duas":[{"ar":"اللَّهُ أَكْبَرُ","tr":"Allahu akbar","t":"Allah Mahabesar.","source":"Takbir ketika sejajar dengan Hajar Aswad — Sahih al-Bukhari 1613"},{"ar":"رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةࣰ وَفِي ٱلۡأٓخِرَةِ حَسَنَةࣰ وَقِنَا عَذَابَ ٱلنَّارِ","tr":"Rabbana atina fi ad-dunya hasanatan wa fi al-akhirati hasanatan wa qina 'adhab an-nar","t":"Ya Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat, dan lindungilah kami dari azab neraka.","source":"Al-Qur'an 2:201 — dibaca di antara Rukun Yamani dan Hajar Aswad: Sunan Abi Dawud 1892 (hasan)"}]},{"id":"say","title":"Sa'i antara Shafa dan Marwah","body":"Setelah tawaf, pergilah ke Shafa. Sa'i adalah tujuh lintasan di antara kedua bukit itu: dari Shafa ke Marwah terhitung satu lintasan, dari Marwah kembali ke Shafa terhitung lintasan kedua, dan seterusnya. Dengan demikian Anda selesai di Marwah.\n\nKetika mendekati Shafa untuk pertama kali, bacalah awal Al-Qur'an 2:158, sebagaimana dilakukan Nabi Muhammad ﷺ (Sahih Muslim 1218). Naiklah sedikit, menghadaplah ke Ka'bah, angkat kedua tangan, agungkan dan esakan Allah dengan lafaz di bawah ini, lalu panjatkan doa Anda sendiri. Hal ini dilakukan tiga kali. Lakukan hal yang sama di Marwah setiap kali Anda tiba di sana.\n\nDi antara dua lampu hijau, laki-laki mempercepat langkah; perempuan berjalan seperti biasa. Seperti halnya tawaf, tidak ada doa khusus yang ditetapkan untuk setiap lintasan. Berwudu dianjurkan, dan orang yang lanjut usia atau sakit boleh memakai kursi roda.","steps":["Pergilah ke Shafa dan bacalah awal Al-Qur'an 2:158 ketika mendekatinya, hanya pada kali pertama ini.","Di atas Shafa, menghadaplah ke Ka'bah, angkat kedua tangan, bacalah zikir Shafa dan berdoalah, tiga kali.","Berjalanlah ke Marwah; laki-laki mempercepat langkah di antara lampu hijau.","Di atas Marwah, menghadaplah ke Ka'bah dan ulangi zikir serta doa itu.","Kembalilah ke Shafa: itulah lintasan kedua.","Lanjutkan hingga lintasan ketujuh, yang berakhir di Marwah."],"duas":[{"ar":"إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِ","tr":"Inna as-Safa wa al-Marwata min sha'a'iri Allah","t":"Sesungguhnya Shafa dan Marwah termasuk syiar-syiar Allah.","source":"Al-Qur'an 2:158 (kalimat pembuka) — dibaca ketika mendekati Shafa: Sahih Muslim 1218"},{"ar":"لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ أَنْجَزَ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الأَحْزَابَ وَحْدَهُ","tr":"La ilaha illa Allahu wahdahu la sharika lah, lahu al-mulku wa lahu al-hamd, wa huwa 'ala kulli shay'in qadir. La ilaha illa Allahu wahdah, anjaza wa'dah, wa nasara 'abdah, wa hazama al-ahzaba wahdah","t":"Tiada tuhan selain Allah semata, tiada sekutu bagi-Nya. Milik-Nya segala kerajaan dan milik-Nya segala puji, dan Dia Mahakuasa atas segala sesuatu. Tiada tuhan selain Allah semata; Dia menepati janji-Nya, menolong hamba-Nya, dan mengalahkan golongan-golongan yang bersekutu seorang diri.","source":"Zikir di atas Shafa dan Marwah — Sahih Muslim 1218"}]},{"id":"halq-taqsir","title":"Mencukur atau memendekkan rambut","body":"Amalan terakhir umrah adalah mencukur kepala (halq) atau memendekkan rambut (taqshir). Bagi laki-laki, mencukur seluruh kepala lebih utama; jika memilih memendekkan, praktik yang umum adalah memendekkan rambut di seluruh kepala, bukan hanya beberapa helai. Perempuan tidak pernah mencukur habis: mereka mengumpulkan rambutnya lalu memotong ujungnya kira-kira sepanjang satu ruas ujung jari.\n\nLaki-laki yang berumrah tidak lama sebelum haji (tamattu') sering memilih memendekkan saja pada saat ini, agar masih ada rambut yang dapat dicukur pada hari kesepuluh.\n\nGunakanlah jasa tukang cukur di luar masjid, jangan memotong rambut di area sa'i, dan perempuan hendaknya memotong rambutnya di tempat tertutup. Dengan amalan ini umrah Anda sempurna, dan semua larangan ihram pun berakhir.","steps":["Tinggalkan area sa'i setelah lintasan ketujuh selesai.","Laki-laki: cukurlah kepala, atau pendekkan rambut di seluruh kepala.","Perempuan: potonglah ujung rambut sepanjang satu ruas ujung jari, di tempat tertutup.","Kini Anda telah keluar dari ihram: umrah Anda telah sempurna."],"duas":[]},{"id":"after","title":"Setelah umrah","body":"Umrah Anda telah selesai: bersyukurlah kepada Allah, yang telah mengizinkan Anda sampai ke rumah-Nya. Semua yang dilarang selama ihram kini diperbolehkan kembali, dan Anda boleh mengenakan pakaian sehari-hari.\n\nManfaatkan sebaik-baiknya hari-hari Anda yang tersisa di Makkah. Kerjakanlah salat lima waktu di Masjidil Haram sesering mungkin, lakukan tawaf sunah ketika tidak terlalu padat, bacalah Al-Qur'an, dan berdoalah untuk diri Anda, keluarga Anda, dan seluruh kaum muslimin. Bersikaplah lembut kepada sesama jemaah serta bersabarlah menghadapi rasa lelah dan keramaian.\n\nBanyak jemaah juga pergi ke Madinah untuk salat di Masjid Nabawi. Kunjungan ini merupakan amal yang penuh berkah, tetapi bukan bagian dari umrah. Sepulang ke rumah, berusahalah menjaga kebiasaan baik yang Anda peroleh di sana.","steps":["Bersyukurlah kepada Allah dan kenakan kembali pakaian sehari-hari Anda.","Salatlah di Masjidil Haram sesering mungkin.","Lakukan tawaf sunah, bacalah Al-Qur'an, dan perbanyaklah doa.","Jagalah kebiasaan baik selama perjalanan ini setelah Anda tiba di rumah."],"duas":[]}]},"hajj":{"title":"Haji hari demi hari","intro":"Haji adalah rukun Islam yang kelima. Ibadah ini wajib sekali seumur hidup atas setiap muslim dewasa yang mampu menempuh perjalanannya (Al-Qur'an 3:97). Rangkaian manasik utamanya berlangsung dari tanggal 8 hingga 13 Zulhijah, di antara Makkah, Mina, Arafah, dan Muzdalifah.\n\nAda tiga cara melaksanakannya. Dalam tamattu', Anda mengerjakan umrah secara lengkap pada bulan-bulan haji, keluar dari ihram, lalu berihram lagi untuk haji pada tanggal 8. Dalam qiran, Anda menggabungkan umrah dan haji dalam satu ihram, tanpa keluar dari ihram di antara keduanya. Dalam ifrad, Anda berihram untuk haji saja. Hewan sembelihan (hadyu) wajib bagi tamattu' dan qiran (Al-Qur'an 2:196), tidak bagi ifrad. Ketiganya sah; para ulama berbeda pendapat tentang mana yang paling utama, dan kebanyakan jemaah yang datang dari jauh melaksanakan tamattu'.\n\nPanduan ini hanyalah ringkasan. Ia tidak menggantikan pembimbing yang mumpuni, juga tidak menggantikan arahan petugas yang berwenang di lokasi dan arahan rombongan Anda, yang mengatur pergerakan dan jadwal demi keselamatan semua orang. Apabila mazhab-mazhab fikih berbeda pendapat tentang suatu perincian, kami menyebutkan praktik yang umum: tanyakanlah keadaan Anda kepada ulama yang Anda percayai.","chapters":[{"id":"day-8-tarwiyah","title":"8 Zulhijah: hari Tarwiyah, di Mina","body":"Ibadah haji dimulai pada tanggal 8 Zulhijah, yang disebut hari Tarwiyah. Jemaah yang melaksanakan tamattu' berihram lagi, kali ini untuk haji, dari tempat ia menginap di Makkah: mandi, mengenakan pakaian ihram, berniat, lalu bertalbiyah. Mereka yang melaksanakan qiran atau ifrad masih dalam keadaan ihram sejak dari miqat.\n\nSemua jemaah kemudian berangkat ke Mina, sebuah lembah penuh tenda yang berjarak beberapa kilometer dari Makkah. Di sana Anda mengerjakan salat Zuhur, Asar, Magrib, Isya, lalu Subuh tanggal 9, masing-masing pada waktunya; salat yang empat rakaat diringkas menjadi dua rakaat, tanpa dijamak.\n\nSiang dan malam di Mina ini adalah sunah dan merupakan waktu untuk bersiap. Beristirahatlah, ulangi talbiyah, bacalah Al-Qur'an, dan siapkan hati Anda untuk esok hari, hari teragung dalam ibadah haji.","steps":["Tamattu': mandilah dan kenakan ihram di tempat Anda menginap di Makkah.","Niatkan haji di dalam hati dan ucapkan: Labbayka Allahumma hajjan.","Berangkatlah ke Mina bersama rombongan Anda sambil mengulang talbiyah.","Kerjakan salat Zuhur, Asar, Magrib, dan Isya di Mina, masing-masing pada waktunya, dengan meringkas salat yang empat rakaat.","Bermalamlah di Mina dan salat Subuh di sana."],"duas":[{"ar":"لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لاَ شَرِيكَ لَكَ","tr":"Labbayka Allahumma labbayk, labbayka la sharika laka labbayk, inna al-hamda wa an-ni'mata laka wa al-mulk, la sharika lak","t":"Aku penuhi panggilan-Mu, ya Allah, aku penuhi panggilan-Mu. Aku penuhi panggilan-Mu, tiada sekutu bagi-Mu, aku penuhi panggilan-Mu. Sesungguhnya segala puji dan segala nikmat adalah milik-Mu, begitu pula seluruh kerajaan. Tiada sekutu bagi-Mu.","source":"Talbiyah — Sahih al-Bukhari 1549; Sahih Muslim 1184"}]},{"id":"day-9-arafat","title":"9 Zulhijah: Arafah, lalu Muzdalifah","body":"Wukuf di Arafah adalah rukun haji yang paling pokok: siapa yang terlewat darinya berarti terlewat hajinya. Nabi Muhammad ﷺ mengajarkan bahwa haji itu adalah Arafah (Jami' at-Tirmidzi 889).\n\nSetelah matahari terbit, tinggalkan Mina menuju Arafah dan pastikan Anda berada di dalam batas-batasnya, yang ditandai dengan papan penunjuk. Setelah khotbah, salat Zuhur dan Asar dikerjakan dengan dijamak dan diringkas, pada waktu Zuhur. Lalu tibalah inti ibadah haji: sejak tengah hari hingga matahari terbenam, menghadaplah ke kiblat dan berdoalah kepada Allah, mohonlah ampunan, dan doakan orang-orang yang Anda cintai. Tidak ada bacaan yang diwajibkan. Jangan beranjak sebelum matahari terbenam.\n\nSetelah matahari terbenam, berangkatlah dengan tenang ke Muzdalifah. Di sana Anda mengerjakan salat Magrib dan Isya dengan dijamak, Isya diringkas, lalu beristirahat malam itu di alam terbuka. Di sana Anda boleh mengumpulkan kerikil-kerikil kecil untuk melontar jumrah.","steps":["Setelah matahari terbit, berangkatlah dari Mina ke Arafah sambil mengulang talbiyah.","Pastikan Anda berada di dalam batas-batas Arafah.","Kerjakan salat Zuhur dan Asar dengan dijamak dan diringkas pada waktu Zuhur.","Isilah waktu siang hingga sore dengan doa, zikir, dan tobat, sambil menghadap kiblat.","Tetaplah di Arafah sampai matahari benar-benar terbenam.","Berangkatlah dengan tenang ke Muzdalifah dan kerjakan salat Magrib dan Isya dengan dijamak di sana.","Kumpulkan kerikil kecil, seukuran biji kacang arab, lalu tidurlah.","Salat Subuh, berdoalah menghadap kiblat, dan berangkatlah ke Mina sebelum matahari terbit."],"duas":[]},{"id":"day-10-nahr","title":"10 Zulhijah: hari penyembelihan kurban","body":"Tanggal 10 adalah hari raya Iduladha dan hari tersibuk dalam ibadah haji. Ada empat amalan yang dikerjakan, idealnya dalam urutan berikut. Pertama, di Mina, lontarkan tujuh kerikil satu per satu ke Jumrah Aqabah, tugu yang terbesar, sambil bertakbir pada setiap lontaran; talbiyah berhenti di sini (Sahih al-Bukhari 1685). Kedua, penyembelihan hadyu, yang wajib bagi tamattu' dan qiran, dan sering kali diurus melalui kupon resmi. Ketiga, laki-laki mencukur atau memendekkan rambut dan perempuan memotong rambut sepanjang satu ruas ujung jari. Keempat, di Makkah, tawaf ifadah, salah satu rukun haji, dilanjutkan dengan sa'i haji bagi yang masih berkewajiban mengerjakannya.\n\nSetelah melontar dan bercukur, larangan-larangan ihram gugur, kecuali hubungan suami istri, yang baru halal setelah tawaf ifadah. Mazhab-mazhab berbeda pendapat tentang perinciannya: tanyakanlah keadaan Anda kepada ulama yang Anda percayai.\n\nJika urutannya berubah, tidak mengapa: demikianlah jawaban Nabi Muhammad ﷺ kepada orang-orang yang bertanya pada hari itu (Sahih al-Bukhari 83).","steps":["Di Mina, lontarkan tujuh kerikil satu per satu ke Jumrah Aqabah, sambil mengucapkan Allahu akbar pada setiap lontaran.","Hentikan talbiyah ketika Anda mulai melontar.","Sembelihlah hadyu, atau pastikan penyembelihan itu dilaksanakan atas nama Anda (tamattu' dan qiran).","Laki-laki mencukur atau memendekkan rambut di seluruh kepala; perempuan memotong rambut sepanjang satu ruas ujung jari.","Kenakan kembali pakaian biasa: semuanya diperbolehkan lagi kecuali hubungan suami istri.","Pergilah ke Makkah untuk tawaf ifadah, tanpa idhtiba' dan tanpa raml, lalu salat dua rakaat.","Kerjakan sa'i haji jika Anda masih berkewajiban mengerjakannya.","Kembalilah ke Mina untuk bermalam di sana."],"duas":[{"ar":"اللَّهُ أَكْبَرُ","tr":"Allahu akbar","t":"Allah Mahabesar.","source":"Takbir pada setiap lontaran kerikil — Sahih al-Bukhari 1751"}]},{"id":"days-11-13-tashriq","title":"11–13 Zulhijah: hari-hari Tasyrik","body":"Hari-hari Tasyrik dihabiskan di Mina. Inilah hari-hari untuk berzikir mengingat Allah (Al-Qur'an 2:203), dan malam-malamnya pun dilewatkan di sana.\n\nSetiap hari, setelah tengah hari, Anda melontar ketiga jumrah secara berurutan: yang kecil, yang tengah, lalu Jumrah Aqabah, masing-masing dengan tujuh kerikil, sambil bertakbir pada setiap lontaran. Setelah jumrah pertama dan setelah jumrah kedua, menepilah, menghadaplah ke kiblat, dan berdoalah panjang dengan mengangkat tangan; setelah jumrah ketiga, pergilah tanpa berhenti (Sahih al-Bukhari 1751).\n\nAnda boleh meninggalkan Mina pada tanggal 12 setelah melontar, sebelum matahari terbenam; siapa yang tetap tinggal melontar lagi pada tanggal 13. Keduanya diperbolehkan (Al-Qur'an 2:203). Ikutilah jadwal yang diberikan kepada rombongan Anda. Jika Anda lemah atau sakit, atau mengenai waktu melontar yang tepat, tanyakanlah keadaan Anda kepada ulama yang Anda percayai.","steps":["Bermalamlah di Mina pada malam tanggal 11 dan 12.","Setiap hari setelah tengah hari, bawalah 21 kerikil ke tempat jumrah.","Lontarlah jumrah yang kecil dengan tujuh kerikil, lalu menepilah dan berdoalah.","Lontarlah jumrah yang tengah dengan tujuh kerikil, lalu menepilah dan berdoalah.","Lontarlah Jumrah Aqabah dengan tujuh kerikil lalu pergilah tanpa berhenti.","Pada tanggal 12, tinggalkan Mina sebelum matahari terbenam jika Anda ingin berangkat lebih awal.","Jika tidak, bermalamlah dan lontarlah ketiga jumrah itu lagi pada tanggal 13."],"duas":[]},{"id":"farewell-tawaf","title":"Tawaf wada'","body":"Apabila seluruh manasik telah selesai dan Anda hendak meninggalkan Makkah, hal terakhir yang Anda kerjakan adalah tawaf perpisahan (tawaf wada'). Orang-orang diperintahkan agar menjadikan Baitullah sebagai persinggahan terakhir mereka; hanya perempuan yang sedang haid yang diberi keringanan untuk tidak mengerjakannya (Sahih al-Bukhari 1755; Sahih Muslim 1328).\n\nIni adalah tawaf biasa sebanyak tujuh putaran dengan pakaian sehari-hari, tanpa idhtiba' dan tanpa raml, dilanjutkan dengan salat dua rakaat. Tidak ada sa'i sesudahnya. Kerjakanlah setelah barang bawaan Anda siap dan keberangkatan Anda sudah dekat; menunggu sebentar untuk kendaraan atau teman serombongan tidaklah mengapa.\n\nTinggalkan Masjidil Haram dengan hati yang penuh syukur. Mohonlah kepada Allah agar menerima haji Anda, mengampuni Anda, dan mengizinkan Anda datang kembali. Lalu berusahalah pulang ke rumah sebagai pribadi yang lebih baik daripada ketika berangkat.","steps":["Selesaikan dahulu seluruh manasik Anda dan siapkan barang bawaan.","Kerjakan tujuh putaran mengelilingi Ka'bah dengan pakaian biasa.","Salatlah dua rakaat setelah tawaf.","Berdoalah agar Allah menerima haji Anda, lalu tinggalkan Makkah tanpa menunda-nunda.","Perempuan yang sedang haid berangkat tanpa mengerjakan tawaf ini."],"duas":[]}]},"mistakes":[{"title":"Berdesakan demi mencium Hajar Aswad","body":"Mencium Hajar Aswad hukumnya sunah; menyakiti seorang muslim hukumnya haram. Jika kerumunan sedang padat, cukup berisyarat ke arah Hajar Aswad dan ucapkan takbir: tawaf Anda tetap sempurna dan tidak ada yang tersakiti."},{"title":"Meyakini bahwa setiap putaran mempunyai doa wajib tersendiri","body":"Sebagian buku saku mencantumkan satu doa untuk setiap putaran. Hal semacam itu tidak diwajibkan: tidak ada doa wajib tertentu untuk putaran-putaran tawaf ataupun lintasan-lintasan sa'i. Berbicaralah kepada Allah dengan kata-kata Anda sendiri, dalam bahasa Anda sendiri."},{"title":"Meninggalkan Arafah sebelum matahari terbenam","body":"Nabi Muhammad ﷺ tetap berada di Arafah sampai matahari terbenam (Sahih Muslim 1218). Jangan bergegas menuju bus pada sore hari: inilah jam-jam paling berharga dalam seluruh rangkaian haji."},{"title":"Mendaki Jabal Rahmah karena mengira hal itu wajib","body":"Seluruh padang Arafah adalah tempat wukuf. Mendaki bukit itu bukan bagian dari ibadah haji dan tidak mendatangkan pahala tambahan; berdesakan di sana melelahkan dan berbahaya. Tetaplah di tempat Anda dapat berdoa dengan tenang."},{"title":"Wukuf di luar batas Arafah","body":"Sebagian jemaah menempati lokasi tepat di luar Arafah tanpa menyadarinya. Karena wukuf adalah rukun haji yang paling pokok, carilah papan penanda batas dan bertanyalah kepada pembimbing Anda jika ada keraguan sedikit pun."},{"title":"Mengumpulkan kerikil yang terlalu besar","body":"Kerikilnya kecil, kira-kira seukuran biji kacang arab. Batu besar, sandal, atau benda lain bukan bagian dari ibadah ini dan dapat melukai orang. Melontar jumrah adalah bentuk ketaatan kepada Allah yang dikerjakan dengan tenang, bukan luapan kemarahan."},{"title":"Sibuk memotret alih-alih beribadah","body":"Satu foto kenang-kenangan hanya perlu beberapa detik; merekam seluruh tawaf atau siaran langsung dari Arafah akan merenggut kekhusyukan hati Anda. Simpanlah ponsel selama manasik dan jagalah keikhlasan niat Anda."},{"title":"Mengabaikan miqat ketika naik pesawat","body":"Pesawat melintasi miqat di udara. Kenakan kain ihram sebelum naik pesawat atau pada awal penerbangan, dan berniatlah ketika miqat diumumkan, atau sedikit sebelumnya. Jika Anda telah melewatinya tanpa berihram, tanyakanlah keadaan Anda kepada ulama yang Anda percayai."},{"title":"Membiarkan bahu kanan terbuka sepanjang waktu","body":"Idhtiba' hanya untuk laki-laki dan hanya selama tawaf kedatangan. Sebelum dan sesudahnya, termasuk ketika salat dan sa'i, kedua bahu ditutup."},{"title":"Menghitung perjalanan pulang-pergi sebagai satu lintasan sa'i","body":"Shafa ke Marwah adalah satu lintasan dan Marwah ke Shafa adalah lintasan berikutnya. Sa'i terdiri atas tujuh lintasan dan berakhir di Marwah. Menghitung setiap perjalanan pulang-pergi sebagai satu lintasan berarti berjalan empat belas lintasan."},{"title":"Memaksakan diri salat tepat di belakang Maqam Ibrahim","body":"Salat di jalur orang-orang yang sedang tawaf menghalangi mereka dan membahayakan diri Anda. Ketika sedang padat, salat dua rakaat itu dapat dikerjakan di mana saja di dalam masjid."},{"title":"Bertengkar dan kehilangan kesabaran","body":"Cuaca panas, antrean, dan rasa lelah menguji semua orang. Al-Qur'an melarang perkataan keji, perbuatan fasik, dan pertengkaran selama haji (2:197). Mengalahlah, tersenyumlah, maafkanlah: akhlak yang baik adalah bagian dari ibadah haji Anda."}],"checklist":[{"id":"passport","group":"documents","label":"Paspor yang masih berlaku sekurang-kurangnya enam bulan"},{"id":"visa-permit","group":"documents","label":"Visa haji atau umrah dan izin resmi"},{"id":"tickets-bookings","group":"documents","label":"Tiket pesawat dan bukti pemesanan penginapan"},{"id":"id-copies","group":"documents","label":"Salinan cetak dan digital semua dokumen"},{"id":"emergency-contacts","group":"documents","label":"Kartu berisi kontak rombongan, hotel, dan nomor darurat"},{"id":"money-card","group":"documents","label":"Sedikit uang tunai mata uang setempat dan kartu bank"},{"id":"ihram-garments","group":"clothing","label":"Laki-laki: dua setel kain ihram"},{"id":"modest-clothing","group":"clothing","label":"Perempuan: pakaian yang longgar, menutup aurat, dan nyaman"},{"id":"sandals","group":"clothing","label":"Sandal nyaman yang sudah biasa dipakai"},{"id":"ihram-belt","group":"clothing","label":"Sabuk ihram atau kantong untuk uang dan dokumen"},{"id":"small-bag","group":"clothing","label":"Tas kecil untuk alas kaki dan kerikil"},{"id":"umbrella","group":"clothing","label":"Payung berwarna terang untuk menahan terik matahari"},{"id":"vaccinations","group":"health","label":"Vaksinasi yang diwajibkan beserta sertifikatnya"},{"id":"medication","group":"health","label":"Obat-obatan rutin beserta resepnya"},{"id":"unscented-toiletries","group":"health","label":"Sabun dan perlengkapan mandi tanpa pewangi untuk ihram"},{"id":"water-bottle","group":"health","label":"Botol minum isi ulang"},{"id":"masks-sanitizer","group":"health","label":"Masker dan cairan pembersih tangan tanpa pewangi"},{"id":"first-aid","group":"health","label":"Kotak P3K kecil dengan plester untuk kaki lecet"},{"id":"sincere-intention","group":"spiritual","label":"Perbarui niat Anda: hanya karena Allah"},{"id":"repentance-debts","group":"spiritual","label":"Bertobat, melunasi utang, dan meminta maaf"},{"id":"learn-rites","group":"spiritual","label":"Mempelajari manasik beserta urutannya"},{"id":"talbiyah-memorised","group":"spiritual","label":"Menghafal talbiyah"},{"id":"dua-list","group":"spiritual","label":"Menulis daftar doa pribadi untuk di Arafah"},{"id":"quran-dhikr","group":"spiritual","label":"Al-Qur'an saku atau aplikasi untuk tilawah dan zikir"}]}$tk$::jsonb)
  on conflict (kind, lang) do update set payload = excluded.payload, updated_at = now();
insert into public.premium_content (kind, lang, payload) values ('quiz', 'id', $tk$[{"id":"q001","cat":"prophets","q":"Menurut Al-Qur'an, siapakah manusia pertama yang diciptakan Allah?","options":["Nuh","Adam","Ibrahim","Idris"],"answer":1,"explain":"Adam alaihissalam adalah manusia pertama dan bapak seluruh umat manusia. Al-Qur'an mengisahkan penciptaannya dalam 2:30-37."},{"id":"q002","cat":"prophets","q":"Nabi siapakah (alaihissalam) yang membuat bahtera atas perintah Allah?","options":["Musa","Yunus","Nuh","Hud"],"answer":2,"explain":"Nuh alaihissalam diperintahkan membuat bahtera sebelum banjir besar, sebagaimana dikisahkan dalam Al-Qur'an (11:37)."},{"id":"q003","cat":"prophets","q":"Nabi siapakah (alaihissalam) yang ditelan seekor ikan besar?","options":["Ayyub","Yusuf","Ilyas","Yunus"],"answer":3,"explain":"Yunus alaihissalam ditelan seekor ikan besar, berdoa kepada Allah dari dalam kegelapan, lalu diselamatkan (37:139-144)."},{"id":"q004","cat":"prophets","q":"Putra manakah yang membantu Ibrahim alaihissalam meninggikan fondasi Ka'bah?","options":["Ishaq","Ya'qub","Ismail","Luth"],"answer":2,"explain":"Al-Qur'an menyebutkan bahwa Ibrahim dan Ismail alaihimassalam bersama-sama meninggikan fondasi Baitullah (2:127)."},{"id":"q005","cat":"prophets","q":"Nabi siapakah (alaihissalam) yang semasa kecil dilemparkan ke dalam sumur oleh saudara-saudaranya?","options":["Yahya","Yusuf","Harun","Dawud"],"answer":1,"explain":"Yusuf alaihissalam dilemparkan ke dalam sumur oleh saudara-saudaranya yang dengki. Kisahnya memenuhi Surah Yusuf, surah ke-12 (12:15)."},{"id":"q006","cat":"prophets","q":"Kepada nabi siapakah (alaihissalam) Taurat diturunkan?","options":["Isa","Dawud","Ibrahim","Musa"],"answer":3,"explain":"Taurat diberikan kepada Musa alaihissalam, yang memimpin Bani Israil keluar dari Mesir."},{"id":"q007","cat":"prophets","q":"Nabi siapakah (alaihissalam) yang menerima Zabur?","options":["Dawud","Sulaiman","Musa","Zakaria"],"answer":0,"explain":"Al-Qur'an menyatakan bahwa Allah memberikan Zabur kepada Dawud alaihissalam (4:163 dan 17:55)."},{"id":"q008","cat":"prophets","q":"Nabi siapakah (alaihissalam) yang menerima Injil?","options":["Isa","Yahya","Musa","Yunus"],"answer":0,"explain":"Injil diberikan kepada Isa putra Maryam alaihimassalam, sebagaimana disebutkan Al-Qur'an dalam 5:46."},{"id":"q009","cat":"prophets","q":"Nabi siapakah yang merupakan saudara Musa alaihissalam dan membantunya dalam mengemban risalah?","options":["Yusya'","Syu'aib","Ilyas","Harun"],"answer":3,"explain":"Musa memohon kepada Allah agar menjadikan saudaranya, Harun, sebagai pembantunya (20:29-32). Semoga keselamatan tercurah atas keduanya."},{"id":"q010","cat":"prophets","q":"Nabi siapakah (alaihissalam) yang diuji dengan penderitaan panjang, lalu masyhur karena kesabarannya dan karena menyeru Tuhannya sebagai ‘Yang Maha Penyayang di antara semua penyayang’?","options":["Ayyub","Harun","Luth","Shalih"],"answer":0,"explain":"Ayyub alaihissalam tetap sabar menjalani penderitaannya dan berdoa kepada Tuhannya, lalu Allah melenyapkan penderitaan itu (21:83-84)."},{"id":"q011","cat":"prophets","q":"Nabi siapakah (alaihissalam) yang diutus kepada kaum 'Ad?","options":["Shalih","Syu'aib","Hud","Luth"],"answer":2,"explain":"Hud alaihissalam diutus kepada kaum 'Ad untuk menyeru mereka agar menyembah Allah semata (7:65)."},{"id":"q012","cat":"prophets","q":"Unta betina yang diberikan sebagai tanda bagi kaum Tsamud berkaitan dengan nabi siapakah (alaihissalam)?","options":["Hud","Shalih","Nuh","Yunus"],"answer":1,"explain":"Shalih alaihissalam diutus kepada kaum Tsamud, dan unta betina itu adalah tanda dari Allah bagi mereka (7:73)."},{"id":"q013","cat":"prophets","q":"Nabi siapakah (alaihissalam) yang dilemparkan ke dalam api oleh kaumnya, lalu Allah menjadikan api itu dingin dan aman baginya?","options":["Musa","Ibrahim","Yahya","Hud"],"answer":1,"explain":"Ketika kaumnya melemparkan Ibrahim alaihissalam ke dalam api, Allah memerintahkan api itu agar menjadi dingin dan menyelamatkan baginya (21:68-69)."},{"id":"q014","cat":"prophets","q":"Menurut Al-Qur'an, nabi siapakah (alaihissalam) yang memahami ucapan seekor semut yang memperingatkan semut-semut lain?","options":["Yunus","Isa","Sulaiman","Yusuf"],"answer":2,"explain":"Sulaiman alaihissalam mendengar seekor semut memperingatkan kawan-kawannya ketika bala tentaranya mendekat, lalu ia tersenyum dan bersyukur kepada Allah (27:18-19)."},{"id":"q015","cat":"prophets","q":"Nabi siapakah (alaihissalam) yang merupakan ayah Yahya?","options":["Imran","Ya'qub","Ayyub","Zakaria"],"answer":3,"explain":"Zakaria alaihissalam berdoa memohon seorang anak pada usia tuanya dan diberi kabar gembira tentang Yahya (19:7)."},{"id":"q016","cat":"seerah","q":"Di kota manakah Nabi Muhammad ﷺ dilahirkan?","options":["Madinah","Makkah","Thaif","Yerusalem"],"answer":1,"explain":"Nabi Muhammad ﷺ dilahirkan di Makkah, dari suku Quraisy."},{"id":"q017","cat":"seerah","q":"Di manakah Nabi Muhammad ﷺ menerima wahyu pertama?","options":["Di Gua Tsur","Di Gua Hira","Di Gunung Uhud","Di Padang Arafah"],"answer":1,"explain":"Wahyu pertama turun di Gua Hira, di Jabal Nur dekat Makkah, tempat beliau biasa menyendiri."},{"id":"q018","cat":"seerah","q":"Malaikat siapakah yang membawa wahyu kepada Nabi Muhammad ﷺ?","options":["Mikail","Jibril","Israfil","Malik"],"answer":1,"explain":"Malaikat Jibril alaihissalam membawa Al-Qur'an kepada Nabi Muhammad ﷺ."},{"id":"q019","cat":"seerah","q":"Apakah kata pertama Al-Qur'an yang diwahyukan kepada Nabi Muhammad ﷺ?","options":["Qul (Katakanlah)","Qum (Bangunlah)","Iqra (Bacalah)","Sabbih (Bertasbihlah)"],"answer":2,"explain":"Wahyu pertama diawali dengan kata ‘Iqra’, yang berarti bacalah (96:1)."},{"id":"q020","cat":"seerah","q":"Siapakah istri pertama Nabi Muhammad ﷺ?","options":["Khadijah binti Khuwailid","Aisyah binti Abu Bakar","Hafshah binti Umar","Saudah binti Zam'ah"],"answer":0,"explain":"Khadijah, seorang saudagar terpandang di Makkah, adalah istri pertama beliau. Beliau tidak menikahi perempuan lain selama Khadijah masih hidup."},{"id":"q021","cat":"seerah","q":"Pada tahun Masehi berapakah Hijrah, yaitu perpindahan dari Makkah ke Madinah, terjadi?","options":["622","570","610","632"],"answer":0,"explain":"Hijrah terjadi pada tahun 622 M. Tahun itu kemudian menjadi tahun pertama kalender Islam."},{"id":"q022","cat":"seerah","q":"Apakah nama kota Madinah sebelum Hijrah?","options":["Khaibar","Tabuk","Thaif","Yatsrib"],"answer":3,"explain":"Kota itu dahulu bernama Yatsrib. Setelah Nabi Muhammad ﷺ menetap di sana, ia dikenal sebagai Madinah, ‘Kota’."},{"id":"q023","cat":"seerah","q":"Di gua manakah Nabi Muhammad ﷺ berlindung ketika Hijrah?","options":["Gua Tsur","Gua Hira","Sebuah gua di Gunung Uhud","Sebuah gua di Bukit Shafa"],"answer":0,"explain":"Beliau bersembunyi di Gua Tsur bersama sahabatnya, Abu Bakar, ketika kaum Quraisy mencari mereka. Al-Qur'an menyebut peristiwa ini dalam 9:40."},{"id":"q024","cat":"seerah","q":"Pada tahun Hijriah berapakah Perang Badar terjadi?","options":["Tahun ke-2","Tahun ke-1","Tahun ke-5","Tahun ke-8"],"answer":0,"explain":"Perang Badar terjadi pada bulan Ramadan tahun 2 H. Inilah pertempuran besar pertama kaum muslimin."},{"id":"q025","cat":"seerah","q":"Siapakah nama kakek yang mengasuh Nabi Muhammad ﷺ setelah ibunda beliau wafat?","options":["Abu Lahab","Abu Sufyan","Abdul Muthalib","Waraqah bin Naufal"],"answer":2,"explain":"Kakek beliau, Abdul Muthalib, seorang pemuka Makkah, mengasuh beliau. Setelah sang kakek wafat, paman beliau, Abu Thalib, yang merawat beliau."},{"id":"q026","cat":"seerah","q":"Siapakah nama ibunda Nabi Muhammad ﷺ?","options":["Halimah as-Sa'diyah","Fatimah binti Asad","Ummu Aiman","Aminah binti Wahb"],"answer":3,"explain":"Ibunda beliau adalah Aminah binti Wahb. Ia wafat ketika beliau masih kecil. Halimah as-Sa'diyah adalah ibu susu beliau."},{"id":"q027","cat":"seerah","q":"Dari suku manakah Nabi Muhammad ﷺ berasal?","options":["Aus","Khazraj","Tsaqif","Quraisy"],"answer":3,"explain":"Beliau berasal dari Quraisy, suku penduduk Makkah, dari kabilah Bani Hasyim."},{"id":"q028","cat":"seerah","q":"Apakah nama perjanjian gencatan senjata yang disepakati kaum muslimin dan Quraisy pada tahun 6 H?","options":["Baiat Aqabah","Piagam Madinah","Perjanjian Hudaibiyah","Hilful Fudhul (Persekutuan Orang-Orang Mulia)"],"answer":2,"explain":"Perjanjian Hudaibiyah disepakati pada tahun 6 H di dekat Makkah. Perjanjian itu menghadirkan masa damai, dan selama masa itu Islam tersebar luas."},{"id":"q029","cat":"seerah","q":"Pada tahun Hijriah berapakah Fathu Makkah (Penaklukan Makkah) terjadi?","options":["Tahun ke-2","Tahun ke-4","Tahun ke-8","Tahun ke-6"],"answer":2,"explain":"Kaum muslimin memasuki Makkah pada tahun 8 H (630 M). Nabi Muhammad ﷺ memaafkan penduduknya."},{"id":"q030","cat":"seerah","q":"Sebelum kenabian, julukan apakah yang diberikan penduduk Makkah kepada Nabi Muhammad ﷺ?","options":["Al-Hakim (Yang Bijaksana)","Al-Karim (Yang Dermawan)","Asy-Syuja' (Yang Pemberani)","Al-Amin (Yang Tepercaya)"],"answer":3,"explain":"Beliau dikenal sebagai al-Amin, Yang Tepercaya, karena kejujurannya. Orang-orang menitipkan barang berharga mereka kepada beliau."},{"id":"q031","cat":"companions","q":"Siapakah muazin pertama dalam Islam?","options":["Salman al-Farisi","Anas bin Malik","Bilal bin Rabah","Zaid bin Haritsah"],"answer":2,"explain":"Bilal bin Rabah, seorang bekas budak keturunan Habasyah yang telah dimerdekakan, dipilih oleh Nabi Muhammad ﷺ untuk mengumandangkan azan."},{"id":"q032","cat":"companions","q":"Sahabat siapakah yang menyertai Nabi Muhammad ﷺ dalam perjalanan Hijrah?","options":["Bilal bin Rabah","Mush'ab bin Umair","Khalid bin Walid","Abu Bakar"],"answer":3,"explain":"Abu Bakar menemani beliau dalam perjalanan dari Makkah ke Madinah dan tinggal bersama beliau di Gua Tsur."},{"id":"q033","cat":"companions","q":"Sahabat siapakah yang mengusulkan penggalian parit untuk mempertahankan Madinah?","options":["Bilal bin Rabah","Abu Ayyub al-Anshari","Salman al-Farisi","Mush'ab bin Umair"],"answer":2,"explain":"Salman al-Farisi, yang berasal dari Persia, mengusulkan penggalian parit itu. Itulah sebabnya pertempuran pada tahun 5 H disebut Perang Khandaq (Perang Parit)."},{"id":"q034","cat":"companions","q":"Sahabat siapakah yang dikenal dengan gelar ‘Pedang Allah’ (Saifullah)?","options":["Khalid bin Walid","Bilal bin Rabah","Zaid bin Tsabit","Anas bin Malik"],"answer":0,"explain":"Khalid bin Walid, seorang panglima yang masyhur, dikenal sebagai Saifullah, Pedang Allah."},{"id":"q035","cat":"companions","q":"Siapakah orang pertama yang beriman kepada risalah Nabi Muhammad ﷺ?","options":["Umar bin Khattab","Khadijah binti Khuwailid","Khalid bin Walid","Abu Sufyan"],"answer":1,"explain":"Istri beliau, Khadijah, adalah orang pertama yang beriman kepada beliau. Ia menenangkan dan mendukung beliau sejak wahyu yang pertama."},{"id":"q036","cat":"companions","q":"Pada masa khalifah siapakah kalender Hijriah ditetapkan, dengan tahun Hijrah sebagai titik awalnya?","options":["Umar bin Khattab","Harun ar-Rasyid","Abdul Malik bin Marwan","Umar bin Abdul Aziz"],"answer":0,"explain":"Kalender Hijriah ditetapkan pada masa kekhalifahan Umar bin Khattab, beberapa tahun setelah wafatnya Nabi Muhammad ﷺ."},{"id":"q037","cat":"companions","q":"Sahabat siapakah, seorang penulis wahyu, yang diberi tugas menghimpun Al-Qur'an menjadi satu kumpulan tertulis?","options":["Bilal bin Rabah","Khalid bin Walid","Salman al-Farisi","Zaid bin Tsabit"],"answer":3,"explain":"Zaid bin Tsabit, salah seorang juru tulis Nabi Muhammad ﷺ, menghimpun tulisan-tulisan Al-Qur'an menjadi satu kumpulan pada masa kekhalifahan Abu Bakar."},{"id":"q038","cat":"companions","q":"Sahabat siapakah yang diutus ke Yatsrib sebelum Hijrah untuk mengajarkan Islam kepada penduduknya?","options":["Mush'ab bin Umair","Khalid bin Walid","Anas bin Malik","Abu Ayyub al-Anshari"],"answer":0,"explain":"Mush'ab bin Umair diutus ke Yatsrib setelah Baiat Aqabah pertama. Banyak penduduknya menerima Islam melalui dirinya."},{"id":"q039","cat":"companions","q":"Dalam pertempuran manakah Hamzah, paman Nabi Muhammad ﷺ, gugur?","options":["Badar","Khandaq","Hunain","Uhud"],"answer":3,"explain":"Hamzah bin Abdul Muthalib gugur sebagai syahid dalam Perang Uhud, pada tahun 3 H."},{"id":"q040","cat":"companions","q":"Siapakah yang dikenang sebagai syahid pertama dalam Islam?","options":["Ummu Aiman","Sumayyah binti Khayyat","Halimah as-Sa'diyah","Ummu Salamah"],"answer":1,"explain":"Sumayyah binti Khayyat, ibunda Ammar bin Yasir, dibunuh di Makkah karena menolak meninggalkan imannya."},{"id":"q041","cat":"companions","q":"Sahabat siapakah yang berbicara mewakili kaum muslimin yang berhijrah di hadapan Najasyi, raja Habasyah?","options":["Bilal bin Rabah","Ja'far bin Abi Thalib","Zaid bin Tsabit","Anas bin Malik"],"answer":1,"explain":"Ja'far bin Abi Thalib menjelaskan Islam kepada Najasyi, yang kemudian membiarkan kaum muslimin tinggal dengan aman di negerinya."},{"id":"q042","cat":"companions","q":"Putri Nabi Muhammad ﷺ yang manakah yang menikah dengan Ali bin Abi Thalib?","options":["Fatimah","Zainab","Ruqayyah","Ummu Kultsum"],"answer":0,"explain":"Fatimah menikah dengan Ali bin Abi Thalib di Madinah. Keduanya adalah orang tua al-Hasan dan al-Husain."},{"id":"q043","cat":"companions","q":"Apakah sebutan bagi penduduk Madinah yang menyambut dan menolong kaum pendatang dari Makkah?","options":["Kaum Muhajirin (Orang-Orang yang Berhijrah)","Kaum Quraisy","Para Tabi'in (Generasi Penerus)","Kaum Anshar (Para Penolong)"],"answer":3,"explain":"Kaum muslimin Madinah disebut Anshar, para penolong. Mereka yang berhijrah dari Makkah disebut Muhajirin."},{"id":"q044","cat":"companions","q":"Siapakah yang tidur di ranjang Nabi Muhammad ﷺ pada malam beliau meninggalkan Makkah untuk berhijrah?","options":["Zaid bin Haritsah","Bilal bin Rabah","Ali bin Abi Thalib","Anas bin Malik"],"answer":2,"explain":"Ali bin Abi Thalib yang masih muda menggantikan beliau di ranjang itu pada malam tersebut, lalu tetap tinggal untuk mengembalikan barang-barang yang dititipkan orang kepada beliau."},{"id":"q045","cat":"companions","q":"Di rumah siapakah Nabi Muhammad ﷺ tinggal di Madinah ketika masjid beliau sedang dibangun?","options":["Salman al-Farisi","Abu Ayyub al-Anshari","Khalid bin Walid","Mush'ab bin Umair"],"answer":1,"explain":"Beliau tinggal di rumah Abu Ayyub al-Anshari sampai masjid dan bilik-bilik beliau selesai dibangun."},{"id":"q046","cat":"quran","q":"Berapakah jumlah surah dalam Al-Qur'an?","options":["114","99","110","120"],"answer":0,"explain":"Al-Qur'an terdiri atas 114 surah, dari al-Fatihah sampai an-Nas."},{"id":"q047","cat":"quran","q":"Surah manakah yang terpanjang dalam Al-Qur'an?","options":["Ali Imran","An-Nisa","Yasin","Al-Baqarah"],"answer":3,"explain":"Al-Baqarah, surah ke-2, adalah surah terpanjang dalam Al-Qur'an."},{"id":"q048","cat":"quran","q":"Surah manakah yang terpendek dalam Al-Qur'an?","options":["Al-Ikhlas","Al-Kautsar","Al-Falaq","Al-Fatihah"],"answer":1,"explain":"Al-Kautsar, surah ke-108, adalah yang terpendek: hanya terdiri atas tiga ayat pendek."},{"id":"q049","cat":"quran","q":"Surah manakah yang membuka Al-Qur'an?","options":["Al-Baqarah","Al-Ikhlas","Al-Fatihah","Al-'Alaq"],"answer":2,"explain":"Al-Fatihah, ‘Pembuka’, adalah surah pertama Al-Qur'an dan dibaca dalam setiap salat."},{"id":"q050","cat":"quran","q":"Surah manakah yang terletak paling akhir dalam Al-Qur'an?","options":["Al-Falaq","Al-Ikhlas","An-Nas","An-Nashr"],"answer":2,"explain":"An-Nas, surah ke-114, menutup Al-Qur'an."},{"id":"q051","cat":"quran","q":"Al-Qur'an dibagi menjadi berapa bagian (juz)?","options":["7","30","60","114"],"answer":1,"explain":"Al-Qur'an dibagi menjadi 30 juz, sehingga mudah dikhatamkan dalam satu bulan."},{"id":"q052","cat":"quran","q":"Pada bulan apakah turunnya Al-Qur'an bermula?","options":["Ramadan","Rajab","Muharam","Zulhijah"],"answer":0,"explain":"Al-Qur'an menyebutkan bahwa ia diturunkan pada bulan Ramadan (2:185)."},{"id":"q053","cat":"quran","q":"Dalam surah manakah Ayat Kursi terdapat?","options":["Ali Imran","Al-Baqarah","Al-Kahfi","Al-Mulk"],"answer":1,"explain":"Ayat Kursi adalah ayat 255 Surah al-Baqarah (2:255)."},{"id":"q054","cat":"quran","q":"Surah manakah satu-satunya yang tidak diawali dengan basmalah?","options":["At-Taubah","Al-Anfal","Yunus","Al-Mulk"],"answer":0,"explain":"At-Taubah, surah ke-9, adalah satu-satunya surah yang tidak dibuka dengan ‘Dengan nama Allah Yang Maha Pengasih, Maha Penyayang’."},{"id":"q055","cat":"quran","q":"Dalam surah manakah basmalah muncul dua kali?","options":["An-Nahl","Al-'Ankabut","Saba'","An-Naml"],"answer":3,"explain":"Dalam Surah an-Naml, basmalah terdapat pada pembukaan dan sekali lagi dalam surat Sulaiman alaihissalam (27:30)."},{"id":"q056","cat":"quran","q":"Surah Al-Qur'an manakah yang menyandang nama ibunda Isa alaihissalam?","options":["An-Nisa","Maryam","Ali Imran","An-Nur"],"answer":1,"explain":"Surah ke-19 dinamai menurut Maryam, ibunda Isa alaihimassalam. Dialah satu-satunya perempuan yang disebut namanya dalam Al-Qur'an."},{"id":"q057","cat":"quran","q":"Selama kira-kira berapa tahun Al-Qur'an diturunkan?","options":["Sekitar 23 tahun","Sekitar 3 tahun","Sekitar 10 tahun","Sekitar 40 tahun"],"answer":0,"explain":"Al-Qur'an diturunkan sedikit demi sedikit selama sekitar 23 tahun, mula-mula di Makkah kemudian di Madinah."},{"id":"q058","cat":"quran","q":"Berapakah jumlah ayat Surah al-Fatihah?","options":["3","5","10","7"],"answer":3,"explain":"Al-Fatihah terdiri atas tujuh ayat. Surah ini dibaca pada setiap rakaat salat."},{"id":"q059","cat":"quran","q":"Apakah sebutan bagi surah-surah yang diturunkan sebelum Hijrah?","options":["Madaniyah","Muhkam","Makkiyah","Mufashshal"],"answer":2,"explain":"Surah-surah yang diturunkan sebelum Hijrah disebut Makkiyah, dan yang diturunkan sesudahnya disebut Madaniyah."},{"id":"q060","cat":"quran","q":"Ayat manakah yang terpanjang dalam Al-Qur'an?","options":["Ayat Kursi (2:255)","Ayat cahaya (24:35)","Ayat utang (2:282)","Ayat pertama al-Fatihah"],"answer":2,"explain":"Ayat terpanjang adalah ayat 282 Surah al-Baqarah. Ayat ini mengajarkan agar orang mencatat utang-piutang mereka dan menghadirkan saksi."},{"id":"q061","cat":"history","q":"Kota manakah yang menjadi ibu kota Kekhalifahan Umayyah?","options":["Bagdad","Damaskus","Kairo","Madinah"],"answer":1,"explain":"Bani Umayyah memerintah dari Damaskus, di Syam (Suriah), dari tahun 661 hingga 750."},{"id":"q062","cat":"history","q":"Khalifah Abbasiyah siapakah yang mendirikan kota Bagdad pada tahun 762?","options":["Harun ar-Rasyid","Al-Manshur","Al-Ma'mun","Al-Mu'tashim"],"answer":1,"explain":"Khalifah al-Manshur mendirikan Bagdad pada tahun 762 di tepi Sungai Tigris. Kota itu menjadi salah satu kota terbesar di dunia."},{"id":"q063","cat":"history","q":"Siapakah yang merebut dan menghancurkan Bagdad pada tahun 1258?","options":["Bangsa Mongol","Tentara Salib","Bani Seljuk","Bani Utsmaniyah"],"answer":0,"explain":"Pasukan Mongol pimpinan Hulagu merebut Bagdad pada tahun 1258, yang mengakhiri Kekhalifahan Abbasiyah di Bagdad."},{"id":"q064","cat":"history","q":"Sultan Utsmaniyah siapakah yang menaklukkan Konstantinopel pada tahun 1453?","options":["Mehmed II","Sulaiman yang Agung","Selim I","Osman I"],"answer":0,"explain":"Mehmed II, yang dijuluki ‘al-Fatih’, Sang Penakluk, merebut Konstantinopel pada tahun 1453. Kota itu menjadi ibu kota Utsmaniyah, Istanbul."},{"id":"q065","cat":"history","q":"Siapakah yang memimpin pasukan muslim menyeberang dari Afrika Utara ke Semenanjung Iberia pada tahun 711?","options":["Uqbah bin Nafi'","Khalid bin Walid","Salahuddin (Saladin)","Thariq bin Ziyad"],"answer":3,"explain":"Thariq bin Ziyad menyeberangi selat itu pada tahun 711. Bukit karang Gibraltar dinamai menurut namanya: Jabal Thariq, ‘gunung Thariq’."},{"id":"q066","cat":"history","q":"Siapakah yang merebut kembali Yerusalem dari Tentara Salib pada tahun 1187?","options":["Baibars","Nuruddin Zanki","Salahuddin (Saladin)","Mehmed II"],"answer":2,"explain":"Salahuddin al-Ayyubi merebut kembali Yerusalem pada tahun 1187, setelah kemenangannya dalam Pertempuran Hittin."},{"id":"q067","cat":"history","q":"Kota manakah, kerajaan muslim terakhir di al-Andalus, yang jatuh pada tahun 1492?","options":["Kordoba","Granada","Sevilla","Toledo"],"answer":1,"explain":"Kerajaan Bani Nashr di Granada jatuh pada tahun 1492, mengakhiri hampir delapan abad pemerintahan muslim di sebagian wilayah Semenanjung Iberia."},{"id":"q068","cat":"history","q":"Siapakah yang mengalahkan bangsa Mongol dalam Pertempuran Ain Jalut pada tahun 1260?","options":["Kaum Mamluk Mesir","Bani Utsmaniyah","Bani Seljuk","Kaum Muwahhidun"],"answer":0,"explain":"Kaum Mamluk Mesir menghentikan laju bangsa Mongol di Ain Jalut, Palestina, pada tahun 1260."},{"id":"q069","cat":"history","q":"Dinasti manakah yang mengambil alih kekhalifahan pada tahun 750 dan kemudian menjadikan Bagdad ibu kotanya?","options":["Utsmaniyah","Mamluk","Murabithun","Abbasiyah"],"answer":3,"explain":"Bani Abbasiyah menggantikan Bani Umayyah pada tahun 750 dan mendirikan Bagdad pada tahun 762."},{"id":"q070","cat":"history","q":"Pangeran Umayyah siapakah yang melarikan diri ke al-Andalus dan mendirikan Keamiran Kordoba pada tahun 756?","options":["Thariq bin Ziyad","Harun ar-Rasyid","Salahuddin (Saladin)","Abdurrahman I"],"answer":3,"explain":"Abdurrahman I, seorang anggota keluarga Umayyah yang selamat, tiba di al-Andalus dan mendirikan Keamiran Kordoba pada tahun 756."},{"id":"q071","cat":"history","q":"Dinasti Utsmaniyah (Ottoman) mengambil namanya dari pendirinya. Siapakah dia?","options":["Mehmed II","Timur Lenk","Alp Arslan","Osman I"],"answer":3,"explain":"Osman I mendirikan negara Utsmaniyah di Anatolia sekitar tahun 1300. Kata ‘Utsmaniyah’ atau ‘Ottoman’ berasal dari namanya."},{"id":"q072","cat":"history","q":"Siapakah yang mendirikan Kekaisaran Mughal di India pada tahun 1526?","options":["Akbar","Shah Jahan","Babur","Aurangzeb"],"answer":2,"explain":"Babur mendirikan Kekaisaran Mughal setelah kemenangannya dalam Pertempuran Panipat pada tahun 1526."},{"id":"q073","cat":"history","q":"Sultan Utsmaniyah abad ke-16 siapakah yang dikenal sebagai ‘yang Agung’ dan ‘Sang Pembuat Undang-Undang’?","options":["Mehmed II","Sulaiman I","Osman I","Abdul Hamid II"],"answer":1,"explain":"Sulaiman I memerintah dari tahun 1520 hingga 1566, ketika Kesultanan Utsmaniyah berada di puncak kejayaannya. Ia dijuluki ‘Kanuni’, Sang Pembuat Undang-Undang."},{"id":"q074","cat":"history","q":"Mansa Musa, yang masyhur karena perjalanan hajinya ke Makkah pada tahun 1324, memerintah kekaisaran apa?","options":["Kekaisaran Songhai","Kekaisaran Ghana","Kekaisaran Mali","Kekaisaran Kanem"],"answer":2,"explain":"Mansa Musa memerintah Kekaisaran Mali di Afrika Barat. Perjalanan hajinya pada tahun 1324 membuat kekayaan Mali termasyhur ke mana-mana."},{"id":"q075","cat":"history","q":"Sultan Seljuk siapakah yang memenangi Pertempuran Manzikert melawan Bizantium pada tahun 1071?","options":["Salahuddin (Saladin)","Baibars","Alp Arslan","Osman I"],"answer":2,"explain":"Alp Arslan mengalahkan pasukan Bizantium di Manzikert pada tahun 1071, yang membuka Anatolia bagi bangsa Turki."},{"id":"q076","cat":"sciences","q":"Cabang matematika manakah yang namanya berasal dari buku ‘al-Jabr’ karya al-Khawarizmi?","options":["Geometri","Aljabar","Trigonometri","Aritmetika"],"answer":1,"explain":"Kata aljabar berasal dari ‘al-jabr’, yang tercantum dalam judul buku yang ditulis al-Khawarizmi di Bagdad pada abad ke-9."},{"id":"q077","cat":"sciences","q":"Kata ‘algoritma’ berasal dari bentuk Latin nama ilmuwan siapa?","options":["Al-Khawarizmi","Al-Kindi","Al-Biruni","Al-Battani"],"answer":0,"explain":"‘Algoritma’ berasal dari ‘Algoritmi’, bentuk Latin dari nama ahli matematika al-Khawarizmi."},{"id":"q078","cat":"sciences","q":"Siapakah penulis ‘Kanun Kedokteran’ (al-Qanun fi ath-Thibb)?","options":["Ar-Razi (Rhazes)","Az-Zahrawi","Ibnu Sina (Avicenna)","Ibnu an-Nafis"],"answer":2,"explain":"Ibnu Sina menulis Kanun Kedokteran pada abad ke-11. Karya itu dipakai untuk mengajarkan ilmu kedokteran selama berabad-abad, di dunia Islam dan di Eropa."},{"id":"q079","cat":"sciences","q":"Ilmuwan siapakah yang menulis ‘Kitab Optik’ dan menjelaskan bahwa kita melihat karena cahaya masuk ke mata?","options":["Al-Khawarizmi","Ibnu al-Haitsam","Ibnu Khaldun","Al-Idrisi"],"answer":1,"explain":"Ibnu al-Haitsam, yang hidup pada abad ke-10 dan ke-11, menulis Kitab Optik (Kitab al-Manazhir) dan bersandar pada eksperimen yang cermat."},{"id":"q080","cat":"sciences","q":"Ilmuwan Andalusia az-Zahrawi masyhur sebagai perintis di bidang apa?","options":["Astronomi","Ilmu bedah","Geografi","Aljabar"],"answer":1,"explain":"Az-Zahrawi, yang hidup di dekat Kordoba pada abad ke-10, menguraikan berbagai operasi bedah dan banyak alat dalam ensiklopedianya, at-Tashrif."},{"id":"q081","cat":"sciences","q":"Tabib siapakah yang menulis risalah terkenal yang membedakan cacar dari campak?","options":["Al-Kindi","Al-Farabi","Al-Idrisi","Ar-Razi (Rhazes)"],"answer":3,"explain":"Ar-Razi, seorang tabib besar abad ke-9 dan ke-10, menulis risalah tentang cacar dan campak yang menguraikan kedua penyakit itu dengan cermat."},{"id":"q082","cat":"sciences","q":"Tabib abad ke-13 siapakah yang menguraikan bagaimana darah mengalir dari jantung melalui paru-paru?","options":["Al-Khawarizmi","Al-Biruni","Ibnu an-Nafis","Ibnu Khaldun"],"answer":2,"explain":"Ibnu an-Nafis menguraikan peredaran darah paru-paru pada abad ke-13, jauh sebelum hal itu dikenal di Eropa."},{"id":"q083","cat":"sciences","q":"Ilmuwan abad ke-11 siapakah yang menghitung jari-jari Bumi dan menulis kajian besar tentang India?","options":["Ibnu Rusyd (Averroes)","Jabir bin Hayyan","Az-Zahrawi","Al-Biruni"],"answer":3,"explain":"Al-Biruni menghitung jari-jari Bumi dengan metode yang cerdik, dengan hasil yang mendekati nilai modern, dan menulis buku yang terperinci tentang India."},{"id":"q084","cat":"sciences","q":"Ahli geografi siapakah yang membuat peta dunia terkenal untuk Raja Roger II dari Sisilia pada abad ke-12?","options":["Ibnu Batutah","Ibnu Khaldun","Al-Idrisi","Al-Khawarizmi"],"answer":2,"explain":"Al-Idrisi merampungkan peta dunianya beserta buku yang menyertainya pada tahun 1154, di istana Roger II di Sisilia."},{"id":"q085","cat":"sciences","q":"Jabir bin Hayyan terutama dikenal karena karyanya di bidang apa?","options":["Optik","Ilmu bedah","Kimia","Geografi"],"answer":2,"explain":"Jabir bin Hayyan adalah salah satu nama besar dalam ilmu kimia awal (alkimia), dan banyak karya dinisbahkan kepadanya."},{"id":"q086","cat":"sciences","q":"Di kota manakah Baitul Hikmah (Rumah Kebijaksanaan), perpustakaan Abbasiyah termasyhur yang terkait dengan gerakan penerjemahan, berada?","options":["Bagdad","Kordoba","Kairo","Damaskus"],"answer":0,"explain":"Baitul Hikmah berada di Bagdad masa Abbasiyah, tempat para ilmuwan menerjemahkan dan mengkaji karya-karya dari tradisi Yunani, Persia, dan India."},{"id":"q087","cat":"sciences","q":"Siapakah penulis ‘Muqaddimah’, sebuah karya terkenal tentang sejarah dan masyarakat?","options":["Ibnu Khaldun","Ibnu Batutah","Ibnu Rusyd (Averroes)","Al-Ghazali"],"answer":0,"explain":"Ibnu Khaldun, yang lahir di Tunis pada tahun 1332, menulis Muqaddimah. Ia dipandang sebagai perintis sosiologi dan kajian sejarah modern."},{"id":"q088","cat":"sciences","q":"Untuk apakah astrolab, alat yang disempurnakan para ilmuwan muslim, digunakan?","options":["Mengukur suhu","Menimbang emas dan perak","Menggiling biji-bijian","Mengamati posisi matahari dan bintang"],"answer":3,"explain":"Astrolab digunakan untuk mengamati matahari dan bintang, sehingga membantu orang mengetahui waktu dan menemukan arah."},{"id":"q089","cat":"sciences","q":"Insinyur al-Jazari, yang merampungkan bukunya yang terkenal pada tahun 1206, dikenal karena apa?","options":["Mesin-mesin cerdik dan jam air","Sebuah peta dunia","Sebuah risalah tentang cacar","Sebuah buku tentang aljabar"],"answer":0,"explain":"Al-Jazari menulis Kitab Pengetahuan tentang Alat-Alat Mekanik yang Cerdik, yang menguraikan jam air, pompa, dan automata."},{"id":"q090","cat":"sciences","q":"Dengan nama Latin apakah ilmuwan Andalusia Ibnu Rusyd dikenal di Eropa?","options":["Avicenna","Alhazen","Rhazes","Averroes"],"answer":3,"explain":"Ibnu Rusyd dari Kordoba dikenal sebagai Averroes. Ulasan-ulasannya atas karya Aristoteles dibaca luas di Eropa abad pertengahan."},{"id":"q091","cat":"pillars","q":"Berapakah jumlah rukun Islam?","options":["Tiga","Lima","Empat","Tujuh"],"answer":1,"explain":"Rukun Islam ada lima: syahadat, salat, zakat, puasa Ramadan, dan haji ke Makkah."},{"id":"q092","cat":"pillars","q":"Apakah rukun Islam yang pertama?","options":["Salat","Puasa (shaum)","Haji","Syahadat (persaksian iman)"],"answer":3,"explain":"Rukun pertama adalah syahadat: bersaksi bahwa tiada tuhan selain Allah dan bahwa Muhammad ﷺ adalah utusan-Nya."},{"id":"q093","cat":"pillars","q":"Berapakah jumlah salat wajib setiap hari?","options":["Dua","Tiga","Lima","Tujuh"],"answer":2,"explain":"Ada lima salat wajib setiap hari: Subuh, Zuhur, Asar, Magrib, dan Isya."},{"id":"q094","cat":"pillars","q":"Apakah nama salat pada waktu fajar?","options":["Zuhur","Subuh","Asar","Isya"],"answer":1,"explain":"Subuh adalah salat pada waktu fajar, yang pertama dari lima salat harian."},{"id":"q095","cat":"pillars","q":"Berapakah jumlah rakaat wajib salat Subuh?","options":["Satu","Dua","Tiga","Empat"],"answer":1,"explain":"Salat Subuh yang wajib terdiri atas dua rakaat."},{"id":"q096","cat":"pillars","q":"Ramadan adalah bulan keberapa dalam kalender Islam?","options":["Kesembilan","Pertama","Ketujuh","Kedua belas"],"answer":0,"explain":"Ramadan adalah bulan kesembilan dalam kalender Hijriah. Inilah bulan puasa."},{"id":"q097","cat":"pillars","q":"Pada bulan Ramadan, kapankah puasa setiap hari dimulai?","options":["Saat fajar","Saat matahari terbit","Saat tengah hari","Saat tengah malam"],"answer":0,"explain":"Puasa dimulai saat fajar, ketika cahaya pertama tampak, sebagaimana dijelaskan Al-Qur'an dalam 2:187."},{"id":"q098","cat":"pillars","q":"Apakah sebutan bagi santapan untuk berbuka puasa pada waktu petang?","options":["Sahur","Walimah","Akikah","Iftar"],"answer":3,"explain":"Iftar adalah santapan untuk berbuka puasa. Sahur adalah santapan yang dimakan sebelum fajar."},{"id":"q099","cat":"pillars","q":"Berapakah kadar zakat yang lazim atas harta simpanan seperti uang, emas, dan perak?","options":["2,5%","1%","5%","15%"],"answer":0,"explain":"Zakat atas harta simpanan adalah 2,5%, yaitu seperempat puluh, setelah batas minimalnya (nisab) dimiliki selama satu tahun kamariah penuh."},{"id":"q100","cat":"pillars","q":"Pada bulan apakah ibadah haji dilaksanakan?","options":["Ramadan","Zulhijah","Muharam","Syawal"],"answer":1,"explain":"Ibadah haji dilaksanakan pada bulan Zulhijah, bulan kedua belas sekaligus terakhir dalam kalender Hijriah."},{"id":"q101","cat":"pillars","q":"Berapa kali jemaah mengelilingi Ka'bah dalam satu tawaf?","options":["Tiga","Lima","Tujuh","Sembilan"],"answer":2,"explain":"Satu tawaf terdiri atas tujuh putaran mengelilingi Ka'bah."},{"id":"q102","cat":"pillars","q":"Di antara dua bukit manakah jemaah berjalan ketika sa'i?","options":["Uhud dan Tsur","Arafah dan Mina","Shafa dan Marwah","Hira dan Tsur"],"answer":2,"explain":"Jemaah berjalan tujuh kali antara Shafa dan Marwah, yang oleh Al-Qur'an disebut sebagai syiar-syiar Allah (2:158)."},{"id":"q103","cat":"pillars","q":"Pada tanggal berapakah bulan Zulhijah jemaah haji wukuf di Arafah?","options":["Tanggal 9","Tanggal 1","Tanggal 10","Tanggal 13"],"answer":0,"explain":"Wukuf di Arafah dilaksanakan pada tanggal 9 Zulhijah. Inilah inti ibadah haji."},{"id":"q104","cat":"pillars","q":"Berapa kali seumur hidup haji diwajibkan atas seorang muslim yang mampu menunaikannya?","options":["Tiga kali","Setiap tahun","Setiap lima tahun","Sekali"],"answer":3,"explain":"Haji diwajibkan sekali seumur hidup bagi mereka yang mampu menempuh perjalanannya (3:97)."},{"id":"q105","cat":"pillars","q":"Ke arah kota manakah kaum muslimin generasi pertama salat sebelum kiblat dialihkan ke Ka'bah?","options":["Madinah","Damaskus","Thaif","Yerusalem"],"answer":3,"explain":"Kaum muslimin generasi pertama salat menghadap ke Yerusalem. Kiblat kemudian dialihkan ke Masjidil Haram di Makkah (2:144)."},{"id":"q106","cat":"civilisation","q":"Siapakah yang pada abad ke-9 mendirikan Masjid al-Qarawiyyin di Fez, yang kemudian berkembang menjadi universitas terkenal?","options":["Rabi'ah al-Adawiyah","Fatimah al-Fihri","Zubaidah binti Ja'far","Syajarat ad-Durr"],"answer":1,"explain":"Menurut riwayat, Fatimah al-Fihri mendirikan al-Qarawiyyin di Fez, Maroko, pada tahun 859. Ia sering disebut sebagai universitas tertua yang masih beroperasi."},{"id":"q107","cat":"civilisation","q":"Di kota al-Andalus manakah terdapat masjid agung yang terkenal dengan hutan tiangnya serta lengkungan merah dan putihnya?","options":["Sevilla","Kordoba","Granada","Toledo"],"answer":1,"explain":"Pembangunan Masjid Agung Kordoba dimulai pada abad ke-8, ketika Kordoba menjadi ibu kota al-Andalus."},{"id":"q108","cat":"civilisation","q":"Di kota manakah Istana Alhambra berada?","options":["Granada","Kordoba","Marrakesh","Fez"],"answer":0,"explain":"Alhambra berdiri di Granada, di Spanyol selatan. Dahulu ia merupakan istana para penguasa Bani Nashr."},{"id":"q109","cat":"civilisation","q":"Kaisar Mughal siapakah yang memerintahkan pembangunan Taj Mahal?","options":["Akbar","Babur","Aurangzeb","Shah Jahan"],"answer":3,"explain":"Shah Jahan memerintahkan pembangunan Taj Mahal di Agra pada abad ke-17, untuk mengenang istrinya, Mumtaz Mahal."},{"id":"q110","cat":"civilisation","q":"Di kota manakah pengelana besar Ibnu Batutah dilahirkan?","options":["Fez","Tunis","Kairo","Tangier"],"answer":3,"explain":"Ibnu Batutah lahir di Tangier, Maroko, pada tahun 1304. Ia mengembara selama hampir tiga puluh tahun melintasi Afrika, Asia, dan Eropa."},{"id":"q111","cat":"civilisation","q":"Timbuktu, pusat ilmu dan manuskrip yang termasyhur, terletak di negara mana sekarang?","options":["Mesir","Maroko","Mali","Sudan"],"answer":2,"explain":"Timbuktu terletak di Mali. Masjid-masjid dan sekolah-sekolahnya menarik para pelajar dan ulama dari seluruh Afrika Barat."},{"id":"q112","cat":"civilisation","q":"Di kota manakah al-Azhar, salah satu universitas tertua di dunia, berada?","options":["Bagdad","Kairo","Damaskus","Kairouan"],"answer":1,"explain":"Al-Azhar didirikan di Kairo pada abad ke-10 dan hingga kini masih menjadi pusat ilmu yang penting."},{"id":"q113","cat":"civilisation","q":"Di kota manakah Kubah Batu (Qubbat ash-Shakhrah) berada?","options":["Yerusalem","Damaskus","Madinah","Kairo"],"answer":0,"explain":"Kubah Batu berada di Yerusalem. Bangunan itu rampung pada akhir abad ke-7 pada masa Khalifah Umayyah Abdul Malik."},{"id":"q114","cat":"civilisation","q":"Arsitek Utsmaniyah siapakah yang merancang Masjid Süleymaniye di Istanbul?","options":["Al-Jazari","Ulugh Beg","Mimar Sinan","Ibnu Khaldun"],"answer":2,"explain":"Mimar Sinan, kepala arsitek Kesultanan Utsmaniyah pada abad ke-16, merancang Süleymaniye di Istanbul dan Selimiye di Edirne."},{"id":"q115","cat":"civilisation","q":"Di dunia Islam abad pertengahan, apakah ‘bimaristan’ itu?","options":["Perpustakaan","Observatorium","Pasar beratap","Rumah sakit"],"answer":3,"explain":"Bimaristan adalah rumah sakit. Kota-kota seperti Bagdad, Damaskus, dan Kairo memiliki rumah sakit besar tempat orang sakit dirawat."},{"id":"q116","cat":"civilisation","q":"Apakah bulan pertama dalam kalender Hijriah?","options":["Muharam","Ramadan","Rajab","Syawal"],"answer":0,"explain":"Muharam adalah bulan pertama dari dua belas bulan kalender Hijriah, yang mengikuti peredaran bulan."},{"id":"q117","cat":"civilisation","q":"Di dalam masjid, apakah mihrab itu?","options":["Mimbar yang dipakai untuk khotbah Jumat","Ceruk yang menunjukkan arah Makkah","Menara yang dipakai untuk mengumandangkan azan","Pancuran yang dipakai untuk berwudu"],"answer":1,"explain":"Mihrab adalah ceruk pada dinding yang menunjukkan kiblat, yaitu arah Makkah. Tempat berkhotbah disebut mimbar dan menaranya disebut minaret."},{"id":"q118","cat":"civilisation","q":"Masjid Agung Kairouan, salah satu yang tertua di Afrika, terletak di negara mana?","options":["Tunisia","Maroko","Mesir","Suriah"],"answer":0,"explain":"Kairouan terletak di Tunisia. Masjid agungnya berasal dari masa pendirian kota itu oleh Uqbah bin Nafi' pada tahun 670."},{"id":"q119","cat":"civilisation","q":"Khat Kufi, salah satu gaya kaligrafi Arab tertua, dinamai menurut kota apa?","options":["Kordoba","Konya","Kufah","Kabul"],"answer":2,"explain":"Khat Kufi mengambil namanya dari Kufah, di Irak. Banyak mushaf Al-Qur'an generasi awal ditulis dengan gaya bersudut ini."},{"id":"q120","cat":"civilisation","q":"Dalam peradaban Islam, apakah ‘wakaf’ itu?","options":["Kafilah dagang","Sebuah gaya kaligrafi","Harta yang diabadikan untuk amal","Pajak atas hasil panen"],"answer":2,"explain":"Wakaf adalah harta yang disisihkan untuk kebaikan, seperti sekolah, rumah sakit, atau pancuran air. Hasilnya terus bermanfaat bagi orang banyak sepanjang masa."}]$tk$::jsonb)
  on conflict (kind, lang) do update set payload = excluded.payload, updated_at = now();
insert into public.premium_content (kind, lang, payload) values ('days', 'id', $tk${"new-year":{"detail":"Hari pertama Muharam membuka tahun Hijriah. Kalender Islam mengikuti peredaran bulan: setiap bulan dimulai dengan munculnya hilal, sehingga satu tahun lebih pendek sekitar sebelas hari daripada tahun matahari.\n\nKalender ini disusun pada masa Khalifah Umar bin Khattab, beberapa tahun setelah wafatnya Nabi Muhammad ﷺ. Para sahabat memilih menghitung tahun sejak Hijrah, yaitu perpindahan Nabi ﷺ dari Makkah ke Madinah pada tahun 622 Masehi, dan tetap menjadikan Muharam sebagai bulan pertama. Peristiwa Hijrah sendiri terjadi belakangan pada tahun itu, yaitu di bulan Rabiulawal.\n\nMuharam adalah salah satu dari empat bulan haram yang disebut dalam Al-Qur'an (9:36). Nabi ﷺ mengajarkan bahwa puasa yang paling utama setelah Ramadan adalah puasa di bulan Allah, yaitu Muharam (Sahih Muslim 1163).\n\nTidak ada salat atau perayaan khusus yang ditetapkan untuk hari ini. Banyak muslim memanfaatkannya untuk mengenang Hijrah, merenungkan tahun yang telah lewat, dan memperbarui niat baik.","sources":["Al-Qur'an 9:36","Sahih Muslim 1163"]},"tasua":{"detail":"Tasu'a adalah hari kesembilan bulan Muharam, sehari sebelum Asyura.\n\nKetika Nabi Muhammad ﷺ berpuasa Asyura dan menyuruh kaum muslimin berpuasa pada hari itu, para sahabat menyampaikan bahwa orang Yahudi dan Nasrani juga mengagungkan hari tersebut. Beliau menjawab bahwa pada tahun berikutnya, jika Allah menghendaki, mereka akan berpuasa juga pada hari kesembilan. Beliau wafat sebelum Muharam berikutnya tiba (Sahih Muslim 1134).\n\nKarena itu para ulama menganjurkan puasa pada hari kesembilan bersama hari kesepuluh. Dengan begitu, puasa kaum muslimin memiliki bentuknya sendiri, sambil tetap terhubung dengan hari ketika Allah menyelamatkan Nabi Musa (alaihis salam).\n\nPuasa ini sunah. Orang yang hanya mampu berpuasa pada hari kesepuluh tetap berpuasa Asyura, dan siapa pun yang sakit, sedang bepergian, atau tidak mampu berpuasa tidak perlu merasa bersalah. Seluruh bulan Muharam adalah bulan haram, dan Nabi ﷺ mengajarkan bahwa puasa di bulan ini adalah puasa paling utama setelah Ramadan (Sahih Muslim 1163).","sources":["Sahih Muslim 1134","Sahih Muslim 1163"]},"ashura":{"detail":"Asyura adalah hari kesepuluh bulan Muharam. Kisahnya berawal dari Nabi Musa (alaihis salam): pada hari ini Allah menyelamatkan beliau dan Bani Israil dari musuh mereka.\n\nKetika Nabi Muhammad ﷺ tiba di Madinah, beliau mendapati orang-orang Yahudi berpuasa pada hari ini untuk mengenang penyelamatan itu. Beliau bersabda bahwa kaum muslimin lebih berhak atas Musa, lalu beliau berpuasa dan menyuruh kaum muslimin berpuasa pada hari itu (Sahih al-Bukhari 2004). Ketika puasa Ramadan diwajibkan, puasa Asyura tetap menjadi amalan sunah yang dianjurkan (Sahih al-Bukhari 2002).\n\nKetika ditanya tentang pahalanya, Nabi ﷺ bersabda bahwa puasa ini menghapus dosa setahun yang lalu (Sahih Muslim 1162). Dianjurkan pula berpuasa pada hari kesembilan bersamanya (Sahih Muslim 1134).","sources":["Sahih al-Bukhari 2004","Sahih al-Bukhari 2002","Sahih Muslim 1162","Sahih Muslim 1134"]},"mawlid":{"detail":"Nabi Muhammad ﷺ lahir di Makkah, dari keluarga Bani Hasyim dalam kabilah Quraisy, pada tahun yang dikenal sebagai Tahun Gajah, sekitar tahun 570 Masehi. Ayah beliau, Abdullah, wafat sebelum beliau lahir, dan ibu beliau, Aminah, wafat ketika beliau masih kecil.\n\nYang sudah pasti, beliau lahir pada hari Senin: ketika ditanya tentang puasa hari Senin, beliau menjawab bahwa itulah hari beliau dilahirkan dan hari wahyu turun kepada beliau (Sahih Muslim 1162). Kebanyakan sejarawan menempatkan kelahiran beliau di bulan Rabiulawal. Tanggal 12 adalah tanggal yang paling dikenal, tetapi ada tanggal lain yang juga disebutkan dan tidak ada yang pasti.\n\nUmat Islam berbeda pendapat tentang memperingati hari ini. Banyak yang berkumpul untuk mengenang kehidupan beliau, bersalawat kepada beliau, dan berbagi makanan. Sebagian lainnya tidak mengkhususkan hari ini, karena Nabi ﷺ dan para sahabat tidak melakukannya. Semua sepakat tentang mencintai beliau dan meneladani beliau setiap hari; Al-Qur'an menyebut beliau sebagai rahmat bagi seluruh alam (21:107).","sources":["Sahih Muslim 1162","Al-Qur'an 21:107"]},"isra-miraj":{"detail":"Isra adalah perjalanan malam Nabi Muhammad ﷺ dari Masjidilharam di Makkah ke Masjidilaqsa di Baitul Maqdis. Al-Qur'an menyebutnya pada awal Surah al-Isra (17:1). Mikraj adalah naiknya beliau dari sana melintasi langit, tempat beliau bertemu dengan para nabi terdahulu (alaihimus salam) dan diperlihatkan tanda-tanda besar dari Tuhannya; Surah an-Najm menyinggung hal ini (53:13-18).\n\nPeristiwa ini terjadi di Makkah, sebelum Hijrah, pada masa yang berat bagi Nabi ﷺ. Anugerah paling abadi dari malam itu adalah salat lima waktu, yang diwajibkan pada saat itu (Sahih al-Bukhari 349).\n\nTanggal pastinya tidak diketahui dengan yakin. Tanggal 27 Rajab adalah tanggal yang paling umum diingat, tetapi para sejarawan awal menyebutkan tanggal-tanggal lain.\n\nTidak ada salat atau puasa khusus yang ditetapkan untuk malam ini. Banyak muslim memanfaatkan kesempatan ini untuk menceritakan kembali peristiwanya dan mengingat nilai salat; sebagian lainnya tidak memperingati tanggal tersebut. Rajab adalah salah satu dari empat bulan haram (9:36).","sources":["Al-Qur'an 17:1","Al-Qur'an 53:13-18","Sahih al-Bukhari 349","Al-Qur'an 9:36"]},"mid-shaban":{"detail":"Syakban adalah bulan kedelapan, tepat sebelum Ramadan. Aisyah (radhiyallahu anha) meriwayatkan bahwa ia tidak pernah melihat Nabi Muhammad ﷺ berpuasa pada suatu bulan, selain Ramadan, sebanyak puasa beliau di bulan Syakban (Sahih al-Bukhari 1969). Syakban adalah bulan persiapan: puasa sunah, mengganti puasa Ramadan sebelumnya yang masih tertinggal, dan membaca Al-Qur'an.\n\nMalam tanggal 15, di pertengahan bulan, dikenal di banyak negeri dengan nama seperti Lailatul Bara'ah, Shab-e-Barat, atau Nisfu Sya'ban. Beberapa riwayat menyebutkan ampunan Allah pada malam ini. Para ulama berbeda pendapat tentang kekuatan riwayat-riwayat itu, sehingga berbeda pula dalam amalannya: banyak muslim mengisi sebagian malam itu dengan salat dan doa serta berpuasa pada siang harinya; sebagian lainnya memperlakukannya seperti malam-malam Syakban yang lain dan tidak mengkhususkan ibadah tertentu.\n\nYang disepakati adalah bahwa memohon ampun, memperbaiki hubungan dengan sesama, dan berpuasa sunah itu baik sepanjang bulan Syakban, pintu gerbang menuju Ramadan.","sources":["Sahih al-Bukhari 1969"]},"ramadan-start":{"detail":"Ramadan adalah bulan kesembilan tahun Hijriah, bulan diturunkannya Al-Qur'an sebagai petunjuk bagi manusia (2:185). Puasa di bulan ini adalah salah satu dari lima rukun Islam (Sahih al-Bukhari 8). Puasa ini diwajibkan di Madinah, pada tahun kedua setelah Hijrah.\n\nBulan ini dimulai ketika hilal terlihat; jika hilal tidak dapat dilihat, bulan Syakban digenapkan menjadi tiga puluh hari (Sahih al-Bukhari 1909). Itulah sebabnya awal Ramadan bisa berbeda satu hari antara satu negeri dan negeri lain.\n\nDari terbit fajar hingga terbenam matahari, orang yang berpuasa menahan diri dari makan, minum, dan hubungan suami istri. Orang sakit dan musafir mendapat keringanan dan mengganti puasanya di hari lain, sedangkan orang yang sama sekali tidak mampu berpuasa memberi makan seorang miskin sebagai gantinya (2:184-185). Al-Qur'an menyebutkan tujuan puasa: agar bertakwa (2:183).\n\nNabi Muhammad ﷺ bersabda bahwa ketika Ramadan tiba, pintu-pintu langit dibuka, pintu-pintu neraka ditutup, dan setan-setan dibelenggu (Sahih al-Bukhari 1899). Ramadan adalah bulan salat, Al-Qur'an, dan kedermawanan.","sources":["Al-Qur'an 2:183-185","Sahih al-Bukhari 8","Sahih al-Bukhari 1909","Sahih al-Bukhari 1899"]},"last-ten-nights":{"detail":"Sepuluh malam terakhir Ramadan dimulai pada malam menjelang hari ke-21 dan berlangsung hingga akhir bulan, yang berjumlah 29 atau 30 hari. Inilah bagian Ramadan yang paling berharga, karena Lailatul Qadar ada di antaranya.\n\nAisyah (radhiyallahu anha) meriwayatkan bahwa ketika sepuluh malam ini tiba, Nabi Muhammad ﷺ mengencangkan ikat pinggangnya, menghidupkan malam dengan salat, dan membangunkan keluarganya (Sahih al-Bukhari 2024). Beliau bersungguh-sungguh dalam ibadah pada malam-malam ini melebihi waktu-waktu lainnya (Sahih Muslim 1175).\n\nBeliau juga beriktikaf, yaitu berdiam di masjid untuk memusatkan diri pada ibadah, pada sepuluh hari terakhir Ramadan hingga beliau wafat (Sahih al-Bukhari 2026).\n\nYang dianjurkan: salat malam, membaca Al-Qur'an, banyak berdoa, memohon ampun, dan bersedekah. Orang yang tidak mampu begadang lama tetap bisa salat sedikit setiap malam, agar tidak terlewat malam yang lebih baik daripada seribu bulan (97:3). Zakat fitrah juga disiapkan pada hari-hari ini, sebelum salat Id.","sources":["Sahih al-Bukhari 2024","Sahih Muslim 1175","Sahih al-Bukhari 2026","Al-Qur'an 97:3"]},"laylat-al-qadr":{"detail":"Lailatul Qadar, Malam Kemuliaan, adalah malam diturunkannya Al-Qur'an. Satu surah penuh membahasnya: malam ini lebih baik daripada seribu bulan, para malaikat dan Ruh turun pada malam itu dengan izin Tuhan mereka, dan malam itu penuh kedamaian hingga terbit fajar (97:1-5). Al-Qur'an juga menyebutnya malam yang diberkahi (44:3).\n\nTanggal pastinya dirahasiakan. Nabi Muhammad ﷺ menyuruh orang-orang beriman mencarinya pada malam-malam ganjil di sepuluh malam terakhir Ramadan (Sahih al-Bukhari 2017): malam ke-21, 23, 25, 27, atau 29. Malam ke-27 adalah yang paling sering disebut, dan banyak masyarakat berkumpul pada malam itu, tetapi hal ini tidak pasti, dan para ulama memiliki pendapat yang berbeda. Sikap paling bijak adalah bersungguh-sungguh pada kesepuluh malam itu.\n\nNabi ﷺ bersabda bahwa siapa yang mendirikan salat pada Lailatul Qadar dengan iman dan mengharap pahala, dosa-dosanya yang telah lalu akan diampuni (Sahih al-Bukhari 2014). Amalan yang dianjurkan adalah salat malam, membaca Al-Qur'an, berdoa, dan memohon ampunan kepada Allah.","sources":["Al-Qur'an 97:1-5","Al-Qur'an 44:3","Sahih al-Bukhari 2017","Sahih al-Bukhari 2014"]},"eid-al-fitr":{"detail":"Idulfitri, hari raya berbuka puasa, jatuh pada hari pertama bulan Syawal dan menutup bulan Ramadan. Al-Qur'an meminta orang-orang beriman untuk menyempurnakan bilangan hari puasa dan mengagungkan Allah atas petunjuk-Nya (2:185).\n\nSebelum salat Id, zakat fitrah ditunaikan: sedekah kecil berupa makanan pokok, yang wajib bagi setiap anggota keluarga, agar orang miskin dapat ikut merasakan hari raya. Nabi Muhammad ﷺ memerintahkan agar zakat ini ditunaikan sebelum orang-orang berangkat salat (Sahih al-Bukhari 1503).\n\nPada pagi hari, kaum muslimin mengumandangkan takbir, mengenakan pakaian terbaik, dan berkumpul untuk salat Id, yang diikuti dengan khotbah (Sahih al-Bukhari 956). Pada hari ini Nabi ﷺ tidak berangkat salat sebelum memakan beberapa butir kurma (Sahih al-Bukhari 953).\n\nBerpuasa pada hari Id tidak diperbolehkan (Sahih al-Bukhari 1991). Ini adalah hari bersyukur, bersilaturahmi dengan keluarga, dan berbuat baik kepada tetangga. Puasa sunah, seperti puasa enam hari Syawal, dapat dimulai sejak hari kedua.","sources":["Al-Qur'an 2:185","Sahih al-Bukhari 1503","Sahih al-Bukhari 956","Sahih al-Bukhari 953","Sahih al-Bukhari 1991"]},"six-shawwal":{"detail":"Syawal adalah bulan setelah Ramadan. Nabi Muhammad ﷺ bersabda bahwa siapa yang berpuasa Ramadan lalu mengikutinya dengan enam hari di bulan Syawal, seakan-akan ia berpuasa setahun penuh (Sahih Muslim 1164).\n\nPara ulama menjelaskannya dengan kaidah bahwa satu kebaikan dibalas sepuluh kali lipat (6:160): bulan Ramadan dihitung seperti sepuluh bulan, dan enam hari tambahan dihitung seperti dua bulan, sehingga genap satu tahun.\n\nEnam hari mana pun di bulan ini boleh dipilih. Aplikasi menampilkan tanggal 2 sampai 7 hanya sebagai rentang yang memudahkan: puasanya boleh dilakukan berturut-turut atau terpisah-pisah, di awal, pertengahan, atau akhir Syawal. Satu-satunya hari yang dikecualikan adalah tanggal 1, yaitu hari Id, ketika berpuasa tidak diperbolehkan.\n\nPuasa ini sunah, bukan kewajiban. Orang yang masih memiliki utang puasa Ramadan perlu merencanakannya juga: banyak ulama menyarankan untuk melunasinya terlebih dahulu, sedangkan ulama lain membolehkan puasa enam hari lebih dulu. Ini adalah cara yang ringan untuk menjaga kebiasaan baik Ramadan tetap hidup.","sources":["Sahih Muslim 1164","Al-Qur'an 6:160"]},"dhul-hijja-nine":{"detail":"Zulhijah adalah bulan kedua belas, bulan ibadah haji. Sepuluh hari pertamanya termasuk hari-hari terbaik dalam setahun: Nabi Muhammad ﷺ bersabda bahwa tidak ada amal saleh yang lebih utama daripada amal yang dikerjakan pada hari-hari ini (Sahih al-Bukhari 969). Banyak ahli tafsir juga memahami bahwa sepuluh malam yang Allah jadikan sumpah dalam Al-Qur'an (89:2) adalah hari-hari ini.\n\nKarena puasa termasuk amal terbaik, dianjurkan berpuasa pada sembilan hari pertama, semampunya. Hari kesembilan, yaitu Hari Arafah, adalah yang paling ditekankan. Hari kesepuluh adalah Iduladha, ketika berpuasa tidak diperbolehkan.\n\nAmalan lain yang dianjurkan adalah mengulang-ulang takbir, banyak memuji Allah, salat, bersedekah, dan membaca Al-Qur'an. Al-Qur'an menyebutkan tentang menyebut nama Allah pada hari-hari yang telah ditentukan (22:28).\n\nOrang yang berniat berkurban diminta untuk tidak memotong rambut dan kukunya sejak awal bulan sampai kurbannya disembelih (Sahih Muslim 1977). Pada hari-hari ini, jemaah haji dari seluruh dunia berkumpul di Makkah.","sources":["Sahih al-Bukhari 969","Al-Qur'an 89:2","Al-Qur'an 22:28","Sahih Muslim 1977"]},"arafat":{"detail":"Tanggal 9 Zulhijah adalah Hari Arafah, inti ibadah haji. Dari tengah hari hingga matahari terbenam, jemaah haji berdiam di padang Arafah, dekat Makkah, untuk salat dan berdoa. Wukuf di Arafah adalah rukun haji yang paling pokok.\n\nPada hari inilah, hari Jumat, dalam Haji Wada' Nabi Muhammad ﷺ, turun ayat yang menyatakan bahwa Allah telah menyempurnakan agama (5:3), sebagaimana diriwayatkan oleh Umar bin Khattab (Sahih al-Bukhari 45).\n\nNabi ﷺ bersabda bahwa tidak ada hari ketika Allah membebaskan lebih banyak hamba dari neraka daripada Hari Arafah (Sahih Muslim 1348).\n\nBagi yang tidak sedang berhaji, puasa pada hari ini sangat dianjurkan: Nabi ﷺ bersabda bahwa puasa ini menghapus dosa setahun yang lalu dan setahun yang akan datang (Sahih Muslim 1162). Jemaah haji sendiri tidak diminta berpuasa; Nabi ﷺ tidak berpuasa ketika wukuf di Arafah (Sahih al-Bukhari 1988).\n\nIni adalah hari untuk berdoa, berzikir kepada Allah, dan memohon ampunan, di mana pun kita berada.","sources":["Al-Qur'an 5:3","Sahih al-Bukhari 45","Sahih Muslim 1348","Sahih Muslim 1162","Sahih al-Bukhari 1988"]},"eid-al-adha":{"detail":"Iduladha, Hari Raya Kurban, jatuh pada tanggal 10 Zulhijah, sehari setelah Arafah. Hari ini bertepatan dengan rangkaian utama ibadah haji di Mina dan Makkah.\n\nHari ini mengenang ujian Nabi Ibrahim (alaihis salam). Beliau melihat dalam mimpi bahwa beliau menyembelih putranya; keduanya tunduk pada perintah Allah, lalu Allah menebus sang putra dengan sembelihan yang agung (37:102-107).\n\nHari ini diawali dengan salat Id, yang diikuti dengan khotbah (Sahih al-Bukhari 956). Setelah salat, orang yang mampu menyembelih domba, kambing, sapi, atau unta. Dagingnya dimakan keluarga, dihadiahkan kepada kerabat dan tetangga, dan diberikan kepada orang miskin. Al-Qur'an mengingatkan orang beriman bahwa daging dan darahnya tidak sampai kepada Allah; yang sampai kepada-Nya adalah ketakwaan mereka (22:37).\n\nBerpuasa pada hari ini tidak diperbolehkan (Sahih al-Bukhari 1991). Kaum muslimin mengumandangkan takbir, mengenakan pakaian terbaik, saling berkunjung, dan berbagi makanan. Kurban juga boleh disembelih pada hari-hari setelahnya.","sources":["Al-Qur'an 37:102-107","Sahih al-Bukhari 956","Al-Qur'an 22:37","Sahih al-Bukhari 1991"]},"tashriq":{"detail":"Hari-hari Tasyrik adalah tanggal 11, 12, dan 13 Zulhijah, tiga hari setelah Iduladha. Nabi Muhammad ﷺ menyebutnya sebagai hari-hari makan, minum, dan berzikir kepada Allah (Sahih Muslim 1141).\n\nPada hari-hari ini jemaah haji bermalam di Mina dan setiap hari melempar kerikil ke tiga tugu yang disebut jamarat. Al-Qur'an memerintahkan mereka untuk berzikir kepada Allah pada hari-hari yang terbilang ini, dan menyatakan bahwa tidak ada dosa bagi orang yang bersegera pulang setelah dua hari, dan tidak pula bagi orang yang tinggal lebih lama (2:203). Jadi, jemaah boleh pulang pada tanggal 12 atau tinggal sampai tanggal 13.\n\nBerpuasa pada hari-hari ini tidak diperbolehkan. Satu-satunya pengecualian yang diriwayatkan adalah bagi jemaah haji yang wajib menyembelih hadyu tetapi tidak mendapatkannya (Sahih al-Bukhari 1997).\n\nBagi selain mereka, ini adalah hari-hari gembira dan bersyukur: berbagi daging kurban, mengunjungi kerabat, dan mengumandangkan takbir, terutama setelah salat lima waktu. Kurban Iduladha masih boleh disembelih pada hari-hari ini, dengan rincian yang berbeda antarmazhab.","sources":["Sahih Muslim 1141","Al-Qur'an 2:203","Sahih al-Bukhari 1997"]}}$tk$::jsonb)
  on conflict (kind, lang) do update set payload = excluded.payload, updated_at = now();

-- ===== 10-premium-ur =====
-- Contenu Premium — ur
-- Fichier GÉNÉRÉ par scripts/build-seed.mjs : ne pas modifier à la main. Idempotent (peut être relancé).

insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$adam$tk$, 'ur', 1, $tk$حضرت آدم علیہ السلام$tk$, $tk$آدم$tk$, $tk$پہلے انسان اور پہلے نبی$tk$, $tk$حضرت آدم علیہ السلام پہلے انسان اور پہلے نبی ہیں۔ قرآن مجید ہمیں بتاتا ہے کہ اللہ تعالیٰ نے فرشتوں کو خبر دی کہ وہ زمین میں ایک ایسی مخلوق بسانے والا ہے جسے زمین کی ذمہ داری سونپی جائے گی۔ فرشتوں کو ایسی مخلوق پر تعجب ہوا جو شاید فساد پھیلائے اور خون بہائے۔ اللہ تعالیٰ نے جواب دیا کہ وہ وہ کچھ جانتا ہے جو وہ نہیں جانتے۔

اللہ تعالیٰ نے حضرت آدم کو مٹی سے پیدا کیا اور انہیں تمام چیزوں کے نام سکھائے۔ جب فرشتوں سے یہ نام بتانے کو کہا گیا تو انہوں نے اعتراف کیا کہ وہ صرف اتنا ہی جانتے ہیں جتنا اللہ تعالیٰ نے انہیں سکھایا ہے۔ پھر حضرت آدم نے وہ نام بتا دیے۔ علم وہ پہلا اعزاز تھا جو انسان کو دیا گیا۔

اللہ تعالیٰ نے فرشتوں کو حکم دیا کہ آدم کو سجدہ کریں۔ سب نے حکم مانا سوائے ابلیس کے، جس نے تکبر کی وجہ سے انکار کر دیا اور دعویٰ کیا کہ وہ آگ سے پیدا ہوا ہے، اس لیے مٹی سے بنی مخلوق سے بہتر ہے۔ اسے نکال دیا گیا، اور اس نے قسم کھائی کہ وہ آدم کی اولاد کو بہکانے کی کوشش کرے گا۔

حضرت آدم اور ان کی بیوی کو جنت میں بسایا گیا۔ وہ ہر چیز میں سے آزادی سے کھا سکتے تھے، سوائے ایک درخت کے۔ شیطان نے ان کے دل میں وسوسہ ڈالا، قسمیں کھائیں کہ وہ ان کا سچا خیر خواہ ہے اور انہیں ہمیشہ کی زندگی کا لالچ دیا۔ دونوں نے اس درخت میں سے کھا لیا۔ قرآن مجید الزام صرف بیوی پر نہیں ڈالتا: وہ کہتا ہے کہ دونوں سے لغزش ہوئی۔ ان پر ان کی برہنگی ظاہر ہو گئی، اور وہ جنت کے پتوں سے خود کو ڈھانپنے لگے۔

اس کے بعد جو ہوا وہی اس قصے کی جان ہے۔ حضرت آدم اور ان کی بیوی نے نہ بحث کی اور نہ بہانے بنائے، جیسا کہ ابلیس نے کیا تھا۔ وہ اپنے رب کی طرف پلٹے، اعتراف کیا کہ انہوں نے اپنی جانوں پر ظلم کیا ہے اور اس کی مغفرت اور رحمت مانگی۔ حضرت آدم نے اپنے رب سے چند کلمات سیکھے، اور اللہ تعالیٰ نے ان کی توبہ قبول فرما لی۔ قرآن مجید بتاتا ہے کہ پھر ان کے رب نے انہیں چن لیا، انہیں معاف کیا اور ہدایت دی۔

حضرت آدم اور ان کی بیوی کو زمین پر اتار دیا گیا، جہاں انسانوں کو جینا، مرنا اور دوبارہ اٹھایا جانا تھا۔ اللہ تعالیٰ نے وعدہ فرمایا کہ ان کے پاس ہدایت آئے گی، اور جو اس کی پیروی کریں گے انہیں نہ کوئی خوف ہوگا اور نہ وہ غمگین ہوں گے۔

قرآن مجید یہ نہیں بتاتا کہ وہ جنت کہاں تھی، وہ درخت کس قسم کا تھا، یا حضرت آدم کتنا عرصہ زندہ رہے، اور اندازے لگانے کی کوئی ضرورت نہیں۔ جو بات وہ سکھاتا ہے وہ یہ ہے کہ تمام انسان ایک ہی باپ اور ایک ہی ماں کی اولاد ہیں، اور توبہ کا دروازہ پہلے ہی دن سے کھلا ہے۔$tk$, $tk$غلطی ہر ایک سے ہوتی ہے؛ اصل بات یہ ہے کہ بہانے بنائے بغیر اسے مان لیا جائے اور جلدی سے اللہ تعالیٰ کی طرف لوٹ آیا جائے۔ تکبر وہ دروازہ بند کر دیتا ہے جسے عاجزی کھولتی ہے۔$tk$, $tk$["2:30-39","7:11-25","20:115-123"]$tk$::jsonb)
