insert into public.premium_content (kind, lang, payload) values ('hajj', 'ur', $tk${"umrah":{"title":"عمرہ قدم بہ قدم","intro":"عمرہ مکہ مکرمہ میں بیت اللہ کی زیارت کا نام ہے۔ یہ سال کے تقریباً کسی بھی وقت ادا کیا جا سکتا ہے اور اس میں صرف چند گھنٹے لگتے ہیں۔ یہ چار اعمال پر مشتمل ہے، جو ہمیشہ اسی ترتیب سے ہوتے ہیں: میقات پر احرام باندھنا، خانہ کعبہ کا طواف، صفا اور مروہ کے درمیان سعی، پھر سر منڈوانا یا بال کتروانا۔\n\nیہ رہنما ایک خلاصہ ہے۔ یہ نہ کسی مستند استاد کا بدل ہے اور نہ وہاں موجود حکام کی ہدایات کا، جن پر آپ کو ہمیشہ عمل کرنا چاہیے۔ جہاں کسی تفصیل میں فقہی مذاہب کا اختلاف ہے وہاں ہم عام معمول بیان کرتے ہیں: اپنی صورتِ حال کے بارے میں کسی ایسے عالم سے پوچھ لیجیے جس پر آپ کو اعتماد ہو۔","chapters":[{"id":"preparation","title":"روانگی سے پہلے","body":"اچھا سفر گھر سے شروع ہوتا ہے۔ اپنی نیت سے آغاز کیجیے: آپ صرف اللہ تعالیٰ کے لیے سفر کر رہے ہیں، دکھاوے یا تعریف کے لیے نہیں۔ سچے دل سے توبہ کیجیے، جہاں تک ہو سکے اپنے قرض ادا کیجیے، اور جن لوگوں کے ساتھ آپ سے زیادتی ہوئی ہو ان سے معافی مانگیے۔ سفر کا خرچ حلال مال سے اٹھائیے۔\n\nپھر جانے سے پہلے مناسک سیکھ لیجیے۔ جو زائر جانتا ہے کہ اسے کیا کرنا ہے وہ پرسکون رہتا ہے، اور پریشان ہونے کے بجائے اپنا دل عبادت میں لگا سکتا ہے۔ اس رہنما کو کئی بار پڑھیے اور، اگر ممکن ہو، کسی استاد کے درس میں شریک ہوں۔\n\nآخر میں اپنے جسم اور اپنے کاغذات کو تیار کیجیے: روانگی سے پہلے کے ہفتوں میں باقاعدگی سے پیدل چلیے، اپنا ویزا، اجازت نامہ اور حفاظتی ٹیکے چیک کیجیے، اور سامان ہلکا رکھیے۔ آپ کو بہت چلنا ہوگا، اکثر گرمی اور ہجوم میں۔","steps":["اپنی نیت خالص کیجیے: یہ سفر صرف اللہ تعالیٰ کے لیے ہے۔","توبہ کیجیے، اپنے قرض چکائیے اور اپنے آس پاس کے لوگوں سے معافی مانگیے۔","عمرے کے چار اعمال اور ان کی ترتیب سیکھ لیجیے۔","اپنا پاسپورٹ، ویزا، اجازت نامہ اور لازمی حفاظتی ٹیکے چیک کیجیے۔","معلوم کیجیے کہ آپ کے راستے میں کون سا میقات آتا ہے اور آپ وہاں کب پہنچیں گے۔","پیدل چلنے کی مشق کیجیے اور ہلکا، آرام دہ سامان ساتھ لیجیے۔"],"duas":[]},{"id":"miqat-ihram","title":"میقات اور احرام","body":"میقات وہ حد ہے جسے زائر احرام کے بغیر پار نہیں کر سکتا۔ میقات پانچ ہیں: مدینہ منورہ سے آنے والوں کے لیے ذوالحلیفہ، اور الجحفہ، قرن المنازل، یلملم اور ذاتِ عرق۔ ہوائی جہاز میں عام طور پر عملہ میقات کا اعلان کرتا ہے: اس لمحے سے پہلے تیار رہیے۔\n\nاحرام سے پہلے غسل کرنا مستحب ہے۔ مرد دو بغیر سلی چادریں پہنتے ہیں، ایک کمر کے گرد اور ایک کندھوں پر؛ عورتیں اپنا عام باپردہ لباس پہنتی ہیں۔ پھر دل میں نیت کیجیے اور تلبیہ پڑھیے۔ مرد اسے بلند آواز سے پڑھتے ہیں اور عورتیں آہستہ۔\n\nاحرام ایک حالت کا نام ہے، کپڑے کا نہیں۔ اس حالت میں بال یا ناخن کاٹنا، خوشبو لگانا، شکار کرنا، نکاح کرنا اور ازدواجی تعلق قائم کرنا منع ہے۔ مرد جسم کے ناپ پر سلے ہوئے کپڑے نہیں پہنتے اور سر نہیں ڈھانپتے؛ عورتیں نقاب اور دستانے نہیں پہنتیں (صحیح بخاری 1838)۔ لڑائی جھگڑے سے بھی بچیے (قرآن مجید 2:197)۔","steps":["میقات سے پہلے ناخن تراش لیجیے اور ہو سکے تو غسل کر لیجیے۔","مرد: احرام کی دونوں چادریں پہن لیں۔ عورتیں: اپنا عام باپردہ لباس ہی رکھیں۔","مرد نیت سے پہلے بدن پر خوشبو لگا سکتے ہیں، چادروں پر نہیں؛ نیت کے بعد ہرگز نہیں۔","میقات پر دل میں عمرے کی نیت کیجیے اور کہیے: لبیک اللہم عمرۃ۔","مکہ مکرمہ کے راستے میں بار بار تلبیہ پڑھتے رہیے۔","اب سے ان تمام باتوں کا خیال رکھیے جو احرام میں منع ہیں۔","طواف شروع کرتے وقت تلبیہ بند کر دیجیے۔"],"duas":[{"ar":"لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لاَ شَرِيكَ لَكَ","tr":"Labbayka Allahumma labbayk, labbayka la sharika laka labbayk, inna al-hamda wa an-ni'mata laka wa al-mulk, la sharika lak","t":"میں حاضر ہوں، اے اللہ، میں حاضر ہوں۔ میں حاضر ہوں، تیرا کوئی شریک نہیں، میں حاضر ہوں۔ بے شک تمام تعریف اور تمام نعمت تیری ہی ہے، اور بادشاہی بھی۔ تیرا کوئی شریک نہیں۔","source":"تلبیہ — صحیح بخاری 1549؛ صحیح مسلم 1184"}]},{"id":"tawaf","title":"خانہ کعبہ کا طواف","body":"طواف خانہ کعبہ کے گرد سات چکر لگانے کا نام ہے، اس طرح کہ کعبہ آپ کے بائیں طرف رہے۔ اس کے لیے باوضو ہونا ضروری ہے۔ ہر چکر حجرِ اسود سے شروع ہو کر وہیں ختم ہوتا ہے: اس کی طرف رخ کیجیے، تکبیر کہیے، اور اسے بوسہ صرف اسی صورت میں دیجیے یا ہاتھ لگائیے جب یہ آسانی سے ہو سکے؛ ورنہ بس اس کی طرف اشارہ کر دیجیے۔ بہت سے زائرین وہاں « بسم اللہ، اللہ اکبر » کہتے ہیں، جیسا کہ صحابی حضرت ابن عمر رضی اللہ عنہما سے منقول ہے۔ نیم دائرے والی دیوار (حطیم) کے باہر سے گزریے، اس کے اندر سے نہیں۔\n\nآمد کے اس طواف میں مرد دایاں کندھا کھلا رکھتے ہیں (اضطباع) اور پہلے تین چکروں میں چھوٹے چھوٹے قدموں کے ساتھ تیز چلتے ہیں (رمل)۔ عورتیں معمول کی چال چلتی ہیں۔\n\nہر چکر کے لیے کوئی مقررہ لازمی دعا نہیں ہے: آپ کسی بھی زبان میں کوئی بھی دعا مانگ سکتے ہیں، اللہ تعالیٰ کا ذکر کر سکتے ہیں یا قرآن مجید کی تلاوت کر سکتے ہیں۔ صرف رکنِ یمانی اور حجرِ اسود کے درمیان ایک متعین دعا منقول ہے: قرآن مجید 2:201۔ اس کے بعد مقامِ ابراہیم کے پیچھے دو رکعت نماز پڑھیے (قرآن مجید 2:125)، پھر زمزم کا پانی پیجیے۔","steps":["یقین کر لیجیے کہ آپ باوضو ہیں۔ مرد دایاں کندھا کھول لیں (اضطباع)۔","حجرِ اسود کے برابر سے شروع کیجیے: اس کی طرف رخ کیجیے، تکبیر کہیے، اور اگر اس تک نہ پہنچ سکیں تو اس کی طرف اشارہ کر دیجیے۔","کعبہ کو بائیں طرف رکھتے ہوئے سات چکر لگائیے، اور حطیم کے باہر سے گزریے۔","مرد پہلے تین چکروں میں تیز چلیں (رمل)، پھر معمول کی چال سے۔","آسانی ہو تو رکنِ یمانی کو ہاتھ لگائیے؛ اس کے اور حجرِ اسود کے درمیان قرآن مجید 2:201 پڑھیے۔","چکروں کے دوران جو دعا چاہیں مانگیے۔","ساتویں چکر کے بعد مرد کندھا دوبارہ ڈھانپ لیں؛ مقامِ ابراہیم کے پیچھے دو رکعت پڑھیے، یا ہجوم ہو تو مسجد میں کہیں بھی۔","زمزم کا پانی پیجیے اور دعا مانگیے۔"],"duas":[{"ar":"اللَّهُ أَكْبَرُ","tr":"Allahu akbar","t":"اللہ سب سے بڑا ہے۔","source":"حجرِ اسود کے برابر پہنچ کر تکبیر — صحیح بخاری 1613"},{"ar":"رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةࣰ وَفِي ٱلۡأٓخِرَةِ حَسَنَةࣰ وَقِنَا عَذَابَ ٱلنَّارِ","tr":"Rabbana atina fi ad-dunya hasanatan wa fi al-akhirati hasanatan wa qina 'adhab an-nar","t":"اے ہمارے رب، ہمیں دنیا میں بھلائی عطا فرما اور آخرت میں بھی بھلائی عطا فرما، اور ہمیں آگ کے عذاب سے بچا۔","source":"قرآن مجید 2:201 — رکنِ یمانی اور حجرِ اسود کے درمیان پڑھی جاتی ہے: سنن ابی داؤد 1892 (حسن)"}]},{"id":"say","title":"صفا اور مروہ کے درمیان سعی","body":"طواف کے بعد صفا پر جائیے۔ سعی دونوں پہاڑیوں کے درمیان سات پھیروں کا نام ہے: صفا سے مروہ تک ایک پھیرا ہے، مروہ سے واپس صفا تک دوسرا، اور اسی طرح آگے۔ اس لیے آپ مروہ پر ختم کرتے ہیں۔\n\nپہلی بار صفا کے قریب پہنچتے وقت قرآن مجید 2:158 کا ابتدائی حصہ پڑھیے، جیسا کہ نبی کریم حضرت محمد ﷺ نے کیا (صحیح مسلم 1218)۔ تھوڑا اوپر چڑھیے، کعبہ کی طرف رخ کیجیے، ہاتھ اٹھائیے، نیچے دیے گئے الفاظ سے اللہ تعالیٰ کی بڑائی اور وحدانیت بیان کیجیے، پھر اپنی دعا مانگیے۔ یہ تین بار کیا جاتا ہے۔ ہر بار مروہ پہنچ کر بھی یہی کیجیے۔\n\nدونوں سبز روشنیوں کے درمیان مرد اپنی رفتار تیز کر لیتے ہیں؛ عورتیں معمول کی چال چلتی ہیں۔ طواف کی طرح یہاں بھی کسی پھیرے کے لیے کوئی خاص دعا لازم نہیں۔ وضو مستحب ہے، اور بوڑھے یا بیمار لوگ وہیل چیئر استعمال کر سکتے ہیں۔","steps":["صفا پر جائیے اور قریب پہنچتے ہوئے قرآن مجید 2:158 کا ابتدائی حصہ پڑھیے، صرف اسی پہلی بار۔","صفا پر کعبہ کی طرف رخ کیجیے، ہاتھ اٹھائیے، صفا کا ذکر پڑھیے اور دعا مانگیے، تین بار۔","مروہ کی طرف چلیے؛ مرد سبز روشنیوں کے درمیان رفتار تیز کر لیں۔","مروہ پر کعبہ کی طرف رخ کیجیے اور ذکر اور دعا دہرائیے۔","صفا واپس جائیے: یہ دوسرا پھیرا ہے۔","ساتویں پھیرے تک جاری رکھیے، جو مروہ پر ختم ہوتا ہے۔"],"duas":[{"ar":"إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِ","tr":"Inna as-Safa wa al-Marwata min sha'a'iri Allah","t":"بے شک صفا اور مروہ اللہ کی نشانیوں میں سے ہیں۔","source":"قرآن مجید 2:158 (ابتدائی الفاظ) — صفا کے قریب پہنچتے وقت پڑھے جاتے ہیں: صحیح مسلم 1218"},{"ar":"لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ أَنْجَزَ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الأَحْزَابَ وَحْدَهُ","tr":"La ilaha illa Allahu wahdahu la sharika lah, lahu al-mulku wa lahu al-hamd, wa huwa 'ala kulli shay'in qadir. La ilaha illa Allahu wahdah, anjaza wa'dah, wa nasara 'abdah, wa hazama al-ahzaba wahdah","t":"اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں۔ بادشاہی اسی کی ہے اور تعریف اسی کے لیے ہے، اور وہ ہر چیز پر قادر ہے۔ اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے؛ اس نے اپنا وعدہ پورا کیا، اپنے بندے کی مدد فرمائی اور اکیلے ہی تمام لشکروں کو شکست دی۔","source":"صفا اور مروہ پر ذکر — صحیح مسلم 1218"}]},{"id":"halq-taqsir","title":"سر منڈوانا یا بال کتروانا","body":"عمرے کا آخری عمل سر منڈوانا (حلق) یا بال چھوٹے کرانا (تقصیر) ہے۔ مردوں کے لیے پورا سر منڈوانا افضل ہے؛ اگر وہ اس کے بجائے بال کتروائیں تو عام معمول یہ ہے کہ پورے سر کے بال چھوٹے کرائے جائیں، صرف چند لٹیں نہیں۔ عورتیں کبھی سر نہیں منڈواتیں: وہ اپنے بال اکٹھے کر کے ان کے سرے سے تقریباً انگلی کے پور کے برابر کاٹ لیتی ہیں۔\n\nجو مرد حج سے کچھ ہی پہلے عمرہ کرتا ہے (تمتع) وہ اکثر اس وقت بال کتروانے کو ترجیح دیتا ہے، تاکہ دسویں تاریخ کو منڈوانے کے لیے بال باقی رہیں۔\n\nسعی کی جگہ پر بال کاٹنے کے بجائے مسجد کے باہر کے حجاموں کے پاس جائیے، اور عورتوں کو اپنے بال پردے میں کاٹنے چاہییں۔ اس عمل کے ساتھ عمرہ مکمل ہو جاتا ہے، اور احرام کی تمام پابندیاں ختم ہو جاتی ہیں۔","steps":["ساتواں پھیرا پورا ہوتے ہی سعی کی جگہ سے نکل آئیے۔","مرد: سر منڈوائیں، یا پورے سر کے بال چھوٹے کرائیں۔","عورتیں: پردے میں اپنے بالوں کے سرے سے انگلی کے پور کے برابر کاٹ لیں۔","اب آپ احرام سے باہر ہیں: آپ کا عمرہ مکمل ہو گیا۔"],"duas":[]},{"id":"after","title":"عمرے کے بعد","body":"آپ کا عمرہ پورا ہو گیا: اللہ تعالیٰ کا شکر ادا کیجیے جس نے آپ کو اپنے گھر تک پہنچنے کی توفیق دی۔ جو کچھ احرام نے منع کر رکھا تھا وہ سب دوبارہ جائز ہو گیا، اور آپ اپنے معمول کے کپڑے پہن سکتے ہیں۔\n\nمکہ مکرمہ میں اپنے باقی دنوں سے خوب فائدہ اٹھائیے۔ جتنا ہو سکے پانچوں نمازیں مسجدِ حرام میں پڑھیے، جب زیادہ ہجوم نہ ہو تو نفلی طواف کیجیے، قرآن مجید پڑھیے اور اپنے لیے، اپنے گھر والوں کے لیے اور تمام مسلمانوں کے لیے دعا مانگیے۔ دوسرے زائرین کے ساتھ نرمی سے پیش آئیے اور تھکن اور ہجوم پر صبر کیجیے۔\n\nبہت سے زائرین مسجدِ نبوی میں نماز پڑھنے کے لیے مدینہ منورہ بھی جاتے ہیں۔ یہ حاضری اپنی جگہ ایک بابرکت عمل ہے، لیکن یہ عمرے کا حصہ نہیں۔ گھر واپس آ کر ان اچھی عادتوں کو برقرار رکھنے کی کوشش کیجیے جو آپ نے وہاں اپنائیں۔","steps":["اللہ تعالیٰ کا شکر ادا کیجیے اور دوبارہ اپنے معمول کے کپڑے پہن لیجیے۔","جتنا ہو سکے مسجدِ حرام میں نماز پڑھیے۔","نفلی طواف کیجیے، قرآن مجید پڑھیے اور خوب دعائیں مانگیے۔","گھر پہنچ کر سفر کی اچھی عادتیں برقرار رکھیے۔"],"duas":[]}]},"hajj":{"title":"حج دن بہ دن","intro":"حج اسلام کا پانچواں رکن ہے۔ یہ ہر اس بالغ مسلمان پر زندگی میں ایک بار فرض ہے جو سفر کی استطاعت رکھتا ہو (قرآن مجید 3:97)۔ اس کے بڑے مناسک 8 سے 13 ذوالحجہ تک مکہ مکرمہ، منیٰ، عرفات اور مزدلفہ کے درمیان ادا ہوتے ہیں۔\n\nاسے ادا کرنے کے تین طریقے ہیں۔ تمتع میں آپ حج کے مہینوں میں پورا عمرہ کرتے ہیں، احرام کھول دیتے ہیں، پھر 8 تاریخ کو حج کے لیے دوبارہ احرام باندھتے ہیں۔ قران میں آپ عمرہ اور حج کو ایک ہی احرام میں جمع کرتے ہیں اور درمیان میں احرام نہیں کھولتے۔ افراد میں آپ صرف حج کا احرام باندھتے ہیں۔ تمتع اور قران میں قربانی واجب ہے (قرآن مجید 2:196)، افراد میں نہیں۔ تینوں طریقے درست ہیں؛ علماء میں اس پر اختلاف ہے کہ کون سا افضل ہے، اور دور سے آنے والے زیادہ تر حاجی تمتع کرتے ہیں۔\n\nیہ رہنما ایک خلاصہ ہے۔ یہ نہ کسی مستند استاد کا بدل ہے اور نہ وہاں موجود حکام اور آپ کے گروپ کی ہدایات کا، جو سب کی سلامتی کے لیے نقل و حرکت اور اوقات کا انتظام کرتے ہیں۔ جہاں کسی تفصیل میں فقہی مذاہب کا اختلاف ہے وہاں ہم عام معمول بیان کرتے ہیں: اپنی صورتِ حال کے بارے میں کسی ایسے عالم سے پوچھ لیجیے جس پر آپ کو اعتماد ہو۔","chapters":[{"id":"day-8-tarwiyah","title":"8 ذوالحجہ: یومِ ترویہ، منیٰ میں","body":"حج 8 ذوالحجہ کو شروع ہوتا ہے، جسے یومِ ترویہ کہتے ہیں۔ تمتع کرنے والا حاجی مکہ مکرمہ میں اپنی قیام گاہ ہی سے دوبارہ احرام باندھتا ہے، اس بار حج کے لیے: غسل، احرام کی چادریں، نیت، پھر تلبیہ۔ قران یا افراد کرنے والے میقات ہی سے احرام میں چلے آ رہے ہوتے ہیں۔\n\nپھر سب منیٰ جاتے ہیں، جو مکہ مکرمہ سے چند کلومیٹر دور خیموں کی ایک وادی ہے۔ وہاں آپ ظہر، عصر، مغرب، عشاء اور پھر 9 تاریخ کی فجر پڑھتے ہیں، ہر نماز اپنے وقت پر؛ چار رکعت والی نمازیں قصر کر کے دو پڑھی جاتی ہیں، مگر انہیں جمع نہیں کیا جاتا۔\n\nمنیٰ کا یہ دن اور رات سنت ہے اور تیاری کا وقت ہے۔ آرام کیجیے، تلبیہ دہراتے رہیے، قرآن مجید پڑھیے اور اپنے دل کو کل کے لیے تیار کیجیے، جو حج کا سب سے بڑا دن ہے۔","steps":["تمتع: مکہ مکرمہ میں اپنی قیام گاہ پر غسل کیجیے اور احرام باندھ لیجیے۔","دل میں حج کی نیت کیجیے اور کہیے: لبیک اللہم حجا۔","تلبیہ پڑھتے ہوئے اپنے گروپ کے ساتھ منیٰ جائیے۔","منیٰ میں ظہر، عصر، مغرب اور عشاء ہر ایک اپنے وقت پر پڑھیے، چار رکعت والی نمازیں قصر کر کے۔","رات منیٰ میں گزاریے اور فجر وہیں پڑھیے۔"],"duas":[{"ar":"لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لاَ شَرِيكَ لَكَ","tr":"Labbayka Allahumma labbayk, labbayka la sharika laka labbayk, inna al-hamda wa an-ni'mata laka wa al-mulk, la sharika lak","t":"میں حاضر ہوں، اے اللہ، میں حاضر ہوں۔ میں حاضر ہوں، تیرا کوئی شریک نہیں، میں حاضر ہوں۔ بے شک تمام تعریف اور تمام نعمت تیری ہی ہے، اور بادشاہی بھی۔ تیرا کوئی شریک نہیں۔","source":"تلبیہ — صحیح بخاری 1549؛ صحیح مسلم 1184"}]},{"id":"day-9-arafat","title":"9 ذوالحجہ: عرفات، پھر مزدلفہ","body":"وقوفِ عرفات حج کا رکن ہے: جس سے یہ رہ گیا اس کا حج رہ گیا۔ نبی کریم حضرت محمد ﷺ نے تعلیم دی کہ حج عرفات ہی ہے (جامع ترمذی 889)۔\n\nسورج نکلنے کے بعد منیٰ سے عرفات کے لیے روانہ ہوں اور دیکھ لیجیے کہ آپ اس کی حدود کے اندر ہیں، جن کی نشان دہی بورڈوں سے کی گئی ہے۔ خطبے کے بعد ظہر اور عصر ظہر کے وقت میں جمع اور قصر کر کے پڑھی جاتی ہیں۔ پھر حج کا اصل وقت آتا ہے: دوپہر سے غروبِ آفتاب تک قبلہ رخ ہو کر اللہ تعالیٰ کو پکاریے، مغفرت مانگیے اور اپنے پیاروں کے لیے دعا کیجیے۔ کوئی عبارت لازم نہیں ہے۔ غروبِ آفتاب سے پہلے وہاں سے نہ نکلیے۔\n\nغروبِ آفتاب کے بعد سکون کے ساتھ مزدلفہ جائیے۔ وہاں آپ مغرب اور عشاء ملا کر پڑھتے ہیں، عشاء قصر کے ساتھ، پھر کھلے آسمان تلے رات آرام کرتے ہیں۔ رمی کے لیے چھوٹی کنکریاں آپ وہیں سے چن سکتے ہیں۔","steps":["سورج نکلنے کے بعد تلبیہ پڑھتے ہوئے منیٰ سے عرفات جائیے۔","دیکھ لیجیے کہ آپ عرفات کی حدود کے اندر ہیں۔","ظہر اور عصر ظہر کے وقت میں جمع اور قصر کر کے پڑھیے۔","دوپہر کے بعد کا وقت قبلہ رخ ہو کر دعا، ذکر اور توبہ میں گزاریے۔","سورج پوری طرح غروب ہونے تک عرفات میں رہیے۔","سکون کے ساتھ مزدلفہ جائیے اور وہاں مغرب اور عشاء ملا کر پڑھیے۔","چنے کے دانے کے برابر چھوٹی کنکریاں چن لیجیے، پھر سو جائیے۔","فجر پڑھیے، قبلہ رخ ہو کر دعا مانگیے، اور سورج نکلنے سے پہلے منیٰ کے لیے روانہ ہو جائیے۔"],"duas":[]},{"id":"day-10-nahr","title":"10 ذوالحجہ: قربانی کا دن","body":"10 تاریخ عید کا دن ہے اور حج کا سب سے مصروف دن۔ اس میں چار کام کیے جاتے ہیں، اور بہتر یہ ہے کہ اسی ترتیب سے ہوں۔ پہلا، منیٰ میں جمرۂ عقبہ کو، جو سب سے بڑا ستون ہے، ایک ایک کر کے سات کنکریاں مارنا اور ہر کنکری کے ساتھ تکبیر کہنا؛ تلبیہ یہیں ختم ہو جاتا ہے (صحیح بخاری 1685)۔ دوسرا، قربانی، جو تمتع اور قران میں واجب ہے اور اکثر سرکاری کوپن کے ذریعے کرائی جاتی ہے۔ تیسرا، مرد سر منڈواتے یا بال کترواتے ہیں اور عورتیں انگلی کے پور کے برابر بال کاٹتی ہیں۔ چوتھا، مکہ مکرمہ میں طوافِ افاضہ، جو حج کا رکن ہے، اور اس کے بعد حج کی سعی ان کے لیے جن کے ذمے وہ ابھی باقی ہے۔\n\nرمی اور حلق کے بعد احرام کی پابندیاں اٹھ جاتی ہیں، سوائے ازدواجی تعلق کے، جو طوافِ افاضہ کے بعد حلال ہوتا ہے۔ تفصیلات میں فقہی مذاہب کا اختلاف ہے: اپنی صورتِ حال کے بارے میں کسی ایسے عالم سے پوچھ لیجیے جس پر آپ کو اعتماد ہو۔\n\nاگر ترتیب بدل جائے تو کوئی حرج نہیں: نبی کریم حضرت محمد ﷺ نے اس دن پوچھنے والوں سے یہی فرمایا (صحیح بخاری 83)۔","steps":["منیٰ میں جمرۂ عقبہ کو ایک ایک کر کے سات کنکریاں ماریے، اور ہر ایک کے ساتھ اللہ اکبر کہیے۔","رمی شروع کرتے وقت تلبیہ بند کر دیجیے۔","قربانی کیجیے، یا یقین کر لیجیے کہ وہ آپ کی طرف سے کر دی گئی ہے (تمتع اور قران)۔","مرد پورا سر منڈوائیں یا پورے سر کے بال کتروائیں؛ عورتیں انگلی کے پور کے برابر بال کاٹیں۔","عام کپڑے پہن لیجیے: ازدواجی تعلق کے سوا سب کچھ دوبارہ جائز ہے۔","طوافِ افاضہ کے لیے مکہ مکرمہ جائیے، اضطباع اور رمل کے بغیر، اور دو رکعت پڑھیے۔","اگر حج کی سعی ابھی آپ کے ذمے ہے تو وہ ادا کیجیے۔","رات گزارنے کے لیے منیٰ واپس آ جائیے۔"],"duas":[{"ar":"اللَّهُ أَكْبَرُ","tr":"Allahu akbar","t":"اللہ سب سے بڑا ہے۔","source":"ہر کنکری کے ساتھ تکبیر — صحیح بخاری 1751"}]},{"id":"days-11-13-tashriq","title":"11 تا 13 ذوالحجہ: ایامِ تشریق","body":"ایامِ تشریق منیٰ میں گزارے جاتے ہیں۔ یہ اللہ تعالیٰ کو یاد کرنے کے دن ہیں (قرآن مجید 2:203)، اور راتیں بھی وہیں گزاری جاتی ہیں۔\n\nہر روز دوپہر کے بعد آپ تینوں جمرات کو ترتیب سے کنکریاں مارتے ہیں: چھوٹا، درمیانہ، پھر جمرۂ عقبہ، ہر ایک کو سات کنکریاں، اور ہر کنکری کے ساتھ تکبیر۔ پہلے کے بعد اور دوسرے کے بعد ایک طرف ہٹ کر قبلہ رخ ہو جائیے اور ہاتھ اٹھا کر لمبی دعا مانگیے؛ تیسرے کے بعد رکے بغیر چلے جائیے (صحیح بخاری 1751)۔\n\nآپ 12 تاریخ کو رمی کے بعد غروبِ آفتاب سے پہلے منیٰ سے جا سکتے ہیں؛ جو ٹھہر جائے وہ 13 تاریخ کو دوبارہ رمی کرتا ہے۔ دونوں صورتیں جائز ہیں (قرآن مجید 2:203)۔ اپنے گروپ کو دیے گئے نظام الاوقات پر عمل کیجیے۔ اگر آپ کمزور یا بیمار ہیں، یا رمی کے ٹھیک وقت کے بارے میں کوئی سوال ہے، تو اپنی صورتِ حال کے بارے میں کسی ایسے عالم سے پوچھ لیجیے جس پر آپ کو اعتماد ہو۔","steps":["11 اور 12 تاریخ کی راتیں منیٰ میں گزاریے۔","ہر روز دوپہر کے بعد 21 کنکریاں لے کر جمرات پر جائیے۔","چھوٹے جمرے کو سات کنکریاں ماریے، پھر ایک طرف ہٹ کر دعا مانگیے۔","درمیانے جمرے کو سات کنکریاں ماریے، پھر ایک طرف ہٹ کر دعا مانگیے۔","جمرۂ عقبہ کو سات کنکریاں ماریے اور رکے بغیر چلے جائیے۔","اگر جلدی جانا چاہتے ہیں تو 12 تاریخ کو غروبِ آفتاب سے پہلے منیٰ سے نکل جائیے۔","ورنہ رات وہیں ٹھہریے اور 13 تاریخ کو تینوں جمرات کی دوبارہ رمی کیجیے۔"],"duas":[]},{"id":"farewell-tawaf","title":"طوافِ وداع","body":"جب تمام مناسک پورے ہو جائیں اور آپ مکہ مکرمہ سے روانہ ہونے والے ہوں تو آخری کام طوافِ وداع ہے۔ لوگوں کو حکم دیا گیا تھا کہ ان کا آخری پڑاؤ بیت اللہ ہو؛ صرف حیض والی عورت کو اس سے رخصت دی گئی (صحیح بخاری 1755؛ صحیح مسلم 1328)۔\n\nیہ روزمرہ کے کپڑوں میں سات چکروں کا ایک عام طواف ہے، اضطباع اور رمل کے بغیر، اور اس کے بعد دو رکعت۔ اس کے بعد سعی نہیں ہے۔ اسے تب کیجیے جب آپ کا سامان تیار ہو اور روانگی قریب ہو؛ سواری یا ساتھیوں کے لیے تھوڑا سا انتظار کرنے میں کوئی حرج نہیں۔\n\nمسجدِ حرام سے شکر گزار دل کے ساتھ نکلیے۔ اللہ تعالیٰ سے دعا کیجیے کہ وہ آپ کا حج قبول فرمائے، آپ کو بخش دے اور آپ کو دوبارہ آنا نصیب کرے۔ پھر کوشش کیجیے کہ آپ اس شخص سے بہتر انسان بن کر گھر لوٹیں جو یہاں سے گیا تھا۔","steps":["پہلے اپنے تمام مناسک پورے کیجیے اور سامان تیار کر لیجیے۔","عام کپڑوں میں خانہ کعبہ کے گرد سات چکر لگائیے۔","طواف کے بعد دو رکعت پڑھیے۔","دعا کیجیے کہ اللہ تعالیٰ آپ کا حج قبول فرمائے، پھر بلا تاخیر مکہ مکرمہ سے روانہ ہو جائیے۔","حیض والی عورت اس طواف کے بغیر روانہ ہو جاتی ہے۔"],"duas":[]}]},"mistakes":[{"title":"حجرِ اسود کو بوسہ دینے کے لیے دھکم پیل کرنا","body":"حجرِ اسود کو بوسہ دینا سنت ہے؛ کسی مسلمان کو تکلیف پہنچانا حرام ہے۔ اگر ہجوم زیادہ ہو تو بس حجرِ اسود کی طرف اشارہ کیجیے اور تکبیر کہیے: آپ کا طواف مکمل ہے اور کسی کو چوٹ بھی نہیں لگتی۔"},{"title":"یہ سمجھنا کہ ہر چکر کی اپنی لازمی دعا ہے","body":"بعض کتابچوں میں ہر چکر کے لیے ایک الگ دعا لکھی ہوتی ہے۔ ایسی کوئی چیز لازم نہیں: طواف کے چکروں یا سعی کے پھیروں کے لیے کوئی مقررہ لازمی دعا نہیں ہے۔ اللہ تعالیٰ سے اپنے الفاظ میں، اپنی زبان میں بات کیجیے۔"},{"title":"غروبِ آفتاب سے پہلے عرفات سے نکل جانا","body":"نبی کریم حضرت محمد ﷺ سورج غروب ہونے تک عرفات میں ٹھہرے رہے (صحیح مسلم 1218)۔ سہ پہر ڈھلتے ہی بسوں کی طرف نہ دوڑیے: یہ پورے حج کی سب سے قیمتی گھڑیاں ہیں۔"},{"title":"جبلِ رحمت پر چڑھنے کو ضروری سمجھنا","body":"عرفات کا پورا میدان وقوف کی جگہ ہے۔ پہاڑی پر چڑھنا حج کا حصہ نہیں اور اس کا کوئی زائد ثواب نہیں؛ وہاں کی بھیڑ تھکا دینے والی اور خطرناک ہوتی ہے۔ وہیں رہیے جہاں آپ سکون سے دعا مانگ سکیں۔"},{"title":"عرفات کی حدود سے باہر وقوف کرنا","body":"بعض حاجی بے خبری میں عرفات کی حد سے ذرا باہر ٹھہر جاتے ہیں۔ چونکہ وقوف حج کا رکن ہے، اس لیے حدود کے بورڈ تلاش کیجیے اور ذرا سا بھی شک ہو تو اپنے رہنما سے پوچھ لیجیے۔"},{"title":"بہت بڑی کنکریاں جمع کرنا","body":"کنکریاں چھوٹی ہوتی ہیں، تقریباً چنے کے دانے کے برابر۔ بڑے پتھر، جوتے یا دوسری چیزیں اس عبادت کا حصہ نہیں اور ان سے لوگ زخمی ہو سکتے ہیں۔ رمی اللہ تعالیٰ کی اطاعت کا ایک عمل ہے جو سکون سے کیا جاتا ہے، غصے کا اظہار نہیں۔"},{"title":"عبادت کے بجائے تصویریں بنانا","body":"یادگار کی ایک تصویر میں چند سیکنڈ لگتے ہیں؛ مگر پورے طواف کی ویڈیو بنانا یا عرفات سے براہِ راست نشر کرنا آپ کے دل کو غافل کر دیتا ہے۔ مناسک کے دوران فون رکھ دیجیے اور اپنی نیت کے اخلاص کی حفاظت کیجیے۔"},{"title":"ہوائی سفر میں میقات سے غفلت","body":"جہاز میقات کو فضا میں پار کرتا ہے۔ احرام کی چادریں سوار ہونے سے پہلے یا پرواز کے شروع میں پہن لیجیے، اور جب میقات کا اعلان ہو، یا اس سے ذرا پہلے، نیت کر لیجیے۔ اگر آپ احرام کے بغیر میقات سے گزر گئے ہیں تو اپنی صورتِ حال کے بارے میں کسی ایسے عالم سے پوچھ لیجیے جس پر آپ کو اعتماد ہو۔"},{"title":"دایاں کندھا ہر وقت کھلا رکھنا","body":"اضطباع صرف مردوں کے لیے ہے اور صرف آمد کے طواف کے دوران۔ اس سے پہلے اور اس کے بعد، نماز اور سعی کے دوران بھی، دونوں کندھے ڈھکے رہتے ہیں۔"},{"title":"آنے جانے کو سعی کا ایک پھیرا شمار کرنا","body":"صفا سے مروہ ایک پھیرا ہے اور مروہ سے صفا دوسرا۔ سعی سات پھیرے ہے اور مروہ پر ختم ہوتی ہے۔ ہر آنے جانے کو ایک شمار کرنے کا مطلب یہ ہوگا کہ آپ چودہ پھیرے چلیں۔"},{"title":"عین مقامِ ابراہیم کے پیچھے نماز پڑھنے پر اصرار","body":"طواف کرنے والوں کے راستے میں نماز پڑھنے سے ان کا راستہ رکتا ہے اور آپ خود بھی خطرے میں پڑتے ہیں۔ جب ہجوم ہو تو دو رکعت مسجد میں کہیں بھی پڑھی جا سکتی ہیں۔"},{"title":"جھگڑنا اور صبر کھو بیٹھنا","body":"گرمی، قطاریں اور تھکن ہر ایک کا امتحان لیتی ہیں۔ قرآن مجید حج کے دوران فحش بات، گناہ اور جھگڑے سے منع کرتا ہے (2:197)۔ راستہ دے دیجیے، مسکرائیے، معاف کر دیجیے: اچھا اخلاق آپ کے حج کا حصہ ہے۔"}],"checklist":[{"id":"passport","group":"documents","label":"پاسپورٹ جو کم از کم چھ ماہ کے لیے کارآمد ہو"},{"id":"visa-permit","group":"documents","label":"حج یا عمرے کا ویزا اور سرکاری اجازت نامہ"},{"id":"tickets-bookings","group":"documents","label":"ہوائی جہاز کے ٹکٹ اور رہائش کی بکنگ"},{"id":"id-copies","group":"documents","label":"تمام دستاویزات کی کاغذی اور ڈیجیٹل نقول"},{"id":"emergency-contacts","group":"documents","label":"کارڈ جس پر آپ کے گروپ، ہوٹل اور ہنگامی رابطوں کے نمبر ہوں"},{"id":"money-card","group":"documents","label":"کچھ مقامی نقدی اور ایک بینک کارڈ"},{"id":"ihram-garments","group":"clothing","label":"مرد: احرام کی چادروں کے دو جوڑے"},{"id":"modest-clothing","group":"clothing","label":"عورتیں: ڈھیلا، باپردہ اور آرام دہ لباس"},{"id":"sandals","group":"clothing","label":"آرام دہ چپل جو پہلے سے پہنی ہوئی ہو"},{"id":"ihram-belt","group":"clothing","label":"رقم اور کاغذات کے لیے احرام کی بیلٹ یا تھیلی"},{"id":"small-bag","group":"clothing","label":"جوتوں اور کنکریوں کے لیے چھوٹا تھیلا"},{"id":"umbrella","group":"clothing","label":"دھوپ سے بچاؤ کے لیے ہلکے رنگ کی چھتری"},{"id":"vaccinations","group":"health","label":"لازمی حفاظتی ٹیکے اور ان کا سرٹیفکیٹ"},{"id":"medication","group":"health","label":"معمول کی دوائیں، نسخے کے ساتھ"},{"id":"unscented-toiletries","group":"health","label":"احرام کے لیے بغیر خوشبو کا صابن اور صفائی کا سامان"},{"id":"water-bottle","group":"health","label":"دوبارہ استعمال ہونے والی پانی کی بوتل"},{"id":"masks-sanitizer","group":"health","label":"ماسک اور بغیر خوشبو کا ہینڈ سینیٹائزر"},{"id":"first-aid","group":"health","label":"ابتدائی طبی امداد کی چھوٹی کٹ، چھالوں کی پٹیوں سمیت"},{"id":"sincere-intention","group":"spiritual","label":"اپنی نیت تازہ کیجیے: صرف اللہ تعالیٰ کے لیے"},{"id":"repentance-debts","group":"spiritual","label":"توبہ کیجیے، قرض چکائیے اور معافی مانگیے"},{"id":"learn-rites","group":"spiritual","label":"مناسک اور ان کی ترتیب سیکھ لیجیے"},{"id":"talbiyah-memorised","group":"spiritual","label":"تلبیہ زبانی یاد کر لیجیے"},{"id":"dua-list","group":"spiritual","label":"عرفات کے لیے اپنی ذاتی دعاؤں کی فہرست لکھ لیجیے"},{"id":"quran-dhikr","group":"spiritual","label":"تلاوت اور ذکر کے لیے جیبی قرآن مجید یا ایپ"}]}$tk$::jsonb)
  on conflict (kind, lang) do update set payload = excluded.payload, updated_at = now();
insert into public.premium_content (kind, lang, payload) values ('quiz', 'ur', $tk$[{"id":"q001","cat":"prophets","q":"قرآن مجید کے مطابق اللہ تعالیٰ نے سب سے پہلے کس انسان کو پیدا فرمایا؟","options":["حضرت نوح علیہ السلام","حضرت آدم علیہ السلام","حضرت ابراہیم علیہ السلام","حضرت ادریس علیہ السلام"],"answer":1,"explain":"حضرت آدم علیہ السلام پہلے انسان اور تمام انسانوں کے باپ ہیں۔ قرآن مجید ان کی تخلیق کا ذکر 2:30-37 میں کرتا ہے۔"},{"id":"q002","cat":"prophets","q":"کس نبی علیہ السلام نے اللہ تعالیٰ کے حکم سے کشتی بنائی؟","options":["حضرت موسیٰ علیہ السلام","حضرت یونس علیہ السلام","حضرت نوح علیہ السلام","حضرت ہود علیہ السلام"],"answer":2,"explain":"حضرت نوح علیہ السلام کو طوفان سے پہلے کشتی بنانے کا حکم دیا گیا تھا، جیسا کہ قرآن مجید میں بیان ہوا ہے (11:37)۔"},{"id":"q003","cat":"prophets","q":"کس نبی علیہ السلام کو ایک بڑی مچھلی نے نگل لیا تھا؟","options":["حضرت ایوب علیہ السلام","حضرت یوسف علیہ السلام","حضرت الیاس علیہ السلام","حضرت یونس علیہ السلام"],"answer":3,"explain":"حضرت یونس علیہ السلام کو ایک بڑی مچھلی نے نگل لیا، انہوں نے اندھیروں میں اللہ تعالیٰ کو پکارا اور انہیں نجات ملی (37:139-144)۔"},{"id":"q004","cat":"prophets","q":"خانہ کعبہ کی بنیادیں اٹھانے میں حضرت ابراہیم علیہ السلام کی مدد ان کے کس بیٹے نے کی؟","options":["حضرت اسحاق علیہ السلام","حضرت یعقوب علیہ السلام","حضرت اسماعیل علیہ السلام","حضرت لوط علیہ السلام"],"answer":2,"explain":"قرآن مجید بتاتا ہے کہ حضرت ابراہیم اور حضرت اسماعیل علیہما السلام نے مل کر بیت اللہ کی بنیادیں اٹھائیں (2:127)۔"},{"id":"q005","cat":"prophets","q":"کس نبی علیہ السلام کو بچپن میں ان کے بھائیوں نے کنویں میں ڈال دیا تھا؟","options":["حضرت یحییٰ علیہ السلام","حضرت یوسف علیہ السلام","حضرت ہارون علیہ السلام","حضرت داؤد علیہ السلام"],"answer":1,"explain":"حضرت یوسف علیہ السلام کو ان کے حاسد بھائیوں نے کنویں میں ڈال دیا تھا۔ ان کا قصہ پوری سورۂ یوسف میں ہے، جو 12 ویں سورت ہے (12:15)۔"},{"id":"q006","cat":"prophets","q":"تورات کس نبی علیہ السلام پر نازل ہوئی؟","options":["حضرت عیسیٰ علیہ السلام","حضرت داؤد علیہ السلام","حضرت ابراہیم علیہ السلام","حضرت موسیٰ علیہ السلام"],"answer":3,"explain":"تورات حضرت موسیٰ علیہ السلام کو عطا کی گئی، جو بنی اسرائیل کو مصر سے نکال کر لے گئے۔"},{"id":"q007","cat":"prophets","q":"زبور کس نبی علیہ السلام کو عطا ہوئی؟","options":["حضرت داؤد علیہ السلام","حضرت سلیمان علیہ السلام","حضرت موسیٰ علیہ السلام","حضرت زکریا علیہ السلام"],"answer":0,"explain":"قرآن مجید بیان کرتا ہے کہ اللہ تعالیٰ نے حضرت داؤد علیہ السلام کو زبور عطا فرمائی (4:163 اور 17:55)۔"},{"id":"q008","cat":"prophets","q":"انجیل کس نبی علیہ السلام کو عطا ہوئی؟","options":["حضرت عیسیٰ علیہ السلام","حضرت یحییٰ علیہ السلام","حضرت موسیٰ علیہ السلام","حضرت یونس علیہ السلام"],"answer":0,"explain":"انجیل حضرت عیسیٰ ابنِ مریم علیہما السلام کو عطا کی گئی، جیسا کہ قرآن مجید 5:46 میں بتاتا ہے۔"},{"id":"q009","cat":"prophets","q":"کون سے نبی حضرت موسیٰ علیہ السلام کے بھائی تھے اور ان کے کام میں ان کے مددگار بنے؟","options":["حضرت یوشع علیہ السلام","حضرت شعیب علیہ السلام","حضرت الیاس علیہ السلام","حضرت ہارون علیہ السلام"],"answer":3,"explain":"حضرت موسیٰ نے اللہ تعالیٰ سے دعا کی کہ ان کے بھائی حضرت ہارون کو ان کا مددگار بنا دیا جائے (20:29-32)۔ ان دونوں پر سلام ہو۔"},{"id":"q010","cat":"prophets","q":"کون سے نبی علیہ السلام، جنہیں ایک لمبی آزمائش سے گزارا گیا، اپنے صبر کے لیے اور اپنے رب کو سب رحم کرنے والوں سے بڑھ کر رحم کرنے والا کہہ کر پکارنے کے لیے مشہور ہیں؟","options":["حضرت ایوب علیہ السلام","حضرت ہارون علیہ السلام","حضرت لوط علیہ السلام","حضرت صالح علیہ السلام"],"answer":0,"explain":"حضرت ایوب علیہ السلام اپنی آزمائش میں صابر رہے اور انہوں نے اپنے رب کو پکارا، جس نے ان کی تکلیف دور کر دی (21:83-84)۔"},{"id":"q011","cat":"prophets","q":"قومِ عاد کی طرف کس نبی علیہ السلام کو بھیجا گیا؟","options":["حضرت صالح علیہ السلام","حضرت شعیب علیہ السلام","حضرت ہود علیہ السلام","حضرت لوط علیہ السلام"],"answer":2,"explain":"حضرت ہود علیہ السلام کو قومِ عاد کی طرف بھیجا گیا تاکہ انہیں صرف ایک اللہ کی عبادت کی دعوت دیں (7:65)۔"},{"id":"q012","cat":"prophets","q":"قومِ ثمود کو نشانی کے طور پر جو اونٹنی دی گئی اس کا تعلق کس نبی علیہ السلام سے ہے؟","options":["حضرت ہود علیہ السلام","حضرت صالح علیہ السلام","حضرت نوح علیہ السلام","حضرت یونس علیہ السلام"],"answer":1,"explain":"حضرت صالح علیہ السلام قومِ ثمود کی طرف بھیجے گئے، اور اونٹنی ان کے لیے اللہ تعالیٰ کی طرف سے ایک نشانی تھی (7:73)۔"},{"id":"q013","cat":"prophets","q":"کس نبی علیہ السلام کو ان کی قوم نے آگ میں ڈالا، اور اللہ تعالیٰ نے اسے ان کے لیے ٹھنڈی اور سلامتی والی بنا دیا؟","options":["حضرت موسیٰ علیہ السلام","حضرت ابراہیم علیہ السلام","حضرت یحییٰ علیہ السلام","حضرت ہود علیہ السلام"],"answer":1,"explain":"جب حضرت ابراہیم علیہ السلام کو ان کی قوم نے آگ میں ڈالا تو اللہ تعالیٰ نے آگ کو حکم دیا کہ وہ ان کے لیے ٹھنڈک اور سلامتی بن جائے (21:68-69)۔"},{"id":"q014","cat":"prophets","q":"قرآن مجید کے مطابق کس نبی علیہ السلام نے ایک چیونٹی کی بات سمجھ لی جو دوسری چیونٹیوں کو خبردار کر رہی تھی؟","options":["حضرت یونس علیہ السلام","حضرت عیسیٰ علیہ السلام","حضرت سلیمان علیہ السلام","حضرت یوسف علیہ السلام"],"answer":2,"explain":"حضرت سلیمان علیہ السلام نے سنا کہ ان کا لشکر قریب آنے پر ایک چیونٹی دوسری چیونٹیوں کو خبردار کر رہی ہے، تو وہ مسکرائے اور اللہ تعالیٰ کا شکر ادا کیا (27:18-19)۔"},{"id":"q015","cat":"prophets","q":"حضرت یحییٰ علیہ السلام کے والد کون سے نبی علیہ السلام تھے؟","options":["عمران","حضرت یعقوب علیہ السلام","حضرت ایوب علیہ السلام","حضرت زکریا علیہ السلام"],"answer":3,"explain":"حضرت زکریا علیہ السلام نے بڑھاپے میں اولاد کے لیے دعا کی اور انہیں حضرت یحییٰ کی خوش خبری دی گئی (19:7)۔"},{"id":"q016","cat":"seerah","q":"نبی کریم حضرت محمد ﷺ کس شہر میں پیدا ہوئے؟","options":["مدینہ","مکہ","طائف","بیت المقدس"],"answer":1,"explain":"نبی کریم حضرت محمد ﷺ مکہ میں قبیلۂ قریش میں پیدا ہوئے۔"},{"id":"q017","cat":"seerah","q":"نبی کریم حضرت محمد ﷺ پر پہلی وحی کہاں نازل ہوئی؟","options":["غارِ ثور میں","غارِ حرا میں","جبلِ احد پر","میدانِ عرفات میں"],"answer":1,"explain":"پہلی وحی مکہ کے قریب جبلِ نور پر واقع غارِ حرا میں آئی، جہاں آپ ﷺ خلوت کے لیے جایا کرتے تھے۔"},{"id":"q018","cat":"seerah","q":"نبی کریم حضرت محمد ﷺ کے پاس وحی کون سا فرشتہ لے کر آیا؟","options":["حضرت میکائیل علیہ السلام","حضرت جبرائیل علیہ السلام","حضرت اسرافیل علیہ السلام","مالک"],"answer":1,"explain":"حضرت جبرائیل علیہ السلام قرآن مجید لے کر نبی کریم حضرت محمد ﷺ کے پاس آئے۔"},{"id":"q019","cat":"seerah","q":"نبی کریم حضرت محمد ﷺ پر قرآن مجید کا سب سے پہلا لفظ کون سا نازل ہوا؟","options":["قل (کہو)","قم (اٹھو)","اقرأ (پڑھو)","سبح (تسبیح کرو)"],"answer":2,"explain":"پہلی وحی لفظ اقرأ سے شروع ہوتی ہے، جس کے معنی ہیں پڑھو (96:1)۔"},{"id":"q020","cat":"seerah","q":"نبی کریم حضرت محمد ﷺ کی پہلی زوجہ کون تھیں؟","options":["حضرت خدیجہ بنت خویلد رضی اللہ عنہا","حضرت عائشہ بنت ابی بکر رضی اللہ عنہا","حضرت حفصہ بنت عمر رضی اللہ عنہا","حضرت سودہ بنت زمعہ رضی اللہ عنہا"],"answer":0,"explain":"حضرت خدیجہ رضی اللہ عنہا، جو مکہ کی ایک معزز تاجرہ تھیں، آپ ﷺ کی پہلی زوجہ تھیں۔ ان کی زندگی میں آپ ﷺ نے کسی اور خاتون سے نکاح نہیں کیا۔"},{"id":"q021","cat":"seerah","q":"ہجرت، یعنی مکہ سے مدینہ کی طرف نقل مکانی، کس عیسوی سال میں ہوئی؟","options":["622","570","610","632"],"answer":0,"explain":"ہجرت 622 عیسوی میں ہوئی۔ بعد میں یہی سال اسلامی تقویم کا سال 1 قرار پایا۔"},{"id":"q022","cat":"seerah","q":"ہجرت سے پہلے شہر مدینہ کا نام کیا تھا؟","options":["خیبر","تبوک","طائف","یثرب"],"answer":3,"explain":"اس شہر کا نام یثرب تھا۔ نبی کریم حضرت محمد ﷺ کے وہاں قیام فرمانے کے بعد یہ مدینہ یعنی شہر کے نام سے مشہور ہوا۔"},{"id":"q023","cat":"seerah","q":"ہجرت کے دوران نبی کریم حضرت محمد ﷺ نے کس غار میں پناہ لی؟","options":["غارِ ثور","غارِ حرا","جبلِ احد کا ایک غار","کوہِ صفا کا ایک غار"],"answer":0,"explain":"آپ ﷺ اپنے ساتھی حضرت ابوبکر رضی اللہ عنہ کے ساتھ غارِ ثور میں چھپے رہے جبکہ قریش ان کی تلاش میں تھے۔ قرآن مجید 9:40 میں اس موقع کا ذکر کرتا ہے۔"},{"id":"q024","cat":"seerah","q":"غزوۂ بدر ہجرت کے کس سال ہوا؟","options":["سن 2 ہجری","سن 1 ہجری","سن 5 ہجری","سن 8 ہجری"],"answer":0,"explain":"غزوۂ بدر سن 2 ہجری کے رمضان میں ہوا۔ یہ مسلمانوں کی پہلی بڑی جنگ تھی۔"},{"id":"q025","cat":"seerah","q":"ان دادا کا نام کیا تھا جنہوں نے والدہ کے انتقال کے بعد نبی کریم حضرت محمد ﷺ کی پرورش کی؟","options":["ابو لہب","ابو سفیان","عبدالمطلب","ورقہ بن نوفل"],"answer":2,"explain":"آپ ﷺ کے دادا عبدالمطلب نے، جو مکہ کے ایک سردار تھے، آپ ﷺ کی دیکھ بھال کی۔ دادا کے انتقال کے بعد آپ ﷺ کے چچا ابو طالب نے آپ ﷺ کو اپنے پاس رکھا۔"},{"id":"q026","cat":"seerah","q":"نبی کریم حضرت محمد ﷺ کی والدہ کا نام کیا تھا؟","options":["حلیمہ سعدیہ","فاطمہ بنت اسد","ام ایمن","آمنہ بنت وہب"],"answer":3,"explain":"آپ ﷺ کی والدہ آمنہ بنت وہب تھیں۔ ان کا انتقال اس وقت ہوا جب آپ ﷺ ابھی چھوٹے بچے تھے۔ حلیمہ سعدیہ آپ ﷺ کی رضاعی ماں تھیں۔"},{"id":"q027","cat":"seerah","q":"نبی کریم حضرت محمد ﷺ کا تعلق کس قبیلے سے تھا؟","options":["اوس","خزرج","ثقیف","قریش"],"answer":3,"explain":"آپ ﷺ کا تعلق مکہ کے قبیلے قریش کی شاخ بنو ہاشم سے تھا۔"},{"id":"q028","cat":"seerah","q":"سن 6 ہجری میں مسلمانوں اور قریش کے درمیان جو صلح طے پائی اس کا نام کیا ہے؟","options":["بیعتِ عقبہ","میثاقِ مدینہ","صلحِ حدیبیہ","حلف الفضول"],"answer":2,"explain":"صلحِ حدیبیہ سن 6 ہجری میں مکہ کے قریب طے پائی۔ اس سے امن کا ایک دور آیا جس میں اسلام خوب پھیلا۔"},{"id":"q029","cat":"seerah","q":"فتحِ مکہ ہجرت کے کس سال ہوئی؟","options":["سن 2 ہجری","سن 4 ہجری","سن 8 ہجری","سن 6 ہجری"],"answer":2,"explain":"مسلمان سن 8 ہجری (630 عیسوی) میں مکہ میں داخل ہوئے۔ نبی کریم حضرت محمد ﷺ نے اہلِ مکہ کو معاف فرما دیا۔"},{"id":"q030","cat":"seerah","q":"نبوت سے پہلے مکہ کے لوگوں نے نبی کریم حضرت محمد ﷺ کو کیا لقب دیا تھا؟","options":["الحکیم (دانا)","الکریم (سخی)","الشجاع (بہادر)","الامین (امانت دار)"],"answer":3,"explain":"آپ ﷺ اپنی دیانت کی وجہ سے الامین یعنی امانت دار کے لقب سے مشہور تھے۔ لوگ اپنی قیمتی چیزیں آپ ﷺ کے پاس امانت رکھتے تھے۔"},{"id":"q031","cat":"companions","q":"اسلام کے پہلے مؤذن کون تھے؟","options":["حضرت سلمان فارسی رضی اللہ عنہ","حضرت انس بن مالک رضی اللہ عنہ","حضرت بلال بن رباح رضی اللہ عنہ","حضرت زید بن حارثہ رضی اللہ عنہ"],"answer":2,"explain":"حضرت بلال بن رباح رضی اللہ عنہ، جو حبشی نسل کے آزاد کردہ غلام تھے، انہیں نبی کریم حضرت محمد ﷺ نے اذان دینے کے لیے منتخب فرمایا۔"},{"id":"q032","cat":"companions","q":"ہجرت کے سفر میں نبی کریم حضرت محمد ﷺ کے ساتھ کون سے صحابی تھے؟","options":["حضرت بلال بن رباح رضی اللہ عنہ","حضرت مصعب بن عمیر رضی اللہ عنہ","حضرت خالد بن ولید رضی اللہ عنہ","حضرت ابوبکر رضی اللہ عنہ"],"answer":3,"explain":"حضرت ابوبکر رضی اللہ عنہ مکہ سے مدینہ کے سفر میں آپ ﷺ کے رفیق تھے اور غارِ ثور میں آپ ﷺ کے ساتھ رہے۔"},{"id":"q033","cat":"companions","q":"مدینہ کے دفاع کے لیے خندق کھودنے کا مشورہ کس صحابی نے دیا؟","options":["حضرت بلال بن رباح رضی اللہ عنہ","حضرت ابو ایوب انصاری رضی اللہ عنہ","حضرت سلمان فارسی رضی اللہ عنہ","حضرت مصعب بن عمیر رضی اللہ عنہ"],"answer":2,"explain":"حضرت سلمان فارسی رضی اللہ عنہ نے، جو فارس سے آئے تھے، خندق کا مشورہ دیا۔ اسی لیے سن 5 ہجری کی جنگ غزوۂ خندق کہلاتی ہے۔"},{"id":"q034","cat":"companions","q":"کون سے صحابی سیف اللہ یعنی اللہ کی تلوار کے لقب سے مشہور ہیں؟","options":["حضرت خالد بن ولید رضی اللہ عنہ","حضرت بلال بن رباح رضی اللہ عنہ","حضرت زید بن ثابت رضی اللہ عنہ","حضرت انس بن مالک رضی اللہ عنہ"],"answer":0,"explain":"مشہور سپہ سالار حضرت خالد بن ولید رضی اللہ عنہ سیف اللہ یعنی اللہ کی تلوار کے لقب سے جانے جاتے ہیں۔"},{"id":"q035","cat":"companions","q":"نبی کریم حضرت محمد ﷺ کے پیغام پر سب سے پہلے کون ایمان لایا؟","options":["حضرت عمر بن خطاب رضی اللہ عنہ","حضرت خدیجہ بنت خویلد رضی اللہ عنہا","حضرت خالد بن ولید رضی اللہ عنہ","حضرت ابو سفیان رضی اللہ عنہ"],"answer":1,"explain":"آپ ﷺ کی زوجہ حضرت خدیجہ رضی اللہ عنہا سب سے پہلے آپ ﷺ پر ایمان لائیں۔ انہوں نے پہلی وحی ہی سے آپ ﷺ کو تسلی دی اور آپ ﷺ کا ساتھ دیا۔"},{"id":"q036","cat":"companions","q":"ہجری تقویم کس خلیفہ کے دور میں اختیار کی گئی، جس کا نقطۂ آغاز ہجرت کا سال ہے؟","options":["عمر بن خطاب","ہارون الرشید","عبدالملک بن مروان","عمر بن عبدالعزیز"],"answer":0,"explain":"ہجری تقویم نبی کریم حضرت محمد ﷺ کے وصال کے چند سال بعد حضرت عمر بن خطاب رضی اللہ عنہ کی خلافت میں مقرر کی گئی۔"},{"id":"q037","cat":"companions","q":"کون سے صحابی کو، جو کاتبِ وحی تھے، قرآن مجید کو ایک تحریری مجموعے میں جمع کرنے کا کام سونپا گیا؟","options":["حضرت بلال بن رباح رضی اللہ عنہ","حضرت خالد بن ولید رضی اللہ عنہ","حضرت سلمان فارسی رضی اللہ عنہ","حضرت زید بن ثابت رضی اللہ عنہ"],"answer":3,"explain":"حضرت زید بن ثابت رضی اللہ عنہ نے، جو نبی کریم حضرت محمد ﷺ کے کاتبوں میں سے تھے، حضرت ابوبکر رضی اللہ عنہ کی خلافت میں لکھے ہوئے قرآن کو ایک مجموعے میں جمع کیا۔"},{"id":"q038","cat":"companions","q":"ہجرت سے پہلے کس صحابی کو یثرب بھیجا گیا تاکہ وہاں کے لوگوں کو اسلام کی تعلیم دیں؟","options":["حضرت مصعب بن عمیر رضی اللہ عنہ","حضرت خالد بن ولید رضی اللہ عنہ","حضرت انس بن مالک رضی اللہ عنہ","حضرت ابو ایوب انصاری رضی اللہ عنہ"],"answer":0,"explain":"حضرت مصعب بن عمیر رضی اللہ عنہ کو پہلی بیعتِ عقبہ کے بعد یثرب بھیجا گیا۔ ان کے ذریعے وہاں کے بہت سے لوگوں نے اسلام قبول کیا۔"},{"id":"q039","cat":"companions","q":"نبی کریم حضرت محمد ﷺ کے چچا حضرت حمزہ رضی اللہ عنہ کس جنگ میں شہید ہوئے؟","options":["بدر","خندق","حنین","احد"],"answer":3,"explain":"حضرت حمزہ بن عبدالمطلب رضی اللہ عنہ سن 3 ہجری میں غزوۂ احد میں شہید ہوئے۔"},{"id":"q040","cat":"companions","q":"اسلام کی پہلی شہید کے طور پر کسے یاد کیا جاتا ہے؟","options":["حضرت ام ایمن رضی اللہ عنہا","حضرت سمیہ بنت خیاط رضی اللہ عنہا","حضرت حلیمہ سعدیہ رضی اللہ عنہا","حضرت ام سلمہ رضی اللہ عنہا"],"answer":1,"explain":"حضرت عمار بن یاسر رضی اللہ عنہ کی والدہ حضرت سمیہ بنت خیاط رضی اللہ عنہا کو مکہ میں اپنا ایمان چھوڑنے سے انکار پر شہید کر دیا گیا۔"},{"id":"q041","cat":"companions","q":"حبشہ کے بادشاہ نجاشی کے سامنے مسلمان مہاجرین کی طرف سے کس صحابی نے گفتگو کی؟","options":["حضرت بلال بن رباح رضی اللہ عنہ","حضرت جعفر بن ابی طالب رضی اللہ عنہ","حضرت زید بن ثابت رضی اللہ عنہ","حضرت انس بن مالک رضی اللہ عنہ"],"answer":1,"explain":"حضرت جعفر بن ابی طالب رضی اللہ عنہ نے نجاشی کے سامنے اسلام کی وضاحت کی، جس کے بعد اس نے مسلمانوں کو اپنے ملک میں امن سے رہنے دیا۔"},{"id":"q042","cat":"companions","q":"نبی کریم حضرت محمد ﷺ کی کس صاحبزادی کا نکاح حضرت علی بن ابی طالب رضی اللہ عنہ سے ہوا؟","options":["حضرت فاطمہ رضی اللہ عنہا","حضرت زینب رضی اللہ عنہا","حضرت رقیہ رضی اللہ عنہا","حضرت ام کلثوم رضی اللہ عنہا"],"answer":0,"explain":"حضرت فاطمہ رضی اللہ عنہا کا نکاح مدینہ میں حضرت علی بن ابی طالب رضی اللہ عنہ سے ہوا۔ وہ حضرت حسن اور حضرت حسین رضی اللہ عنہما کے والدین تھے۔"},{"id":"q043","cat":"companions","q":"مدینہ کے ان لوگوں کو کیا کہا جاتا ہے جنہوں نے مکہ سے آنے والے مہاجرین کا استقبال کیا اور ان کی مدد کی؟","options":["مہاجرین (ہجرت کرنے والے)","قریش","تابعین (صحابہ کے بعد کی نسل)","انصار (مدد کرنے والے)"],"answer":3,"explain":"مدینہ کے مسلمان انصار یعنی مدد کرنے والے کہلاتے ہیں۔ جنہوں نے مکہ سے ہجرت کی وہ مہاجرین کہلاتے ہیں۔"},{"id":"q044","cat":"companions","q":"جس رات نبی کریم حضرت محمد ﷺ ہجرت کے لیے مکہ سے نکلے، اس رات آپ ﷺ کے بستر پر کون سویا؟","options":["حضرت زید بن حارثہ رضی اللہ عنہ","حضرت بلال بن رباح رضی اللہ عنہ","حضرت علی بن ابی طالب رضی اللہ عنہ","حضرت انس بن مالک رضی اللہ عنہ"],"answer":2,"explain":"نوجوان حضرت علی بن ابی طالب رضی اللہ عنہ اس رات آپ ﷺ کی جگہ بستر پر لیٹے اور پیچھے ٹھہر گئے تاکہ لوگوں کی وہ چیزیں لوٹا دیں جو انہوں نے آپ ﷺ کے پاس امانت رکھی تھیں۔"},{"id":"q045","cat":"companions","q":"جب مدینہ میں مسجدِ نبوی تعمیر ہو رہی تھی تو نبی کریم حضرت محمد ﷺ کس کے گھر میں ٹھہرے؟","options":["حضرت سلمان فارسی رضی اللہ عنہ","حضرت ابو ایوب انصاری رضی اللہ عنہ","حضرت خالد بن ولید رضی اللہ عنہ","حضرت مصعب بن عمیر رضی اللہ عنہ"],"answer":1,"explain":"آپ ﷺ اپنی مسجد اور اپنے حجروں کی تعمیر تک حضرت ابو ایوب انصاری رضی اللہ عنہ کے گھر میں ٹھہرے۔"},{"id":"q046","cat":"quran","q":"قرآن مجید میں کتنی سورتیں ہیں؟","options":["114","99","110","120"],"answer":0,"explain":"قرآن مجید میں الفاتحہ سے الناس تک 114 سورتیں ہیں۔"},{"id":"q047","cat":"quran","q":"قرآن مجید کی سب سے لمبی سورت کون سی ہے؟","options":["آل عمران","النساء","یٰسین","البقرہ"],"answer":3,"explain":"البقرہ، جو 2 نمبر کی سورت ہے، قرآن مجید کی سب سے لمبی سورت ہے۔"},{"id":"q048","cat":"quran","q":"قرآن مجید کی سب سے چھوٹی سورت کون سی ہے؟","options":["الاخلاص","الکوثر","الفلق","الفاتحہ"],"answer":1,"explain":"الکوثر، جو 108 ویں سورت ہے، سب سے چھوٹی ہے: اس میں صرف تین مختصر آیات ہیں۔"},{"id":"q049","cat":"quran","q":"قرآن مجید کس سورت سے شروع ہوتا ہے؟","options":["البقرہ","الاخلاص","الفاتحہ","العلق"],"answer":2,"explain":"الفاتحہ، یعنی کھولنے والی، قرآن مجید کی پہلی سورت ہے اور ہر نماز میں پڑھی جاتی ہے۔"},{"id":"q050","cat":"quran","q":"قرآن مجید میں سب سے آخر میں کون سی سورت رکھی گئی ہے؟","options":["الفلق","الاخلاص","الناس","النصر"],"answer":2,"explain":"الناس، جو 114 ویں سورت ہے، قرآن مجید کی آخری سورت ہے۔"},{"id":"q051","cat":"quran","q":"قرآن مجید کتنے پاروں (اجزاء) میں تقسیم ہے؟","options":["7","30","60","114"],"answer":1,"explain":"قرآن مجید 30 پاروں میں تقسیم ہے، جس سے اسے ایک مہینے میں پورا پڑھنا آسان ہو جاتا ہے۔"},{"id":"q052","cat":"quran","q":"قرآن مجید کا نزول کس مہینے میں شروع ہوا؟","options":["رمضان","رجب","محرم","ذوالحجہ"],"answer":0,"explain":"قرآن مجید بتاتا ہے کہ وہ رمضان کے مہینے میں نازل کیا گیا (2:185)۔"},{"id":"q053","cat":"quran","q":"آیت الکرسی کس سورت میں ہے؟","options":["آل عمران","البقرہ","الکہف","الملک"],"answer":1,"explain":"آیت الکرسی سورۂ بقرہ کی آیت 255 ہے (2:255)۔"},{"id":"q054","cat":"quran","q":"وہ واحد سورت کون سی ہے جو بسم اللہ سے شروع نہیں ہوتی؟","options":["التوبہ","الانفال","یونس","الملک"],"answer":0,"explain":"التوبہ، جو 9 ویں سورت ہے، واحد سورت ہے جس کے شروع میں بسم اللہ الرحمٰن الرحیم نہیں ہے۔"},{"id":"q055","cat":"quran","q":"کس سورت میں بسم اللہ دو بار آئی ہے؟","options":["النحل","العنکبوت","سبا","النمل"],"answer":3,"explain":"سورۂ نمل میں بسم اللہ ایک بار شروع میں اور دوسری بار حضرت سلیمان علیہ السلام کے خط میں آئی ہے (27:30)۔"},{"id":"q056","cat":"quran","q":"قرآن مجید کی کون سی سورت حضرت عیسیٰ علیہ السلام کی والدہ کے نام پر ہے؟","options":["النساء","مریم","آل عمران","النور"],"answer":1,"explain":"19 ویں سورت کا نام حضرت عیسیٰ علیہ السلام کی والدہ حضرت مریم علیہا السلام کے نام پر ہے۔ وہ واحد خاتون ہیں جن کا نام لے کر قرآن مجید میں ذکر آیا ہے۔"},{"id":"q057","cat":"quran","q":"قرآن مجید تقریباً کتنے سال میں نازل ہوا؟","options":["تقریباً 23 سال","تقریباً 3 سال","تقریباً 10 سال","تقریباً 40 سال"],"answer":0,"explain":"قرآن مجید تقریباً 23 سال میں تھوڑا تھوڑا کر کے نازل ہوا، پہلے مکہ میں اور پھر مدینہ میں۔"},{"id":"q058","cat":"quran","q":"سورۂ فاتحہ میں کتنی آیات ہیں؟","options":["3","5","10","7"],"answer":3,"explain":"الفاتحہ میں سات آیات ہیں۔ یہ نماز کی ہر رکعت میں پڑھی جاتی ہے۔"},{"id":"q059","cat":"quran","q":"ہجرت سے پہلے نازل ہونے والی سورتوں کو کیا کہا جاتا ہے؟","options":["مدنی","محکم","مکی","مفصل"],"answer":2,"explain":"ہجرت سے پہلے نازل ہونے والی سورتیں مکی اور اس کے بعد نازل ہونے والی سورتیں مدنی کہلاتی ہیں۔"},{"id":"q060","cat":"quran","q":"قرآن مجید کی سب سے لمبی آیت کون سی ہے؟","options":["آیت الکرسی (2:255)","آیتِ نور (24:35)","آیتِ دَین، یعنی قرض والی آیت (2:282)","الفاتحہ کی پہلی آیت"],"answer":2,"explain":"سب سے لمبی آیت البقرہ کی آیت 282 ہے۔ یہ لوگوں کو سکھاتی ہے کہ اپنے قرض لکھ لیا کریں اور گواہ بنا لیا کریں۔"},{"id":"q061","cat":"history","q":"خلافتِ بنو امیہ کا دارالحکومت کون سا شہر تھا؟","options":["بغداد","دمشق","قاہرہ","مدینہ"],"answer":1,"explain":"بنو امیہ نے 661 سے 750 تک شام کے شہر دمشق سے حکومت کی۔"},{"id":"q062","cat":"history","q":"کس عباسی خلیفہ نے 762 میں شہر بغداد کی بنیاد رکھی؟","options":["ہارون الرشید","المنصور","المامون","المعتصم"],"answer":1,"explain":"خلیفہ المنصور نے 762 میں دریائے دجلہ کے کنارے بغداد کی بنیاد رکھی۔ یہ دنیا کے عظیم ترین شہروں میں سے ایک بن گیا۔"},{"id":"q063","cat":"history","q":"1258 میں بغداد پر قبضہ کر کے اسے کس نے تباہ کیا؟","options":["منگولوں نے","صلیبیوں نے","سلجوقیوں نے","عثمانیوں نے"],"answer":0,"explain":"ہلاکو کی قیادت میں منگول فوج نے 1258 میں بغداد پر قبضہ کر لیا، جس سے بغداد کی عباسی خلافت کا خاتمہ ہو گیا۔"},{"id":"q064","cat":"history","q":"کس عثمانی سلطان نے 1453 میں قسطنطنیہ فتح کیا؟","options":["محمد ثانی","سلیمان القانونی","سلیم اول","عثمان اول"],"answer":0,"explain":"محمد ثانی نے، جو فاتح کے لقب سے مشہور ہیں، 1453 میں قسطنطنیہ فتح کیا۔ یہ شہر عثمانی دارالحکومت استنبول بن گیا۔"},{"id":"q065","cat":"history","q":"711 میں شمالی افریقہ سے جزیرہ نما آئبیریا میں داخل ہونے والی مسلم فوج کی قیادت کس نے کی؟","options":["عقبہ بن نافع","خالد بن ولید","صلاح الدین ایوبی","طارق بن زیاد"],"answer":3,"explain":"طارق بن زیاد نے 711 میں آبنائے کو پار کیا۔ جبرالٹر کی چٹان انہی کے نام پر ہے: جبل طارق، یعنی طارق کا پہاڑ۔"},{"id":"q066","cat":"history","q":"1187 میں بیت المقدس کو صلیبیوں سے کس نے واپس لیا؟","options":["بیبرس","نور الدین زنگی","صلاح الدین ایوبی","محمد ثانی"],"answer":2,"explain":"صلاح الدین ایوبی نے جنگِ حطین میں فتح کے بعد 1187 میں بیت المقدس دوبارہ حاصل کیا۔"},{"id":"q067","cat":"history","q":"اندلس کی آخری مسلم سلطنت کون سا شہر تھا، جس کا سقوط 1492 میں ہوا؟","options":["قرطبہ","غرناطہ","اشبیلیہ","طلیطلہ"],"answer":1,"explain":"غرناطہ کی نصری سلطنت کا سقوط 1492 میں ہوا، جس سے جزیرہ نما آئبیریا کے حصوں پر تقریباً آٹھ صدیوں کی مسلم حکمرانی ختم ہو گئی۔"},{"id":"q068","cat":"history","q":"1260 میں عین جالوت کی جنگ میں منگولوں کو کس نے شکست دی؟","options":["مصر کے مملوکوں نے","عثمانیوں نے","سلجوقیوں نے","موحدین نے"],"answer":0,"explain":"مصر کے مملوکوں نے 1260 میں فلسطین میں عین جالوت کے مقام پر منگولوں کی پیش قدمی روک دی۔"},{"id":"q069","cat":"history","q":"کس خاندان نے 750 میں خلافت سنبھالی اور بعد میں بغداد کو اپنا دارالحکومت بنایا؟","options":["عثمانی","مملوک","مرابطین","عباسی"],"answer":3,"explain":"عباسیوں نے 750 میں بنو امیہ کی جگہ لی اور 762 میں بغداد کی بنیاد رکھی۔"},{"id":"q070","cat":"history","q":"کون سا اموی شہزادہ بچ کر اندلس پہنچا اور 756 میں امارتِ قرطبہ کی بنیاد رکھی؟","options":["طارق بن زیاد","ہارون الرشید","صلاح الدین ایوبی","عبدالرحمٰن اول"],"answer":3,"explain":"عبدالرحمٰن اول، جو اموی خاندان کے بچ نکلنے والوں میں سے تھے، اندلس پہنچے اور 756 میں امارتِ قرطبہ کی بنیاد رکھی۔"},{"id":"q071","cat":"history","q":"عثمانی خاندان کا نام اس کے بانی کے نام پر ہے۔ وہ کون تھے؟","options":["محمد ثانی","تیمور لنگ","الپ ارسلان","عثمان اول"],"answer":3,"explain":"عثمان اول نے 1300 کے لگ بھگ اناطولیہ میں عثمانی ریاست کی بنیاد رکھی۔ لفظ عثمانی انہی کے نام سے نکلا ہے۔"},{"id":"q072","cat":"history","q":"1526 میں ہندوستان میں سلطنتِ مغلیہ کی بنیاد کس نے رکھی؟","options":["اکبر","شاہ جہاں","بابر","اورنگ زیب"],"answer":2,"explain":"بابر نے 1526 میں پانی پت کی جنگ میں فتح کے بعد سلطنتِ مغلیہ کی بنیاد رکھی۔"},{"id":"q073","cat":"history","q":"16 ویں صدی کا کون سا عثمانی سلطان ذی شان اور قانونی یعنی قانون ساز کے لقب سے مشہور ہے؟","options":["محمد ثانی","سلیمان اول","عثمان اول","عبدالحمید ثانی"],"answer":1,"explain":"سلیمان اول نے 1520 سے 1566 تک حکومت کی، جب سلطنتِ عثمانیہ اپنے عروج پر تھی۔ انہیں قانونی یعنی قانون ساز کہا جاتا ہے۔"},{"id":"q074","cat":"history","q":"منسا موسیٰ، جو 1324 میں اپنے سفرِ حج کے لیے مشہور ہیں، کس سلطنت کے حکمران تھے؟","options":["سلطنتِ سونگھائی","سلطنتِ گھانا","سلطنتِ مالی","سلطنتِ کانم"],"answer":2,"explain":"منسا موسیٰ مغربی افریقہ میں سلطنتِ مالی کے حکمران تھے۔ 1324 کے ان کے حج نے مالی کی دولت کو دور دور تک مشہور کر دیا۔"},{"id":"q075","cat":"history","q":"کس سلجوقی سلطان نے 1071 میں بازنطینیوں کے خلاف جنگِ ملازگرد جیتی؟","options":["صلاح الدین ایوبی","بیبرس","الپ ارسلان","عثمان اول"],"answer":2,"explain":"الپ ارسلان نے 1071 میں ملازگرد کے مقام پر بازنطینی فوج کو شکست دی، جس سے اناطولیہ کے دروازے ترکوں کے لیے کھل گئے۔"},{"id":"q076","cat":"sciences","q":"ریاضی کی کس شاخ کا نام الخوارزمی کی کتاب الجبر سے لیا گیا ہے؟","options":["جیومیٹری","الجبرا","مثلثات","حساب"],"answer":1,"explain":"لفظ الجبرا الجبر سے نکلا ہے، جو اس کتاب کے عنوان میں ہے جو الخوارزمی نے 9 ویں صدی میں بغداد میں لکھی۔"},{"id":"q077","cat":"sciences","q":"لفظ الگورتھم کس عالم کے نام کی لاطینی شکل سے نکلا ہے؟","options":["الخوارزمی","الکندی","البیرونی","البتانی"],"answer":0,"explain":"الگورتھم کا لفظ الگورتمی سے نکلا ہے، جو ریاضی دان الخوارزمی کے نام کی لاطینی شکل ہے۔"},{"id":"q078","cat":"sciences","q":"القانون فی الطب کس نے لکھی؟","options":["الرازی","الزہراوی","ابن سینا","ابن النفیس"],"answer":2,"explain":"ابن سینا نے القانون فی الطب 11 ویں صدی میں لکھی۔ یہ صدیوں تک مسلم دنیا اور یورپ میں طب کی تعلیم کے لیے استعمال ہوتی رہی۔"},{"id":"q079","cat":"sciences","q":"کس عالم نے کتاب المناظر لکھی اور بتایا کہ ہم اس لیے دیکھتے ہیں کہ روشنی آنکھ میں داخل ہوتی ہے؟","options":["الخوارزمی","ابن الہیثم","ابن خلدون","الادریسی"],"answer":1,"explain":"ابن الہیثم نے، جو 10 ویں اور 11 ویں صدی میں گزرے، بصریات پر کتاب المناظر لکھی اور محتاط تجربات پر انحصار کیا۔"},{"id":"q080","cat":"sciences","q":"اندلسی عالم الزہراوی کس شعبے کے بانیوں میں شمار ہونے کی وجہ سے مشہور ہیں؟","options":["فلکیات","جراحی","جغرافیہ","الجبرا"],"answer":1,"explain":"الزہراوی نے، جو 10 ویں صدی میں قرطبہ کے قریب رہتے تھے، اپنے انسائیکلوپیڈیا التصریف میں جراحی کے عمل اور بہت سے آلات بیان کیے۔"},{"id":"q081","cat":"sciences","q":"کس طبیب نے وہ مشہور رسالہ لکھا جس میں چیچک اور خسرہ کا فرق بتایا گیا؟","options":["الکندی","الفارابی","الادریسی","الرازی"],"answer":3,"explain":"الرازی نے، جو 9 ویں اور 10 ویں صدی کے عظیم طبیب تھے، چیچک اور خسرہ پر ایک رسالہ لکھا جس میں دونوں بیماریوں کو باریکی سے بیان کیا گیا ہے۔"},{"id":"q082","cat":"sciences","q":"13 ویں صدی کے کس طبیب نے بیان کیا کہ خون دل سے پھیپھڑوں کے راستے کیسے گزرتا ہے؟","options":["الخوارزمی","البیرونی","ابن النفیس","ابن خلدون"],"answer":2,"explain":"ابن النفیس نے 13 ویں صدی میں پھیپھڑوں کے راستے خون کی گردش بیان کی، یورپ میں اس کے معلوم ہونے سے بہت پہلے۔"},{"id":"q083","cat":"sciences","q":"11 ویں صدی کے کس عالم نے زمین کا نصف قطر معلوم کیا اور ہندوستان پر ایک اہم تحقیقی کتاب لکھی؟","options":["ابن رشد","جابر بن حیان","الزہراوی","البیرونی"],"answer":3,"explain":"البیرونی نے ایک نہایت ذہانت بھرے طریقے سے زمین کا نصف قطر معلوم کیا، جس کا نتیجہ جدید قیمت کے قریب ہے، اور ہندوستان کے بارے میں ایک مفصل کتاب لکھی۔"},{"id":"q084","cat":"sciences","q":"کس جغرافیہ دان نے 12 ویں صدی میں صقلیہ کے بادشاہ راجر دوم کے لیے دنیا کا مشہور نقشہ بنایا؟","options":["ابن بطوطہ","ابن خلدون","الادریسی","الخوارزمی"],"answer":2,"explain":"الادریسی نے دنیا کا نقشہ اور اس کے ساتھ کی کتاب 1154 میں صقلیہ میں راجر دوم کے دربار میں مکمل کی۔"},{"id":"q085","cat":"sciences","q":"جابر بن حیان خاص طور پر کس شعبے میں اپنے کام کے لیے مشہور ہیں؟","options":["بصریات","جراحی","کیمیا","جغرافیہ"],"answer":2,"explain":"جابر بن حیان ابتدائی کیمیا (کیمیا گری) کے بڑے ناموں میں سے ہیں، اور بہت سی تصانیف ان سے منسوب ہیں۔"},{"id":"q086","cat":"sciences","q":"بیت الحکمت، جو تحریکِ ترجمہ سے وابستہ مشہور عباسی کتب خانہ تھا، کس شہر میں تھا؟","options":["بغداد","قرطبہ","قاہرہ","دمشق"],"answer":0,"explain":"بیت الحکمت عباسی دور کے بغداد میں تھا، جہاں اہلِ علم یونانی، فارسی اور ہندوستانی روایتوں کی کتابوں کا ترجمہ اور مطالعہ کرتے تھے۔"},{"id":"q087","cat":"sciences","q":"تاریخ اور معاشرے پر مشہور کتاب مقدمہ کس نے لکھی؟","options":["ابن خلدون","ابن بطوطہ","ابن رشد","الغزالی"],"answer":0,"explain":"ابن خلدون نے، جو 1332 میں تیونس میں پیدا ہوئے، مقدمہ لکھا۔ انہیں عمرانیات اور تاریخ کے جدید مطالعے کا پیش رو سمجھا جاتا ہے۔"},{"id":"q088","cat":"sciences","q":"اصطرلاب، جسے مسلمان اہلِ علم نے ترقی دے کر بہتر بنایا، کس کام آتا تھا؟","options":["درجۂ حرارت ناپنے کے","سونا اور چاندی تولنے کے","اناج پیسنے کے","سورج اور ستاروں کے مقام کا مشاہدہ کرنے کے"],"answer":3,"explain":"اصطرلاب سورج اور ستاروں کے مشاہدے کے لیے استعمال ہوتا تھا، جس سے لوگوں کو وقت معلوم کرنے اور سمتیں تلاش کرنے میں مدد ملتی تھی۔"},{"id":"q089","cat":"sciences","q":"انجینئر الجزری، جنہوں نے اپنی مشہور کتاب 1206 میں مکمل کی، کس چیز کے لیے مشہور ہیں؟","options":["حیرت انگیز مشینیں اور آبی گھڑیاں","دنیا کا ایک نقشہ","چیچک پر ایک رسالہ","الجبرا پر ایک کتاب"],"answer":0,"explain":"الجزری نے حیرت انگیز میکانکی آلات کے علم پر ایک کتاب لکھی، جس میں آبی گھڑیوں، پمپوں اور خودکار مشینوں کا بیان ہے۔"},{"id":"q090","cat":"sciences","q":"اندلسی عالم ابن رشد یورپ میں کس لاطینی نام سے جانے جاتے ہیں؟","options":["ایویسینا","الہازن","رازیس","ایوروس"],"answer":3,"explain":"قرطبہ کے ابن رشد ایوروس کے نام سے جانے جاتے ہیں۔ ارسطو پر ان کی شرحیں قرونِ وسطیٰ کے یورپ میں بڑے پیمانے پر پڑھی گئیں۔"},{"id":"q091","cat":"pillars","q":"اسلام کے کتنے ارکان ہیں؟","options":["تین","پانچ","چار","سات"],"answer":1,"explain":"اسلام کے پانچ ارکان ہیں: کلمۂ شہادت، نماز، زکوٰۃ، رمضان کے روزے اور بیت اللہ کا حج۔"},{"id":"q092","cat":"pillars","q":"اسلام کا پہلا رکن کیا ہے؟","options":["نماز (صلوٰۃ)","روزہ (صوم)","حج","کلمۂ شہادت"],"answer":3,"explain":"پہلا رکن شہادت ہے: اس بات کی گواہی دینا کہ اللہ کے سوا کوئی معبود نہیں اور حضرت محمد ﷺ اللہ کے رسول ہیں۔"},{"id":"q093","cat":"pillars","q":"ہر روز کتنی نمازیں فرض ہیں؟","options":["دو","تین","پانچ","سات"],"answer":2,"explain":"ہر روز پانچ نمازیں فرض ہیں: فجر، ظہر، عصر، مغرب اور عشاء۔"},{"id":"q094","cat":"pillars","q":"صبح صادق کے وقت کی نماز کا نام کیا ہے؟","options":["ظہر","فجر","عصر","عشاء"],"answer":1,"explain":"فجر صبح صادق کے وقت کی نماز ہے، جو پانچ روزانہ نمازوں میں سب سے پہلی ہے۔"},{"id":"q095","cat":"pillars","q":"نمازِ فجر میں کتنی رکعتیں فرض ہیں؟","options":["ایک","دو","تین","چار"],"answer":1,"explain":"فجر کی فرض نماز دو رکعت ہے۔"},{"id":"q096","cat":"pillars","q":"رمضان اسلامی تقویم کا کون سا مہینہ ہے؟","options":["نواں","پہلا","ساتواں","بارہواں"],"answer":0,"explain":"رمضان ہجری تقویم کا نواں مہینہ ہے۔ یہ روزوں کا مہینہ ہے۔"},{"id":"q097","cat":"pillars","q":"رمضان میں ہر دن کا روزہ کب شروع ہوتا ہے؟","options":["صبح صادق کے وقت","سورج نکلنے کے وقت","دوپہر کے وقت","آدھی رات کے وقت"],"answer":0,"explain":"روزہ صبح صادق سے شروع ہوتا ہے، جب پہلی روشنی ظاہر ہوتی ہے، جیسا کہ قرآن مجید 2:187 میں واضح کرتا ہے۔"},{"id":"q098","cat":"pillars","q":"شام کے وقت جس کھانے سے روزہ کھولا جاتا ہے اسے کیا کہتے ہیں؟","options":["سحری","ولیمہ","عقیقہ","افطار"],"answer":3,"explain":"افطار وہ کھانا ہے جس سے روزہ کھولا جاتا ہے۔ سحری وہ کھانا ہے جو صبح صادق سے پہلے کھایا جاتا ہے۔"},{"id":"q099","cat":"pillars","q":"نقدی، سونے اور چاندی جیسی جمع پونجی پر زکوٰۃ کی عام شرح کیا ہے؟","options":["2.5%","1%","5%","15%"],"answer":0,"explain":"جمع پونجی پر زکوٰۃ 2.5% یعنی چالیسواں حصہ ہے، جب کم از کم مقررہ مقدار پر پورا ایک قمری سال گزر جائے۔"},{"id":"q100","cat":"pillars","q":"حج کس مہینے میں ہوتا ہے؟","options":["رمضان","ذوالحجہ","محرم","شوال"],"answer":1,"explain":"حج ذوالحجہ میں ہوتا ہے، جو ہجری تقویم کا بارہواں اور آخری مہینہ ہے۔"},{"id":"q101","cat":"pillars","q":"ایک طواف میں حاجی خانہ کعبہ کے گرد کتنے چکر لگاتے ہیں؟","options":["تین","پانچ","سات","نو"],"answer":2,"explain":"ایک طواف خانہ کعبہ کے گرد سات چکروں پر مشتمل ہوتا ہے۔"},{"id":"q102","cat":"pillars","q":"سعی کے دوران حاجی کن دو پہاڑیوں کے درمیان چلتے ہیں؟","options":["احد اور ثور","عرفات اور منیٰ","صفا اور مروہ","حرا اور ثور"],"answer":2,"explain":"حاجی صفا اور مروہ کے درمیان سات بار چلتے ہیں، جنہیں قرآن مجید اللہ کی نشانیاں قرار دیتا ہے (2:158)۔"},{"id":"q103","cat":"pillars","q":"حاجی ذوالحجہ کی کس تاریخ کو عرفات میں وقوف کرتے ہیں؟","options":["9 تاریخ","1 تاریخ","10 تاریخ","13 تاریخ"],"answer":0,"explain":"وقوفِ عرفات 9 ذوالحجہ کو ہوتا ہے۔ یہ حج کا سب سے اہم رکن ہے۔"},{"id":"q104","cat":"pillars","q":"جو مسلمان استطاعت رکھتا ہو اس پر زندگی میں کتنی بار حج فرض ہے؟","options":["تین بار","ہر سال","ہر پانچ سال بعد","ایک بار"],"answer":3,"explain":"حج ان لوگوں پر زندگی میں ایک بار فرض ہے جو سفر کی استطاعت رکھتے ہوں (3:97)۔"},{"id":"q105","cat":"pillars","q":"خانہ کعبہ کے قبلہ بننے سے پہلے ابتدائی مسلمان کس شہر کی طرف رخ کر کے نماز پڑھتے تھے؟","options":["مدینہ","دمشق","طائف","بیت المقدس"],"answer":3,"explain":"ابتدائی مسلمان بیت المقدس کی طرف رخ کر کے نماز پڑھتے تھے۔ پھر قبلہ مکہ کی مسجدِ حرام کی طرف پھیر دیا گیا (2:144)۔"},{"id":"q106","cat":"civilisation","q":"9 ویں صدی میں فاس میں جامع القرویین کی بنیاد کس نے رکھی، جو آگے چل کر ایک مشہور یونیورسٹی بنی؟","options":["رابعہ عدویہ","فاطمہ الفہری","زبیدہ بنت جعفر","شجرۃ الدر"],"answer":1,"explain":"روایت کے مطابق فاطمہ الفہری نے 859 میں مراکش کے شہر فاس میں القرویین کی بنیاد رکھی۔ اسے اکثر اب تک چلنے والی سب سے پرانی یونیورسٹی کہا جاتا ہے۔"},{"id":"q107","cat":"civilisation","q":"اندلس کے کس شہر میں وہ جامع مسجد ہے جو اپنے ستونوں کے جنگل اور سرخ و سفید محرابوں کے لیے مشہور ہے؟","options":["اشبیلیہ","قرطبہ","غرناطہ","طلیطلہ"],"answer":1,"explain":"قرطبہ کی جامع مسجد کی تعمیر 8 ویں صدی میں شروع ہوئی، جب قرطبہ اندلس کا دارالحکومت تھا۔"},{"id":"q108","cat":"civilisation","q":"قصر الحمراء کس شہر میں ہے؟","options":["غرناطہ","قرطبہ","مراکش شہر","فاس"],"answer":0,"explain":"الحمراء اسپین کے جنوب میں غرناطہ میں واقع ہے۔ یہ نصری حکمرانوں کا محل تھا۔"},{"id":"q109","cat":"civilisation","q":"تاج محل کس مغل شہنشاہ نے بنوایا؟","options":["اکبر","بابر","اورنگ زیب","شاہ جہاں"],"answer":3,"explain":"شاہ جہاں نے 17 ویں صدی میں آگرہ میں اپنی بیوی ممتاز محل کی یاد میں تاج محل بنوایا۔"},{"id":"q110","cat":"civilisation","q":"عظیم سیاح ابن بطوطہ کس شہر میں پیدا ہوئے؟","options":["فاس","تیونس","قاہرہ","طنجہ"],"answer":3,"explain":"ابن بطوطہ 1304 میں مراکش کے شہر طنجہ میں پیدا ہوئے۔ انہوں نے تقریباً تیس سال تک افریقہ، ایشیا اور یورپ میں سفر کیا۔"},{"id":"q111","cat":"civilisation","q":"ٹمبکٹو، جو علم اور مخطوطات کا مشہور مرکز ہے، آج کے کس ملک میں ہے؟","options":["مصر","مراکش","مالی","سوڈان"],"answer":2,"explain":"ٹمبکٹو مالی میں ہے۔ اس کی مسجدیں اور مدرسے پورے مغربی افریقہ سے طلبہ اور اہلِ علم کو اپنی طرف کھینچتے تھے۔"},{"id":"q112","cat":"civilisation","q":"جامعہ الازہر، جو دنیا کی قدیم ترین یونیورسٹیوں میں سے ایک ہے، کس شہر میں ہے؟","options":["بغداد","قاہرہ","دمشق","قیروان"],"answer":1,"explain":"الازہر کی بنیاد 10 ویں صدی میں قاہرہ میں رکھی گئی اور یہ آج بھی علم کا ایک بڑا مرکز ہے۔"},{"id":"q113","cat":"civilisation","q":"قبۃ الصخرہ کس شہر میں ہے؟","options":["بیت المقدس","دمشق","مدینہ","قاہرہ"],"answer":0,"explain":"قبۃ الصخرہ بیت المقدس میں ہے۔ یہ 7 ویں صدی کے آخر میں اموی خلیفہ عبدالملک کے دور میں مکمل ہوا۔"},{"id":"q114","cat":"civilisation","q":"استنبول کی سلیمانیہ مسجد کس عثمانی معمار نے ڈیزائن کی؟","options":["الجزری","الغ بیگ","معمار سنان","ابن خلدون"],"answer":2,"explain":"معمار سنان نے، جو 16 ویں صدی میں سلطنتِ عثمانیہ کے معمارِ اعظم تھے، استنبول کی سلیمانیہ اور ادرنہ کی سلیمیہ مسجد ڈیزائن کی۔"},{"id":"q115","cat":"civilisation","q":"قرونِ وسطیٰ کی مسلم دنیا میں بیمارستان کیا ہوتا تھا؟","options":["کتب خانہ","رصد گاہ","چھت والا بازار","شفاخانہ (ہسپتال)"],"answer":3,"explain":"بیمارستان ہسپتال کو کہتے تھے۔ بغداد، دمشق اور قاہرہ جیسے شہروں میں بڑے بڑے ہسپتال تھے جہاں بیماروں کا علاج ہوتا تھا۔"},{"id":"q116","cat":"civilisation","q":"ہجری تقویم کا پہلا مہینہ کون سا ہے؟","options":["محرم","رمضان","رجب","شوال"],"answer":0,"explain":"محرم ہجری تقویم کے بارہ مہینوں میں پہلا ہے، اور یہ تقویم چاند کے حساب سے چلتی ہے۔"},{"id":"q117","cat":"civilisation","q":"مسجد میں محراب کیا ہوتی ہے؟","options":["وہ منبر جس پر جمعہ کا خطبہ دیا جاتا ہے","وہ طاق جو مکہ کی سمت بتاتا ہے","وہ مینار جہاں سے اذان دی جاتی ہے","وہ فوارہ جہاں وضو کیا جاتا ہے"],"answer":1,"explain":"محراب دیوار میں بنا ہوا ایک طاق ہے جو قبلہ یعنی مکہ کی سمت بتاتا ہے۔ خطبے کی جگہ کو منبر اور برج کو مینار کہتے ہیں۔"},{"id":"q118","cat":"civilisation","q":"قیروان کی جامع مسجد، جو افریقہ کی قدیم ترین مسجدوں میں سے ایک ہے، کس ملک میں ہے؟","options":["تیونس","مراکش","مصر","شام"],"answer":0,"explain":"قیروان تیونس میں ہے۔ اس کی جامع مسجد کی تاریخ 670 میں عقبہ بن نافع کے ہاتھوں اس شہر کی بنیاد سے شروع ہوتی ہے۔"},{"id":"q119","cat":"civilisation","q":"خطِ کوفی، جو عربی خطاطی کے قدیم ترین اسالیب میں سے ایک ہے، کس شہر کے نام پر ہے؟","options":["قرطبہ","قونیہ","کوفہ","کابل"],"answer":2,"explain":"خطِ کوفی کا نام عراق کے شہر کوفہ سے لیا گیا ہے۔ قرآن مجید کے بہت سے ابتدائی نسخے اسی زاویہ دار خط میں لکھے گئے۔"},{"id":"q120","cat":"civilisation","q":"اسلامی تہذیب میں وقف کیا ہے؟","options":["تجارتی قافلہ","خطاطی کا ایک اسلوب","خیراتی مقصد کے لیے مخصوص کی گئی جائیداد","فصلوں پر محصول"],"answer":2,"explain":"وقف وہ جائیداد ہے جو بھلائی کے کاموں کے لیے مخصوص کر دی جائے، جیسے مدرسہ، ہسپتال یا سبیل۔ اس کی آمدنی مدتوں لوگوں کے کام آتی رہتی ہے۔"}]$tk$::jsonb)
  on conflict (kind, lang) do update set payload = excluded.payload, updated_at = now();
insert into public.premium_content (kind, lang, payload) values ('days', 'ur', $tk${"new-year":{"detail":"محرم کا پہلا دن ہجری سال کا آغاز ہے۔ اسلامی تقویم قمری ہے: ہر مہینہ نئے چاند سے شروع ہوتا ہے، اس لیے ہجری سال شمسی سال سے تقریباً گیارہ دن چھوٹا ہوتا ہے۔\n\nیہ تقویم خلیفہ حضرت عمر بن خطاب کے دور میں ترتیب دی گئی، نبی کریم حضرت محمد ﷺ کی وفات کے چند سال بعد۔ صحابہ نے فیصلہ کیا کہ سالوں کا شمار ہجرت سے کیا جائے، یعنی نبی ﷺ کے مکہ سے مدینہ تشریف لے جانے سے، جو 622 عیسوی میں ہوئی، اور محرم کو پہلا مہینہ برقرار رکھا جائے۔ خود ہجرت اسی سال میں بعد کو، ربیع الاول کے مہینے میں ہوئی تھی۔\n\nمحرم ان چار حرمت والے مہینوں میں سے ایک ہے جن کا ذکر قرآن میں ہے (9:36)۔ نبی ﷺ نے سکھایا کہ رمضان کے بعد سب سے افضل روزے اللہ کے مہینے محرم کے ہیں (صحیح مسلم 1163)۔\n\nاس دن کے لیے کوئی خاص نماز یا خاص تقریب مقرر نہیں۔ بہت سے مسلمان اس موقع پر ہجرت کو یاد کرتے ہیں، گزرے ہوئے سال کا جائزہ لیتے ہیں اور نیکی کے نئے ارادے کرتے ہیں۔","sources":["قرآن 9:36","صحیح مسلم 1163"]},"tasua":{"detail":"تاسوعاء محرم کا نواں دن ہے، یعنی عاشوراء سے ایک دن پہلے۔\n\nجب نبی کریم حضرت محمد ﷺ نے عاشوراء کا روزہ رکھا اور مسلمانوں کو اس کا حکم دیا تو صحابہ نے عرض کیا کہ یہود اور نصاریٰ بھی اس دن کی تعظیم کرتے ہیں۔ آپ ﷺ نے فرمایا کہ اگلے سال، اگر اللہ نے چاہا، تو وہ نویں تاریخ کا روزہ بھی رکھیں گے۔ اگلا محرم آنے سے پہلے آپ ﷺ کا وصال ہو گیا (صحیح مسلم 1134)۔\n\nاسی لیے علماء دسویں کے ساتھ نویں تاریخ کا روزہ رکھنے کو مستحب کہتے ہیں۔ اس طرح مسلمانوں کے روزے کی اپنی الگ صورت بن جاتی ہے، اور اس دن سے تعلق بھی قائم رہتا ہے جس دن اللہ نے حضرت موسیٰ علیہ السلام کو نجات دی۔\n\nیہ روزہ نفلی ہے۔ جو شخص صرف دسویں کا روزہ رکھ سکے اس نے بھی عاشوراء کا روزہ رکھا، اور جو بیمار ہو، سفر میں ہو یا روزہ نہ رکھ سکتا ہو اسے اپنے آپ کو قصوروار نہیں سمجھنا چاہیے۔ پورا محرم حرمت والا مہینہ ہے، اور نبی ﷺ نے سکھایا کہ اس مہینے کے روزے رمضان کے بعد سب سے افضل ہیں (صحیح مسلم 1163)۔","sources":["صحیح مسلم 1134","صحیح مسلم 1163"]},"ashura":{"detail":"عاشوراء محرم کا دسواں دن ہے۔ اس کا قصہ حضرت موسیٰ علیہ السلام تک جاتا ہے: اس دن اللہ نے انہیں اور بنی اسرائیل کو ان کے دشمن سے نجات دی۔\n\nجب نبی کریم حضرت محمد ﷺ مدینہ تشریف لائے تو آپ نے یہود کو اس نجات کی یاد میں اس دن روزہ رکھتے ہوئے پایا۔ آپ ﷺ نے فرمایا کہ مسلمان موسیٰ پر زیادہ حق رکھتے ہیں، چنانچہ آپ نے روزہ رکھا اور مسلمانوں کو بھی اس کا حکم دیا (صحیح بخاری 2004)۔ جب رمضان کے روزے فرض ہوئے تو عاشوراء کا روزہ ایک نفلی اور مستحب عمل کے طور پر باقی رہا (صحیح بخاری 2002)۔\n\nاس کے ثواب کے بارے میں پوچھا گیا تو نبی ﷺ نے فرمایا کہ یہ گزشتہ سال کے گناہوں کا کفارہ ہے (صحیح مسلم 1162)۔ اس کے ساتھ نویں تاریخ کا روزہ رکھنا بھی مستحب ہے (صحیح مسلم 1134)۔","sources":["صحیح بخاری 2004","صحیح بخاری 2002","صحیح مسلم 1162","صحیح مسلم 1134"]},"mawlid":{"detail":"نبی کریم حضرت محمد ﷺ مکہ میں، قبیلہ قریش کے خاندان بنو ہاشم میں، عام الفیل کہلانے والے سال میں پیدا ہوئے، تقریباً 570 عیسوی میں۔ آپ کے والد عبداللہ آپ کی ولادت سے پہلے وفات پا گئے، اور والدہ آمنہ کا انتقال آپ کے بچپن میں ہوا۔\n\nثابت ہے کہ آپ پیر کے دن پیدا ہوئے: جب آپ سے پیر کے روزے کے بارے میں پوچھا گیا تو فرمایا کہ یہ وہ دن ہے جس میں آپ پیدا ہوئے اور جس میں آپ پر وحی نازل ہوئی (صحیح مسلم 1162)۔ اکثر مؤرخین آپ کی ولادت ربیع الاول میں بتاتے ہیں۔ 12 تاریخ سب سے مشہور ہے، لیکن دوسری تاریخیں بھی بیان ہوئی ہیں اور کوئی بھی یقینی نہیں۔\n\nاس دن کو منانے کے بارے میں مسلمانوں کی آراء مختلف ہیں۔ بہت سے لوگ جمع ہو کر آپ کی سیرت بیان کرتے ہیں، آپ پر درود بھیجتے ہیں اور کھانا تقسیم کرتے ہیں۔ دوسرے لوگ اس دن کو خاص نہیں کرتے، کیونکہ نبی ﷺ اور آپ کے صحابہ نے ایسا نہیں کیا۔ آپ سے محبت اور ہر روز آپ کے اسوہ کی پیروی پر سب متفق ہیں؛ قرآن آپ کو تمام جہانوں کے لیے رحمت کہتا ہے (21:107)۔","sources":["صحیح مسلم 1162","قرآن 21:107"]},"isra-miraj":{"detail":"اسراء نبی کریم حضرت محمد ﷺ کا وہ رات کا سفر ہے جو مکہ کی مسجدِ حرام سے بیت المقدس کی مسجدِ اقصیٰ تک ہوا۔ قرآن نے سورۂ اسراء کے آغاز میں اس کا ذکر کیا ہے (17:1)۔ معراج وہاں سے آسمانوں کی طرف آپ کا عروج ہے، جہاں آپ کی ملاقات پچھلے انبیاء علیہم السلام سے ہوئی اور آپ کو اپنے رب کی بڑی نشانیاں دکھائی گئیں؛ سورۂ نجم میں اس کی طرف اشارہ ہے (53:13-18)۔\n\nیہ واقعہ ہجرت سے پہلے مکہ میں پیش آیا، ایسے وقت میں جو نبی ﷺ کے لیے آزمائش کا زمانہ تھا۔ اس رات کا سب سے دیرپا تحفہ پانچ وقت کی نمازیں ہیں، جو اسی وقت فرض کی گئیں (صحیح بخاری 349)۔\n\nاس کی صحیح تاریخ یقین کے ساتھ معلوم نہیں۔ 27 رجب سب سے زیادہ مشہور تاریخ ہے، لیکن ابتدائی مؤرخین نے دوسری تاریخیں بھی ذکر کی ہیں۔\n\nاس رات کے لیے کوئی خاص نماز یا روزہ ثابت نہیں۔ بہت سے مسلمان اس موقع پر یہ واقعہ بیان کرتے ہیں اور نماز کی قدر و قیمت کو یاد کرتے ہیں؛ دوسرے لوگ اس تاریخ کو نہیں مناتے۔ رجب چار حرمت والے مہینوں میں سے ایک ہے (9:36)۔","sources":["قرآن 17:1","قرآن 53:13-18","صحیح بخاری 349","قرآن 9:36"]},"mid-shaban":{"detail":"شعبان آٹھواں مہینہ ہے، رمضان سے بالکل پہلے۔ حضرت عائشہ رضی اللہ عنہا نے بیان کیا کہ انہوں نے نبی کریم حضرت محمد ﷺ کو رمضان کے سوا کسی مہینے میں اتنے روزے رکھتے نہیں دیکھا جتنے آپ شعبان میں رکھتے تھے (صحیح بخاری 1969)۔ یہ تیاری کا مہینہ ہے: نفلی روزے، پچھلے رمضان کے چھوٹے ہوئے روزوں کی قضا اور قرآن کی تلاوت۔\n\nمہینے کے درمیان کی پندرھویں رات بہت سے ملکوں میں لیلۃ البراءۃ، شبِ برات یا نصف شعبان جیسے ناموں سے جانی جاتی ہے۔ کئی روایات میں اس رات اللہ کی مغفرت کا ذکر آیا ہے۔ ان روایات کی قوت کے بارے میں علماء کی آراء مختلف ہیں، اور اسی لیے عمل کے بارے میں بھی اختلاف ہے: بہت سے مسلمان رات کا کچھ حصہ نماز اور دعا میں گزارتے ہیں اور دن کو روزہ رکھتے ہیں؛ دوسرے لوگ اسے شعبان کی عام راتوں کی طرح سمجھتے ہیں اور اس کے لیے کوئی خاص عبادت مقرر نہیں کرتے۔\n\nجس بات پر اتفاق ہے وہ یہ ہے کہ استغفار، لوگوں سے تعلقات کی اصلاح اور نفلی روزے پورے شعبان میں اچھے اعمال ہیں، جو رمضان کا دروازہ ہے۔","sources":["صحیح بخاری 1969"]},"ramadan-start":{"detail":"رمضان ہجری سال کا نواں مہینہ ہے، وہ مہینہ جس میں قرآن لوگوں کے لیے ہدایت بن کر نازل ہوا (2:185)۔ اس کے روزے اسلام کے پانچ ارکان میں سے ایک ہیں (صحیح بخاری 8)۔ یہ روزے مدینہ میں، ہجرت کے دوسرے سال فرض ہوئے۔\n\nمہینہ نیا چاند نظر آنے سے شروع ہوتا ہے؛ اگر چاند نظر نہ آ سکے تو شعبان کے تیس دن پورے کیے جاتے ہیں (صحیح بخاری 1909)۔ اسی وجہ سے ایک ملک اور دوسرے ملک میں آغاز کا ایک دن کا فرق ہو سکتا ہے۔\n\nصبح صادق سے غروبِ آفتاب تک روزہ دار کھانے، پینے اور ازدواجی تعلق سے رکے رہتے ہیں۔ بیمار اور مسافر کو رخصت ہے اور وہ بعد میں ان دنوں کی قضا کرتے ہیں، اور جو بالکل روزہ نہ رکھ سکے وہ اس کے بدلے ایک مسکین کو کھانا کھلاتا ہے (2:184-185)۔ قرآن نے روزے کا مقصد بتایا ہے: تقویٰ حاصل کرنا (2:183)۔\n\nنبی کریم حضرت محمد ﷺ نے فرمایا کہ جب رمضان آتا ہے تو آسمان کے دروازے کھول دیے جاتے ہیں، جہنم کے دروازے بند کر دیے جاتے ہیں اور شیاطین جکڑ دیے جاتے ہیں (صحیح بخاری 1899)۔ یہ نماز، قرآن اور سخاوت کا مہینہ ہے۔","sources":["قرآن 2:183-185","صحیح بخاری 8","صحیح بخاری 1909","صحیح بخاری 1899"]},"last-ten-nights":{"detail":"رمضان کی آخری دس راتیں اکیسویں دن سے پہلے والی شام سے شروع ہوتی ہیں اور مہینے کے آخر تک رہتی ہیں، جو 29 یا 30 دن کا ہوتا ہے۔ یہ رمضان کا سب سے قیمتی حصہ ہے، کیونکہ شبِ قدر انہی راتوں میں ہے۔\n\nحضرت عائشہ رضی اللہ عنہا نے بیان کیا کہ جب یہ عشرہ شروع ہوتا تو نبی کریم حضرت محمد ﷺ کمر کس لیتے، رات کو عبادت میں گزارتے اور اپنے گھر والوں کو جگاتے (صحیح بخاری 2024)۔ آپ ان راتوں میں عبادت میں اتنی محنت فرماتے جتنی کسی اور وقت نہیں فرماتے تھے (صحیح مسلم 1175)۔\n\nآپ رمضان کے آخری دس دنوں میں اعتکاف بھی فرماتے تھے، یعنی عبادت کے لیے یکسو ہو کر مسجد میں ٹھہرنا، یہاں تک کہ آپ کا وصال ہو گیا (صحیح بخاری 2026)۔\n\nمستحب اعمال یہ ہیں: رات کی نماز، قرآن کی تلاوت، کثرت سے دعا، استغفار اور صدقہ۔ جو لوگ دیر تک نہیں جاگ سکتے وہ بھی ہر رات تھوڑی سی نماز پڑھ سکتے ہیں، تاکہ وہ رات ان سے چھوٹ نہ جائے جو ہزار مہینوں سے بہتر ہے (97:3)۔ انہی دنوں میں نمازِ عید سے پہلے صدقۂ فطر کی تیاری بھی کی جاتی ہے۔","sources":["صحیح بخاری 2024","صحیح مسلم 1175","صحیح بخاری 2026","قرآن 97:3"]},"laylat-al-qadr":{"detail":"شبِ قدر وہ رات ہے جس میں قرآن نازل ہوا۔ ایک پوری سورت اس کے بارے میں ہے: یہ ہزار مہینوں سے بہتر ہے، اس میں فرشتے اور روح اپنے رب کے حکم سے اترتے ہیں، اور یہ طلوعِ فجر تک سلامتی ہے (97:1-5)۔ قرآن نے اسے برکت والی رات بھی کہا ہے (44:3)۔\n\nاس کی صحیح تاریخ پوشیدہ رکھی گئی ہے۔ نبی کریم حضرت محمد ﷺ نے مومنوں کو حکم دیا کہ اسے رمضان کے آخری عشرے کی طاق راتوں میں تلاش کریں (صحیح بخاری 2017): یعنی 21، 23، 25، 27 یا 29 ویں رات۔ 27 ویں رات کا ذکر سب سے زیادہ ہوتا ہے، اور بہت سی جگہوں پر لوگ اس رات جمع ہوتے ہیں، لیکن یہ یقینی نہیں، اور علماء کی آراء مختلف ہیں۔ سب سے دانشمندانہ طریقہ یہ ہے کہ دسوں راتوں میں محنت کی جائے۔\n\nنبی ﷺ نے فرمایا کہ جو شخص شبِ قدر میں ایمان کے ساتھ اور ثواب کی امید رکھتے ہوئے قیام کرے، اس کے پچھلے گناہ معاف کر دیے جائیں گے (صحیح بخاری 2014)۔ مستحب اعمال یہ ہیں: رات کی نماز، قرآن کی تلاوت، دعا اور اللہ سے معافی مانگنا۔","sources":["قرآن 97:1-5","قرآن 44:3","صحیح بخاری 2017","صحیح بخاری 2014"]},"eid-al-fitr":{"detail":"عید الفطر، یعنی روزے کھولنے کی عید، شوال کی پہلی تاریخ کو ہوتی ہے اور رمضان کے مہینے کا اختتام ہے۔ قرآن مومنوں سے کہتا ہے کہ وہ دنوں کی گنتی پوری کریں اور اللہ کی بڑائی بیان کریں کہ اس نے انہیں ہدایت دی (2:185)۔\n\nنمازِ عید سے پہلے صدقۂ فطر ادا کیا جاتا ہے: بنیادی خوراک کا ایک چھوٹا سا صدقہ، جو گھر کے ہر فرد کی طرف سے واجب ہے، تاکہ غریب بھی اس دن کی خوشی میں شریک ہو سکیں۔ نبی کریم حضرت محمد ﷺ نے حکم دیا کہ اسے لوگوں کے نماز کے لیے نکلنے سے پہلے ادا کیا جائے (صحیح بخاری 1503)۔\n\nصبح کے وقت مسلمان تکبیر کہتے ہیں، اپنے بہترین کپڑے پہنتے ہیں اور نمازِ عید کے لیے جمع ہوتے ہیں، جس کے بعد خطبہ ہوتا ہے (صحیح بخاری 956)۔ اس دن نبی ﷺ نماز کے لیے اس وقت تک نہیں نکلتے تھے جب تک چند کھجوریں نہ کھا لیتے (صحیح بخاری 953)۔\n\nعید کے دن روزہ رکھنا جائز نہیں (صحیح بخاری 1991)۔ یہ شکر، رشتہ داروں سے ملاقات اور پڑوسیوں کے ساتھ حسنِ سلوک کا دن ہے۔ نفلی روزے، جیسے شوال کے چھ روزے، دوسرے دن سے شروع کیے جا سکتے ہیں۔","sources":["قرآن 2:185","صحیح بخاری 1503","صحیح بخاری 956","صحیح بخاری 953","صحیح بخاری 1991"]},"six-shawwal":{"detail":"شوال رمضان کے بعد کا مہینہ ہے۔ نبی کریم حضرت محمد ﷺ نے فرمایا کہ جس نے رمضان کے روزے رکھے اور پھر شوال کے چھ روزے رکھے، تو یہ ایسا ہے جیسے اس نے پورے سال کے روزے رکھے (صحیح مسلم 1164)۔\n\nعلماء اس کی وضاحت اس اصول سے کرتے ہیں کہ ایک نیکی کا بدلہ دس گنا ملتا ہے (6:160): رمضان کا مہینہ دس مہینوں کے برابر ہوا، اور مزید چھ دن دو مہینوں کے برابر، یوں پورا سال بن جاتا ہے۔\n\nمہینے کے کوئی بھی چھ دن ہو سکتے ہیں۔ ایپ میں 2 سے 7 تاریخ صرف سہولت کے لیے دکھائی گئی ہے: یہ روزے لگاتار بھی رکھے جا سکتے ہیں اور الگ الگ بھی، شوال کے شروع میں، درمیان میں یا آخر میں۔ صرف پہلی تاریخ مستثنیٰ ہے، یعنی عید کا دن، جس میں روزہ رکھنا جائز نہیں۔\n\nیہ روزے نفلی ہیں، فرض نہیں۔ جس کے ذمے رمضان کے کچھ روزے باقی ہوں اسے ان کا بھی خیال رکھنا چاہیے: بہت سے علماء پہلے قضا روزے رکھنے کا مشورہ دیتے ہیں، جبکہ دوسرے چھ روزے پہلے رکھنے کی اجازت دیتے ہیں۔ یہ رمضان کی اچھی عادتوں کو زندہ رکھنے کا ایک آسان طریقہ ہے۔","sources":["صحیح مسلم 1164","قرآن 6:160"]},"dhul-hijja-nine":{"detail":"ذوالحجہ بارھواں مہینہ ہے، حج کا مہینہ۔ اس کے پہلے دس دن سال کے بہترین دنوں میں سے ہیں: نبی کریم حضرت محمد ﷺ نے فرمایا کہ کوئی نیک عمل ان دنوں کے عمل سے افضل نہیں (صحیح بخاری 969)۔ بہت سے مفسرین یہ بھی کہتے ہیں کہ قرآن میں اللہ نے جن دس راتوں کی قسم کھائی ہے (89:2) ان سے مراد یہی دن ہیں۔\n\nچونکہ روزہ بہترین اعمال میں سے ہے، اس لیے پہلے نو دنوں میں جتنا ہو سکے روزے رکھنا مستحب ہے۔ نواں دن، یعنی یومِ عرفہ، سب سے زیادہ تاکید والا ہے۔ دسواں دن عید الاضحیٰ ہے، جس میں روزہ رکھنا جائز نہیں۔\n\nدوسرے مستحب اعمال یہ ہیں: بار بار تکبیر کہنا، کثرت سے اللہ کی حمد کرنا، نماز، صدقہ اور قرآن کی تلاوت۔ قرآن میں معلوم دنوں میں اللہ کا نام لینے کا ذکر ہے (22:28)۔\n\nجو شخص قربانی کا ارادہ رکھتا ہو اسے کہا گیا ہے کہ مہینے کے آغاز سے قربانی ہونے تک اپنے بال اور ناخن نہ کاٹے (صحیح مسلم 1977)۔ ان دنوں میں دنیا بھر سے حاجی مکہ میں جمع ہوتے ہیں۔","sources":["صحیح بخاری 969","قرآن 89:2","قرآن 22:28","صحیح مسلم 1977"]},"arafat":{"detail":"9 ذوالحجہ یومِ عرفہ ہے، جو حج کا دل ہے۔ دوپہر سے غروبِ آفتاب تک حاجی مکہ کے قریب میدانِ عرفات میں نماز اور دعا میں ٹھہرتے ہیں۔ وقوفِ عرفہ حج کا سب سے بنیادی رکن ہے۔\n\nاسی دن، جو جمعہ کا دن تھا، نبی کریم حضرت محمد ﷺ کے حجۃ الوداع کے موقع پر وہ آیت نازل ہوئی جس میں اعلان ہے کہ اللہ نے دین مکمل کر دیا (5:3)، جیسا کہ حضرت عمر بن خطاب نے بیان کیا (صحیح بخاری 45)۔\n\nنبی ﷺ نے فرمایا کہ کوئی دن ایسا نہیں جس میں اللہ یومِ عرفہ سے زیادہ بندوں کو آگ سے آزاد کرتا ہو (صحیح مسلم 1348)۔\n\nجو لوگ حج پر نہیں ہیں ان کے لیے اس دن کا روزہ بہت تاکید کے ساتھ مستحب ہے: نبی ﷺ نے فرمایا کہ یہ گزشتہ سال اور آنے والے سال کے گناہوں کا کفارہ ہے (صحیح مسلم 1162)۔ خود حاجیوں سے روزے کا مطالبہ نہیں؛ نبی ﷺ نے عرفات میں وقوف کے دوران روزہ نہیں رکھا تھا (صحیح بخاری 1988)۔\n\nیہ دعا، اللہ کے ذکر اور استغفار کا دن ہے، انسان جہاں بھی ہو۔","sources":["قرآن 5:3","صحیح بخاری 45","صحیح مسلم 1348","صحیح مسلم 1162","صحیح بخاری 1988"]},"eid-al-adha":{"detail":"عید الاضحیٰ، یعنی قربانی کی عید، 10 ذوالحجہ کو ہوتی ہے، عرفہ کے اگلے دن۔ یہ منیٰ اور مکہ میں حج کے بڑے مناسک کے ساتھ آتی ہے۔\n\nیہ حضرت ابراہیم علیہ السلام کی آزمائش کی یاد دلاتی ہے۔ انہوں نے خواب میں دیکھا کہ وہ اپنے بیٹے کو ذبح کر رہے ہیں؛ دونوں نے اللہ کے حکم کے آگے سر جھکا دیا، اور اللہ نے بیٹے کے بدلے ایک عظیم قربانی دے دی (37:102-107)۔\n\nدن کا آغاز نمازِ عید سے ہوتا ہے، جس کے بعد خطبہ ہوتا ہے (صحیح بخاری 956)۔ نماز کے بعد جو لوگ استطاعت رکھتے ہیں وہ بھیڑ، بکری، گائے یا اونٹ قربان کرتے ہیں۔ گوشت گھر والے کھاتے ہیں، رشتہ داروں اور پڑوسیوں کو ہدیہ کیا جاتا ہے اور غریبوں کو دیا جاتا ہے۔ قرآن مومنوں کو یاد دلاتا ہے کہ اللہ تک نہ گوشت پہنچتا ہے نہ خون؛ اس تک ان کا تقویٰ پہنچتا ہے (22:37)۔\n\nاس دن روزہ رکھنا جائز نہیں (صحیح بخاری 1991)۔ مسلمان تکبیر کہتے ہیں، اپنے بہترین کپڑے پہنتے ہیں، ایک دوسرے سے ملتے ہیں اور کھانا بانٹتے ہیں۔ قربانی اس کے بعد کے دنوں میں بھی کی جا سکتی ہے۔","sources":["قرآن 37:102-107","صحیح بخاری 956","قرآن 22:37","صحیح بخاری 1991"]},"tashriq":{"detail":"ایامِ تشریق ذوالحجہ کی 11، 12 اور 13 تاریخ ہیں، یعنی عید الاضحیٰ کے بعد کے تین دن۔ نبی کریم حضرت محمد ﷺ نے انہیں کھانے، پینے اور اللہ کے ذکر کے دن قرار دیا (صحیح مسلم 1141)۔\n\nان دنوں میں حاجی منیٰ میں ٹھہرتے ہیں اور ہر روز ان تین ستونوں کو کنکریاں مارتے ہیں جنہیں جمرات کہا جاتا ہے۔ قرآن انہیں ان گنتی کے دنوں میں اللہ کو یاد کرنے کا حکم دیتا ہے، اور بتاتا ہے کہ جو دو دن کے بعد جلدی روانہ ہو جائے اس پر کوئی گناہ نہیں، اور جو زیادہ ٹھہرے اس پر بھی نہیں (2:203)۔ چنانچہ حاجی 12 تاریخ کو روانہ ہو سکتے ہیں یا 13 تک ٹھہر سکتے ہیں۔\n\nان دنوں میں روزہ رکھنا جائز نہیں۔ واحد استثنا جو منقول ہے ان حاجیوں کے لیے ہے جن پر ہدی کی قربانی لازم ہو اور انہیں وہ میسر نہ آئے (صحیح بخاری 1997)۔\n\nباقی سب کے لیے یہ خوشی اور شکر کے دن ہیں: قربانی کا گوشت بانٹنا، رشتہ داروں سے ملنا اور تکبیر کہنا، خاص طور پر روزانہ کی نمازوں کے بعد۔ عید کی قربانی ان دنوں میں بھی کی جا سکتی ہے، جس کی تفصیل فقہی مذاہب میں مختلف ہے۔","sources":["صحیح مسلم 1141","قرآن 2:203","صحیح بخاری 1997"]}}$tk$::jsonb)
  on conflict (kind, lang) do update set payload = excluded.payload, updated_at = now();
